#!/usr/bin/env bash
set -euo pipefail

# Minimal, cleaned installer for XUI dashboard
    # Fixes: defines missing helpers, removes duplicated blocks, and ensures a runnable flow

USER_HOME="${HOME:-/home/$(whoami)}"
XUI_DIR="$USER_HOME/.xui"
DATA_DIR="$XUI_DIR/data"
BIN_DIR="$XUI_DIR/bin"
DASH_DIR="$XUI_DIR/dashboard"
CASINO_DIR="$XUI_DIR/casino"
GAMES_DIR="$XUI_DIR/games"
ASSETS_DIR="$XUI_DIR/assets"
LOG_DIR="$XUI_DIR/logs"
BACKUP_DIR="$XUI_DIR/backups"
SYSTEMD_USER_DIR="$USER_HOME/.config/systemd/user"
AUTOSTART_DIR="$USER_HOME/.config/autostart"

info(){ echo -e "[INFO] $*"; }
warn(){ echo -e "[WARN] $*" >&2; }
check_cmd(){ command -v "$1" >/dev/null 2>&1; }

linux_distro_info(){
    if [ -r /etc/os-release ]; then
        . /etc/os-release
        printf '%s|%s|%s' "${ID:-unknown}" "${ID_LIKE:-}" "${PRETTY_NAME:-Linux}"
    elif check_cmd lsb_release; then
        printf '%s|%s|%s' "$(lsb_release -si 2>/dev/null | tr '[:upper:]' '[:lower:]')" "" "$(lsb_release -sd 2>/dev/null)"
    else
        printf '%s|%s|%s' unknown "" "Linux"
    fi
}

run_as_root(){
    if [ "$(id -u)" -eq 0 ]; then
        "$@"
        return $?
    fi
    if check_cmd sudo && sudo -n true >/dev/null 2>&1; then
        sudo -n "$@"
        return $?
    fi
    if [ "${XUI_NONINTERACTIVE:-0}" = "1" ] || [ ! -t 0 ]; then
        if [ "${XUI_ALLOW_NONINTERACTIVE_PKEXEC:-0}" = "1" ] && check_cmd pkexec; then
            pkexec "$@"
            return $?
        fi
        warn "non-interactive root unavailable (no cached sudo); skipping: $*"
        return 1
    fi
    if check_cmd sudo; then
        sudo -v >/dev/null 2>&1 || true
        if sudo -n true >/dev/null 2>&1; then
            sudo -n "$@"
            return $?
        fi
        sudo "$@"
        return $?
    fi
    if check_cmd pkexec; then
        pkexec "$@"
        return $?
    fi
    warn "root privileges unavailable; cannot run: $*"
    return 1
}

wait_for_apt_lock(){
    if ! check_cmd apt && ! check_cmd apt-get; then
        return 0
    fi
    if [ "${XUI_SKIP_APT_WAIT:-0}" = "1" ]; then
        info "Skipping apt/dpkg wait (XUI_SKIP_APT_WAIT=1)"
        return 0
    fi
    local waited=0
    local step=2
    local max_wait="${XUI_APT_WAIT_SECONDS:-180}"
    if ! [[ "$max_wait" =~ ^[0-9]+$ ]]; then
        max_wait=180
    fi
    while true; do
        local lock_busy=0
        if check_cmd fuser; then
            for lf in /var/lib/dpkg/lock-frontend /var/lib/dpkg/lock /var/lib/apt/lists/lock /var/cache/apt/archives/lock; do
                [ -e "$lf" ] || continue
                if fuser "$lf" >/dev/null 2>&1; then
                    lock_busy=1
                    break
                fi
            done
        fi
        if [ "$lock_busy" -eq 0 ]; then
            # Fallback: process check when lock files can't be inspected.
            if pgrep -x apt >/dev/null 2>&1 || pgrep -x apt-get >/dev/null 2>&1 || pgrep -x dpkg >/dev/null 2>&1 || pgrep -f unattended-upgrade >/dev/null 2>&1; then
                lock_busy=1
            fi
        fi

        if [ "$lock_busy" -eq 1 ]; then
            if [ "$waited" -ge "$max_wait" ]; then
                warn "APT/DPKG lock still busy after ${max_wait}s; continuing anyway"
                break
            fi
            info "Waiting apt/dpkg lock (${waited}s/${max_wait}s)..."
            if [ "$waited" -eq 0 ]; then
                info "Tip: use --skip-apt-wait or --apt-wait-seconds 30"
            fi
            sleep "$step"
            waited=$((waited + step))
            continue
        fi
        break
    done
}

apt_binary(){
    if check_cmd apt-get; then
        command -v apt-get
    elif check_cmd apt; then
        command -v apt
    else
        return 1
    fi
}

apt_safe_update(){
    wait_for_apt_lock
    local apt_cmd
    apt_cmd="$(apt_binary)" || return 1
    run_as_root "$apt_cmd" update
}

apt_safe_install(){
    wait_for_apt_lock
    local apt_cmd
    apt_cmd="$(apt_binary)" || return 1
    run_as_root "$apt_cmd" install -y "$@"
}

# Install APT packages one by one and continue on errors.
apt_install_each_best_effort(){
    local pkg
    local failed=0
    if [ "$(id -u)" -ne 0 ] && { [ "${XUI_NONINTERACTIVE:-0}" = "1" ] || [ ! -t 0 ]; }; then
        if ! check_cmd sudo || ! sudo -n true >/dev/null 2>&1; then
            warn "Skipping per-package apt retries to avoid repeated auth popups (cached sudo not available)"
            return 1
        fi
    fi
    for pkg in "$@"; do
        if ! apt_safe_install "$pkg"; then
            warn "Failed apt package: $pkg"
            failed=1
        fi
    done
    return "$failed"
}

# Simple confirmation helper. Respects AUTO_CONFIRM=1 for automation.
confirm(){
    if [ "${AUTO_CONFIRM:-0}" = "1" ] || [ "${AUTO_INSTALL_TOOLS:-0}" = "1" ]; then
        return 0
    fi
    while true; do
        printf "%s [y/N]: " "$1"
        read -r ans || return 1
        case "$ans" in
            [Yy]|[Yy][Ee][Ss]) return 0;;
            [Nn]|[Nn][Oo]|"") return 1;;
        esac
    done
}

install_dependencies(){
    if ! check_cmd python3; then
        warn "python3 not found; cannot continue dependency setup"
        return 0
    fi
    if [ "${AUTO_INSTALL_TOOLS:-0}" != "1" ]; then
        info "AUTO_INSTALL_TOOLS=0; skipping system package installation"
        if ! python3 - <<'PY' >/dev/null 2>&1
import PyQt5, PIL
PY
        then
            warn "PyQt5/Pillow missing in system Python; preparing the XUI user virtualenv"
            local venv_dir="$XUI_DIR/.venv"
            if ! python3 -m venv "$venv_dir"; then
                warn "Could not create $venv_dir; install python3-venv or run with --yes-install"
                return 0
            fi
            if ! "$venv_dir/bin/python" -m pip install PyQt5 Pillow; then
                warn "Could not install XUI Python dependencies; check network access and pip, or run with --yes-install"
                return 0
            fi
            "$venv_dir/bin/python" -m pip install PyQtWebEngine pygame evdev >/dev/null 2>&1 || \
                info "Some optional Python modules are unavailable; core dashboard dependencies are installed"
            if "$venv_dir/bin/python" - <<'PY' >/dev/null 2>&1
import PyQt5, PIL
PY
            then
                info "XUI user virtualenv ready (PyQt5/Pillow)"
            else
                warn "XUI user virtualenv is missing PyQt5/Pillow; dashboard may not start"
            fi
        fi
        return 0
    fi

    info "Installing system dependencies (best effort)"
    local distro_info distro_id distro_like distro_pretty
    distro_info="$(linux_distro_info)"
    IFS='|' read -r distro_id distro_like distro_pretty <<< "$distro_info"
    if check_cmd apt || check_cmd apt-get; then
        local arch_now
        local core_pkgs optional_pkgs
        arch_now="$(uname -m)"
        info "Detected Linux distribution: $distro_pretty (ID=$distro_id${distro_like:+, ID_LIKE=$distro_like}); using APT-compatible packages"
        core_pkgs=(
            python3 python3-pip python3-venv python3-pyqt5 python3-pil
        )
        optional_pkgs=(
            python3-pyqt5.qtmultimedia python3-pyqt5.qtgamepad python3-pyqt5.qtwebengine python3-evdev
            hicolor-icon-theme adwaita-icon-theme humanity-icon-theme libqt5svg5 qt5-gtk-platformtheme qt5ct
            ffmpeg mpv jq xdotool x11-utils curl ca-certificates iproute2 bc
            xclip xsel rofi feh maim scrot udisks2 p7zip-full joystick joycond evtest jstest-gtk xboxdrv
            retroarch lutris kodi
            binutils file xz-utils
            libc6 libstdc++6 libgcc-s1 libasound2 libx11-6 libxrandr2 libxinerama1 libxcursor1 libxi6
            libgl1 libglu1-mesa libpulse0 mesa-vulkan-drivers
            steam-installer steam
        )
        apt_safe_update || warn "apt update failed"
        # Install critical runtime first (must succeed for dashboard)
        if ! apt_safe_install "${core_pkgs[@]}"; then
            warn "Core apt dependencies failed in bulk install; retrying one by one"
            apt_install_each_best_effort "${core_pkgs[@]}" || warn "Some core apt dependencies are still missing"
        fi
        # Debian derivatives differ in optional package availability; attempt independently
        # so one absent package never prevents icons, Qt plugins, or other tools installing.
        apt_install_each_best_effort qml-module-qtgamepad libqt5gamepad5 qt6-gtk-platformtheme || true
        apt_install_each_best_effort "${optional_pkgs[@]}" || warn "Some optional APT packages are unavailable on this distribution"
        # Windows compatibility (best effort): Wine + Winetricks + ARM helpers
        if [ "$arch_now" = "x86_64" ] || [ "$arch_now" = "amd64" ]; then
            apt_install_each_best_effort wine wine64 winetricks || warn "Wine/Winetricks install failed on x86_64"
        elif [ "$arch_now" = "aarch64" ] || [ "$arch_now" = "arm64" ]; then
            apt_install_each_best_effort wine64 winetricks || true
            apt_install_each_best_effort box64 box86 qemu-user-static || warn "ARM compatibility packages failed (box64/box86/qemu)"
            info "AArch64 detected: x86 Windows .exe may need box64 + x86 Wine build"
        fi
        # Optional gaming/compat packages (best effort one by one)
        for pkg in flatpak steam-installer steamcmd box64 box86 qemu-user-static retroarch lutris heroic heroic-games-launcher joycond; do
            apt_safe_install "$pkg" || true
        done
    elif command -v dnf >/dev/null 2>&1; then
        run_as_root dnf install -y \
            python3 python3-pip python3-virtualenv python3-qt5 python3-pillow python3-evdev \
            ffmpeg mpv jq xdotool xorg-x11-utils curl iproute bc \
            xclip xsel rofi feh scrot udisks2 p7zip joystick joycond retroarch lutris kodi || warn "Some dnf packages failed to install"
        run_as_root dnf install -y python3-qt5-webengine || true
        for pkg in python3-qt5-gamepad qt5-qtgamepad qt5-qtgamepad-devel; do
            run_as_root dnf install -y "$pkg" || true
        done
        run_as_root dnf install -y wine winetricks || true
        for pkg in flatpak steam box64 fex-emu qemu-user-static retroarch lutris heroic-games-launcher joycond; do
            run_as_root dnf install -y "$pkg" || true
        done
    elif command -v pacman >/dev/null 2>&1; then
        run_as_root pacman -Syu --noconfirm \
            python python-pip python-virtualenv pyqt5 python-pillow python-evdev \
            ffmpeg mpv jq xdotool xorg-xprop curl iproute2 bc \
            xclip xsel rofi feh scrot maim udisks2 p7zip joystick joycond retroarch lutris kodi || warn "Some pacman packages failed to install"
        run_as_root pacman -S --noconfirm python-pyqt5-webengine || true
        for pkg in qt5-gamepad; do
            run_as_root pacman -S --noconfirm "$pkg" || true
        done
        run_as_root pacman -S --noconfirm wine winetricks || true
        for pkg in flatpak steam box64 qemu-user-static retroarch lutris heroic-games-launcher joycond; do
            run_as_root pacman -S --noconfirm "$pkg" || true
        done
    else
        warn "No known package manager found; skipping system package installation"
    fi

    # Validate Python modules and fallback to local venv if needed
    if python3 - <<'PY' >/dev/null 2>&1
import PyQt5, PIL
PY
    then
        info "Python modules available: PyQt5, Pillow"
        return 0
    fi

    warn "PyQt5/Pillow missing in system Python; creating local venv fallback"
    VENV_DIR="$XUI_DIR/.venv"
    if ! python3 -m venv "$VENV_DIR"; then
        warn "Failed to create venv at $VENV_DIR; install python3-venv and retry"
        return 0
    fi
    if ! "$VENV_DIR/bin/python" -m pip install PyQt5 Pillow; then
        warn "Could not install required PyQt5/Pillow dependencies into $VENV_DIR"
        return 0
    fi
    "$VENV_DIR/bin/python" -m pip install PyQtWebEngine pygame evdev >/dev/null 2>&1 || \
        info "Some optional Python modules are unavailable; core dashboard dependencies are installed"

    # Validate fallback runtime
    if "$VENV_DIR/bin/python" - <<'PY' >/dev/null 2>&1
import PyQt5, PIL
PY
    then
        info "venv runtime ready (PyQt5/Pillow)"
    else
        warn "PyQt5/Pillow are still unavailable in $VENV_DIR"
    fi
}

install_browser(){
    # Best-effort installer for a browser or a no-op stub so calls don't fail.
    if [ "${AUTO_INSTALL_TOOLS:-0}" != "1" ]; then
        info "AUTO_INSTALL_TOOLS not set; skipping browser install"
        return 0
    fi
    # Prefer chromium/firefox and don't fail on distro package differences
    if command -v apt >/dev/null 2>&1; then
        apt_safe_update || true
        if ! apt_safe_install chromium-browser; then
            if ! apt_safe_install chromium; then
                apt_safe_install firefox || warn "Failed to install browser via apt"
            fi
        fi
        return 0
    elif command -v dnf >/dev/null 2>&1; then
        run_as_root dnf install -y chromium || warn "Failed to install chromium via dnf"
        return 0
    elif command -v pacman >/dev/null 2>&1; then
        run_as_root pacman -S --noconfirm chromium || warn "Failed to install chromium via pacman"
        return 0
    fi
    warn "No supported package manager found for automatic browser install; please install a browser (chromium/firefox) manually"
}

parse_args(){
    # System package installation is opt-in; use --yes-install to enable it.
    AUTO_INSTALL_TOOLS=0
    XUI_INSTALL_SYSTEM=1
    XUI_USE_EXTERNAL_DASHBOARD=0
    XUI_SKIP_APT_WAIT=0
    XUI_APT_WAIT_SECONDS="${XUI_APT_WAIT_SECONDS:-180}"
    XUI_ONLY_REFRESH_STORE=0
    XUI_ONLY_REFRESH_CONTROLLERS=0
    XUI_ONLY_REFRESH_UPDATER=0
    XUI_ONLY_REFRESH_XENIA=0
    XUI_EXPORT_WIN=0
    XUI_ONLY_EXPORT_WIN=0
    XUI_SKIP_XENIA=0
    while [ "$#" -gt 0 ]; do
        case "$1" in
            --yes-install|-y)
                AUTO_INSTALL_TOOLS=1
                XUI_INSTALL_SYSTEM=1
                shift
                ;;
            --no-auto-install)
                AUTO_INSTALL_TOOLS=0
                XUI_INSTALL_SYSTEM=0
                shift
                ;;
            --skip-xenia)
                XUI_SKIP_XENIA=1
                shift
                ;;
            --use-external-dashboard)
                XUI_USE_EXTERNAL_DASHBOARD=1
                shift
                ;;
            --skip-apt-wait)
                XUI_SKIP_APT_WAIT=1
                shift
                ;;
            --apt-wait-seconds)
                if [ "${2:-}" != "" ] && [[ "${2:-}" =~ ^[0-9]+$ ]]; then
                    XUI_APT_WAIT_SECONDS="$2"
                    shift 2
                else
                    warn "--apt-wait-seconds requires numeric value"
                    shift
                fi
                ;;
            --refresh-store-ui|--fix-store-ui|--refresh-casino|--fix-casino)
                XUI_ONLY_REFRESH_STORE=1
                shift
                ;;
            --refresh-controllers|--fix-controllers)
                XUI_ONLY_REFRESH_CONTROLLERS=1
                shift
                ;;
            --refresh-updater|--fix-updater)
                XUI_ONLY_REFRESH_UPDATER=1
                shift
                ;;
            --refresh-xenia|--fix-xenia|--refresh-xbox-emulators|--fix-xbox-emulators)
                XUI_ONLY_REFRESH_XENIA=1
                shift
                ;;
            --export-win|--windows-bundle)
                XUI_EXPORT_WIN=1
                shift
                ;;
            --export-win-only|--windows-only)
                XUI_EXPORT_WIN=1
                XUI_ONLY_EXPORT_WIN=1
                shift
                ;;
            --help|-h)
                echo "Usage: $0 [--yes-install|-y] [--no-auto-install] [--skip-xenia] [--use-external-dashboard] [--skip-apt-wait] [--apt-wait-seconds N] [--refresh-store-ui|--refresh-casino] [--refresh-controllers] [--refresh-updater] [--refresh-xbox-emulators] [--export-win] [--export-win-only]"; exit 0 ;;
            *)
                warn "Ignoring unknown argument: $1"
                shift
                ;;
        esac
    done
    export AUTO_INSTALL_TOOLS XUI_INSTALL_SYSTEM XUI_USE_EXTERNAL_DASHBOARD XUI_SKIP_APT_WAIT XUI_APT_WAIT_SECONDS XUI_ONLY_REFRESH_STORE XUI_ONLY_REFRESH_CONTROLLERS XUI_ONLY_REFRESH_UPDATER XUI_ONLY_REFRESH_XENIA XUI_EXPORT_WIN XUI_ONLY_EXPORT_WIN XUI_SKIP_XENIA
}

ensure_dirs(){
  mkdir -p "$ASSETS_DIR" "$BIN_DIR" "$DASH_DIR" "$DATA_DIR" "$SYSTEMD_USER_DIR" "$AUTOSTART_DIR" || true
    cat > "$BIN_DIR/xui_python.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
if [ -x "$HOME/.xui/.venv/bin/python" ] && \
   "$HOME/.xui/.venv/bin/python" -c 'import PyQt5, PIL' >/dev/null 2>&1; then
    exec "$HOME/.xui/.venv/bin/python" "$@"
fi
if command -v python3 >/dev/null 2>&1; then
    exec python3 "$@"
fi
echo "XUI: python3 is required to launch this app." >&2
exit 127
BASH
    chmod +x "$BIN_DIR/xui_python.sh" || true
}

copy_web_game_ports_catalog(){
    local script_dir catalog_source candidate
    script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    catalog_source=""
    for candidate in \
        "$script_dir/win/web_game_ports.json" \
        "$script_dir/web_game_ports.json" \
        "$(dirname "$script_dir")/win/web_game_ports.json"; do
        if [ -s "$candidate" ]; then
            catalog_source="$candidate"
            break
        fi
    done
    if [ -n "$catalog_source" ]; then
        if ! python3 -c 'import json,sys; d=json.load(open(sys.argv[1], encoding="utf-8")); assert isinstance(d.get("games"), list) and d["games"]' "$catalog_source" >/dev/null 2>&1; then
            warn "Web game ports catalog is invalid: $catalog_source"
            warn "Continuing with the built-in web game list"
            return 0
        fi
        cp -f "$catalog_source" "$DATA_DIR/web_game_ports.json"
        info "Copied $(python3 -c 'import json,sys; print(len(json.load(open(sys.argv[1], encoding="utf-8"))["games"]))' "$DATA_DIR/web_game_ports.json") web game entries"
    elif [ -s "$DATA_DIR/web_game_ports.json" ]; then
        info "Using existing web game ports catalog ($(python3 -c 'import json,sys; print(len(json.load(open(sys.argv[1], encoding="utf-8"))["games"]))' "$DATA_DIR/web_game_ports.json") entries)"
    else
        warn "Web game ports catalog missing; using the built-in web game list"
        return 0
    fi
}

write_windows_bundle(){
    local script_dir win_dir
    script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    win_dir="$script_dir/win"
    mkdir -p "$win_dir"
    info "Writing Windows bundle to $win_dir"

    cat > "$win_dir/extract_xui_payload.py" <<'PY'
#!/usr/bin/env python3
import argparse
import json
import re
import sys
from pathlib import Path

TARGETS = [
    ("$DASH_DIR/pyqt_dashboard_improved.py", "pyqt_dashboard_improved.py", True),
    ("$BIN_DIR/xui_webhub.py", "xui_webhub.py", True),
    ("$BIN_DIR/xui_social_chat.py", "xui_social_chat.py", True),
    ("$GAMES_DIR/store.py", "xui_store_modern.py", True),
    ("$BIN_DIR/xui_global_guide.py", "xui_global_guide.py", True),
    ("$BIN_DIR/xui_first_setup.py", "xui_first_setup.py", False),
    ("$BIN_DIR/xui_game_lib.py", "xui_game_lib.py", False),
    ("$BIN_DIR/xui_web_api.py", "xui_web_api.py", False),
]


def extract_last_heredoc(src_text: str, target_path: str):
    pattern = re.compile(
        r'cat > "' + re.escape(target_path) + r'" <<\'([^\']+)\'\n',
        re.MULTILINE,
    )
    matches = list(pattern.finditer(src_text))
    if not matches:
        return None
    m = matches[-1]
    marker = m.group(1)
    start = m.end()
    end_token = f"\n{marker}\n"
    end = src_text.find(end_token, start)
    if end < 0:
        raise RuntimeError(f"Heredoc marker not closed for {target_path} ({marker})")
    payload = src_text[start:end]
    if payload and not payload.endswith("\n"):
        payload += "\n"
    return payload


def main() -> int:
    ap = argparse.ArgumentParser(description="Extract Windows payload from xui11.sh.fixed.sh")
    ap.add_argument("--source", required=True, help="Path to xui11.sh.fixed.sh")
    ap.add_argument("--out", required=True, help="Output directory")
    args = ap.parse_args()

    src = Path(args.source).expanduser().resolve()
    out = Path(args.out).expanduser().resolve()
    if not src.exists():
        print(f"[ERROR] source not found: {src}", file=sys.stderr)
        return 2
    out.mkdir(parents=True, exist_ok=True)

    text = src.read_text(encoding="utf-8", errors="replace")
    extracted = {}
    missing_required = []
    for bash_target, out_name, required in TARGETS:
        block = extract_last_heredoc(text, bash_target)
        if block is None:
            if required:
                missing_required.append(bash_target)
            continue
        dst = out / out_name
        dst.write_text(block, encoding="utf-8")
        extracted[out_name] = {
            "source_target": bash_target,
            "size": len(block),
            "lines": block.count("\n"),
        }
        print(f"[OK] extracted {out_name}")

    if missing_required:
        print("[ERROR] required targets were not found:", file=sys.stderr)
        for item in missing_required:
            print(f" - {item}", file=sys.stderr)
        return 3

    manifest = {
        "source": str(src),
        "files": extracted,
        "count": len(extracted),
    }
    (out / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    print(f"[OK] manifest: {out / 'manifest.json'}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
PY
    chmod +x "$win_dir/extract_xui_payload.py" || true

    cat > "$win_dir/xui_update_check.py" <<'PY'
#!/usr/bin/env python3
import argparse
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

REPO = os.environ.get("XUI_UPDATE_REPO", "afitler79-alt/XUI-X360-FRONTEND").strip() or "afitler79-alt/XUI-X360-FRONTEND"
XUI_HOME = Path.home() / ".xui"
DATA_HOME = XUI_HOME / "data"
STATE_FILE = DATA_HOME / "update_state.json"
CHANNEL_FILE = DATA_HOME / "update_channel.json"
SRC = Path(os.environ.get("XUI_SOURCE_DIR", str(XUI_HOME / "src" / "XUI-X360-FRONTEND"))).expanduser()
INSTALLER_NAME = os.environ.get("XUI_UPDATE_INSTALLER", "win/install_xui_windows.ps1").strip() or "win/install_xui_windows.ps1"
DEFAULT_BRANCH = os.environ.get("XUI_DEFAULT_UPDATE_BRANCH", "Windows").strip() or "Windows"


def ensure_data_home() -> None:
    DATA_HOME.mkdir(parents=True, exist_ok=True)


def read_state_commit() -> str:
    if not STATE_FILE.exists():
        return ""
    try:
        data = json.loads(STATE_FILE.read_text(encoding="utf-8"))
    except Exception:
        return ""
    return str(data.get("installed_commit", "") or "").strip()


def read_channel_branch() -> str:
    if not CHANNEL_FILE.exists():
        return ""
    try:
        data = json.loads(CHANNEL_FILE.read_text(encoding="utf-8"))
    except Exception:
        return ""
    return str(data.get("branch", "") or "").strip()


def resolve_branch() -> str:
    env_branch = str(os.environ.get("XUI_UPDATE_BRANCH", "") or "").strip()
    if env_branch:
        return env_branch
    file_branch = read_channel_branch()
    if file_branch:
        return file_branch
    return DEFAULT_BRANCH


TARGET_BRANCH = resolve_branch()


def write_state(commit: str, branch: str, remote_date: str, src: Path) -> None:
    ensure_data_home()
    payload = {
        "installed_commit": str(commit or ""),
        "branch": str(branch or ""),
        "remote_date": str(remote_date or ""),
        "installed_at_epoch": int(time.time()),
        "source_dir": str(src),
        "version": 2,
    }
    STATE_FILE.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
    print("state-updated")


def fetch_json(url: str, timeout: int = 12):
    req = urllib.request.Request(
        url,
        headers={
            "Accept": "application/vnd.github+json",
            "User-Agent": "xui-update-checker-win",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="ignore")
    return json.loads(raw)


def remote_meta():
    try:
        branch = TARGET_BRANCH
        commit = fetch_json(f"https://api.github.com/repos/{REPO}/commits/{branch}")
        sha = str(commit.get("sha", "") or "").strip()
        date = str((((commit.get("commit") or {}).get("committer") or {}).get("date")) or "")
        html = str(commit.get("html_url", "") or "")
        if not sha:
            return {"ok": False, "error": "missing-remote-sha", "branch": branch}
        return {
            "ok": True,
            "branch": branch,
            "sha": sha,
            "date": date,
            "url": html,
        }
    except Exception as exc:
        return {"ok": False, "error": str(exc), "branch": TARGET_BRANCH}


def emit_json(checked: bool, required: bool, reason: str, branch: str, local_commit: str, remote_commit: str, remote_date: str, remote_url: str) -> None:
    obj = {
        "checked": bool(checked),
        "mandatory": True,
        "update_required": bool(required),
        "reason": str(reason or ""),
        "repo": REPO,
        "branch": str(branch or ""),
        "local_commit": str(local_commit or ""),
        "remote_commit": str(remote_commit or ""),
        "remote_date": str(remote_date or ""),
        "remote_url": str(remote_url or ""),
    }
    print(json.dumps(obj, ensure_ascii=False))


def compute_status(json_out: bool = False) -> int:
    local_commit = read_state_commit()
    if not local_commit and (SRC / ".git").exists() and shutil.which("git"):
        try:
            local_commit = subprocess.check_output(
                ["git", "-C", str(SRC), "rev-parse", "HEAD"],
                stderr=subprocess.DEVNULL,
                text=True,
            ).strip()
        except Exception:
            local_commit = ""

    meta = remote_meta()
    if not meta.get("ok"):
        checked = False
        required = False
        reason = f"remote-unavailable:{meta.get('error', 'unknown')}"
        branch = str(meta.get("branch") or TARGET_BRANCH)
        remote_commit = ""
        remote_date = ""
        remote_url = ""
    else:
        checked = True
        branch = str(meta.get("branch") or TARGET_BRANCH)
        remote_commit = str(meta.get("sha") or "")
        remote_date = str(meta.get("date") or "")
        remote_url = str(meta.get("url") or "")
        if not local_commit:
            required = True
            reason = "missing-local-version"
        elif local_commit != remote_commit:
            required = True
            reason = "outdated"
        else:
            required = False
            reason = "up-to-date"

    if json_out:
        emit_json(checked, required, reason, branch, local_commit, remote_commit, remote_date, remote_url)
    else:
        print(f"Repo: {REPO}")
        print(f"Branch: {branch}")
        print(f"Checked: {'yes' if checked else 'no'}")
        print("Mandatory: yes")
        print(f"Local commit: {local_commit or '<none>'}")
        print(f"Remote commit: {remote_commit or '<unknown>'}")
        if remote_date:
            print(f"Remote date: {remote_date}")
        if remote_url:
            print(f"Remote URL: {remote_url}")
        print(f"Update required: {'yes' if required else 'no'}")
        print(f"Reason: {reason}")

    return 10 if required else 0


def run_stream(cmd, cwd=None) -> int:
    proc = subprocess.Popen(
        cmd,
        cwd=str(cwd) if cwd else None,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    assert proc.stdout is not None
    for line in proc.stdout:
        print(line.rstrip("\n"))
    return int(proc.wait())


def find_installer() -> Path:
    candidates = [
        INSTALLER_NAME,
        "win/install_xui_windows.ps1",
        "install_xui_windows.ps1",
        "win/install_xui_windows.bat",
        "install_xui_windows.bat",
    ]
    for item in candidates:
        p = Path(item)
        if not p.is_absolute():
            p = SRC / p
        if p.exists() and p.is_file():
            return p
    raise FileNotFoundError(f"Installer not found in repo: {SRC}")


def apply_update() -> int:
    git = shutil.which("git")
    if not git:
        print("git is required for apply mode")
        return 1

    meta = remote_meta()
    if not meta.get("ok"):
        print(f"Cannot reach GitHub metadata: {meta.get('error', 'unknown')}")
        return 1
    branch = str(meta.get("branch") or TARGET_BRANCH)
    remote_commit = str(meta.get("sha") or "")
    remote_date = str(meta.get("date") or "")

    SRC.parent.mkdir(parents=True, exist_ok=True)
    if not (SRC / ".git").exists():
        print("step=git-clone")
        rc = run_stream([git, "clone", f"https://github.com/{REPO}.git", str(SRC)])
        if rc != 0:
            return rc

    print("step=git-fetch")
    rc = run_stream([git, "-C", str(SRC), "fetch", "--all", "--prune"])
    if rc != 0:
        return rc
    rc = run_stream([git, "-C", str(SRC), "checkout", "-B", branch, f"origin/{branch}"])
    if rc != 0:
        return rc
    rc = run_stream([git, "-C", str(SRC), "reset", "--hard", f"origin/{branch}"])
    if rc != 0:
        return rc
    run_stream([git, "-C", str(SRC), "clean", "-fd"])

    installer = find_installer()
    print("step=installer-start")
    if installer.suffix.lower() == ".ps1":
        ps = shutil.which("pwsh") or shutil.which("powershell")
        if not ps:
            print("PowerShell is required to run Windows installer")
            return 1
        cmd = [
            ps,
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(installer),
            "-SourceRoot",
            str(SRC),
            "-SkipPip",
        ]
    elif installer.suffix.lower() in (".bat", ".cmd"):
        cmd = ["cmd.exe", "/c", str(installer)]
    else:
        cmd = [str(installer)]
    rc = run_stream(cmd, cwd=SRC)
    print("step=installer-done")
    if rc != 0:
        print(f"Installer failed with code {rc}")
        return rc

    installed_commit = ""
    try:
        installed_commit = subprocess.check_output(
            [git, "-C", str(SRC), "rev-parse", "HEAD"],
            stderr=subprocess.DEVNULL,
            text=True,
        ).strip()
    except Exception:
        installed_commit = remote_commit

    try:
        write_state(installed_commit, branch, remote_date, SRC)
        print("step=state-written")
    except Exception:
        print("warning=state-write-failed")

    print("update-applied")
    print(f"installed_commit={installed_commit}")
    return 0


def pull_only() -> int:
    git = shutil.which("git")
    if not git:
        print("git is required for pull mode")
        return 1
    if not (SRC / ".git").exists():
        print(f"No git repo at {SRC}")
        return 1
    rc = run_stream([git, "-C", str(SRC), "fetch", "--all", "--prune"])
    if rc != 0:
        return rc
    return run_stream([git, "-C", str(SRC), "checkout", "-B", TARGET_BRANCH, f"origin/{TARGET_BRANCH}"])


def release_info() -> int:
    try:
        info = fetch_json(f"https://api.github.com/repos/{REPO}/releases/latest")
        print("Latest release:", str(info.get("tag_name") or "unknown"))
        return 0
    except Exception as exc:
        print("Could not query latest release:", exc)
        return 1


def mark_current() -> int:
    git = shutil.which("git")
    if not git:
        print("git is required for mark mode")
        return 1
    if not (SRC / ".git").exists():
        print(f"No git repo at {SRC}")
        return 1
    commit = subprocess.check_output([git, "-C", str(SRC), "rev-parse", "HEAD"], text=True).strip()
    branch = subprocess.check_output([git, "-C", str(SRC), "rev-parse", "--abbrev-ref", "HEAD"], text=True).strip()
    write_state(commit, branch, "", SRC)
    print(f"marked-installed={commit}")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("mode", nargs="?", default="status")
    parser.add_argument("--json", action="store_true", dest="json_out")
    args, _extra = parser.parse_known_args()
    ensure_data_home()
    mode = str(args.mode or "status").strip().lower()
    if mode in ("status", "mandatory"):
        return compute_status(json_out=bool(args.json_out))
    if mode == "pull":
        return pull_only()
    if mode == "apply":
        return apply_update()
    if mode == "release":
        return release_info()
    if mode == "mark":
        return mark_current()
    print("Usage: xui_update_check.py {status|mandatory|pull|apply|release|mark} [--json]")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
