#!/usr/bin/env bash
set -euo pipefail
ARCH=$(uname -m)
CHECK_ONLY=0
if [ "${1:-}" = "--check" ]; then
  CHECK_ONLY=1
  shift || true
fi

has_steam(){
  if command -v steam >/dev/null 2>&1; then
    return 0
  fi
  if command -v flatpak >/dev/null 2>&1 && flatpak info com.valvesoftware.Steam >/dev/null 2>&1; then
    return 0
  fi
  if [ "$ARCH" = "aarch64" ] || [ "$ARCH" = "arm64" ]; then
    if command -v box64 >/dev/null 2>&1; then
      for c in \
        "$HOME/.local/share/Steam/ubuntu12_64/steam" \
        "$HOME/.steam/steam/ubuntu12_64/steam" \
        "/usr/lib/steam/steam" \
        "/usr/games/steam"; do
        if [ -x "$c" ]; then
          return 0
        fi
      done
    fi
  fi
  return 1
}

if [ "$CHECK_ONLY" = "1" ]; then
  if has_steam; then
    echo "steam: available"
    exit 0
  fi
  echo "steam: missing"
  exit 1
fi

if command -v steam >/dev/null 2>&1; then
  exec steam "$@"
fi

if command -v flatpak >/dev/null 2>&1 && flatpak info com.valvesoftware.Steam >/dev/null 2>&1; then
  exec flatpak run com.valvesoftware.Steam "$@"
fi

if [ "$ARCH" = "aarch64" ] || [ "$ARCH" = "arm64" ]; then
  if command -v box64 >/dev/null 2>&1; then
    for c in \
      "$HOME/.local/share/Steam/ubuntu12_64/steam" \
      "$HOME/.steam/steam/ubuntu12_64/steam" \
      "/usr/lib/steam/steam" \
      "/usr/games/steam"; do
      if [ -x "$c" ]; then
        exec "$HOME/.xui/bin/xui_run_x86.sh" "$c" "$@"
      fi
    done
  fi
fi

echo "Steam not available yet."
echo "Run: $HOME/.xui/bin/xui_install_steam.sh"
exit 1
BASH
    chmod +x "$BIN_DIR/xui_steam.sh"

