def local_ipv4_addresses():
    ips = set()
    try:
        for ip in subprocess.getoutput('hostname -I 2>/dev/null').split():
            if ip and not ip.startswith('127.'):
                ips.add(ip)
    except Exception:
        pass
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(('1.1.1.1', 80))
        ip = s.getsockname()[0]
        s.close()
        if ip and not ip.startswith('127.'):
            ips.add(ip)
    except Exception:
        pass
    return sorted(ips) if ips else ['127.0.0.1']


def local_ipv4_broadcasts():
    targets = set()
    try:
        out = subprocess.getoutput('ip -o -4 addr show scope global 2>/dev/null')
        for line in out.splitlines():
            parts = line.split()
            if 'brd' in parts:
                idx = parts.index('brd')
                if idx + 1 < len(parts):
                    brd = parts[idx + 1].strip()
                    if brd and not brd.startswith('127.'):
                        targets.add(brd)
    except Exception:
        pass
    if not targets:
        # Keep LAN discovery working on minimal Debian installs without iproute2.
        # Linux SIOCGIF* ioctls expose interface IPv4 address/netmask using stdlib only.
        try:
            import fcntl
            import struct
            probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            for _, ifname in socket.if_nameindex():
                encoded_name = ifname.encode('ascii', errors='ignore')[:15]
                request = struct.pack('256s', encoded_name)
                try:
                    address = socket.inet_ntoa(fcntl.ioctl(probe.fileno(), 0x8915, request)[20:24])
                    netmask = socket.inet_ntoa(fcntl.ioctl(probe.fileno(), 0x891B, request)[20:24])
                    if address.startswith('127.'):
                        continue
                    address_int = struct.unpack('!I', socket.inet_aton(address))[0]
                    mask_int = struct.unpack('!I', socket.inet_aton(netmask))[0]
                    broadcast = socket.inet_ntoa(struct.pack('!I', address_int | (~mask_int & 0xffffffff)))
                    if broadcast != address:
                        targets.add(broadcast)
                except OSError:
                    continue
            probe.close()
        except Exception:
            pass
    return sorted(targets)


def parse_peer_id(text):
    raw = str(text or '').strip()
    if not raw:
        return None
    alias = ''
    if '@' in raw:
        alias, raw = raw.split('@', 1)
    if ':' not in raw:
        return None
    host, port_s = raw.rsplit(':', 1)
    host = host.strip()
    try:
        port = int(port_s.strip())
    except Exception:
        return None
    if not host or port < 1 or port > 65535:
        return None
    return {
        'name': alias.strip() or host,
        'host': host,
        'port': int(port),
        'source': 'manual',
    }


class InlineSocialEngine:
    def __init__(self, nickname, user_id='', chat_base=38600, discovery_port=38655):
        self.nickname = nickname
        raw_uid = str(user_id or '').strip()
        raw_uid = ''.join(ch for ch in raw_uid if ch.isalnum() or ch in ('-', '_'))
        self.user_id = raw_uid[:40] if raw_uid else uuid.uuid4().hex[:16]
        self.node_id = uuid.uuid4().hex[:12]
        self.chat_port = self._find_open_port(chat_base, 24)
        self.discovery_port = int(discovery_port)
        self.world_relay = os.environ.get('XUI_WORLD_RELAY_URL', 'https://ntfy.sh').strip().rstrip('/')
        self.world_topic = self._sanitize_topic(
            os.environ.get('XUI_WORLD_TOPIC', 'xui-world-global')
        )
        self.world_enabled = True
        self._world_response = None
        self._world_response_lock = threading.Lock()
        self.events = queue.Queue()
        self.running = False
        self.threads = []
        self.peers = {}
        self.lock = threading.Lock()
        self.local_ips = set(local_ipv4_addresses())
        self._seen_world_ids = set()
        self._presence_tick = 0

    def _sanitize_topic(self, text):
        raw = ''.join(ch.lower() if ch.isalnum() or ch in ('-', '_', '.') else '-' for ch in str(text or '').strip())
        while '--' in raw:
            raw = raw.replace('--', '-')
        raw = raw.strip('-._')
        return raw or 'xui-world-global'

    def set_world_topic(self, topic):
        new_topic = self._sanitize_topic(topic)
        if new_topic == self.world_topic:
            return
        self.world_topic = new_topic
        self._interrupt_world_stream()
        self._seen_world_ids.clear()
        self.events.put(('world_room', self.world_topic))
        self.events.put(('status', f'World chat room set to: {self.world_topic}'))

    def set_world_enabled(self, enabled):
        self.world_enabled = bool(enabled)
        if not self.world_enabled:
            self._interrupt_world_stream()
        self.events.put(('world_status', self.world_enabled, self.world_topic))
        if self.world_enabled:
            self.events.put(('status', f'Connecting to public relay room: {self.world_topic}…'))
        else:
            self.events.put(('status', 'World chat disconnected'))

    def _find_open_port(self, base, span):
        for port in range(int(base), int(base) + int(span)):
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                s.bind(('', port))
                s.close()
                return int(port)
            except OSError:
                s.close()
                continue
        return 0

    def start(self):
        self.running = True
        for fn in (
            self._tcp_server_loop,
            self._udp_discovery_listener,
            self._udp_discovery_sender,
            self._peer_gc_loop,
            self._world_recv_loop,
            self._world_presence_loop,
        ):
            t = threading.Thread(target=fn, daemon=True)
            self.threads.append(t)
            t.start()
        if self.chat_port:
            self.events.put(('status', f'Chat TCP listening on port {self.chat_port}'))
        else:
            self.events.put(('status', 'No free TCP chat port available'))
        self.events.put(('world_status', self.world_enabled, self.world_topic))

    def stop(self):
        self.running = False
        self._interrupt_world_stream()
        for t in self.threads:
            t.join(timeout=0.2)

    def _send_packet(self, host, port, payload):
        payload = dict(payload)
        message_id = str(payload.get('message_id') or uuid.uuid4().hex)
        payload['message_id'] = message_id
        body = (json.dumps(payload, ensure_ascii=False) + '\n').encode('utf-8', errors='ignore')
        with socket.create_connection((str(host), int(port)), timeout=4.0) as s:
            s.sendall(body)
            s.shutdown(socket.SHUT_WR)
            s.settimeout(4.0)
            response = bytearray()
            while len(response) <= 4096 and b'\n' not in response:
                chunk = s.recv(1024)
                if not chunk:
                    break
                response.extend(chunk)
            if not response:
                return False
            try:
                ack = json.loads(bytes(response).split(b'\n', 1)[0].decode('utf-8'))
            except (ValueError, UnicodeError):
                return False
            if not isinstance(ack, dict) or str(ack.get('message_id') or '') != message_id:
                return False
            return bool(ack.get('ok'))

    def send_chat(self, host, port, text, message_id=''):
        payload = {
            'type': 'chat',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'from': self.nickname,
            'text': str(text),
            'ts': time.time(),
            'reply_port': int(self.chat_port or 0),
            'message_id': str(message_id or uuid.uuid4().hex),
        }
        return self._send_packet(host, port, payload)

    def send_private_message(self, host, port, text, message_id=''):
        payload = {
            'type': 'private_message',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'from': self.nickname,
            'text': str(text),
            'ts': time.time(),
            'reply_port': int(self.chat_port or 0),
            'message_id': str(message_id or uuid.uuid4().hex),
        }
        return self._send_packet(host, port, payload)

    def send_friend_request(self, host, port, note=''):
        payload = {
            'type': 'friend_request',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'from': self.nickname,
            'note': str(note or 'XUI friend request'),
            'ts': time.time(),
            'reply_port': int(self.chat_port or 0),
        }
        return self._send_packet(host, port, payload)

    def send_friend_accept(self, host, port):
        payload = {
            'type': 'friend_accept',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'from': self.nickname,
            'ts': time.time(),
            'reply_port': int(self.chat_port or 0),
        }
        return self._send_packet(host, port, payload)

    def send_voice_message(self, host, port, mime, duration, encoded_audio):
        payload = {
            'type': 'voice_message',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'from': self.nickname,
            'mime': str(mime or 'audio/ogg'),
            'duration': float(duration or 0.0),
            'audio': str(encoded_audio or ''),
            'ts': time.time(),
            'reply_port': int(self.chat_port or 0),
        }
        self._send_packet(host, port, payload)

    def _world_url(self, suffix='', topic=None):
        topic = urllib.parse.quote(str(topic or self.world_topic), safe='')
        return f'{self.world_relay}/{topic}{suffix}'

    def _interrupt_world_stream(self):
        with self._world_response_lock:
            response = self._world_response
            self._world_response = None
        if response is not None:
            try:
                response.close()
            except Exception:
                pass

    def _post_world_payload(self, payload):
        data = json.dumps(payload, ensure_ascii=False).encode('utf-8', errors='ignore')
        req = urllib.request.Request(
            self._world_url(''),
            data=data,
            method='POST',
            headers={
                'Content-Type': 'text/plain; charset=utf-8',
                'User-Agent': 'xui-dashboard-world-chat',
                'X-Title': f'XUI:{self.nickname}:{self.user_id}',
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=8) as r:
                _ = r.read(256)
        except urllib.error.HTTPError as exc:
            if exc.code == 429:
                retry_after = str(exc.headers.get('Retry-After') or '').strip()
                detail = f' (retry after {retry_after}s)' if retry_after.isdigit() else ''
                raise RuntimeError(
                    'El relay público limitó las solicitudes (HTTP 429)'
                    f'{detail}. Prueba por LAN o configura XUI_WORLD_RELAY_URL con un relay propio.'
                ) from exc
            raise RuntimeError(f'El relay devolvió HTTP {exc.code}.') from exc
        except urllib.error.URLError as exc:
            raise RuntimeError(f'No se pudo conectar con el relay: {exc.reason}') from exc

    def send_world_event(self, kind, **extra):
        payload = {
            'kind': str(kind or ''),
            'message_id': uuid.uuid4().hex,
            'node_id': self.node_id,
            'user_id': self.user_id,
            'from': self.nickname,
            'room': self.world_topic,
            'ts': time.time(),
        }
        payload.update(extra or {})
        self._post_world_payload(payload)

    def send_world_chat(self, text):
        self.send_world_event('xui_world_chat', text=str(text or ''))

    def send_world_private_message(self, to_user_id, text):
        to_uid = str(to_user_id or '').strip()
        if not to_uid:
            raise RuntimeError('missing target user id')
        self.send_world_event(
            'xui_world_pm',
            to_user_id=to_uid,
            text=str(text or ''),
        )

    def send_world_friend_request(self, to_user_id, note=''):
        to_uid = str(to_user_id or '').strip()
        if not to_uid:
            raise RuntimeError('missing target user id')
        self.send_world_event(
            'xui_friend_request',
            to_user_id=to_uid,
            note=str(note or 'XUI friend request'),
        )

    def send_world_friend_accept(self, to_user_id):
        to_uid = str(to_user_id or '').strip()
        if not to_uid:
            raise RuntimeError('missing target user id')
        self.send_world_event('xui_friend_accept', to_user_id=to_uid)

    def send_world_party_invite(self, to_user_id, party_id, party_name=''):
        to_uid = str(to_user_id or '').strip()
        pid = str(party_id or '').strip()
        if not to_uid or not pid:
            raise RuntimeError('missing party invite data')
        self.send_world_event(
            'xui_party_invite',
            to_user_id=to_uid,
            party_id=pid,
            party_name=str(party_name or ''),
        )

    def send_world_party_state(self, party_id, state='join'):
        pid = str(party_id or '').strip()
        if not pid:
            return False
        try:
            self.send_world_event(
                'xui_party_state',
                party_id=pid,
                state=str(state or 'join'),
            )
            return True
        except Exception:
            # Party presence is optional. A blocked public relay must not
            # terminate the daemon thread or prevent LAN/social operations.
            return False

    def send_world_voice_message(self, to_user_id, mime, duration, encoded_audio, party_id=''):
        to_uid = str(to_user_id or '').strip()
        pid = str(party_id or '').strip()
        if not to_uid and not pid:
            raise RuntimeError('missing voice target')
        self.send_world_event(
            'xui_voice_msg',
            to_user_id=to_uid,
            party_id=pid,
            mime=str(mime or 'audio/ogg'),
            duration=float(duration or 0.0),
            audio=str(encoded_audio or ''),
        )

    def _world_presence_loop(self):
        while self.running:
            if self.world_enabled:
                self._presence_tick += 1
                try:
                    self.send_world_event(
                        'xui_presence',
                        chat_port=int(self.chat_port or 0),
                        tick=int(self._presence_tick),
                    )
                except Exception:
                    pass
            # Public ntfy topics are rate-limited; avoid flooding presence on a
            # shared room (many clients share the same topic).
            time.sleep(60.0)

    def _peer_key(self, host, port):
        return f'{host}:{int(port)}'

    def _is_local_host(self, host):
        h = str(host or '').strip()
        if not h:
            return False
        return h.startswith('127.') or h in self.local_ips

    def _upsert_peer(self, name, host, port, source='LAN', node_id='', user_id=''):
        if not host or not port:
            return
        key = self._peer_key(host, port)
        now = time.time()
        data = {
            'name': name or host,
            'host': str(host),
            'port': int(port),
            'source': source,
            'node_id': str(node_id or ''),
            'user_id': str(user_id or '')[:40],
            'last_seen': now,
        }
        changed = False
        with self.lock:
            prev = self.peers.get(key)
            if prev is None:
                changed = True
            elif (
                prev.get('name') != data['name']
                or prev.get('node_id') != data['node_id']
                or prev.get('user_id') != data['user_id']
            ):
                changed = True
            self.peers[key] = data
        if changed:
            self.events.put(('peer_up', key, data))

    def _peer_gc_loop(self):
        while self.running:
            time.sleep(2.0)
            now = time.time()
            removed = []
            with self.lock:
                for key, peer in list(self.peers.items()):
                    if peer.get('source') == 'LAN' and (now - float(peer.get('last_seen', 0.0))) > 10.0:
                        self.peers.pop(key, None)
                        removed.append(key)
            for key in removed:
                self.events.put(('peer_down', key))

    def _discovery_targets(self):
        out = [('255.255.255.255', self.discovery_port)]
        seen = {out[0]}
        for brd in local_ipv4_broadcasts():
            target = (str(brd), self.discovery_port)
            if target not in seen:
                seen.add(target)
                out.append(target)
        return out

    def _announce_packet(self):
        return {
            'type': 'announce',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'name': self.nickname,
            'chat_port': int(self.chat_port or 0),
            'reply_port': int(self.discovery_port),
            'ts': time.time(),
        }

    def _probe_packet(self):
        return {
            'type': 'probe',
            'node_id': self.node_id,
            'user_id': self.user_id,
            'name': self.nickname,
            'chat_port': int(self.chat_port or 0),
            'reply_port': int(self.discovery_port),
            'ts': time.time(),
        }

    def _udp_discovery_sender(self):
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        targets = self._discovery_targets()
        ticks = 0
        self.events.put(('status', f'LAN autodiscovery active on UDP {self.discovery_port}'))
        while self.running:
            if ticks % 8 == 0:
                targets = self._discovery_targets()
            packets = [self._announce_packet()]
            if ticks % 2 == 0:
                packets.insert(0, self._probe_packet())
            for pkt in packets:
                raw = json.dumps(pkt).encode('utf-8', errors='ignore')
                for target in targets:
                    try:
                        sock.sendto(raw, target)
                    except Exception:
                        pass
            time.sleep(2.5)
            ticks += 1
        sock.close()

    def _udp_discovery_listener(self):
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            sock.bind(('', self.discovery_port))
        except OSError:
            self.events.put(('status', f'Cannot bind UDP discovery port {self.discovery_port}'))
            sock.close()
            return
        sock.settimeout(1.0)
        while self.running:
            try:
                raw, addr = sock.recvfrom(4096)
            except socket.timeout:
                continue
            except Exception:
                continue
            host = addr[0]
            if self._is_local_host(host):
                continue
            try:
                pkt = json.loads(raw.decode('utf-8', errors='ignore'))
            except Exception:
                continue
            if not isinstance(pkt, dict):
                continue
            remote_node = str(pkt.get('node_id') or '')
            remote_user_id = str(pkt.get('user_id') or '').strip()[:40]
            if remote_node == self.node_id:
                continue
            ptype = str(pkt.get('type') or '')
            try:
                port = int(pkt.get('chat_port') or 0)
            except Exception:
                port = 0
            name = str(pkt.get('name') or host)
            if ptype == 'probe':
                reply = self._announce_packet()
                try:
                    sock.sendto(json.dumps(reply).encode('utf-8', errors='ignore'), (host, self.discovery_port))
                except Exception:
                    pass
                if port > 0:
                    self._upsert_peer(name, host, port, 'LAN', remote_node, user_id=remote_user_id)
                continue
            if ptype != 'announce':
                continue
            if port <= 0:
                continue
            self._upsert_peer(name, host, port, 'LAN', remote_node, user_id=remote_user_id)
        sock.close()

    def _handle_tcp_connection(self, conn, host):
        try:
            conn.settimeout(3.0)
            data = bytearray()
            while len(data) <= 1_500_000 and b'\n' not in data:
                chunk = conn.recv(min(16384, 1_500_001 - len(data)))
                if not chunk:
                    break
                data.extend(chunk)
        except OSError:
            return
        if not data or len(data) > 1_500_000 or b'\n' not in data:
            return
        try:
            msg = json.loads(bytes(data).split(b'\n', 1)[0].decode('utf-8'))
        except (ValueError, UnicodeError):
            return
        if not isinstance(msg, dict):
            return
        mtype = str(msg.get('type') or '')
        if mtype not in ('chat', 'private_message', 'friend_request', 'friend_accept', 'voice_message'):
            return
        sender = str(msg.get('from') or host).strip()[:48] or host
        text = str(msg.get('text') or '').strip()
        note = str(msg.get('note') or '').strip()[:500]
        sender_node = str(msg.get('node_id') or '')[:64]
        sender_user_id = str(msg.get('user_id') or '').strip()[:40]
        message_id = str(msg.get('message_id') or '')[:80]
        mime = str(msg.get('mime') or 'audio/ogg')[:80]
        voice_blob = str(msg.get('audio') or '').strip()
        try:
            voice_dur = max(0.0, min(120.0, float(msg.get('duration') or 0.0)))
        except (TypeError, ValueError, OverflowError):
            voice_dur = 0.0
        try:
            reply_port = int(msg.get('reply_port') or 0)
        except (TypeError, ValueError, OverflowError):
            reply_port = 0
        reply_port = reply_port if 0 < reply_port <= 65535 else 0
        if mtype in ('chat', 'private_message') and (not text or len(text) > 4000):
            return
        if mtype == 'voice_message' and (not voice_blob or len(voice_blob) > 1_400_000 or voice_dur <= 0):
            return
        if reply_port > 0:
            self._upsert_peer(sender, host, reply_port, 'LAN', sender_node, user_id=sender_user_id)
        if mtype == 'friend_request':
            self.events.put(('friend_request', sender, host, reply_port, note, sender_user_id))
        elif mtype == 'friend_accept':
            self.events.put(('friend_accept', sender, host, reply_port, sender_user_id))
        elif mtype == 'voice_message':
            self.events.put(('voice_message', sender, host, reply_port, mime, voice_dur, voice_blob, sender_user_id, message_id))
        elif mtype == 'private_message':
            self.events.put(('private_message', sender, text, sender_user_id, host, reply_port, message_id))
        else:
            self.events.put(('chat', sender, text, sender_user_id, host, reply_port, message_id))
        try:
            ack = json.dumps({'ok': True, 'message_id': message_id}, separators=(',', ':')).encode('utf-8') + b'\n'
            conn.sendall(ack)
        except OSError:
            pass

    def _tcp_server_loop(self):
        if not self.chat_port:
            return
        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            srv.bind(('', self.chat_port))
            srv.listen(16)
        except OSError:
            self.events.put(('status', f'Cannot bind TCP chat port {self.chat_port}'))
            self.chat_port = 0
            srv.close()
            return
        srv.settimeout(1.0)
        while self.running:
            try:
                conn, addr = srv.accept()
            except socket.timeout:
                continue
            except Exception:
                continue
            host = addr[0]
            with conn:
                self._handle_tcp_connection(conn, host)
        srv.close()

    def _world_recv_loop(self):
        backoff = 1.2
        while self.running:
            if not self.world_enabled:
                time.sleep(0.4)
                continue
            room = self.world_topic
            url = self._world_url('/json', room)
            req = urllib.request.Request(
                url,
                headers={
                    'User-Agent': 'xui-dashboard-world-chat',
                    'Cache-Control': 'no-cache',
                    'Connection': 'keep-alive',
                },
            )
            response = None
            try:
                with urllib.request.urlopen(req, timeout=35) as resp:
                    response = resp
                    with self._world_response_lock:
                        self._world_response = resp
                    backoff = 1.2
                    self.events.put(('world_connection', 'connected', room))
                    while self.running and self.world_enabled:
                        if room != self.world_topic:
                            break
                        raw = resp.readline()
                        if not raw:
                            break
                        line = raw.decode('utf-8', errors='ignore').strip()
                        if not line:
                            continue
                        try:
                            evt = json.loads(line)
                        except Exception:
                            continue
                        if not isinstance(evt, dict):
                            continue
                        if str(evt.get('event') or '') != 'message':
                            continue
                        msg_id = str(evt.get('id') or '')
                        if msg_id:
                            if msg_id in self._seen_world_ids:
                                continue
                            self._seen_world_ids.add(msg_id)
                            if len(self._seen_world_ids) > 1200:
                                self._seen_world_ids = set(list(self._seen_world_ids)[-600:])
                        body = str(evt.get('message') or '').strip()
                        if not body or len(body) > 1_500_000:
                            continue
                        try:
                            payload = json.loads(body)
                        except Exception:
                            payload = {
                                'kind': 'xui_world_chat',
                                'node_id': '',
                                'from': str(evt.get('title') or 'WORLD'),
                                'text': body,
                                'room': self.world_topic,
                                'ts': evt.get('time', time.time()),
                            }
                        if not isinstance(payload, dict):
                            continue
                        kind = str(payload.get('kind') or 'xui_world_chat')
                        if str(payload.get('room') or self.world_topic) != self.world_topic:
                            continue
                        if str(payload.get('node_id') or '') == self.node_id:
                            continue
                        from_user_id = str(payload.get('user_id') or '').strip()
                        if from_user_id and from_user_id == self.user_id:
                            continue
                        who = str(payload.get('from') or 'WORLD')
                        txt = str(payload.get('text') or '').strip()

                        if kind == 'xui_world_chat':
                            if txt:
                                self.events.put(('world_chat', who, txt))
                            continue
                        if kind == 'xui_presence':
                            try:
                                chat_port = int(payload.get('chat_port') or 0)
                            except Exception:
                                chat_port = 0
                            self.events.put((
                                'world_presence',
                                {
                                    'name': who,
                                    'user_id': from_user_id,
                                    'node_id': str(payload.get('node_id') or ''),
                                    'chat_port': chat_port,
                                    'ts': float(payload.get('ts') or time.time()),
                                },
                            ))
                            continue
                        if kind == 'xui_world_pm':
                            to_user = str(payload.get('to_user_id') or '').strip()
                            if to_user and to_user == self.user_id and txt:
                                self.events.put(('world_private_message', who, from_user_id, txt))
                            continue
                        if kind == 'xui_friend_request':
                            to_user = str(payload.get('to_user_id') or '').strip()
                            if to_user and to_user == self.user_id:
                                note = str(payload.get('note') or '').strip()
                                self.events.put(('global_friend_request', who, from_user_id, note))
                            continue
                        if kind == 'xui_friend_accept':
                            to_user = str(payload.get('to_user_id') or '').strip()
                            if to_user and to_user == self.user_id:
                                self.events.put(('global_friend_accept', who, from_user_id))
                            continue
                        if kind == 'xui_party_invite':
                            to_user = str(payload.get('to_user_id') or '').strip()
                            if to_user and to_user == self.user_id:
                                self.events.put((
                                    'party_invite',
                                    {
                                        'from': who,
                                        'from_user_id': from_user_id,
                                        'party_id': str(payload.get('party_id') or '').strip(),
                                        'party_name': str(payload.get('party_name') or '').strip(),
                                        'ts': int(time.time()),
                                    },
                                ))
                            continue
                        if kind == 'xui_party_state':
                            self.events.put((
                                'party_state',
                                {
                                    'from': who,
                                    'from_user_id': from_user_id,
                                    'party_id': str(payload.get('party_id') or '').strip(),
                                    'state': str(payload.get('state') or '').strip(),
                                    'ts': int(time.time()),
                                },
                            ))
                            continue
                        if kind == 'xui_voice_msg':
                            to_user = str(payload.get('to_user_id') or '').strip()
                            party_id = str(payload.get('party_id') or '').strip()
                            if (to_user and to_user == self.user_id) or party_id:
                                mime = str(payload.get('mime') or 'audio/ogg')
                                audio = str(payload.get('audio') or '').strip()
                                try:
                                    duration = float(payload.get('duration') or 0.0)
                                except Exception:
                                    duration = 0.0
                                if audio:
                                    self.events.put(('world_voice_message', who, from_user_id, party_id, mime, duration, audio))
                            continue
                with self._world_response_lock:
                    if self._world_response is resp:
                        self._world_response = None
            except Exception as exc:
                with self._world_response_lock:
                    if self._world_response is response:
                        self._world_response = None
                if room == self.world_topic and self.world_enabled:
                    self.events.put(('world_connection', 'reconnecting', room, str(exc)[:180]))
                    time.sleep(min(8.0, backoff))
                    backoff = min(8.0, backoff * 1.5)


def _fit_dialog_to_screen(dialog, parent=None, width_ratio=0.92, height_ratio=0.88, min_width=640, min_height=420):
    screen = None
    try:
        screen = parent.screen() if parent is not None else None
    except Exception:
        screen = None
    if screen is None:
        screen = QtWidgets.QApplication.primaryScreen()
    if screen is None:
        return
    bounds = screen.availableGeometry()
    max_width = max(1, bounds.width() - 32)
    max_height = max(1, bounds.height() - 48)
    min_width = min(max_width, max(1, int(min_width)))
    min_height = min(max_height, max(1, int(min_height)))
    width = min(max_width, max(min_width, int(bounds.width() * width_ratio)))
    height = min(max_height, max(min_height, int(bounds.height() * height_ratio)))
    try:
        layout = dialog.layout()
        if layout is not None:
            layout.setSizeConstraint(QtWidgets.QLayout.SetNoConstraint)
        dialog.setMinimumSize(min_width, min_height)
        dialog.resize(width, height)
        dialog.move(
            bounds.x() + (bounds.width() - width) // 2,
            bounds.y() + (bounds.height() - height) // 2,
        )
    except Exception:
        pass


class SocialOverlay(QtWidgets.QDialog):
    def __init__(self, parent=None, notification_cb=None, engine=None):
        super().__init__(parent)
        self._notification_cb = notification_cb
        self.nickname = current_gamertag()
        self.social_profile = self._load_social_profile()
        self.user_id = str(self.social_profile.get('user_id') or uuid.uuid4().hex[:16])
        self.engine = engine or InlineSocialEngine(self.nickname, self.user_id)
        self._owns_engine = engine is None
        self.peer_items = {}
        self.peer_data = {}
        self.friend_row_widgets = []
        self.global_players = {}
        self.friends = []
        self.friend_requests = []
        self.voice_inbox = []
        self.last_party_invite = None
        self.party_state = {
            'party_id': '',
            'party_name': '',
            'members': {},
        }
        self._community_mode = 'messages'
        self._focus_zone = 0
        self._friend_action_index = 0
        self._active_conversation_key = ''
        self._pending_sends = set()
        self.setModal(True)
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint | QtCore.Qt.WindowStaysOnTopHint)
        self.setAttribute(QtCore.Qt.WA_TranslucentBackground, True)
        screen = parent.screen() if parent is not None else QtWidgets.QApplication.primaryScreen()
        if screen is None:
            screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            self.setGeometry(screen.geometry())
        else:
            self.resize(1200, 760)
        self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
        self._build()
        self.setWindowTitle('Community / Messages')
        self._load_friends()
        self._load_friend_requests()
        self._load_voice_inbox()
        self._load_party_state()
        self._load_manual_peers()
        self._load_world_settings()
        if self._owns_engine:
            self.engine.start()
        if str(self.party_state.get('party_id') or '').strip():
            threading.Thread(
                target=self.engine.send_world_party_state,
                args=(str(self.party_state.get('party_id')),),
                kwargs={'state': 'join'},
                name='xui-party-presence',
                daemon=True,
            ).start()
        self._refresh_world_peer()
        self.timer = None
        if self._owns_engine:
            self.timer = QtCore.QTimer(self)
            self.timer.timeout.connect(self._poll_events)
            self.timer.start(120)
        self._append_system('LAN autodiscovery enabled (broadcast + probe).')
        self._append_system('Security: LAN P2P is not encrypted or authenticated; use it only on trusted networks.')
        self._append_system('World room messages use a shared public relay; they are not private or end-to-end encrypted.')
        self._append_system(f"World chat ready via relay ({self.engine.world_relay}) room: {self.engine.world_topic}")
        self._append_system(f'Global social ID: {self.user_id}')

    def _build(self):
        self._vk_opening = False
        self._vk_last_close = 0.0
        self._action_items = {}
        self.setStyleSheet('''
            QDialog { background:rgba(5,8,12,0.48); }
            QFrame#social_panel {
                background:#cbd1d4;
                border:1px solid #f0f3f4;
                border-radius:0px;
            }
            QFrame#social_header {
                background:#171b20;
                border:none;
            }
            QFrame#social_col {
                background:#dfe5e6;
                border:1px solid #9ca7aa;
            }
            QLabel#social_title { color:#f4f7f8; font-size:26px; font-weight:800; }
            QLabel#social_hint { color:#596469; font-size:14px; font-weight:650; }
