    def _add_action_item(self, key, text):
        it = QtWidgets.QListWidgetItem(str(text))
        it.setData(QtCore.Qt.UserRole, str(key))
        self.actions.addItem(it)
        self._action_items[str(key)] = it

    def _community_order(self):
        return ['friends', 'party', 'messages', 'players', 'global']

    def _recent_players(self):
        arr = safe_json_read(SOCIAL_MESSAGES_FILE, [])
        if not isinstance(arr, list):
            arr = []
        out = []
        seen = set()
        for row in arr:
            if not isinstance(row, dict):
                continue
            who = str(row.get('from') or '').strip()
            if not who:
                continue
            low = who.lower()
            if low.startswith('you') or '[world]' in low:
                continue
            clean = who.replace('[PM]', '').replace('[pm]', '').strip()
            if not clean:
                continue
            if clean.lower() in seen:
                continue
            seen.add(clean.lower())
            out.append({
                'name': clean,
                'host': '',
                'port': 0,
                'source': 'RECENT',
                'last': str(row.get('text') or '').strip()[:72],
            })
            if len(out) >= 48:
                break
        return out

    def _refresh_community_tabs(self):
        friends_n = len(self.friends)
        party_rows = self._party_member_rows()
        party_n = len(party_rows) if party_rows else len([f for f in self.friends if bool(f.get('online'))])
        messages_n = len([p for p in self.peer_data.values() if str(p.get('source')) != 'WORLD'])
        players_n = len(self.global_players) if self.global_players else len(self._recent_players())
        counts = {
            'friends': friends_n,
            'party': party_n,
            'messages': messages_n,
            'players': players_n,
            'global': len(self.global_players),
        }
        labels = {
            'friends': 'Friends',
            'party': 'Party',
            'messages': 'Messages',
            'players': 'Players',
            'global': 'Global Chat',
        }
        for key, btn in self.community_tabs.items():
            active = (key == self._community_mode)
            btn.setChecked(active)
            btn.setText(f'{labels.get(key, key)} ({counts.get(key, 0)})')
            if active:
                btn.setStyleSheet(
                    'QPushButton { background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #67c84a, stop:1 #3d9533);'
                    ' color:#f4fff2; border:1px solid rgba(255,255,255,0.34); font-size:16px; font-weight:800; }'
                )
            else:
                btn.setStyleSheet(
                    'QPushButton { background:rgba(49,58,71,0.95); color:#e8f0f6; border:1px solid rgba(202,216,232,0.24);'
                    ' font-size:16px; font-weight:700; }'
                )

    def _set_community_mode(self, mode):
        mode = str(mode or 'messages').strip().lower()
        if mode not in self._community_order():
            mode = 'messages'
        self._community_mode = mode
        friends_view = mode == 'friends'
        self.friend_actions.setVisible(friends_view)
        self.center_wrap.setVisible(not friends_view)
        self.right_wrap.setVisible(not friends_view)
        self.community_body.setStretch(self.community_body.indexOf(self.left_wrap), 1 if friends_view else 3)
        if not friends_view:
            self.community_body.setStretch(self.community_body.indexOf(self.center_wrap), 2)
            self.community_body.setStretch(self.community_body.indexOf(self.right_wrap), 5)
        title_map = {
            'friends': 'Community  /  Friends',
            'party': 'Community  /  Party',
            'messages': 'Community  /  Messages',
            'players': 'Community  /  Players',
            'global': 'Community  /  Global Chat',
        }
        if hasattr(self, 'title_lbl'):
            self.title_lbl.setText(title_map.get(mode, 'community / messages'))
        if mode in ('messages', 'global'):
            if mode == 'global' and not self.engine.world_enabled:
                self.engine.set_world_enabled(True)
                self._refresh_world_peer()
                self._save_world_settings()
            self.left_lbl.setText('Messages / Peers')
            self._rebuild_message_peers()
            if mode == 'global':
                self.left_lbl.setText('Global Room')
                for row in range(self.peers.count()):
                    item = self.peers.item(row)
                    peer = self.peer_data.get(item.data(QtCore.Qt.UserRole)) if item else None
                    if isinstance(peer, dict) and str(peer.get('source') or '').upper() == 'WORLD':
                        self.peers.setCurrentRow(row)
                        break
        elif mode == 'friends':
            self.left_lbl.setText('Friends')
            self._rebuild_community_rows(self._community_friends_rows())
        elif mode == 'party':
            self.left_lbl.setText('Party')
            self._rebuild_community_rows(self._community_party_rows())
        else:
            self.left_lbl.setText('Players')
            self._rebuild_community_rows(self._community_players_rows())
        self._refresh_community_tabs()
        self._set_focus_zone(0)
        self._update_peer_meta()

    def _cycle_community_mode(self, step=1):
        order = self._community_order()
        cur = order.index(self._community_mode) if self._community_mode in order else 0
        nxt = (cur + int(step)) % len(order)
        self._set_community_mode(order[nxt])

    def _community_friends_rows(self):
        rows = []
        for f in sorted(
            self.friends,
            key=lambda x: (0 if bool(x.get('online')) else 1, str(x.get('name') or '').lower()),
        ):
            rows.append({
                'name': str(f.get('name') or 'Friend'),
                'user_id': str(f.get('user_id') or ''),
                'host': str(f.get('host') or ''),
                'port': int(f.get('port') or 0),
                'source': 'FRIEND',
                'online': bool(f.get('online')),
                'last_seen': int(f.get('last_seen') or 0),
            })
        return rows

    def _community_party_rows(self):
        rows = self._party_member_rows()
        if rows:
            return rows
        fallback = []
        for f in self._community_friends_rows():
            if bool(f.get('online')):
                fallback.append(dict(f))
        if not fallback:
            fallback = self._community_friends_rows()[:12]
        return fallback

    def _community_players_rows(self):
        rows = []
        for uid, p in sorted(self.global_players.items(), key=lambda kv: str(kv[1].get('name') or '').lower()):
            if not str(uid or '').strip():
                continue
            rows.append({
                'name': str(p.get('name') or 'Player'),
                'user_id': str(uid),
                'host': '',
                'port': 0,
                'source': 'GLOBAL',
                'online': bool(p.get('online', True)),
                'last_seen': int(p.get('last_seen') or int(time.time())),
                'last': str(p.get('status') or 'online'),
            })
        if rows:
            return rows
        return self._recent_players()

    def _community_row_text(self, row):
        name = str(row.get('name') or 'Player')
        src = str(row.get('source') or '')
        if src in ('FRIEND', 'PARTY', 'GLOBAL'):
            status = 'Online' if bool(row.get('online')) else 'Offline'
            host = str(row.get('host') or '')
            port = int(row.get('port') or 0)
            endpoint = f' [{host}:{port}]' if host and port > 0 else ''
            tag = 'GLOBAL' if src == 'GLOBAL' else src
            return f'{name}  -  {status}{endpoint} ({tag})'
        if src == 'RECENT':
            last = str(row.get('last') or '').strip()
            return f'{name}  -  {last}' if last else name
        host = str(row.get('host') or '')
        port = int(row.get('port') or 0)
        if host and port > 0:
            return f'{name}  [{host}:{port}]'
        return name

    def _rebuild_community_rows(self, rows):
        prev = self.peers.currentItem().text() if self.peers.currentItem() is not None else ''
        # currentItemChanged fires during clear(); discard references to old item widgets first.
        self.friend_row_widgets = []
        self.peers.clear()
        self.peer_items = {}
        keep_row = -1
        for row in rows:
            it = QtWidgets.QListWidgetItem(self._community_row_text(row))
            it.setData(QtCore.Qt.UserRole, dict(row))
            self.peers.addItem(it)
            if str(row.get('source') or '').upper() == 'FRIEND':
                it.setSizeHint(QtCore.QSize(max(280, self.peers.viewport().width() - 4), 62))
                card = QtWidgets.QFrame()
                card.setObjectName('friend_row')
                line = QtWidgets.QHBoxLayout(card)
                line.setContentsMargins(10, 5, 14, 5)
                line.setSpacing(12)
                avatar = QtWidgets.QLabel(str(row.get('name') or 'F')[:1].upper())
                avatar.setAlignment(QtCore.Qt.AlignCenter)
                avatar.setFixedSize(42, 42)
                avatar.setStyleSheet('background:#aeb9c1; color:#ffffff; border-radius:21px; font-size:18px; font-weight:800;')
                identity = QtWidgets.QVBoxLayout()
                identity.setSpacing(1)
                name = QtWidgets.QLabel(str(row.get('name') or 'Friend'))
                name.setObjectName('friend_row_name')
                status = QtWidgets.QLabel(str(row.get('last') or ('Online' if row.get('online') else 'Offline')))
                status.setObjectName('friend_row_status')
                identity.addWidget(name)
                identity.addWidget(status)
                line.addWidget(avatar)
                line.addLayout(identity, 1)
                status_badge = QtWidgets.QLabel('● Online' if row.get('online') else '○ Offline')
                status_badge.setObjectName('friend_row_badge')
                line.addWidget(status_badge)
                self.peers.setItemWidget(it, card)
                self.friend_row_widgets.append((it, card, avatar, name, status, status_badge))
            if keep_row < 0 and prev and it.text() == prev:
                keep_row = self.peers.count() - 1
        if self.peers.count() > 0:
            if keep_row >= 0:
                self.peers.setCurrentRow(keep_row)
            else:
                self.peers.setCurrentRow(0)
        self._update_friend_row_selection()

    def _update_friend_row_selection(self):
        current = self.peers.currentItem()
        for item, card, avatar, name, status, badge in self.friend_row_widgets:
            try:
                selected = item is current
                bg = '#58b83c' if selected else '#f1f3f5'
                fg = '#ffffff' if selected else '#252b31'
                secondary = '#ecf5e9' if selected else '#66717a'
                card.setStyleSheet(f'QFrame#friend_row {{ background:{bg}; border-bottom:1px solid #cbd0d5; }}')
                avatar.setStyleSheet(
                    f'background:{"#3e912d" if selected else "#aeb9c1"}; color:#ffffff; '
                    'border-radius:21px; font-size:18px; font-weight:800;'
                )
                name.setStyleSheet(f'color:{fg}; font-size:17px; font-weight:750;')
                status.setStyleSheet(f'color:{secondary}; font-size:12px; font-weight:600;')
                badge.setStyleSheet(f'color:{fg}; font-size:13px; font-weight:700;')
            except RuntimeError:
                continue

    def _rebuild_message_peers(self):
        # This view uses plain list items; never let selection updates retain deleted friend cards.
        self.friend_row_widgets = []
        self.peers.clear()
        self.peer_items = {}
        ordered = sorted(
            self.peer_data.items(),
            key=lambda kv: (
                0 if str(kv[1].get('source')) == 'WORLD'
                else (1 if str(kv[1].get('source')) == 'GLOBAL' else 2),
                str(kv[1].get('name') or '').lower(),
            ),
        )
        for key, row in ordered:
            it = QtWidgets.QListWidgetItem(self._peer_row(row))
            it.setData(QtCore.Qt.UserRole, key)
            self.peers.addItem(it)
            self.peer_items[key] = it
        if self.peers.count() > 0:
            self.peers.setCurrentRow(0)

    def _set_focus_zone(self, zone):
        max_zone = 1 if self._community_mode == 'friends' else 3
        self._focus_zone = max(0, min(max_zone, int(zone)))
        if self._focus_zone == 0:
            self.peers.setFocus(QtCore.Qt.OtherFocusReason)
        elif self._community_mode == 'friends':
            if self._focus_zone == 1 and self.friend_action_buttons:
                self._friend_action_index = max(0, min(len(self.friend_action_buttons) - 1, self._friend_action_index))
                self.friend_action_buttons[self._friend_action_index].setFocus(QtCore.Qt.OtherFocusReason)
        elif self._focus_zone == 1:
            self.actions.setFocus(QtCore.Qt.OtherFocusReason)
        elif self._focus_zone == 2:
            self.input.setFocus(QtCore.Qt.OtherFocusReason)
        else:
            self.btn_send.setFocus(QtCore.Qt.OtherFocusReason)

    def _show_notice(self, title, text):
        d = InfoNoticeDialog(str(title or 'Notice'), str(text or ''), self)
        d.exec_()

    def _pick_from_menu(self, title, options, descriptions=None):
        opts = [str(x).strip() for x in (options or []) if str(x).strip()]
        if not opts:
            return None
        desc = descriptions or {}
        detail_lines = []
        for k in opts[:8]:
            v = str(desc.get(k, '')).strip()
            if v:
                detail_lines.append(f'{k}: {v}')
        body = '\n'.join(detail_lines) if detail_lines else 'Select an option.'
        d = GuidePromptDialog(
            str(title or 'Menu'),
            body,
            opts,
            self,
            default_choice=opts[0],
            cancel_choice='Cancel' if 'Cancel' in opts else ('Back' if 'Back' in opts else opts[-1]),
        )
        if d.exec_() == QtWidgets.QDialog.Accepted:
            return d.selected_choice()
        return None

    def _move_in_list(self, listw, delta):
        n = int(listw.count())
        if n <= 0:
            return
        row = int(listw.currentRow())
        if row < 0:
            row = 0
        row = max(0, min(n - 1, row + int(delta)))
        listw.setCurrentRow(row)

    def _select_message_peer(self, host='', port=0, name=''):
        host = str(host or '').strip().lower()
        try:
            port = int(port or 0)
        except Exception:
            port = 0
        name = str(name or '').strip().lower()
        for i in range(self.peers.count()):
            it = self.peers.item(i)
            if it is None:
                continue
            key = it.data(QtCore.Qt.UserRole)
            peer = self.peer_data.get(key)
            if not isinstance(peer, dict):
                continue
            ph = str(peer.get('host') or '').strip().lower()
            pp = int(peer.get('port') or 0)
            pn = str(peer.get('name') or '').strip().lower()
            if host and port > 0 and ph == host and pp == port:
                self.peers.setCurrentRow(i)
                return True
            if name and pn == name:
                self.peers.setCurrentRow(i)
                return True
        return False

    def _run_selected_action(self, *_):
        it = self.actions.currentItem()
        if it is None:
            return
        key = str(it.data(QtCore.Qt.UserRole) or '').strip()
        if key == 'reply':
            self.input.setFocus(QtCore.Qt.OtherFocusReason)
            self._open_chat_keyboard()
            return
        if key == 'friend_request':
            self._send_friend_request()
            return
        if key == 'friend_requests':
            self._open_friend_requests()
            return
        if key == 'friends':
            self._show_friends()
            return
        if key == 'party_hub':
            self._open_party_hub()
            return
        if key == 'voice_hub':
            self._open_voice_hub()
            return
        if key == 'players_hub':
            self._set_community_mode('players')
            return
        if key == 'add_peer':
            self._add_peer()
            return
        if key == 'peer_ids':
            self._show_peer_ids()
            return
        if key == 'lan_status':
            self._show_lan_status()
            return
        if key == 'world_toggle':
            self._toggle_world_chat()
            return
        if key == 'world_room':
            self._change_world_room()
            return

    def _update_peer_meta(self):
        peer = self._selected_peer()
        if not peer:
            self.peer_meta.setText('Select a peer to chat.')
            self._show_conversation_for(None)
            return
        self._show_conversation_for(peer)
        src = str(peer.get('source') or '').upper()
        if src in ('FRIEND', 'PARTY', 'RECENT', 'GLOBAL'):
            name = str(peer.get('name') or 'Player')
            online = bool(peer.get('online', False))
            host = str(peer.get('host') or '')
            port = int(peer.get('port') or 0)
            endpoint = f' [{host}:{port}]' if host and port > 0 else ''
            if src == 'RECENT':
                last = str(peer.get('last') or '').strip()
                self.peer_meta.setText(f'{name}{endpoint}  (RECENT){(" - " + last) if last else ""}')
            elif src == 'GLOBAL':
                uid = str(peer.get('user_id') or '').strip()
                self.peer_meta.setText(f'{name}  (GLOBAL relay; not private)  {"Online" if online else "Offline"}  id:{uid or "-"}')
            else:
                self.peer_meta.setText(f'{name}{endpoint}  ({src}; LAN is unencrypted)  {"Online" if online else "Offline"}')
            return
        if str(peer.get('source')) == 'WORLD':
            self.peer_meta.setText(f"WORLD relay room #{self.engine.world_topic}")
            return
        name = str(peer.get('name') or 'Peer')
        host = str(peer.get('host') or '-')
        port = int(peer.get('port') or 0)
        src = str(peer.get('source') or 'LAN')
        self.peer_meta.setText(f'{name}  [{host}:{port}]  ({src})')

    def _open_chat_keyboard(self):
        if self._vk_opening:
            return
        if (time.monotonic() - float(self._vk_last_close)) < 0.35:
            return
        self._vk_opening = True
        try:
            d = VirtualKeyboardDialog(self.input.text(), self)
            if d.exec_() == QtWidgets.QDialog.Accepted:
                self.input.setText(d.text())
        finally:
            self._vk_last_close = time.monotonic()
            self._vk_opening = False
            self.input.setFocus(QtCore.Qt.OtherFocusReason)

    def eventFilter(self, obj, event):
        if obj is self.input:
            et = event.type()
            if et in (QtCore.QEvent.FocusIn, QtCore.QEvent.MouseButtonPress):
                if not self._vk_opening and (time.monotonic() - float(self._vk_last_close)) >= 0.35:
                    QtCore.QTimer.singleShot(0, self._open_chat_keyboard)
        return super().eventFilter(obj, event)

    def showEvent(self, e):
        super().showEvent(e)
        screen = self.screen() or QtWidgets.QApplication.primaryScreen()
        if screen is not None and self.geometry() != screen.geometry():
            self.setGeometry(screen.geometry())
        self._apply_responsive_style()
        QtCore.QTimer.singleShot(0, lambda: self._set_focus_zone(self._focus_zone))

    def _apply_responsive_style(self):
        base_style = getattr(self, '_social_base_style', '')
        if not base_style:
            return
        scale = max(0.72, min(1.0, float(self.width()) / 1280.0))
        px = lambda value, floor: max(floor, int(round(value * scale)))
        self.setStyleSheet(base_style + f'''
            QLabel#social_title {{ font-size:{px(36, 24)}px; }}
            QLabel#social_hint {{ font-size:{px(15, 11)}px; }}
            QLabel#social_col_title {{ font-size:{px(18, 13)}px; }}
            QListWidget {{ font-size:{px(18, 12)}px; }}
            QPlainTextEdit {{ font-size:{px(14, 11)}px; }}
            QLineEdit {{ font-size:{px(17, 12)}px; padding:{px(7, 4)}px; }}
            QPushButton {{ font-size:{px(15, 11)}px; padding:{px(7, 4)}px {px(9, 6)}px; }}
        ''')

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._apply_responsive_style()

    def keyPressEvent(self, e):
        k = e.key()
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.reject()
            return
        if k in (QtCore.Qt.Key_PageUp,):
            self._cycle_community_mode(-1)
            return
        if k in (QtCore.Qt.Key_PageDown,):
            self._cycle_community_mode(1)
            return
        if k in (QtCore.Qt.Key_Y, QtCore.Qt.Key_Space):
            self._cycle_community_mode(1)
            return
        if k in (QtCore.Qt.Key_Left,):
            if self._community_mode == 'friends' and self._focus_zone == 1:
                self._friend_action_index = (self._friend_action_index - 1) % len(self.friend_action_buttons)
                self.friend_action_buttons[self._friend_action_index].setFocus(QtCore.Qt.OtherFocusReason)
            elif self._focus_zone == 0:
                self._cycle_community_mode(-1)
            else:
                self._set_focus_zone(self._focus_zone - 1)
            return
        if k in (QtCore.Qt.Key_Right,):
            if self._community_mode == 'friends' and self._focus_zone == 1:
                self._friend_action_index = (self._friend_action_index + 1) % len(self.friend_action_buttons)
                self.friend_action_buttons[self._friend_action_index].setFocus(QtCore.Qt.OtherFocusReason)
            elif self._focus_zone == 0:
                self._cycle_community_mode(1)
            else:
                self._set_focus_zone(self._focus_zone + 1)
            return
        if k in (QtCore.Qt.Key_Up,):
            if self._focus_zone == 0:
                self._move_in_list(self.peers, -1)
            elif self._focus_zone == 1:
                self._move_in_list(self.actions, -1)
            return
        if k in (QtCore.Qt.Key_Down,):
            if self._focus_zone == 0:
                self._move_in_list(self.peers, 1)
            elif self._focus_zone == 1:
                self._move_in_list(self.actions, 1)
            return
        if k in (QtCore.Qt.Key_Tab,):
            zone_count = 2 if self._community_mode == 'friends' else 4
            self._set_focus_zone((self._focus_zone + 1) % zone_count)
            return
        if k in (QtCore.Qt.Key_X,):
            if self._community_mode == 'friends' and self._focus_zone == 1:
                self.friend_action_buttons[self._friend_action_index].click()
            elif self._focus_zone == 0 and self._community_mode in ('friends', 'party', 'players'):
                self._send_friend_request()
            else:
                self._send_current()
            return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            if self._community_mode == 'friends' and self._focus_zone == 1:
                focused = QtWidgets.QApplication.focusWidget()
                if focused in self.friend_action_buttons:
                    self._friend_action_index = self.friend_action_buttons.index(focused)
                    focused.click()
                else:
                    self.friend_action_buttons[self._friend_action_index].click()
                return
            if self._focus_zone == 0:
                if self._community_mode == 'messages':
                    self._open_chat_keyboard()
                else:
                    chosen = self._selected_peer() or {}
                    self._set_community_mode('messages')
                    self._select_message_peer(
                        host=chosen.get('host'),
                        port=chosen.get('port'),
                        name=chosen.get('name'),
                    )
                    self._open_chat_keyboard()
            elif self._focus_zone == 1:
                self._run_selected_action()
            elif self._focus_zone == 2:
                self._open_chat_keyboard()
            else:
                self._send_current()
            return
        super().keyPressEvent(e)

    def _append_line(self, text):
        self.chat.appendPlainText(text)
        sb = self.chat.verticalScrollBar()
        sb.setValue(sb.maximum())

    def _append_system(self, text):
        self._append_line(f"[{time.strftime('%H:%M:%S')}] [SYSTEM] {text}")

    def _append_chat(self, who, text, peer=None, message_id=''):
        self._notify_incoming_message()
        if isinstance(peer, dict):
            self._save_conversation_message(peer, 'in', text, 'delivered', message_id)
            if self._conversation_key(peer) != self._active_conversation_key:
                self._push_recent_message(who, text)
                return
        else:
            self._append_line(f"[{time.strftime('%H:%M:%S')}] {who}: {text}")
        self._push_recent_message(who, text)

    def _notify_incoming_message(self):
        if callable(self._notification_cb):
            try:
                self._notification_cb()
            except Exception:
                pass

    def _conversation_key(self, peer=None, user_id='', host='', port=0):
        peer = peer if isinstance(peer, dict) else {}
        uid = str(user_id or peer.get('user_id') or '').strip()
        if uid:
            return f'user:{uid[:80]}'
        source = str(peer.get('source') or '').upper()
        if source == 'WORLD':
            return f'world:{self.engine.world_topic}'
        host = str(host or peer.get('host') or '').strip()
        try:
            port = int(port or peer.get('port') or 0)
        except (TypeError, ValueError, OverflowError):
            port = 0
        if host:
            return f'endpoint:{host[:120]}:{port}'
        return ''

    def _save_conversation_message(self, peer, direction, text, status='delivered', message_id='', user_id='', host='', port=0, ts=None):
        key = self._conversation_key(peer, user_id=user_id, host=host, port=port)
        body = str(text or '').strip()
        if not key or not body:
            return
        data = safe_json_read(SOCIAL_CONVERSATIONS_FILE, {'conversations': {}})
        if not isinstance(data, dict):
            data = {'conversations': {}}
        conversations = data.get('conversations')
        if not isinstance(conversations, dict):
            conversations = {}
        rows = conversations.get(key)
        if not isinstance(rows, list):
            rows = []
        record_id = str(message_id or uuid.uuid4().hex)[:80]
        record = {
            'id': record_id,
            'ts': int(ts or time.time()),
            'direction': 'out' if direction == 'out' else 'in',
            'status': str(status or 'delivered')[:32],
            'text': body[:4000],
        }
        existing_idx = next((i for i, row in enumerate(rows) if isinstance(row, dict) and str(row.get('id') or '') == record_id), -1)
        if existing_idx >= 0:
            rows[existing_idx].update(record)
        else:
            rows.append(record)
        conversations[key] = rows[-100:]
        if len(conversations) > 40:
            oldest = sorted(conversations, key=lambda item: max((int(row.get('ts') or 0) for row in conversations[item] if isinstance(row, dict)), default=0))
            for old_key in oldest[:-40]:
                conversations.pop(old_key, None)
        data['conversations'] = conversations
        safe_json_write(SOCIAL_CONVERSATIONS_FILE, data)
        if key == self._active_conversation_key:
            self._render_conversation()

    def _show_conversation_for(self, peer):
        key = self._conversation_key(peer)
        if key == self._active_conversation_key:
            return
        self._active_conversation_key = key
        self._render_conversation()

    def _render_conversation(self):
        self.chat.clear()
        if not self._active_conversation_key:
            return
        data = safe_json_read(SOCIAL_CONVERSATIONS_FILE, {'conversations': {}})
        conversations = data.get('conversations', {}) if isinstance(data, dict) else {}
        rows = conversations.get(self._active_conversation_key, []) if isinstance(conversations, dict) else []
        if not isinstance(rows, list):
            return
        for row in rows[-100:]:
            if not isinstance(row, dict):
                continue
            try:
                stamp = time.strftime('%H:%M:%S', time.localtime(int(row.get('ts') or 0)))
            except (TypeError, ValueError, OverflowError, OSError):
                stamp = '--:--:--'
            direction = 'You' if row.get('direction') == 'out' else 'Peer'
            state = str(row.get('status') or 'delivered')
            self.chat.appendPlainText(f'[{stamp}] {direction} [{state}]: {str(row.get("text") or "")}')
        scrollbar = self.chat.verticalScrollBar()
        scrollbar.setValue(scrollbar.maximum())

    def _push_recent_message(self, who, text):
        who_txt = str(who or '').strip() or 'Unknown'
        body = str(text or '').strip()
        if not body:
            return
        arr = safe_json_read(SOCIAL_MESSAGES_FILE, [])
        if not isinstance(arr, list):
            arr = []
        arr.insert(0, {'ts': int(time.time()), 'from': who_txt[:48], 'text': body[:320]})
        safe_json_write(SOCIAL_MESSAGES_FILE, arr[:80])

    def _load_social_profile(self):
        data = safe_json_read(SOCIAL_PROFILE_FILE, {})
        if not isinstance(data, dict):
            data = {}
        uid = ''.join(ch for ch in str(data.get('user_id') or '').strip() if ch.isalnum() or ch in ('-', '_'))
        if not uid:
            uid = uuid.uuid4().hex[:16]
        data['user_id'] = uid[:40]
        data['gamertag'] = str(self.nickname or 'Player1').strip() or 'Player1'
        safe_json_write(SOCIAL_PROFILE_FILE, data)
        return data

    def _load_party_state(self):
        raw = safe_json_read(PARTY_STATE_FILE, {})
        if not isinstance(raw, dict):
            raw = {}
        pid = str(raw.get('party_id') or '').strip()
        pname = str(raw.get('party_name') or '').strip()
        members = raw.get('members') if isinstance(raw.get('members'), dict) else {}
        norm = {}
        for uid, row in members.items():
            k = str(uid or '').strip()
            if not k:
                continue
            if isinstance(row, dict):
                norm[k] = {
                    'name': str(row.get('name') or 'Player'),
                    'online': bool(row.get('online', False)),
                    'last_seen': int(row.get('last_seen') or int(time.time())),
                }
        if self.user_id not in norm:
            norm[self.user_id] = {
                'name': self.nickname,
                'online': True,
                'last_seen': int(time.time()),
            }
        self.party_state = {
            'party_id': pid,
            'party_name': pname or (f'{self.nickname} Party' if pid else ''),
            'members': norm,
        }

    def _save_party_state(self):
        safe_json_write(PARTY_STATE_FILE, self.party_state)

    def _load_voice_inbox(self):
        arr = safe_json_read(VOICE_INBOX_FILE, [])
        if not isinstance(arr, list):
            arr = []
        out = []
        for raw in arr:
            if not isinstance(raw, dict):
                continue
            path = str(raw.get('path') or '').strip()
            if path and not Path(path).exists():
                continue
            out.append({
                'sender': str(raw.get('sender') or 'Unknown'),
                'sender_user_id': str(raw.get('sender_user_id') or ''),
                'mime': str(raw.get('mime') or 'audio/ogg'),
                'duration': float(raw.get('duration') or 0.0),
                'path': path,
                'ts': int(raw.get('ts') or int(time.time())),
                'party_id': str(raw.get('party_id') or ''),
            })
        self.voice_inbox = out[:120]

    def _save_voice_inbox(self):
        safe_json_write(VOICE_INBOX_FILE, self.voice_inbox[:120])

    def _voice_file_suffix(self, mime):
        m = str(mime or '').lower()
        if 'wav' in m:
            return '.wav'
        if 'ogg' in m or 'opus' in m:
            return '.ogg'
        return '.bin'

    def _save_voice_blob(self, sender, sender_user_id, mime, duration, blob_bytes, party_id=''):
        try:
            data = bytes(blob_bytes or b'')
        except Exception:
            data = b''
        if not data:
            return None
        safe_sender = ''.join(ch if ch.isalnum() or ch in ('-', '_') else '_' for ch in str(sender or 'peer'))[:28]
        p = VOICE_DIR / f'voice_{int(time.time())}_{safe_sender}{self._voice_file_suffix(mime)}'
        try:
            p.write_bytes(data)
        except Exception:
            return None
        item = {
            'sender': str(sender or 'Unknown'),
            'sender_user_id': str(sender_user_id or ''),
            'mime': str(mime or 'audio/ogg'),
            'duration': float(duration or 0.0),
            'path': str(p),
            'ts': int(time.time()),
            'party_id': str(party_id or ''),
        }
        self.voice_inbox.insert(0, item)
        self.voice_inbox = self.voice_inbox[:120]
        self._save_voice_inbox()
        return item

    def _play_voice_file(self, path):
        p = str(path or '').strip()
        if not p or not Path(p).exists():
            self.status.setText('Voice file not found.')
            return
        if shutil.which('mpv'):
            subprocess.Popen(['mpv', '--really-quiet', '--no-terminal', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return
        if shutil.which('ffplay'):
            subprocess.Popen(['ffplay', '-nodisp', '-autoexit', '-loglevel', 'quiet', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return
        if shutil.which('aplay'):
            subprocess.Popen(['aplay', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return
        self.status.setText('No audio player found (mpv/ffplay/aplay).')

    def _record_voice_clip(self, duration_sec):
        secs = max(1, min(int(duration_sec), 6))
        tmp_ogg = Path(tempfile.mktemp(prefix='xui_voice_', suffix='.ogg'))
        tmp_wav = Path(tempfile.mktemp(prefix='xui_voice_', suffix='.wav'))
        try:
            if shutil.which('ffmpeg'):
                cmds = [
                    ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-y', '-f', 'pulse', '-i', 'default',
                     '-t', str(secs), '-ac', '1', '-ar', '12000', '-c:a', 'libopus', '-b:a', '12k', str(tmp_ogg)],
                    ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-y', '-f', 'alsa', '-i', 'default',
                     '-t', str(secs), '-ac', '1', '-ar', '12000', '-c:a', 'libopus', '-b:a', '12k', str(tmp_ogg)],
                ]
                for cmd in cmds:
                    rc = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode
                    if rc == 0 and tmp_ogg.exists() and tmp_ogg.stat().st_size > 256:
                        return (tmp_ogg.read_bytes(), 'audio/ogg', float(secs), '')
            if shutil.which('arecord'):
                cmd = ['arecord', '-q', '-d', str(secs), '-f', 'S16_LE', '-r', '8000', '-c', '1', str(tmp_wav)]
                rc = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode
                if rc == 0 and tmp_wav.exists() and tmp_wav.stat().st_size > 1024:
                    return (tmp_wav.read_bytes(), 'audio/wav', float(secs), '')
            return (b'', '', 0.0, 'No recording backend (ffmpeg/arecord).')
        except Exception as exc:
            return (b'', '', 0.0, str(exc))
        finally:
            try:
                tmp_ogg.unlink(missing_ok=True)
            except Exception:
                pass
            try:
                tmp_wav.unlink(missing_ok=True)
            except Exception:
                pass

    def _open_voice_inbox(self):
        if not self.voice_inbox:
            self._show_notice('Voice Inbox', 'No voice messages yet.')
            return
        options = []
        desc = {}
        for i, msg in enumerate(self.voice_inbox[:40], 1):
            hh = time.strftime('%H:%M:%S', time.localtime(int(msg.get('ts') or time.time())))
            who = str(msg.get('sender') or 'Unknown')
            dur = float(msg.get('duration') or 0.0)
            party_id = str(msg.get('party_id') or '').strip()
            label = f'{i:02d}. {who} ({dur:.0f}s) [{hh}]'
            options.append(label)
            info = f'MIME: {msg.get("mime", "audio")} | Duration: {dur:.0f}s'
            if party_id:
                info += f' | Party: {party_id}'
            desc[label] = info
        options.append('Cancel')
        pick = self._pick_from_menu('Voice Inbox', options, desc)
        if not pick or pick == 'Cancel':
            return
        try:
            idx = int(str(pick).split('.', 1)[0]) - 1
        except Exception:
            return
        if idx < 0 or idx >= len(self.voice_inbox):
            return
        sel = self.voice_inbox[idx]
        self._play_voice_file(sel.get('path'))
        self.status.setText(f"Playing voice from {sel.get('sender', 'Unknown')}")

    def _send_voice_message(self, peer=None, to_party=False):
        target = dict(peer or (self._selected_peer() or {}))
        if to_party:
            if not str(self.party_state.get('party_id') or '').strip():
                self.status.setText('No active party.')
                return
        else:
            if not target:
                self._show_notice('Voice Message', 'Select a user first.')
                return
            if str(target.get('source') or '').upper() == 'WORLD':
                self._show_notice('Voice Message', 'Select a player/friend, not WORLD room.')
                return

        pick = self._pick_from_menu(
            'Voice Message',
            ['2', '3', '4', '5', '6', 'Cancel'],
            {'2': 'Record 2s', '3': 'Record 3s', '4': 'Record 4s', '5': 'Record 5s', '6': 'Record 6s'},
        )
        if not pick or pick == 'Cancel':
            return
        try:
            seconds = int(str(pick).strip())
        except Exception:
            return

        self.status.setText(f'Recording voice message ({seconds}s)...')
        QtWidgets.QApplication.processEvents()
        blob, mime, duration, err = self._record_voice_clip(seconds)
        if not blob:
            self.status.setText(f'Voice record failed: {err}')
            return
        b64 = base64.b64encode(blob).decode('ascii', errors='ignore')

        if to_party:
            party_id = str(self.party_state.get('party_id') or '').strip()
            if len(b64) > 3200:
                self.status.setText('Party voice too large for relay. Try 2s.')
                return
            try:
                self.engine.send_world_voice_message('', mime, duration, b64, party_id=party_id)
                self._append_line(f"[{time.strftime('%H:%M:%S')}] You -> PARTY [{duration:.0f}s]")
                self.status.setText('Party voice message sent.')
            except Exception as exc:
                self.status.setText(f'Party voice send failed: {exc}')
            return

        source = str(target.get('source') or '').upper()
        user_id = str(target.get('user_id') or '').strip()
        if not user_id:
            low_name = str(target.get('name') or '').strip().lower()
            for uid, row in self.global_players.items():
                if str(row.get('name') or '').strip().lower() == low_name:
                    user_id = str(uid)
                    break
        if user_id and source in ('GLOBAL', 'FRIEND', 'PARTY', 'RECENT'):
            if len(b64) > 3200:
                self.status.setText('Voice clip too large for global relay. Try 2s.')
                return
            try:
                self.engine.send_world_voice_message(user_id, mime, duration, b64, party_id='')
                self._append_line(f"[{time.strftime('%H:%M:%S')}] You -> {target.get('name','User')} [VOICE {duration:.0f}s]")
                self.status.setText(f"Voice sent to {target.get('name', 'user')}")
                return
            except Exception as exc:
                self.status.setText(f'Global voice send failed: {exc}')
                return

        candidates = self._send_candidates(target)
        last_err = None
        for host, port, _key in candidates:
            try:
                self.engine.send_voice_message(host, port, mime, duration, b64)
                self._append_line(f"[{time.strftime('%H:%M:%S')}] You -> {target.get('name','peer')} [VOICE {duration:.0f}s]")
                self.status.setText(f'Voice sent to {host}:{port}')
                return
            except Exception as exc:
                last_err = exc
        self.status.setText(f'Voice send failed: {last_err or "no route"}')

    def _open_voice_hub(self):
        options = [
            'Send Voice Message',
            'Voice Inbox',
            'Send Party Voice',
            'Open Party Hub',
            'Cancel',
        ]
        desc = {
            'Send Voice Message': 'Send global voice message to selected user (no IP manual).',
            'Voice Inbox': 'Play received voice messages.',
            'Send Party Voice': 'Send voice note to current party room.',
            'Open Party Hub': 'Open party controls and invites.',
            'Cancel': 'Back.',
        }
        pick = self._pick_from_menu('Voice/Call Hub', options, desc)
        if not pick or pick == 'Cancel':
            return
        if pick == 'Send Voice Message':
            self._send_voice_message()
        elif pick == 'Voice Inbox':
            self._open_voice_inbox()
        elif pick == 'Send Party Voice':
            self._send_voice_message(to_party=True)
        elif pick == 'Open Party Hub':
            self._open_party_hub()

    def _party_member_rows(self):
        members = self.party_state.get('members') if isinstance(self.party_state, dict) else {}
        if not isinstance(members, dict):
            members = {}
        rows = []
        for uid, row in members.items():
            if not isinstance(row, dict):
                continue
            gp = self.global_players.get(str(uid), {})
            online = bool(row.get('online', False))
            if isinstance(gp, dict) and gp:
                online = bool(gp.get('online', online))
            rows.append({
                'name': str(row.get('name') or 'Player'),
                'user_id': str(uid or ''),
                'source': 'PARTY',
                'online': online,
                'host': '',
                'port': 0,
                'last_seen': int(row.get('last_seen') or int(time.time())),
            })
        rows.sort(key=lambda x: (0 if x.get('online') else 1, str(x.get('name') or '').lower()))
        return rows

    def _open_party_hub(self):
        pid = str(self.party_state.get('party_id') or '').strip()
        options = ['Create Party', 'Invite Selected User', 'Party Members', 'Join Last Invite', 'Leave Party', 'Cancel']
        desc = {
            'Create Party': 'Create/refresh a global party room.',
            'Invite Selected User': 'Invite selected global player or friend.',
            'Party Members': 'Show current party roster.',
            'Join Last Invite': 'Join latest incoming party invite.',
            'Leave Party': 'Leave current party room.',
            'Cancel': 'Back.',
        }
        pick = self._pick_from_menu('Party Hub', options, desc)
        if not pick or pick == 'Cancel':
            return
        if pick == 'Create Party':
            party_id = pid or f'party-{self.user_id[:6]}-{uuid.uuid4().hex[:6]}'
            members = self.party_state.get('members') if isinstance(self.party_state.get('members'), dict) else {}
            self.party_state['party_id'] = party_id
            self.party_state['party_name'] = f'{self.nickname} Party'
            members[self.user_id] = {'name': self.nickname, 'online': True, 'last_seen': int(time.time())}
            self.party_state['members'] = members
            self._save_party_state()
            self.engine.send_world_party_state(party_id, state='join')
            self.status.setText(f'Party ready: {party_id}')
            self._append_system(f'Party ready: {party_id}')
            self._set_community_mode('party')
            return
        if pick == 'Invite Selected User':
            peer = self._selected_peer() or {}
            user_id = str(peer.get('user_id') or '').strip()
            if not user_id:
                low_name = str(peer.get('name') or '').strip().lower()
                for uid, row in self.global_players.items():
                    if str(row.get('name') or '').strip().lower() == low_name:
                        user_id = str(uid)
                        break
            if not user_id:
                self.status.setText('Select a global user to invite.')
                return
            if user_id == self.user_id:
                self.status.setText('Cannot invite yourself.')
                return
            party_id = pid or f'party-{self.user_id[:6]}-{uuid.uuid4().hex[:6]}'
            members = self.party_state.get('members') if isinstance(self.party_state.get('members'), dict) else {}
            if not pid:
                self.party_state['party_id'] = party_id
                self.party_state['party_name'] = f'{self.nickname} Party'
            members[self.user_id] = {'name': self.nickname, 'online': True, 'last_seen': int(time.time())}
            self.party_state['members'] = members
            try:
                self.engine.send_world_party_invite(user_id, party_id, self.party_state.get('party_name', 'XUI Party'))
                self.engine.send_world_party_state(party_id, state='join')
                self._save_party_state()
                self.status.setText(f"Party invite sent to {peer.get('name', 'user')}")
                self._append_system(f"Party invite sent to {peer.get('name', 'user')}")
            except Exception as exc:
                self.status.setText(f'Party invite failed: {exc}')
            return
        if pick == 'Party Members':
            rows = self._party_member_rows()
            if not rows:
                self._show_notice('Party Members', 'No members in party.')
                return
            txt = '\n'.join([f"- {r.get('name')} ({'Online' if r.get('online') else 'Offline'})" for r in rows[:48]])
            self._show_notice('Party Members', txt)
            return
        if pick == 'Join Last Invite':
            inv = self.last_party_invite or {}
            party_id = str(inv.get('party_id') or '').strip()
            if not party_id:
                self.status.setText('No incoming party invite yet.')
                return
            members = self.party_state.get('members') if isinstance(self.party_state.get('members'), dict) else {}
            self.party_state['party_id'] = party_id
            self.party_state['party_name'] = str(inv.get('party_name') or f'Party {party_id}')
            members[self.user_id] = {'name': self.nickname, 'online': True, 'last_seen': int(time.time())}
            inv_uid = str(inv.get('from_user_id') or '').strip()
            inv_name = str(inv.get('from') or 'Player')
            if inv_uid and inv_uid != self.user_id:
                members[inv_uid] = {'name': inv_name, 'online': True, 'last_seen': int(time.time())}
            self.party_state['members'] = members
            self._save_party_state()
            self.engine.send_world_party_state(party_id, state='join')
            self.status.setText(f'Joined party {party_id}')
            self._append_system(f'Joined party {party_id}')
            self._set_community_mode('party')
            return
        if pick == 'Leave Party':
            party_id = str(self.party_state.get('party_id') or '').strip()
            if party_id:
                self.engine.send_world_party_state(party_id, state='leave')
            self.party_state = {'party_id': '', 'party_name': '', 'members': {}}
            self._save_party_state()
            self.status.setText('Party closed.')
            self._append_system('Party closed.')
            self._set_community_mode('messages')

    def _friend_endpoint_key(self, host, port):
        h = str(host or '').strip().lower()
        try:
            p = int(port or 0)
        except Exception:
            p = 0
        return f'{h}:{p}'

    def _load_friends(self):
        arr = safe_json_read(FRIENDS_FILE, [])
        if not isinstance(arr, list):
            arr = []
        out = []
        for raw in arr:
            if not isinstance(raw, dict):
                continue
            name = str(raw.get('name') or '').strip()
            if name.casefold() in {'friend1', 'friend2'}:
                continue
            host = str(raw.get('host') or '').strip()
            try:
                port = int(raw.get('port') or 0)
            except Exception:
                port = 0
            out.append({
                'name': name or host or 'Friend',
                'user_id': str(raw.get('user_id') or '').strip(),
                'host': host,
                'port': int(port),
                'online': bool(raw.get('online', False)),
                'accepted': bool(raw.get('accepted', True)),
                'source': str(raw.get('source') or 'GLOBAL'),
                'last_seen': int(raw.get('last_seen', int(time.time()))),
            })
        self.friends = out
        if out != arr:
            self._save_friends()

    def _save_friends(self):
        safe_json_write(FRIENDS_FILE, self.friends)

    def _friend_matches_peer(self, friend, peer):
        fu = str(friend.get('user_id') or '').strip()
        pu = str(peer.get('user_id') or '').strip()
        if fu and pu and fu == pu:
            return True
        fh = str(friend.get('host') or '').strip().lower()
        ph = str(peer.get('host') or '').strip().lower()
        fp = int(friend.get('port') or 0)
        pp = int(peer.get('port') or 0)
        if fh and ph and fh == ph and fp > 0 and pp > 0 and fp == pp:
            return True
        fn = str(friend.get('name') or '').strip().lower()
        pn = str(peer.get('name') or '').strip().lower()
        return bool(fn and pn and fn == pn)

    def _is_friend(self, peer):
        for f in self.friends:
            if self._friend_matches_peer(f, peer):
                return True
        return False

    def _mark_friend_online(self, peer, online=True):
        changed = False
        now = int(time.time())
        for f in self.friends:
            if self._friend_matches_peer(f, peer):
                if f.get('online') != bool(online):
                    f['online'] = bool(online)
                    changed = True
                prev_seen = int(f.get('last_seen') or 0)
                if abs(now - prev_seen) >= 20:
                    f['last_seen'] = now
                    changed = True
        if changed:
            self._save_friends()

    def _upsert_friend(self, name, host, port, user_id='', source='GLOBAL'):
        host = str(host or '').strip()
        user_id = str(user_id or '').strip()
        try:
            port = int(port or 0)
        except Exception:
            port = 0
        key = self._friend_endpoint_key(host, port) if (host or port > 0) else ''
        now = int(time.time())
        for f in self.friends:
            same_uid = bool(user_id and str(f.get('user_id') or '').strip() == user_id)
            same_ep = bool(key and self._friend_endpoint_key(f.get('host'), f.get('port')) == key)
            if same_uid or same_ep:
                f['name'] = str(name or f.get('name') or host or 'Friend')
                f['user_id'] = user_id or str(f.get('user_id') or '')
                f['online'] = True
                f['accepted'] = True
                f['source'] = str(source or f.get('source') or 'GLOBAL')
                f['last_seen'] = now
                self._save_friends()
                return
        self.friends.append({
            'name': str(name or host or 'Friend'),
            'user_id': user_id,
            'host': host,
            'port': int(port),
            'online': True,
            'accepted': True,
            'source': str(source or 'GLOBAL'),
            'last_seen': now,
        })
        self._save_friends()

    def _load_friend_requests(self):
        arr = safe_json_read(FRIEND_REQUESTS_FILE, [])
        if not isinstance(arr, list):
            arr = []
        out = []
        for raw in arr:
            if not isinstance(raw, dict):
                continue
            out.append({
                'name': str(raw.get('name') or 'Unknown').strip() or 'Unknown',
                'user_id': str(raw.get('user_id') or '').strip(),
                'host': str(raw.get('host') or '').strip(),
                'port': int(raw.get('port') or 0),
                'note': str(raw.get('note') or '').strip(),
                'kind': str(raw.get('kind') or 'lan').strip().lower(),
                'ts': int(raw.get('ts') or int(time.time())),
            })
        self.friend_requests = out

    def _save_friend_requests(self):
        safe_json_write(FRIEND_REQUESTS_FILE, self.friend_requests)

    def _queue_friend_request(self, name, host, port, note='', user_id='', kind='lan'):
        key = self._friend_endpoint_key(host, port) if (str(host or '').strip() or int(port or 0) > 0) else ''
        uid = str(user_id or '').strip()
        for req in self.friend_requests:
            req_uid = str(req.get('user_id') or '').strip()
            same_uid = bool(uid and req_uid == uid)
            same_ep = bool(key and self._friend_endpoint_key(req.get('host'), req.get('port')) == key)
            if same_uid or same_ep:
                req['name'] = str(name or req.get('name') or 'Unknown')
                req['user_id'] = uid or req_uid
                req['note'] = str(note or req.get('note') or '')
                req['kind'] = str(kind or req.get('kind') or 'lan').strip().lower()
                req['ts'] = int(time.time())
                self._save_friend_requests()
                return
        self.friend_requests.insert(0, {
            'name': str(name or 'Unknown'),
            'user_id': uid,
            'host': str(host or ''),
            'port': int(port or 0),
            'note': str(note or ''),
            'kind': str(kind or 'lan').strip().lower(),
            'ts': int(time.time()),
        })
        self.friend_requests = self.friend_requests[:120]
        self._save_friend_requests()

    def _show_friends(self):
        self._set_community_mode('friends')
        self.status.setText('Community: Friends')

    def _send_friend_request(self):
        peer = self._selected_peer()
        if not peer or str(peer.get('source')) == 'WORLD':
            self._show_notice('Friend Request', 'Select a player first.')
            return
        peer_name = str(peer.get('name') or 'player')
        peer_uid = str(peer.get('user_id') or '').strip()
        if self._is_friend(peer):
            self.status.setText(f'{peer_name} is already your friend.')
            return
        if not peer_uid:
            low_name = peer_name.strip().lower()
            for uid, row in self.global_players.items():
                if str(row.get('name') or '').strip().lower() == low_name:
                    peer_uid = str(uid)
                    break
        if peer_uid:
            try:
                self.engine.send_world_friend_request(peer_uid, f'Add {self.nickname} as friend')
                self.status.setText(f'Friend request sent to {peer_name}')
                self._append_system(f'Global friend request sent to {peer_name}')
                return
            except Exception as exc:
                relay_error = str(exc)
                # A GLOBAL player may also have a LAN discovery endpoint. Try
                # that direct route when the shared public relay is throttled.
                candidates = self._send_candidates(peer)
                sent = None
                for host, port, _key in candidates:
                    try:
                        if self.engine.send_friend_request(host, port, f'Add {self.nickname} as friend'):
                            sent = (host, int(port))
                            break
                    except Exception:
                        continue
                if sent:
                    self.status.setText(f'Friend request sent to {peer_name} over LAN ({sent[0]}:{sent[1]})')
                    self._append_system(f'Friend request sent to {peer_name} over LAN; public relay was rate-limited.')
                    return
                self.status.setText(f'Friend request failed: {relay_error}')
                self._append_system(
                    f'Could not send request to {peer_name}. The public relay may be rate-limited; '
                    'both players must be on the same reachable LAN for direct fallback.'
                )
                return
        candidates = self._send_candidates(peer)
        err = None
        sent = None
        for host, port, _key in candidates:
            try:
                self.engine.send_friend_request(host, port, f'Add {self.nickname} as friend')
                sent = (host, int(port))
                break
            except Exception as exc:
                err = exc
        if sent:
            self.status.setText(f'Friend request sent to {sent[0]}:{sent[1]}')
            self._append_system(f"Friend request sent to {peer.get('name', 'peer')}")
            return
        self.status.setText(f'Friend request failed: {err or "unreachable peer"}')

    def _open_friend_requests(self):
        if not self.friend_requests:
            self._show_notice('Friend Requests', 'No pending requests.')
            return
        options = []
        descriptions = {}
        for i, req in enumerate(self.friend_requests[:40], 1):
            name = str(req.get('name') or 'Unknown')
            uid = str(req.get('user_id') or '').strip()
            host = str(req.get('host') or '-')
            port = int(req.get('port') or 0)
            note = str(req.get('note') or '').strip()
            op = f'{i:02d}. {name}'
            options.append(op)
            if uid:
                descriptions[op] = f'global user: {uid}' + (f' | {note}' if note else '')
            else:
                descriptions[op] = f'{host}:{port}' + (f' | {note}' if note else '')
        options.append('Back')
        pick = self._pick_from_menu('Friend Requests', options, descriptions)
        if not pick or pick == 'Back':
            return
        try:
            idx = int(str(pick).split('.', 1)[0]) - 1
        except Exception:
            return
        if idx < 0 or idx >= len(self.friend_requests):
            return
        req = self.friend_requests[idx]
        ask = self._pick_from_menu(
            'Friend Request',
            ['Accept', 'Reject', 'Cancel'],
            {
                'Accept': f"Add {req.get('name','Unknown')} to friends.",
                'Reject': f"Reject request from {req.get('name','Unknown')}.",
                'Cancel': 'Go back.',
            },
        )
        if not ask or ask == 'Cancel':
            return
        if ask == 'Accept':
            self._upsert_friend(
                req.get('name'),
                req.get('host'),
                req.get('port'),
                user_id=req.get('user_id'),
                source='GLOBAL' if str(req.get('kind') or '').lower() == 'global' else 'LAN',
            )
            req_uid = str(req.get('user_id') or '').strip()
            if req_uid:
                self._touch_global_player(req_uid, req.get('name'), 'friend')
            if str(req.get('kind') or '').lower() == 'global' and req_uid:
                try:
                    self.engine.send_world_friend_accept(req_uid)
                except Exception:
                    pass
            else:
                host = str(req.get('host') or '').strip()
                try:
                    port = int(req.get('port') or 0)
                except (TypeError, ValueError, OverflowError):
                    port = 0
                if host and 0 < port <= 65535:
                    try:
                        self.engine.send_friend_accept(host, port)
                    except Exception as exc:
                        self.status.setText(f'Friend added locally; acceptance reply failed: {exc}')
            self._append_system(f"Friend added: {req.get('name', 'Unknown')}")
            self.status.setText(f"Friend added: {req.get('name', 'Unknown')}")
        else:
            self._append_system(f"Friend request rejected: {req.get('name', 'Unknown')}")
        self.friend_requests.pop(idx)
        self._save_friend_requests()

    def _peer_row(self, peer):
        src = str(peer.get('source') or '').upper()
        if src == 'WORLD':
            return f"{peer['name']}  [global relay]  (WORLD)"
        if src == 'GLOBAL':
            st = 'online' if bool(peer.get('online', True)) else 'offline'
            return f"{peer['name']}  [global {st}]  (GLOBAL)"
        if src == 'FRIEND':
            return f"{peer['name']}  [friend]  (FRIEND)"
        return f"{peer['name']}  [{peer['host']}:{peer['port']}]  ({peer['source']})"

    def _upsert_peer(self, peer, persist=False):
        source = str(peer.get('source') or 'LAN')
        uid = str(peer.get('user_id') or '').strip()
        if uid:
            key = f'uid:{uid}:{source}'
        else:
            key = f"{peer['host']}:{int(peer.get('port', 0) or 0)}:{source}"
        data = {
            'name': str(peer.get('name') or peer.get('host')),
            'host': str(peer.get('host')),
            'port': int(peer.get('port') or 0),
            'source': source,
            'node_id': str(peer.get('node_id') or ''),
            'user_id': uid,
            'online': bool(peer.get('online', True)),
            '_world': bool(peer.get('_world', False)),
        }
        if not data['host'] and not uid:
            return
        if data['source'] not in ('WORLD', 'GLOBAL', 'FRIEND', 'PARTY', 'RECENT') and data['port'] <= 0:
            return
        if key in self.peer_data:
            self.peer_data[key].update(data)
        else:
            self.peer_data[key] = data
        if self._community_mode != 'messages':
            self._refresh_community_tabs()
            return
        if key in self.peer_items:
            self.peer_items[key].setText(self._peer_row(self.peer_data[key]))
        else:
            it = QtWidgets.QListWidgetItem(self._peer_row(self.peer_data[key]))
            it.setData(QtCore.Qt.UserRole, key)
            self.peers.addItem(it)
            self.peer_items[key] = it
            if self.peers.currentRow() < 0:
                self.peers.setCurrentRow(0)
        self._update_peer_meta()
        if persist:
            self._save_manual_peers()

    def _remove_peer(self, key):
        self.peer_data.pop(key, None)
        it = self.peer_items.pop(key, None)
        if it is None:
            self._refresh_community_tabs()
            return
        row = self.peers.row(it)
        if row >= 0:
            self.peers.takeItem(row)
        self._update_peer_meta()
        self._refresh_community_tabs()

    def _selected_peer(self):
        it = self.peers.currentItem()
        if not it:
            return None
        key = it.data(QtCore.Qt.UserRole)
        if isinstance(key, dict):
            return dict(key)
        return self.peer_data.get(key)

    def _host_priority(self, host):
        h = str(host or '')
        if h.startswith('127.'):
            return 30
        if h.startswith('10.0.2.'):
            # VirtualBox NAT default, often not valid between different VMs.
            return 20
        return 0

    def _send_candidates(self, peer):
        selected_host = str(peer.get('host') or '')
        selected_port = int(peer.get('port') or 0)
        selected_node = str(peer.get('node_id') or '')
        selected_user = str(peer.get('user_id') or '').strip()
        candidates = []
        for key, p in self.peer_data.items():
            host = str(p.get('host') or '')
            if str(p.get('source') or '') == 'WORLD':
                continue
            try:
                port = int(p.get('port') or 0)
            except Exception:
                port = 0
            if not host or port <= 0:
                continue
            node = str(p.get('node_id') or '')
            user_id = str(p.get('user_id') or '').strip()
            exact_endpoint = host == selected_host and port == selected_port
            same_identity = bool(
                (selected_node and node and node == selected_node)
                or (selected_user and user_id and user_id == selected_user)
            )
            same_host_identity = bool(
                host == selected_host
                and str(p.get('name') or '').strip().casefold()
                == str(peer.get('name') or '').strip().casefold()
            )
            if exact_endpoint or same_identity or same_host_identity:
                rank = 0 if exact_endpoint else 1
                candidates.append((rank, self._host_priority(host), host, port, key))
        candidates.sort(key=lambda row: (row[0], row[1], row[2], row[3]))
        out = []
        seen = set()
        for _rank, _hp, host, port, key in candidates:
            endpoint = (host, int(port))
            if endpoint in seen:
                continue
            seen.add(endpoint)
            out.append((host, int(port), key))
        return out

    def _save_manual_peers(self):
        arr = []
        for p in self.peer_data.values():
            if p.get('source') == 'manual':
                arr.append({'name': p.get('name'), 'host': p.get('host'), 'port': int(p.get('port') or 0)})
        safe_json_write(PEERS_FILE, {'manual_peers': arr})

    def _load_manual_peers(self):
        data = safe_json_read(PEERS_FILE, {'manual_peers': []})
        for p in data.get('manual_peers', []):
            try:
                self._upsert_peer({
                    'name': p.get('name') or p.get('host'),
                    'host': p.get('host'),
                    'port': int(p.get('port') or 0),
                    'source': 'manual',
                }, persist=False)
            except Exception:
                continue

    def _add_peer(self):
        d = EscInputDialog(self)
        d.setWindowTitle('Add P2P peer')
        d.setLabelText('Format: alias@host:port or host:port')
        d.setInputMode(QtWidgets.QInputDialog.TextInput)
        if d.exec_() != QtWidgets.QDialog.Accepted:
            return
        parsed = parse_peer_id(d.textValue())
        if not parsed:
            self._show_notice('Invalid peer', 'Use alias@host:port or host:port')
            return
        self._upsert_peer(parsed, persist=True)
        self._append_system(f"Manual peer added: {parsed['host']}:{parsed['port']}")

    def _show_peer_ids(self):
        ips = local_ipv4_addresses()
        lines = [f'{ip}:{self.engine.chat_port}' for ip in ips]
        if not self.engine.chat_port:
            lines += ['', 'Warning: chat TCP server is not active on this dashboard.']
        if ips and all(str(ip).startswith('10.0.2.') for ip in ips):
            lines += ['', 'VirtualBox NAT detected (10.0.2.x only).', 'Use Bridged or Host-Only Adapter for VM-to-VM LAN chat.']
        self._show_notice('My Peer IDs', '\n'.join(lines))

    def _show_lan_status(self):
        out = subprocess.getoutput('ip -brief -4 addr 2>/dev/null || ip -4 addr show 2>/dev/null || true')
        self._show_notice('LAN Status', out or 'No network data.')

    def _open_voice_call_hub(self):
        self._open_voice_hub()

    def _stop_call_session(self, notify=False):
        if notify:
            self.status.setText('Voice session is integrated in Social Hub.')

    def _load_world_settings(self):
        cfg = safe_json_read(WORLD_CHAT_FILE, {})
        room = str(cfg.get('room', '')).strip()
        enabled = bool(cfg.get('enabled', True))
        if room:
            self.engine.set_world_topic(room)
        self.engine.set_world_enabled(enabled)
        self._update_world_toggle_button()

    def _save_world_settings(self):
        safe_json_write(
            WORLD_CHAT_FILE,
            {
                'room': self.engine.world_topic,
                'enabled': bool(self.engine.world_enabled),
                'relay': self.engine.world_relay,
            },
        )

    def _world_peer_payload(self):
        return {
            'name': f"WORLD #{self.engine.world_topic}",
            'host': self.engine.world_relay,
            'port': 0,
            'source': 'WORLD',
            'node_id': f'world:{self.engine.world_topic}',
            '_world': True,
        }

    def _refresh_world_peer(self):
        existing = None
        for key, p in list(self.peer_data.items()):
            if str(p.get('source')) == 'WORLD' or bool(p.get('_world')):
                existing = key
                break
        if existing is not None:
            self._remove_peer(existing)
        if self.engine.world_enabled:
            self._upsert_peer(self._world_peer_payload(), persist=False)
        self._update_world_toggle_button()

    def _update_world_toggle_button(self):
        it = self._action_items.get('world_toggle')
        if it is None:
            return
        if self.engine.world_enabled:
            it.setText('World Chat: ON')
        else:
            it.setText('World Chat: OFF')

    def _toggle_world_chat(self):
        self.engine.set_world_enabled(not self.engine.world_enabled)
        self._refresh_world_peer()
        self._save_world_settings()

    def _change_world_room(self):
        d = EscInputDialog(self)
        d.setWindowTitle('World Chat Room')
        d.setLabelText('Room/topic name (letters, numbers, -, _, .)')
        d.setInputMode(QtWidgets.QInputDialog.TextInput)
        d.setTextValue(self.engine.world_topic)
        if d.exec_() != QtWidgets.QDialog.Accepted:
            return
        raw = d.textValue()
        self.engine.set_world_topic(raw)
        self._refresh_world_peer()
        self._save_world_settings()
        self._append_system(f'World room changed to: {self.engine.world_topic}')

    def _send_current(self):
        peer = self._selected_peer()
        if not peer:
            self._show_notice('Peer required', 'Select a peer first.')
            return
        txt = self.input.text().strip()
        if not txt:
            return
        if len(txt) > 4000:
            self.status.setText('Message too long (maximum 4000 characters).')
            return
        if len(self._pending_sends) >= 4:
            self.status.setText('Several messages are still sending; wait a moment.')
            return
        message_id = uuid.uuid4().hex
        peer = dict(peer)
        peer['_is_friend'] = self._is_friend(peer)
        peer['_send_candidates'] = self._send_candidates(peer)
        self._pending_sends.add(message_id)
        self.input.clear()
        self.status.setText(f"Sending to {peer.get('name') or 'peer'}…")
        self._save_conversation_message(peer, 'out', txt, status='pending', message_id=message_id)
        worker = threading.Thread(
            target=self._send_message_worker,
            args=(dict(peer), txt, message_id),
            name=f'xui-chat-send-{message_id[:8]}',
            daemon=True,
        )
        worker.start()

    def _send_message_worker(self, peer, text, message_id):
        result = {
            'peer': peer,
            'text': text,
            'message_id': message_id,
            'ok': False,
            'status': 'failed',
            'detail': '',
        }
        try:
            source = str(peer.get('source') or '').upper()
            if source == 'WORLD':
                self.engine.send_world_chat(text)
                result.update(ok=True, status='relay accepted; public room', detail=f"Room #{self.engine.world_topic}; delivery is not confirmed.")
            elif source in ('GLOBAL', 'FRIEND', 'PARTY', 'RECENT') and str(peer.get('user_id') or '').strip() and not int(peer.get('port') or 0):
                self.engine.send_world_private_message(str(peer['user_id']), text)
                result.update(ok=True, status='relay accepted; not private', detail='The shared public relay can read this message; end-to-end encryption is not enabled.')
            else:
                last_error = None
                is_friend = bool(peer.get('_is_friend', False))
                delivered = False
                legacy_sent = False
                used_endpoint = None
                for host, port, _key in peer.get('_send_candidates', []):
                    try:
                        acknowledged = (
                            self.engine.send_private_message(host, port, text, message_id)
                            if is_friend
                            else self.engine.send_chat(host, port, text, message_id)
                        )
                        used_endpoint = (host, port)
                        delivered = bool(acknowledged)
                        legacy_sent = not bool(acknowledged)
                        break
                    except Exception as exc:
                        last_error = exc
                if used_endpoint is None:
                    raise RuntimeError(str(last_error or 'No endpoint for this peer identity was reachable.'))
                result['endpoint'] = used_endpoint
                if delivered:
                    result.update(ok=True, status='delivered', detail=f'Delivery acknowledged by {used_endpoint[0]}:{used_endpoint[1]}.')
                elif legacy_sent:
                    result.update(ok=True, status='unconfirmed', detail='Peer accepted the TCP write but did not support delivery acknowledgements.')
        except Exception as exc:
            result['detail'] = str(exc)[:300]
        self.engine.events.put(('send_result', result))

    def _touch_global_player(self, user_id, name, status='online'):
        uid = str(user_id or '').strip()
        if not uid or uid == self.user_id:
            return
        now = int(time.time())
        row = self.global_players.get(uid, {})
        row.update({
            'name': str(name or row.get('name') or 'Player'),
            'status': str(status or 'online'),
            'online': True,
            'last_seen': now,
        })
        self.global_players[uid] = row
        members = self.party_state.get('members') if isinstance(self.party_state.get('members'), dict) else {}
        if uid in members:
            m = dict(members.get(uid) or {})
            m['name'] = row.get('name', m.get('name', 'Player'))
            m['online'] = True
            m['last_seen'] = now
            members[uid] = m
            self.party_state['members'] = members
        self._upsert_peer(
            {
                'name': row.get('name', 'Player'),
                'host': 'global',
                'port': 0,
                'source': 'GLOBAL',
                'node_id': str(row.get('node_id') or ''),
                'user_id': uid,
                'online': bool(row.get('online', True)),
            },
            persist=False,
        )
        self._mark_friend_online({'user_id': uid, 'name': row.get('name')}, True)

    def _expire_global_players(self):
        now = int(time.time())
        changed = False
        for uid, row in list(self.global_players.items()):
            last_seen = int(row.get('last_seen') or 0)
            online = bool(row.get('online', False))
            if online and (now - last_seen) > 80:
                row['online'] = False
                self.global_players[uid] = row
                members = self.party_state.get('members') if isinstance(self.party_state.get('members'), dict) else {}
                if uid in members:
                    m = dict(members.get(uid) or {})
                    m['online'] = False
                    members[uid] = m
                    self.party_state['members'] = members
                self._upsert_peer(
                    {
                        'name': row.get('name', 'Player'),
                        'host': 'global',
                        'port': 0,
                        'source': 'GLOBAL',
                        'node_id': str(row.get('node_id') or ''),
                        'user_id': uid,
                        'online': False,
                    },
                    persist=False,
                )
                self._mark_friend_online({'user_id': uid, 'name': row.get('name')}, False)
                changed = True
        return changed

    def _poll_events(self):
        while True:
            try:
                evt = self.engine.events.get_nowait()
            except queue.Empty:
                break
            kind = evt[0]
            if kind == 'send_result':
                result = evt[1] if len(evt) > 1 and isinstance(evt[1], dict) else {}
                message_id = str(result.get('message_id') or '')
                self._pending_sends.discard(message_id)
                peer = result.get('peer') if isinstance(result.get('peer'), dict) else {}
                text = str(result.get('text') or '')
                status = str(result.get('status') or 'failed')
                if bool(result.get('ok')):
                    self._save_conversation_message(peer, 'out', text, status, message_id)
                    self._push_recent_message(f"You -> {peer.get('name') or 'peer'}", text)
                    self.status.setText(str(result.get('detail') or 'Message sent.'))
                else:
                    self._save_conversation_message(peer, 'out', text, 'failed', message_id)
                    detail = str(result.get('detail') or 'unknown error')
                    detail_lower = detail.lower()
                    if 'errno 113' in detail_lower or 'no route to host' in detail_lower or 'no existe ninguna ruta hasta el host' in detail_lower:
                        detail = (
                            f'{detail}. Las VMs no tienen ruta entre sí: si VirtualBox usa NAT normal, '
                            'cámbialo en ambas a Adaptador puente, Solo-anfitrión o la misma Red NAT; '
                            'permite TCP 38600-38623 y UDP 38655 en el firewall.'
                        )
                    elif 'errno 111' in detail_lower or 'connection refused' in detail_lower or 'conexión rehusada' in detail_lower:
                        detail = (
                            f'{detail}. El host responde, pero el puerto de chat está cerrado o bloqueado; '
                            'comprueba que XUI siga abierto y permite TCP 38600-38623.'
                        )
                    self.status.setText(f'Mensaje no entregado: {detail}')
                    self._append_system(f"Message to {peer.get('name') or 'peer'} failed: {detail}")
            elif kind == 'status':
                self.status.setText(str(evt[1]))
            elif kind == 'peer_up':
                _kind, _key, data = evt
                self._upsert_peer(data, persist=False)
                self._mark_friend_online(data, True)
                if isinstance(data, dict) and str(data.get('source') or '').upper() == 'LAN':
                    self._append_system(
                        f"LAN player discovered: {data.get('name') or 'Player'} "
                        f"[{data.get('host')}:{data.get('port')}]"
                    )
            elif kind == 'peer_down':
                _kind, key = evt
                peer = self.peer_data.get(key)
                if peer and peer.get('source') == 'LAN':
                    self._mark_friend_online(peer, False)
                    self._remove_peer(key)
            elif kind == 'chat':
                _kind, sender, text = evt[:3]
                sender_uid = str(evt[3] or '') if len(evt) > 3 else ''
                host = str(evt[4] or '') if len(evt) > 4 else ''
                port = int(evt[5] or 0) if len(evt) > 5 else 0
                message_id = str(evt[6] or '') if len(evt) > 6 else ''
                peer = {'name': sender, 'user_id': sender_uid, 'host': host, 'port': port, 'source': 'LAN'}
                self._append_chat(sender, text, peer, message_id)
            elif kind == 'private_message':
                _kind, sender, text = evt[:3]
                sender_uid = str(evt[3] or '') if len(evt) > 3 else ''
                host = str(evt[4] or '') if len(evt) > 4 else ''
                port = int(evt[5] or 0) if len(evt) > 5 else 0
                message_id = str(evt[6] or '') if len(evt) > 6 else ''
                peer = {'name': sender, 'user_id': sender_uid, 'host': host, 'port': port, 'source': 'FRIEND'}
                self._notify_incoming_message()
                self._save_conversation_message(peer, 'in', text, 'delivered', message_id)
                if self._conversation_key(peer) == self._active_conversation_key:
                    self.status.setText(f'Private message received from {sender}; LAN traffic is not encrypted.')
                self._push_recent_message(f'{sender} [PM]', text)
            elif kind == 'world_private_message':
                _kind, sender, sender_user_id, text = evt
                peer = {'name': sender, 'user_id': sender_user_id, 'source': 'GLOBAL'}
                self._notify_incoming_message()
                self._save_conversation_message(peer, 'in', text, 'relay', '')
                self._push_recent_message(f'{sender} [PM]', text)
                self._touch_global_player(sender_user_id, sender, 'pm')
                self.status.setText(f'Relay message from {sender}; it is not end-to-end private.')
            elif kind == 'friend_request':
                sender = str(evt[1] if len(evt) > 1 else 'Unknown')
                host = str(evt[2] if len(evt) > 2 else '')
                try:
                    port = int(evt[3] if len(evt) > 3 else 0)
                except Exception:
                    port = 0
                note = str(evt[4] if len(evt) > 4 else '')
                sender_user_id = str(evt[5] if len(evt) > 5 else '').strip()
                self._queue_friend_request(sender, host, port, note, user_id=sender_user_id, kind='lan')
                self._append_system(f"Friend request from {sender} [{host}:{port}]")
                self.status.setText(f"Pending friend requests: {len(self.friend_requests)}")
            elif kind == 'friend_accept':
                _kind, sender, host, port, sender_user_id = evt
                self._upsert_friend(sender, host, port, user_id=sender_user_id, source='LAN')
                self._append_system(f'{sender} accepted your friend request.')
                self.status.setText(f'Friend added: {sender}')
            elif kind == 'global_friend_request':
                _kind, sender, sender_user_id, note = evt
                self._queue_friend_request(sender, '', 0, note, user_id=sender_user_id, kind='global')
                self._touch_global_player(sender_user_id, sender, 'friend request')
                self._append_system(f"Global friend request from {sender}")
                self.status.setText(f"Pending friend requests: {len(self.friend_requests)}")
            elif kind == 'global_friend_accept':
                _kind, sender, sender_user_id = evt
                self._upsert_friend(sender, '', 0, user_id=sender_user_id, source='GLOBAL')
                self._touch_global_player(sender_user_id, sender, 'friend')
                self._append_system(f'{sender} accepted your friend request.')
                self.status.setText(f'Friend added: {sender}')
            elif kind == 'world_chat':
                _kind, sender, text = evt
                peer = {'name': sender, 'source': 'WORLD'}
                self._notify_incoming_message()
                self._save_conversation_message(peer, 'in', text, 'relay')
                self._push_recent_message(f'{sender} [WORLD]', text)
            elif kind == 'world_presence':
                _kind, data = evt
                if isinstance(data, dict):
                    uid = str(data.get('user_id') or '').strip()
                    name = str(data.get('name') or 'Player')
                    if uid and uid != self.user_id:
                        was_online = bool(self.global_players.get(uid, {}).get('online'))
                        self._touch_global_player(uid, name, 'online')
                        if not was_online:
                            self._append_system(f'Online player discovered via public relay: {name}.')
            elif kind == 'party_invite':
                _kind, data = evt
                if isinstance(data, dict):
                    self.last_party_invite = dict(data)
                    who = str(data.get('from') or 'Player')
                    who_uid = str(data.get('from_user_id') or '').strip()
                    pid = str(data.get('party_id') or '')
                    if who_uid:
                        self._touch_global_player(who_uid, who, 'party invite')
                    self._append_system(f'Party invite from {who} ({pid})')
                    self.status.setText(f'Party invite: {who}')
            elif kind == 'party_state':
                _kind, data = evt
                if not isinstance(data, dict):
                    continue
                uid = str(data.get('from_user_id') or '').strip()
                who = str(data.get('from') or 'Player')
                pid = str(data.get('party_id') or '').strip()
                state = str(data.get('state') or '').strip().lower()
                if uid and pid and (pid == str(self.party_state.get('party_id') or '').strip()):
                    members = self.party_state.get('members') if isinstance(self.party_state.get('members'), dict) else {}
                    if state == 'leave':
                        members.pop(uid, None)
                    else:
                        members[uid] = {'name': who, 'online': True, 'last_seen': int(time.time())}
                    self.party_state['members'] = members
                    self._save_party_state()
                    self._touch_global_player(uid, who, 'party')
            elif kind == 'voice_message':
                sender = str(evt[1] if len(evt) > 1 else 'Unknown')
                mime = str(evt[4] if len(evt) > 4 else 'audio/ogg')
                try:
                    duration = float(evt[5] if len(evt) > 5 else 0.0)
                except Exception:
                    duration = 0.0
                encoded_audio = str(evt[6] if len(evt) > 6 else '')
                sender_user_id = str(evt[7] if len(evt) > 7 else '').strip()
                try:
                    blob = base64.b64decode(str(encoded_audio or '').encode('ascii', errors='ignore'), validate=False)
                except Exception:
                    blob = b''
                if blob:
                    item = self._save_voice_blob(sender, sender_user_id, mime, duration, blob, party_id='')
                    if item is not None:
                        self._notify_incoming_message()
                        self._append_line(f"[{time.strftime('%H:%M:%S')}] {sender} [VOICE {float(duration):.0f}s]")
                        self._push_recent_message(f'{sender} [VOICE]', f'Voice message ({float(duration):.0f}s)')
                        if sender_user_id:
                            self._touch_global_player(sender_user_id, sender, 'voice')
                        self.status.setText(f'New voice message from {sender}')
            elif kind == 'world_voice_message':
                _kind, sender, sender_user_id, party_id, mime, duration, encoded_audio = evt
                if party_id and party_id != str(self.party_state.get('party_id') or '').strip():
                    continue
                try:
                    blob = base64.b64decode(str(encoded_audio or '').encode('ascii', errors='ignore'), validate=False)
                except Exception:
                    blob = b''
                if blob:
                    item = self._save_voice_blob(sender, sender_user_id, mime, duration, blob, party_id=party_id)
                    if item is not None:
                        self._notify_incoming_message()
                        tag = 'PARTY VOICE' if party_id else 'VOICE'
                        self._append_line(f"[{time.strftime('%H:%M:%S')}] {sender} [{tag} {float(duration):.0f}s]")
                        self._push_recent_message(f'{sender} [{tag}]', f'Voice message ({float(duration):.0f}s)')
                        self._touch_global_player(sender_user_id, sender, 'voice')
                        self.status.setText(f'New voice message from {sender}')
            elif kind == 'world_status':
                _kind, enabled, room = evt
                self._update_world_toggle_button()
                if bool(enabled):
                    self.status.setText(f'Connecting to public room #{room}…')
                else:
                    self.status.setText('World chat disconnected')
                self._refresh_world_peer()
            elif kind == 'world_connection':
                _kind, state, room, *detail = evt
                if state == 'connected':
                    self.status.setText(f'Connected to public room #{room}; messages are visible to relay subscribers.')
                else:
                    error_text = str(detail[0] if detail else 'connection lost')
                    error_lower = error_text.lower()
                    dns_failure = any(marker in error_lower for marker in (
                        'temporary failure in name resolution',
                        'name or service not known',
                        'nodename nor servname provided',
                        'getaddrinfo failed',
                        'errno -3',
                    ))
                    if dns_failure:
                        relay_host = urllib.parse.urlparse(self.engine.world_relay).hostname or 'servidor del chat'
                        self.status.setText(
                            f'Chat global sin DNS: no se puede resolver {relay_host}. Reintentando…'
                        )
                    else:
                        self.status.setText(f'Chat global reconectando ({room}): {error_text}')
            elif kind == 'world_room':
                _kind, room = evt
                self._refresh_world_peer()
                self.status.setText(f'World room: {room}')
        self._expire_global_players()
        self._refresh_community_tabs()
        if self._community_mode != 'messages':
            if self._community_mode == 'friends':
                self._rebuild_community_rows(self._community_friends_rows())
            elif self._community_mode == 'party':
                self._rebuild_community_rows(self._community_party_rows())
            elif self._community_mode == 'players':
                self._rebuild_community_rows(self._community_players_rows())

    def closeEvent(self, e):
        try:
            self.timer.stop()
        except Exception:
            pass
        try:
            if self._gp_timer is not None:
                self._gp_timer.stop()
        except Exception:
            pass
        self._stop_call_session(notify=False)
        self._save_world_settings()
        self._save_party_state()
        self._save_voice_inbox()
        if self._owns_engine:
            self.engine.stop()
        if self._owns_engine:
            e.accept()
            super().closeEvent(e)
        else:
            self.hide()
            e.ignore()


class TabLabel(QtWidgets.QLabel):
    clicked = QtCore.pyqtSignal()

    def mousePressEvent(self, e):
        self.clicked.emit()
        super().mousePressEvent(e)


class TopTabs(QtWidgets.QWidget):
    changed = QtCore.pyqtSignal(int)

    def __init__(self, names, parent=None):
        super().__init__(parent)
        self.names = list(names)
        self.labels = []
        self.current = 0
        self._active_px = None
        self._idle_px = None
        self._scale = 1.0
        self._compact = False
        h = QtWidgets.QHBoxLayout(self)
        self._layout = h
        h.setContentsMargins(0, 0, 0, 0)
        h.setSpacing(20)
        for i, n in enumerate(self.names):
            lbl = TabLabel(str(n))
            lbl.setObjectName('dashboard_tab')
            lbl.setAlignment(QtCore.Qt.AlignCenter)
            lbl.setMinimumHeight(48)
            lbl.setSizePolicy(QtWidgets.QSizePolicy.Minimum, QtWidgets.QSizePolicy.Fixed)
            lbl.setFocusPolicy(QtCore.Qt.StrongFocus)
            lbl.setCursor(QtGui.QCursor(QtCore.Qt.PointingHandCursor))
            lbl.setToolTip(f'Open {n.title()}')
            lbl.clicked.connect(lambda i=i: self.changed.emit(i))
            self.labels.append(lbl)
            h.addWidget(lbl)
        self.apply_scale(1.0, False)
        self.set_current(0)

    def apply_scale(self, scale=1.0, compact=False):
        self._scale = max(0.62, float(scale))
        self._compact = bool(compact)
        spacing = int(20 * self._scale * (0.78 if self._compact else 1.0))
        self._layout.setSpacing(max(8, spacing))
        self.setMinimumWidth(0)
        self._layout.setContentsMargins(0, 0, 0, 0)
        tab_height = max(32, int(48 * self._scale))
        for label in self.labels:
            label.setMinimumHeight(tab_height)
        self.set_current(self.current)

    def set_current(self, idx):
        new_idx = max(0, min(idx, len(self.labels) - 1))
        active_px = max(16, int((30 if not self._compact else 24) * self._scale))
        idle_px = max(12, int((24 if not self._compact else 19) * self._scale))
        old_idx = int(self.current)
        sizes_changed = (active_px != self._active_px) or (idle_px != self._idle_px)
        self._active_px = active_px
        self._idle_px = idle_px
        self.current = new_idx

        if sizes_changed:
            for i, lbl in enumerate(self.labels):
                if i == self.current:
                    lbl.setStyleSheet(
                        f'QLabel#dashboard_tab {{ color:#f3f3f3; font-size:{active_px}px; font-weight:300; '
                        'font-family:"Segoe UI Light","Segoe UI","Noto Sans",sans-serif; '
                        'background:transparent; border:0; border-bottom:2px solid rgba(255,255,255,0.86); padding:2px 4px 8px; } '
                        'QLabel#dashboard_tab:hover { color:#ffffff; }'
                    )
                else:
                    lbl.setStyleSheet(
                        f'QLabel#dashboard_tab {{ color:rgba(235,235,235,0.48); font-size:{idle_px}px; font-weight:300; '
                        'font-family:"Segoe UI Light","Segoe UI","Noto Sans",sans-serif; '
                        'background:transparent; border:0; border-bottom:2px solid transparent; padding:2px 4px 8px; } '
                        'QLabel#dashboard_tab:hover { color:rgba(255,255,255,0.92); }'
                    )
            return

        if old_idx == self.current:
            return

        if 0 <= old_idx < len(self.labels):
            self.labels[old_idx].setStyleSheet(
                f'QLabel#dashboard_tab {{ color:rgba(235,235,235,0.48); font-size:{idle_px}px; font-weight:300; '
                'font-family:"Segoe UI Light","Segoe UI","Noto Sans",sans-serif; '
                'background:transparent; border:0; border-bottom:2px solid transparent; padding:2px 4px 8px; } '
                'QLabel#dashboard_tab:hover { color:rgba(255,255,255,0.92); }'
            )
        if 0 <= self.current < len(self.labels):
            self.labels[self.current].setStyleSheet(
                f'QLabel#dashboard_tab {{ color:#f3f3f3; font-size:{active_px}px; font-weight:300; '
                'font-family:"Segoe UI Light","Segoe UI","Noto Sans",sans-serif; '
                'background:transparent; border:0; border-bottom:2px solid rgba(255,255,255,0.86); padding:2px 4px 8px; } '
                'QLabel#dashboard_tab:hover { color:#ffffff; }'
            )


def tile_icon(action, text=''):
    key = f'{action} {text}'.lower()
    cached = _TILE_ICON_CACHE.get(key)
    if cached is not None and not cached.isNull():
        return cached
    style = QtWidgets.QApplication.style()

    def themed(names, fallback):
        for name in names:
            icon = QtGui.QIcon.fromTheme(name)
            if not icon.isNull():
                return icon
        return style.standardIcon(fallback)

    if any(token in key for token in ('steam', 'retroarch', 'lutris', 'heroic', 'runner', 'casino', 'mission', 'game')):
        icon = themed(['steam', 'applications-games', 'input-gaming'], QtWidgets.QStyle.SP_MediaPlay)
    elif any(token in key for token in ('store', 'avatar')):
        icon = themed(['folder-downloads', 'applications-other'], QtWidgets.QStyle.SP_DirIcon)
    elif any(token in key for token in ('music', 'audio', 'playlist', 'visualizer', 'startup sound')):
        icon = themed(['audio-x-generic', 'multimedia-volume-control'], QtWidgets.QStyle.SP_MediaVolume)
    elif any(token in key for token in ('tv', 'movie', 'media', 'youtube', 'netflix', 'kodi', 'video')):
        icon = themed(['video-x-generic', 'applications-multimedia'], QtWidgets.QStyle.SP_MediaPlay)
    elif any(token in key for token in ('social', 'friend', 'message', 'party', 'gamer')):
        icon = themed(['user-available', 'im-user-online'], QtWidgets.QStyle.SP_DirHomeIcon)
    elif any(token in key for token in ('settings', 'system', 'service', 'developer', 'battery', 'power', 'profile')):
        icon = themed(['preferences-system', 'applications-system'], QtWidgets.QStyle.SP_ComputerIcon)
    elif any(token in key for token in ('web', 'browser', 'network', 'lan')):
        icon = themed(['internet-web-browser', 'network-workgroup'], QtWidgets.QStyle.SP_DriveNetIcon)
    elif any(token in key for token in ('turn off', 'exit', 'shutdown')):
        icon = themed(['system-shutdown', 'application-exit'], QtWidgets.QStyle.SP_TitleBarCloseButton)
    else:
        icon = themed(['applications-other'], QtWidgets.QStyle.SP_FileIcon)
    _TILE_ICON_CACHE[key] = icon
    return icon


class GreenTile(QtWidgets.QFrame):
    clicked = QtCore.pyqtSignal(str)

    def __init__(self, action, text, size=(250, 140), parent=None, icon_scale=1.0, text_scale=1.0, dense=False):
        super().__init__(parent)
        self.action = action
        self.text = text
        self.base_size = (int(size[0]), int(size[1]))
        self.icon_scale = max(0.55, float(icon_scale))
        self.text_scale = max(0.65, float(text_scale))
        self.dense = bool(dense)
        self._selected = None
        self._scale_key = None
        self._last_icon_px = None
        self._last_label_px = None
        self.setObjectName('green_tile')
        self.setFocusPolicy(QtCore.Qt.StrongFocus)
        self.setCursor(QtGui.QCursor(QtCore.Qt.PointingHandCursor))
        self.setAccessibleName(f'{text}: {action}')
        v = QtWidgets.QVBoxLayout(self)
        self._layout = v
        v.setContentsMargins(10, 8, 10, 8)
        top = QtWidgets.QHBoxLayout()
        self._top_layout = top
        top.setContentsMargins(0, 0, 0, 0)
        self.icon = QtWidgets.QLabel()
        self.icon.setObjectName('tile_icon')
        self.icon.setFixedSize(52, 52)
        self.icon.setAlignment(QtCore.Qt.AlignCenter)
        icon = tile_icon(action, text)
        self.icon.setPixmap(icon.pixmap(34, 34))
        top.addStretch(1)
        top.addWidget(self.icon, 0, alignment=QtCore.Qt.AlignTop)
        top.addStretch(1)
        v.addLayout(top)
        v.addStretch(1)
        self.lbl = QtWidgets.QLabel(text)
        self.lbl.setStyleSheet('color:#f4fff3; font-size:17px; font-weight:700; font-family:"Segoe UI","Noto Sans",sans-serif;')
        v.addWidget(self.lbl, alignment=QtCore.Qt.AlignLeft | QtCore.Qt.AlignBottom)
        self.apply_scale(1.0, False)
        self.set_selected(False)

    def apply_scale(self, scale=1.0, compact=False):
        s = max(0.58, float(scale))
        compact_factor = 0.96 if compact else 1.0
        if self.dense:
            compact_factor *= 0.93
        w = max(120, int(self.base_size[0] * s * compact_factor))
        h = max(72, int(self.base_size[1] * s * compact_factor))
        pad_x = max(6, int((9 if self.dense else 12) * s * compact_factor))
        pad_y = max(4, int((5 if self.dense else 8) * s * compact_factor))
        icon_sz = max(22, int(52 * s * compact_factor * self.icon_scale))
        pix_sz = max(16, int(34 * s * compact_factor * self.icon_scale))
        font_px = max(10, int(17 * s * compact_factor * self.text_scale))
        scale_key = (w, h, pad_x, pad_y, icon_sz, pix_sz, font_px)
        if scale_key == self._scale_key:
            return
        self._scale_key = scale_key

        if self.size() != QtCore.QSize(w, h):
            self.setFixedSize(w, h)
        margins = self._layout.contentsMargins()
        if (
            margins.left() != pad_x
            or margins.top() != pad_y
            or margins.bottom() != pad_y
            or margins.right() != pad_x
        ):
            self._layout.setContentsMargins(pad_x, pad_y, pad_x, pad_y)
        if self.icon.width() != icon_sz or self.icon.height() != icon_sz:
            self.icon.setFixedSize(icon_sz, icon_sz)
        if self._last_icon_px != pix_sz:
            self._last_icon_px = pix_sz
            icon = tile_icon(self.action, self.text)
            self.icon.setPixmap(icon.pixmap(pix_sz, pix_sz))
        if self._last_label_px != font_px:
            self._last_label_px = font_px
            self.lbl.setStyleSheet(
                f'color:#f4fff3; font-size:{font_px}px; font-weight:700; '
                'font-family:"Segoe UI","Noto Sans",sans-serif;'
            )

    def set_selected(self, on):
        on = bool(on)
        if self._selected is on:
            return
        self._selected = on
        border = 'rgba(245,255,237,0.98)' if on else 'rgba(173,205,174,0.24)'
        width = '2px' if on else '1px'
        bg_a = '#74b82a' if on else '#378b12'
        bg_b = '#4f9b12' if on else '#347f0c'
        self.setStyleSheet(f'''
            QFrame#green_tile {{
                background:qlineargradient(x1:0,y1:0,x2:0,y2:1, stop:0 {bg_a}, stop:1 {bg_b});
                border:{width} solid {border};
                border-radius:0px;
            }}
            QFrame#green_tile:hover {{ border:2px solid #a6ed5c; }}
            QLabel#tile_icon {{
                background:rgba(235,255,220,0.13);
                border:none;
            }}
            QLabel{{color:{'#ffffff' if on else '#e5eee7'};}}
        ''')

    def mousePressEvent(self, e):
        self.clicked.emit(self.action)
        super().mousePressEvent(e)


