                background:#e7eaee;
                border:2px solid rgba(242,247,250,0.9);
            }
            QLabel#title {
                color:#f6f8fb;
                background:#151a1f;
                font-size:34px;
                font-weight:800;
                padding:8px 14px;
            }
            QLabel#body {
                color:#27313a;
                font-size:28px;
                font-weight:700;
            }
            QLabel#detail {
                color:#34414e;
                font-size:17px;
                font-weight:700;
            }
            QProgressBar {
                border:1px solid #c9d3db;
                border-radius:2px;
                background:#dfe4e8;
                height:24px;
                text-align:center;
                color:#1e252c;
                font-size:14px;
                font-weight:800;
            }
            QProgressBar::chunk {
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #37b935, stop:1 #5dd43f);
            }
        ''')
        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        v.setSpacing(0)
        self.lbl_title = QtWidgets.QLabel('Update in Progress')
        self.lbl_title.setObjectName('title')
        v.addWidget(self.lbl_title)
        body = QtWidgets.QWidget()
        body_l = QtWidgets.QVBoxLayout(body)
        body_l.setContentsMargins(28, 28, 28, 20)
        body_l.setSpacing(18)
        self.lbl = QtWidgets.QLabel('Applying update. Do not turn off or unplug your console.')
        self.lbl.setObjectName('body')
        self.lbl.setWordWrap(True)
        body_l.addStretch(1)
        body_l.addWidget(self.lbl)
        self.bar = QtWidgets.QProgressBar()
        self.bar.setRange(0, 100)
        self.bar.setValue(self._progress_value)
        self.bar.setFormat('%p%')
        body_l.addWidget(self.bar)
        self.detail = QtWidgets.QLabel('Preparing update...')
        self.detail.setObjectName('detail')
        self.detail.setTextInteractionFlags(QtCore.Qt.TextSelectableByMouse)
        body_l.addWidget(self.detail)
        body_l.addStretch(1)
        v.addWidget(body, 1)
    def set_stage(self, text, percent):
        try:
            percent = max(self._progress_value, min(94, int(percent)))
        except (TypeError, ValueError):
            percent = self._progress_value
        self._progress_value = percent
        self.bar.setValue(percent)
        self.detail.setText(str(text or 'Applying update...')[:220])

    def set_detail(self, text):
        t = str(text or '').strip()
        if t:
            self.detail.setText(t[:220])

    def _pulse_progress(self):
        if self.isVisible() and self._progress_value < 94:
            self.bar.setValue(min(94, self._progress_value + 1))

    def finish_ok(self):
        self._progress_value = 100
        self.bar.setValue(100)
        self.detail.setText('Update installed successfully. Restarting dashboard...')

    def _center_dialog(self):
        parent = self.parentWidget()
        if parent is not None and parent.isVisible():
            g = parent.frameGeometry()
            x = g.x() + max(0, (g.width() - self.width()) // 2)
            y = g.y() + max(0, (g.height() - self.height()) // 2)
            self.move(x, y)
            return
        scr = QtWidgets.QApplication.screenAt(QtGui.QCursor.pos()) if hasattr(QtWidgets.QApplication, 'screenAt') else None
        if scr is None:
            scr = QtWidgets.QApplication.primaryScreen()
        if scr is None:
            return
        g = scr.availableGeometry()
        x = g.x() + max(0, (g.width() - self.width()) // 2)
        y = g.y() + max(0, (g.height() - self.height()) // 2)
        self.move(x, y)

    def showEvent(self, e):
        super().showEvent(e)
        self._pulse_timer.start(1500)
        QtCore.QTimer.singleShot(0, self._center_dialog)

    def hideEvent(self, e):
        self._pulse_timer.stop()
        super().hideEvent(e)


