            }
            QLabel#title {
                color:#f6f8fb;
                background:#151a1f;
                font-size:34px;
                font-weight:800;
                padding:8px 14px;
            }
            QLabel#app {
                color:#293645;
                font-size:30px;
                font-weight:800;
            }
            QLabel#body {
                color:#27313a;
                font-size:25px;
                font-weight:700;
            }
