                color:#34414e;
                font-size:17px;
                font-weight:700;
            }
            QProgressBar {
                border:1px solid #c9d3db;
                border-radius:2px;
                background:#dfe4e8;
                height:24px;
                text-align:center;
                color:#1e252c;
                font-size:14px;
                font-weight:800;
            }
            QProgressBar::chunk {
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #37b935, stop:1 #5dd43f);
            }
        ''')
        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        v.setSpacing(0)
        self.lbl_title = QtWidgets.QLabel('Install in Progress')
        self.lbl_title.setObjectName('title')
        v.addWidget(self.lbl_title)
        body = QtWidgets.QWidget()
        body_l = QtWidgets.QVBoxLayout(body)
        body_l.setContentsMargins(28, 24, 28, 20)
        body_l.setSpacing(16)
        self.lbl_app = QtWidgets.QLabel(str(app_title or 'App'))
        self.lbl_app.setObjectName('app')
        self.lbl_app.setAlignment(QtCore.Qt.AlignLeft | QtCore.Qt.AlignVCenter)
        body_l.addWidget(self.lbl_app)
        self.lbl = QtWidgets.QLabel('Installing app. Do not turn off or unplug your console.')
        self.lbl.setObjectName('body')
        self.lbl.setWordWrap(True)
        body_l.addWidget(self.lbl)
        self.bar = QtWidgets.QProgressBar()
        self.bar.setRange(0, 100)
        self.bar.setValue(7)
        self.bar.setFormat('%p%')
        body_l.addWidget(self.bar)
        self.detail = QtWidgets.QLabel('Preparing installer...')
        self.detail.setObjectName('detail')
        body_l.addWidget(self.detail)
        body_l.addStretch(1)
        v.addWidget(body, 1)
        self._tick = QtCore.QTimer(self)
        self._tick.timeout.connect(self._pulse)
        self._tick.start(130)

    def _pulse(self):
        cur = self.bar.value()
        target = 93 if self._phase < 1 else 98
        nxt = cur + 1
        if nxt > target:
            nxt = target
        self.bar.setValue(nxt)

    def set_detail(self, text):
        t = str(text or '').strip()
        if t:
            self.detail.setText(t[:220])
        if self.bar.value() < 93:
            self.bar.setValue(min(93, self.bar.value() + 1))

    def finish_ok(self, text='Install completed successfully.'):
        self._phase = 1
        self.bar.setValue(100)
        self.detail.setText(str(text or 'Install completed successfully.'))

    def finish_error(self, text='Install failed.'):
        self._phase = 1
        self.bar.setValue(min(100, max(self.bar.value(), 97)))
        self.detail.setText(str(text or 'Install failed.'))

    def _center_dialog(self):
        parent = self.parentWidget()
        if parent is not None and parent.isVisible():
            g = parent.frameGeometry()
            x = g.x() + max(0, (g.width() - self.width()) // 2)
            y = g.y() + max(0, (g.height() - self.height()) // 2)
            self.move(x, y)
            return
        scr = QtWidgets.QApplication.screenAt(QtGui.QCursor.pos()) if hasattr(QtWidgets.QApplication, 'screenAt') else None
        if scr is None:
            scr = QtWidgets.QApplication.primaryScreen()
        if scr is None:
            return
        g = scr.availableGeometry()
        x = g.x() + max(0, (g.width() - self.width()) // 2)
        y = g.y() + max(0, (g.height() - self.height()) // 2)
        self.move(x, y)

    def showEvent(self, e):
        super().showEvent(e)
        QtCore.QTimer.singleShot(0, self._center_dialog)


class VerticalTextLabel(QtWidgets.QLabel):
    def __init__(self, text='', clockwise=False, parent=None):
        super().__init__(text, parent)
        self._clockwise = bool(clockwise)
        self.setAlignment(QtCore.Qt.AlignCenter)

    def sizeHint(self):
        s = super().sizeHint()
        return QtCore.QSize(s.height() + 8, s.width() + 8)

    def minimumSizeHint(self):
        s = super().minimumSizeHint()
        return QtCore.QSize(s.height() + 8, s.width() + 8)

    def paintEvent(self, _event):
        painter = QtGui.QPainter(self)
        painter.setRenderHint(QtGui.QPainter.Antialiasing, True)
        painter.setRenderHint(QtGui.QPainter.TextAntialiasing, True)
        if self._clockwise:
            painter.translate(self.width(), 0)
            painter.rotate(90)
        else:
            painter.translate(0, self.height())
            painter.rotate(-90)
        rect = QtCore.QRect(0, 0, self.height(), self.width())
        painter.setPen(self.palette().windowText().color())
        painter.setFont(self.font())
        painter.drawText(rect, QtCore.Qt.AlignCenter, self.text())
        painter.end()


class GuideSideBlade(QtWidgets.QFrame):
    activated = QtCore.pyqtSignal(int)

    def __init__(self, clockwise=False, width=44, parent=None):
        super().__init__(parent)
        self._section_idx = 0
        self._active = False
        self._clockwise = bool(clockwise)
        self.setFixedWidth(max(28, int(width)))
        self.setCursor(QtGui.QCursor(QtCore.Qt.PointingHandCursor))
        lay = QtWidgets.QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        self.label = VerticalTextLabel('', clockwise=self._clockwise)
        self.label.setAlignment(QtCore.Qt.AlignCenter)
        lay.addWidget(self.label, 1)
        self._apply_style()

    def set_payload(self, section_idx, text, active=False):
        self._section_idx = int(section_idx)
        self.label.setText(str(text or ''))
        self._active = bool(active)
        self._apply_style()

    def _apply_style(self):
        if self._active:
            bg0, bg1, fg, bdr = '#e5e9ed', '#ccd3da', '#303943', 'rgba(255,255,255,0.88)'
            fs = 13
            fw = 800
        elif self._section_idx == 2:
            bg0, bg1, fg, bdr = '#46535e', '#35414b', '#f5f7fa', 'rgba(236,245,253,0.74)'
            fs = 12
            fw = 700
        elif self._section_idx in (0, 3):
            bg0, bg1, fg, bdr = '#e5e9ed', '#ccd3da', '#303943', 'rgba(255,255,255,0.74)'
            fs = 12
            fw = 700
        else:
            bg0, bg1, fg, bdr = '#687fb9', '#526aa5', '#f5f7ff', 'rgba(236,245,253,0.74)'
            fs = 12
            fw = 700
        self.setStyleSheet(
            f'''
            QFrame {{
                background:qlineargradient(x1:0,y1:0,x2:0,y2:1, stop:0 {bg0}, stop:1 {bg1});
                border:1px solid {bdr};
                border-radius:0px;
            }}
            '''
        )
        self.label.setStyleSheet(
            f'color:{fg}; font-size:{fs}px; font-weight:{fw}; font-family:"Segoe UI","Noto Sans",sans-serif;'
        )

    def mousePressEvent(self, e):
        self.activated.emit(int(self._section_idx))
        super().mousePressEvent(e)


class GuideMenuDelegate(QtWidgets.QStyledItemDelegate):
    def paint(self, painter, option, index):
        rect = option.rect
        row_data = index.data(QtCore.Qt.UserRole)
        row_data = row_data if isinstance(row_data, dict) else {}
        selected = bool(option.state & QtWidgets.QStyle.State_Selected)
        painter.save()
        if selected:
            gradient = QtGui.QLinearGradient(rect.topLeft(), rect.topRight())
            gradient.setColorAt(0.0, QtGui.QColor('#61bb43'))
            gradient.setColorAt(1.0, QtGui.QColor('#43a735'))
            painter.fillRect(rect, gradient)
        else:
            painter.fillRect(rect, QtGui.QColor('#e8ebee'))
        painter.setPen(QtGui.QColor(255, 255, 255, 55) if selected else QtGui.QColor(38, 48, 62, 34))
        painter.drawLine(rect.bottomLeft(), rect.bottomRight())
        painter.setPen(QtGui.QColor('#ffffff' if selected else '#26303a'))
        font = QtGui.QFont(option.font)
        font.setPointSize(17)
        font.setWeight(QtGui.QFont.Medium)
        painter.setFont(font)
        left = rect.adjusted(14, 0, -150, 0)
        painter.drawText(left, QtCore.Qt.AlignVCenter | QtCore.Qt.AlignLeft, str(index.data(QtCore.Qt.DisplayRole) or ''))
        icon = str(row_data.get('icon') or '')
        count = row_data.get('count')
        if count is not None:
            painter.setPen(QtGui.QColor('#ffffff' if selected else '#68717a'))
            painter.drawText(rect.adjusted(0, 0, -43, 0), QtCore.Qt.AlignVCenter | QtCore.Qt.AlignRight, str(count))
        if icon:
            painter.setPen(QtGui.QColor('#ffffff' if selected else '#68717a'))
            painter.drawText(rect.adjusted(0, 0, -15, 0), QtCore.Qt.AlignVCenter | QtCore.Qt.AlignRight, icon)
        painter.restore()

    def sizeHint(self, option, index):
        return QtCore.QSize(300, 41)


class XboxGuideMenu(QtWidgets.QDialog):
    def __init__(self, gamertag='Player1', parent=None, sfx_cb=None, mode='dashboard'):
        super().__init__(parent)
        self.gamertag = str(gamertag or 'Player1')
        self.mode = 'app' if str(mode or '').strip().lower() == 'app' else 'dashboard'
        self._play_sfx = sfx_cb
        self._selection = None
        self._open_anim = None
        self._page_anim = None
        self._blade_anim = None
        self._shortcuts = []
        self._last_row = 0
        self._section_idx = 0
        self._sections = self._build_sections()
        self._section_lists = []
        self.setWindowTitle('Xbox Guide')
        self.setWindowFlags(
            QtCore.Qt.Dialog
            | QtCore.Qt.FramelessWindowHint
            | QtCore.Qt.WindowStaysOnTopHint
        )
        self.setAttribute(QtCore.Qt.WA_TranslucentBackground, True)
        self.setModal(True)
        screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            self.setGeometry(screen.geometry())
        else:
            self.resize(980, 520)
        self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
        self.setStyleSheet('''
            QDialog { background:rgba(13, 19, 22, 0.78); }
            QFrame#xguide_panel {
                background:qlineargradient(x1:0,y1:0,x2:0,y2:1, stop:0 #727b80, stop:1 #a8afb2);
                border:2px solid #dfe5e6;
