        self.uninstall_btn = QtWidgets.QPushButton('Uninstall')
        self.close_btn = QtWidgets.QPushButton('Close')
        for b in (self.play_btn, self.install_btn, self.uninstall_btn, self.close_btn):
            b.setObjectName('gio_btn')
            row.addWidget(b, 0)
