        root.addLayout(row)

        self.hint = QtWidgets.QLabel('A/ENTER = Open | X/SPACE = Install | Y/TAB = Uninstall | B/ESC = Back')
        self.hint.setObjectName('gio_hint')
        root.addWidget(self.hint, 0, QtCore.Qt.AlignLeft)

        self.play_btn.clicked.connect(self._play_current)
        self.install_btn.clicked.connect(self._install_current)
        self.uninstall_btn.clicked.connect(self._uninstall_current)
        self.close_btn.clicked.connect(self.close_overlay)
        self.blade_my_games.clicked.connect(lambda: self._focus_label('My Games'))
        self.blade_browse.clicked.connect(lambda: self.actionTriggered.emit('Browse Games'))
        self.blade_search.clicked.connect(lambda: self.actionTriggered.emit('Search Games'))

    def set_items(self, items, title='My Games'):
        self._items = list(items or [])
        self._item_index = {}
        self.title.setText(str(title or 'My Games'))
        self.listw.clear()
        for idx, item in enumerate(self._items):
            label = str(item.get('label', 'Item'))
            it = QtWidgets.QListWidgetItem(label)
            it.setData(QtCore.Qt.UserRole, dict(item))
            self.listw.addItem(it)
            self._item_index[label.strip().lower()] = idx
        if self.listw.count() > 0:
            self.listw.setCurrentRow(0)
        self._update_meta(self.listw.currentRow())

    def _focus_label(self, label):
        key = str(label or '').strip().lower()
        idx = self._item_index.get(key)
        if idx is None:
            return
        self.listw.setCurrentRow(int(idx))
        self.listw.scrollToItem(self.listw.item(int(idx)), QtWidgets.QAbstractItemView.PositionAtCenter)
        self.listw.setFocus()

    def _current_payload(self):
        it = self.listw.currentItem()
        if it is None:
            return {}
        data = it.data(QtCore.Qt.UserRole)
        return data if isinstance(data, dict) else {}

    def _update_meta(self, _row):
        data = self._current_payload()
        label = str(data.get('label', 'My Games')).strip() or 'My Games'
        desc = str(data.get('desc', 'Select a game/app tile.')).strip()
        self.meta.setText(desc or 'Select a game/app tile.')
        self.featured_title.setText(label)
        self.featured_desc.setText(desc or 'Select a game/app tile.')

    def _play_current(self):
        data = self._current_payload()
        action = str(data.get('play', '')).strip()
        if action:
            self.actionTriggered.emit(action)

    def _install_current(self):
        data = self._current_payload()
        action = str(data.get('install', '')).strip()
        if action:
            self.actionTriggered.emit(action)

    def _uninstall_current(self):
        data = self._current_payload()
        action = str(data.get('uninstall', '')).strip()
        if action:
            self.actionTriggered.emit(action)

    def open_overlay(self):
        self.setVisible(True)
        self.raise_()
        self.activateWindow()
        self.setFocus()
        self.listw.setFocus()
        effect = QtWidgets.QGraphicsOpacityEffect(self)
        self.setGraphicsEffect(effect)
        effect.setOpacity(0.0)
        end_rect = self.geometry()
        start_rect = QtCore.QRect(end_rect.x() + 20, end_rect.y(), end_rect.width(), end_rect.height())
        self.setGeometry(start_rect)
        grp = QtCore.QParallelAnimationGroup(self)
        fade = QtCore.QPropertyAnimation(effect, b'opacity', self)
        fade.setDuration(170)
        fade.setStartValue(0.0)
        fade.setEndValue(1.0)
        fade.setEasingCurve(QtCore.QEasingCurve.OutCubic)
        slide = QtCore.QPropertyAnimation(self, b'geometry', self)
        slide.setDuration(210)
        slide.setStartValue(start_rect)
        slide.setEndValue(end_rect)
        slide.setEasingCurve(QtCore.QEasingCurve.OutCubic)
        grp.addAnimation(fade)
        grp.addAnimation(slide)
        grp.finished.connect(lambda: self.setGraphicsEffect(None))
        grp.start(QtCore.QAbstractAnimation.DeleteWhenStopped)

    def close_overlay(self):
        if not self.isVisible():
            return
        self.setVisible(False)
        self.closed.emit()

    def keyPressEvent(self, e):
        k = e.key()
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.close_overlay()
            return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            self._play_current()
            return
        if k == QtCore.Qt.Key_Space:
            self._install_current()
            return
        if k == QtCore.Qt.Key_Tab:
            self._uninstall_current()
            return
        if k in (QtCore.Qt.Key_PageUp, QtCore.Qt.Key_PageDown):
            n = int(self.listw.count())
            if n > 0:
                step = -6 if k == QtCore.Qt.Key_PageUp else 6
                row = int(self.listw.currentRow())
                if row < 0:
                    row = 0
                row = max(0, min(n - 1, row + step))
                self.listw.setCurrentRow(row)
            return
        super().keyPressEvent(e)


class VirtualKeyboardDialog(QtWidgets.QDialog):
    def __init__(self, initial='', parent=None, sfx_cb=None):
        super().__init__(parent)
        self._play_sfx = sfx_cb
        self._nav_default_cols = 10
        self.setWindowTitle('Virtual Keyboard')
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        self.setModal(True)
        self.resize(920, 420)
        self.setStyleSheet('''
            QDialog { background:#d2d7dc; border:2px solid #e8edf1; }
            QLineEdit { background:#ffffff; border:1px solid #8a96a3; color:#1e2731; font-size:24px; font-weight:700; padding:8px; }
            QListWidget { background:#eef2f5; border:1px solid #9da8b3; color:#24303b; font-size:18px; font-weight:800; outline:none; }
            QListWidget::item { border:1px solid #c1c9d2; min-width:74px; min-height:46px; margin:4px; }
            QListWidget::item:selected { background:#66b340; color:#fff; border:2px solid #2f6e28; }
            QLabel { color:#2f3944; font-size:14px; font-weight:700; }
        ''')
        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(12, 10, 12, 10)
        v.setSpacing(8)
        self.edit = QtWidgets.QLineEdit(str(initial or ''))
        self.edit.setFocusPolicy(QtCore.Qt.ClickFocus)
        self.edit.installEventFilter(self)
        v.addWidget(self.edit)
        self.keys = QtWidgets.QListWidget()
        self.keys.setViewMode(QtWidgets.QListView.IconMode)
        self.keys.setMovement(QtWidgets.QListView.Static)
        self.keys.setResizeMode(QtWidgets.QListView.Adjust)
        self.keys.setWrapping(True)
        self.keys.setSpacing(4)
        self.keys.setGridSize(QtCore.QSize(84, 54))
        self.keys.itemActivated.connect(self._activate_current)
        self.keys.installEventFilter(self)
        for token in list("1234567890QWERTYUIOPASDFGHJKLZXCVBNM") + ['-', '_', '@', '.', '/', ':', 'SPACE', 'BACK', 'CLEAR', 'DONE']:
            self.keys.addItem(QtWidgets.QListWidgetItem(token))
        self.keys.setCurrentRow(0)
        self.keys.setFocus(QtCore.Qt.OtherFocusReason)
        v.addWidget(self.keys, 1)
        v.addWidget(QtWidgets.QLabel('A/ENTER = Select | B/ESC = Back | X = Backspace | Y = Space'))

    def text(self):
        return self.edit.text()

    def _sfx(self):
        if callable(self._play_sfx):
            try:
                self._play_sfx('select')
            except Exception:
                pass

    def _activate_current(self):
        it = self.keys.currentItem()
        if it is None:
            return
        key = str(it.text() or '')
        self._sfx()
        if key == 'DONE':
            self.accept()
            return
        if key == 'SPACE':
            self.edit.setText(self.edit.text() + ' ')
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if key == 'BACK':
            self.edit.setText(self.edit.text()[:-1])
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if key == 'CLEAR':
            self.edit.setText('')
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        self.edit.setText(self.edit.text() + key)
        self.keys.setFocus(QtCore.Qt.OtherFocusReason)

    def _nav_cols(self):
        try:
            grid_w = int(self.keys.gridSize().width())
            view_w = int(self.keys.viewport().width())
            cols = max(1, view_w // max(1, grid_w))
            return cols
        except Exception:
            return self._nav_default_cols

    def _move_selection(self, dr=0, dc=0):
        total = int(self.keys.count())
        if total <= 0:
            return
        cols = max(1, int(self._nav_cols() or self._nav_default_cols))
        idx = int(self.keys.currentRow())
        if idx < 0:
            idx = 0
        row = idx // cols
        col = idx % cols
        row += int(dr)
        col += int(dc)
        max_row = (total - 1) // cols
        row = max(0, min(max_row, row))
        col = max(0, col)
        row_start = row * cols
        row_end = min(total - 1, row_start + cols - 1)
        new_idx = min(row_end, row_start + col)
        self.keys.setCurrentRow(new_idx)
        it = self.keys.currentItem()
        if it is not None:
            self.keys.scrollToItem(it, QtWidgets.QAbstractItemView.PositionAtCenter)

    def eventFilter(self, obj, event):
        if event.type() == QtCore.QEvent.KeyPress:
            if event.key() in (
                QtCore.Qt.Key_Left, QtCore.Qt.Key_Right,
                QtCore.Qt.Key_Up, QtCore.Qt.Key_Down,
                QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter,
                QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back,
                QtCore.Qt.Key_Space, QtCore.Qt.Key_Backspace,
            ):
                self.keyPressEvent(event)
                return True
        return super().eventFilter(obj, event)

    def keyPressEvent(self, e):
        k = e.key()
        if k in (QtCore.Qt.Key_Left,):
            self._move_selection(0, -1)
            return
        if k in (QtCore.Qt.Key_Right,):
            self._move_selection(0, 1)
            return
        if k in (QtCore.Qt.Key_Up,):
            self._move_selection(-1, 0)
            return
        if k in (QtCore.Qt.Key_Down,):
            self._move_selection(1, 0)
            return
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.reject()
            return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            self._activate_current()
            return
        if k == QtCore.Qt.Key_Space:
            self._sfx()
            self.edit.setText(self.edit.text() + ' ')
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if k == QtCore.Qt.Key_Backspace:
            self._sfx()
            self.edit.setText(self.edit.text()[:-1])
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        super().keyPressEvent(e)


class EscInputDialog(QtWidgets.QInputDialog):
    def keyPressEvent(self, e):
        if e.key() in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.reject()
            return
        super().keyPressEvent(e)


class WebKioskWindow(QtWidgets.QMainWindow):
    def __init__(self, url, parent=None, sfx_cb=None):
        super().__init__(parent)
        self._play_sfx = sfx_cb
        self._ultra_low_ram = ultra_low_ram_mode()
        self._gp = None
        self._gp_prev = {}
        self._gp_timer = None
        self._gp_repeat_at = {}
        self.setWindowTitle(url)
        self.setAttribute(QtCore.Qt.WA_DeleteOnClose, True)
        self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
        self.resize(1280, 720)
        self.setStyleSheet('background:#000;')
        self.view = QtWebEngineWidgets.QWebEngineView(self)
        self._configure_web_runtime()
        self._browser_stack = QtWidgets.QStackedWidget(self)
        self._browser_stack.addWidget(self.view)
        self._browser_error_page = QtWidgets.QWidget(self._browser_stack)
        error_layout = QtWidgets.QVBoxLayout(self._browser_error_page)
        error_layout.setContentsMargins(32, 24, 32, 24)
        error_layout.addStretch(1)
        error_card = QtWidgets.QFrame()
        error_card.setStyleSheet(
            'QFrame{background:#202830;border:1px solid #53616d;border-radius:12px;}'
            'QLabel{color:#f2f5f7;} QPushButton{background:#318b48;color:white;'
            'border:0;border-radius:6px;padding:10px 18px;font-weight:700;}'
            'QPushButton:focus{background:#43ae5e;}'
        )
        error_card.setMaximumWidth(760)
        card_layout = QtWidgets.QVBoxLayout(error_card)
        card_layout.setContentsMargins(28, 24, 28, 24)
        error_title = QtWidgets.QLabel('No se pudo cargar la página')
        error_title.setStyleSheet('font-size:28px;font-weight:800;border:0;')
        card_layout.addWidget(error_title)
        error_message = QtWidgets.QLabel(
            'Comprueba que Debian tenga conexión a Internet y pueda resolver DNS. '
            'Si continúa en blanco, puede faltar una biblioteca gráfica de QtWebEngine.'
        )
        error_message.setWordWrap(True)
        error_message.setStyleSheet('font-size:17px;border:0;')
        card_layout.addWidget(error_message)
        self._browser_error_url = QtWidgets.QLabel()
        self._browser_error_url.setWordWrap(True)
        self._browser_error_url.setStyleSheet('color:#b8c4ce;font-size:13px;border:0;')
        card_layout.addWidget(self._browser_error_url)
        error_buttons = QtWidgets.QHBoxLayout()
        self._browser_retry_button = QtWidgets.QPushButton('Reintentar')
        self._browser_retry_button.clicked.connect(self._retry_browser_load)
        self._browser_external_button = QtWidgets.QPushButton('Abrir navegador externo')
        self._browser_external_button.clicked.connect(self._open_external_browser)
        error_buttons.addWidget(self._browser_retry_button)
        error_buttons.addWidget(self._browser_external_button)
        error_buttons.addStretch(1)
        card_layout.addLayout(error_buttons)
        error_layout.addWidget(error_card, 0, QtCore.Qt.AlignHCenter)
        error_layout.addStretch(1)
        self._browser_stack.addWidget(self._browser_error_page)
        self.setCentralWidget(self._browser_stack)
        self.view.loadStarted.connect(lambda: self._browser_stack.setCurrentWidget(self.view))
        self.view.loadFinished.connect(self._on_browser_load_finished)
        try:
            self.view.page().renderProcessTerminated.connect(self._on_browser_renderer_terminated)
        except Exception:
            pass
        self.view.load(QtCore.QUrl(url))
        self.keyboard_button = QtWidgets.QPushButton('KB', self)
        self.keyboard_button.setToolTip(
            'Keyboard: arrows/Tab navigate, Enter/Space activate, Ctrl+L address/search, '
            'Alt+Left/Right history, F2/Ctrl+K type, Ctrl+W close. '
            'Controller: D-pad navigates, A selects, X keyboard, Y address, LB/RB history, B back.'
        )
        self.keyboard_button.setAccessibleName('Browser controls and on-screen keyboard')
        self.keyboard_button.setFixedSize(58, 48)
        self.keyboard_button.setStyleSheet(
            'QPushButton{background:rgba(24,35,42,0.92);color:#f3f7f8;'
            'border:1px solid rgba(255,255,255,0.44);font-size:17px;font-weight:800;}'
            'QPushButton:hover,QPushButton:focus{background:#358f4a;}'
        )
        self.keyboard_button.clicked.connect(self._open_virtual_keyboard_for_page)
        self.keyboard_button.raise_()
        self._close_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+W'), self)
        self._close_shortcut.activated.connect(self.close)
        self._kbd = QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_F2), self)
        self._kbd.activated.connect(self._open_virtual_keyboard_for_page)
        self._kbd2 = QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+K'), self)
        self._kbd2.activated.connect(self._open_virtual_keyboard_for_page)
        self._address_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+L'), self)
        self._address_shortcut.activated.connect(self._open_address_prompt)
        self._reload_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+R'), self)
        self._reload_shortcut.activated.connect(self.view.reload)
        self._reload_f5 = QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_F5), self)
        self._reload_f5.activated.connect(self.view.reload)
        self._back_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence('Alt+Left'), self)
        self._back_shortcut.activated.connect(self._go_back)
        self._forward_shortcut = QtWidgets.QShortcut(QtGui.QKeySequence('Alt+Right'), self)
        self._forward_shortcut.activated.connect(self._go_forward)
        self._guide = QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_F1), self)
        self._guide.activated.connect(self._show_guide)
        self._guide2 = QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_Home), self)
        self._guide2.activated.connect(self._show_guide)
        self._guide_keys = {QtCore.Qt.Key_F1, QtCore.Qt.Key_Home, QtCore.Qt.Key_Meta}
        key_super_l = getattr(QtCore.Qt, 'Key_Super_L', None)
        key_super_r = getattr(QtCore.Qt, 'Key_Super_R', None)
        if key_super_l is not None:
            self._guide_keys.add(key_super_l)
        if key_super_r is not None:
            self._guide_keys.add(key_super_r)
        self._guide_shortcuts = []
        self._setup_gamepad()

    def _on_browser_load_finished(self, ok):
        if ok:
            self._browser_stack.setCurrentWidget(self.view)
            self.setWindowTitle(self.view.title() or self.view.url().toString())
            self.view.setFocus(QtCore.Qt.OtherFocusReason)
            return
        self._browser_error_url.setText(self.view.url().toString())
        self._browser_stack.setCurrentWidget(self._browser_error_page)

    def _on_browser_renderer_terminated(self, *details):
        detail = ', '.join(str(item) for item in details)
        self._browser_error_url.setText(
            'El proceso Chromium de QtWebEngine se cerró' + (f' ({detail})' if detail else '')
        )
        self._browser_stack.setCurrentWidget(self._browser_error_page)

    def _retry_browser_load(self):
        self._browser_stack.setCurrentWidget(self.view)
        self.view.reload()

    def _open_external_browser(self):
        url = self.view.url()
        if url.isValid():
            QtGui.QDesktopServices.openUrl(url)

    def _configure_web_runtime(self):
        if QtWebEngineWidgets is None or self.view is None:
            return
        try:
            page = self.view.page()
        except Exception:
            page = None
        if page is None:
            return
        try:
            settings = page.settings()
            attrs = (
                ('JavascriptEnabled', True),
                ('LocalStorageEnabled', True),
                ('PluginsEnabled', True),
                ('FullScreenSupportEnabled', True),
                ('PlaybackRequiresUserGesture', False),
                ('WebGLEnabled', True),
                ('Accelerated2dCanvasEnabled', True),
            )
            for name, value in attrs:
                attr = getattr(QtWebEngineWidgets.QWebEngineSettings, name, None)
                if attr is not None:
                    settings.setAttribute(attr, bool(value))
        except Exception:
            pass
        try:
            profile = page.profile()
        except Exception:
            profile = None
        if profile is None:
            return
        try:
            cache_dir = DATA_HOME / 'webengine-cache'
            storage_dir = DATA_HOME / 'webengine-profile'
            cache_dir.mkdir(parents=True, exist_ok=True)
            storage_dir.mkdir(parents=True, exist_ok=True)
            profile.setCachePath(str(cache_dir))
            profile.setPersistentStoragePath(str(storage_dir))
            profile.setHttpCacheType(QtWebEngineWidgets.QWebEngineProfile.DiskHttpCache)
            if self._ultra_low_ram:
                try:
                    profile.setHttpCacheMaximumSize(16 * 1024 * 1024)
                except Exception:
                    pass
            profile.setPersistentCookiesPolicy(QtWebEngineWidgets.QWebEngineProfile.ForcePersistentCookies)
        except Exception:
            pass

    def _sfx(self, name='select'):
        if callable(self._play_sfx):
            try:
                self._play_sfx(name)
            except Exception:
                pass

    def _inject_text(self, text):
        payload = json.dumps(str(text or ''))
        js = f"""
(() => {{
  const el = document.activeElement;
  if (!el) return false;
  const tag = (el.tagName || '').toLowerCase();
  const tp = (el.type || '').toLowerCase();
  const editable = el.isContentEditable || tag === 'textarea' ||
    (tag === 'input' && !['button','submit','checkbox','radio','range','color','file','image','reset'].includes(tp));
  if (!editable) return false;
    const txt = {payload};
  if (el.isContentEditable) {{
    try {{ document.execCommand('insertText', false, txt); }} catch (_e) {{ el.textContent = (el.textContent || '') + txt; }}
  }} else {{
        const proto = tag === 'textarea' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
        const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
        const value = el.value || '';
        const start = Number.isInteger(el.selectionStart) ? el.selectionStart : value.length;
        const end = Number.isInteger(el.selectionEnd) ? el.selectionEnd : start;
        const next = value.slice(0, start) + txt + value.slice(end);
        if (setter) setter.call(el, next); else el.value = next;
        try {{ el.setSelectionRange(start + txt.length, start + txt.length); }} catch (_e) {{}}
  }}
    el.dispatchEvent(new InputEvent('input', {{ bubbles: true, inputType: 'insertText', data: txt }}));
  el.dispatchEvent(new Event('change', {{ bubbles: true }}));
  return true;
}})();
"""
        self.view.page().runJavaScript(js)
        self.view.setFocus(QtCore.Qt.OtherFocusReason)

    def _open_virtual_keyboard_for_page(self):
        self._sfx('open')
        d = VirtualKeyboardDialog('', self, sfx_cb=self._play_sfx)
        if d.exec_() == QtWidgets.QDialog.Accepted:
            txt = d.text()
            if txt:
                self._inject_text(txt)
                self._sfx('select')
            return
        self._sfx('back')

    def _open_keyboard_if_editable(self):
        probe = """
(() => {
  const el = document.activeElement;
  if (!el) return false;
  const tag = (el.tagName || '').toLowerCase();
  const tp = (el.type || '').toLowerCase();
  return !!(el.isContentEditable || tag === 'textarea' ||
    (tag === 'input' && !['button','submit','checkbox','radio','range','color','file','image','reset'].includes(tp)));
})();
"""
        def cb(editable):
            if bool(editable):
                self._open_virtual_keyboard_for_page()
            else:
                self._forward_enter_to_view()
        self.view.page().runJavaScript(probe, cb)

    def _forward_enter_to_view(self):
        self.view.setFocus()
        press = QtGui.QKeyEvent(QtCore.QEvent.KeyPress, QtCore.Qt.Key_Return, QtCore.Qt.NoModifier)
        rel = QtGui.QKeyEvent(QtCore.QEvent.KeyRelease, QtCore.Qt.Key_Return, QtCore.Qt.NoModifier)
        QtWidgets.QApplication.postEvent(self.view, press)
        QtWidgets.QApplication.postEvent(self.view, rel)

    def _show_guide(self):
        parent = self.parentWidget()
        gamertag = 'Player1'
        if parent is not None and hasattr(parent, '_gamertag'):
            try:
                gamertag = str(parent._gamertag())
            except Exception:
                pass
        d = XboxGuideMenu(gamertag, self, sfx_cb=self._play_sfx, mode='app')
        if d.exec_() != QtWidgets.QDialog.Accepted:
            self._sfx('back')
            return
        sel = str(d.selected() or '').strip()
        if not sel:
            return
        if sel in ('Cerrar app actual', 'Close Current App', 'Leave Game'):
            self.close()
            return
        if parent is not None and hasattr(parent, '_handle_xbox_guide_action'):
            try:
                parent._handle_xbox_guide_action(sel)
            except Exception:
                pass

    def _setup_gamepad(self):
        if QtGamepad is None:
            return
        try:
            mgr = QtGamepad.QGamepadManager.instance()
            ids = list(mgr.connectedGamepads())
            if not ids:
                return
            self._gp = QtGamepad.QGamepad(ids[0], self)
            self._gp_timer = QtCore.QTimer(self)
            self._gp_timer.timeout.connect(self._poll_gamepad)
            self._gp_timer.start(95 if self._ultra_low_ram else 75)
        except Exception:
            self._gp = None

    def _gpv(self, name, default=0.0):
        gp = self._gp
        if gp is None:
            return default
        v = getattr(gp, name, None)
        try:
            return v() if callable(v) else v
        except Exception:
            return default

    def _send_key_to_view(self, key):
        dialog = self._active_virtual_keyboard()
        if dialog is not None:
            target = QtWidgets.QApplication.focusWidget() or dialog
        else:
            self.view.setFocus(QtCore.Qt.OtherFocusReason)
            target = self.view
        press = QtGui.QKeyEvent(QtCore.QEvent.KeyPress, key, QtCore.Qt.NoModifier)
        rel = QtGui.QKeyEvent(QtCore.QEvent.KeyRelease, key, QtCore.Qt.NoModifier)
        QtWidgets.QApplication.postEvent(target, press)
        QtWidgets.QApplication.postEvent(target, rel)

    def _active_virtual_keyboard(self):
        modal = QtWidgets.QApplication.activeModalWidget()
        if isinstance(modal, VirtualKeyboardDialog) and modal.isVisible():
            return modal
        for widget in QtWidgets.QApplication.topLevelWidgets():
            if isinstance(widget, VirtualKeyboardDialog) and widget.isVisible():
                return widget
        return None

    def _go_back(self):
        self.view.back()

    def _navigate_back_or_close(self):
        if self.view.history().canGoBack():
            self._go_back()
        else:
            self.close()

    def _open_address_prompt(self):
        current = self.view.url().toString()
        dialog = EscInputDialog(self)
        dialog.setWindowTitle('Open web address')
        dialog.setLabelText('URL or search query')
        dialog.setInputMode(QtWidgets.QInputDialog.TextInput)
        dialog.setTextValue(current)
        if dialog.exec_() == QtWidgets.QDialog.Accepted:
            value = str(dialog.textValue() or '').strip()
            if value:
                self._load_address(value)

    def _open_address_with_virtual_keyboard(self):
        dialog = VirtualKeyboardDialog(self.view.url().toString(), self, sfx_cb=self._play_sfx)
        if dialog.exec_() == QtWidgets.QDialog.Accepted:
            self._load_address(dialog.text())

    def _load_address(self, raw):
        value = str(raw or '').strip()
        if not value:
            return
        if '://' not in value and ' ' in value:
            value = 'https://www.google.com/search?q=' + urllib.parse.quote_plus(value)
        elif '://' not in value:
            value = 'https://' + value
        self.view.load(QtCore.QUrl(value))

    def _go_forward(self):
        self.view.forward()

    def _poll_gamepad(self):
        gp = self._gp
        if gp is None:
            return
        cur = {
            'left': bool(self._gpv('buttonLeft', False)) or float(self._gpv('axisLeftX', 0.0)) < -0.6,
            'right': bool(self._gpv('buttonRight', False)) or float(self._gpv('axisLeftX', 0.0)) > 0.6,
            'up': bool(self._gpv('buttonUp', False)) or float(self._gpv('axisLeftY', 0.0)) < -0.6,
            'down': bool(self._gpv('buttonDown', False)) or float(self._gpv('axisLeftY', 0.0)) > 0.6,
            'a': bool(self._gpv('buttonA', False)),
            'b': bool(self._gpv('buttonB', False)),
            'x': bool(self._gpv('buttonX', False)),
            'y': bool(self._gpv('buttonY', False)),
            'guide': bool(self._gpv('buttonGuide', False)),
            'lb': bool(self._gpv('buttonL1', False)),
            'rb': bool(self._gpv('buttonR1', False)),
        }

        def pressed(name):
            return cur.get(name, False) and not self._gp_prev.get(name, False)

        vk = self._active_virtual_keyboard()
        if vk is not None:
            if pressed('guide') or pressed('b'):
                self._send_key_to_view(QtCore.Qt.Key_Escape)
            elif pressed('a'):
                self._send_key_to_view(QtCore.Qt.Key_Return)
            elif pressed('y'):
                self._send_key_to_view(QtCore.Qt.Key_Space)
            elif pressed('x'):
                self._send_key_to_view(QtCore.Qt.Key_Backspace)
            else:
                now = time.monotonic()
                for name, key in (
                    ('left', QtCore.Qt.Key_Left), ('right', QtCore.Qt.Key_Right),
                    ('up', QtCore.Qt.Key_Up), ('down', QtCore.Qt.Key_Down),
                ):
                    if not cur.get(name, False):
                        self._gp_repeat_at.pop(name, None)
                        continue
                    repeat_at = self._gp_repeat_at.get(name, 0.0)
                    if pressed(name) or now >= repeat_at:
                        self._send_key_to_view(key)
                        self._gp_repeat_at[name] = now + (0.34 if pressed(name) else 0.11)
                        break
            self._gp_prev = cur
            return

        if pressed('guide'):
            self._show_guide()
        elif pressed('y'):
            self._open_address_with_virtual_keyboard()
        elif pressed('b'):
            self._navigate_back_or_close()
        elif pressed('x'):
            self._open_virtual_keyboard_for_page()
        elif pressed('lb'):
            self._go_back()
        elif pressed('rb'):
            self._go_forward()
        elif pressed('a'):
            self._open_keyboard_if_editable()
        else:
            now = time.monotonic()
            directions = (
                ('left', QtCore.Qt.Key_Left),
                ('right', QtCore.Qt.Key_Right),
                ('up', QtCore.Qt.Key_Up),
                ('down', QtCore.Qt.Key_Down),
            )
            for name, key in directions:
                if not cur.get(name, False):
                    self._gp_repeat_at.pop(name, None)
                    continue
                repeat_at = self._gp_repeat_at.get(name, 0.0)
                if pressed(name):
                    self._send_key_to_view(key)
                    self._gp_repeat_at[name] = now + 0.34
                    break
                if now >= repeat_at:
                    self._send_key_to_view(key)
                    self._gp_repeat_at[name] = now + 0.11
                    break
        self._gp_prev = cur

    def keyPressEvent(self, e):
        k = e.key()
        if k in self._guide_keys:
            self._show_guide()
            return
        super().keyPressEvent(e)

    def closeEvent(self, e):
        try:
            if self._gp_timer is not None:
                self._gp_timer.stop()
        except Exception:
            pass
        try:
            if self.view is not None:
                self.view.stop()
        except Exception:
            pass
        super().closeEvent(e)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, 'keyboard_button'):
            self.keyboard_button.move(self.width() - self.keyboard_button.width() - 22, self.height() - self.keyboard_button.height() - 22)
            self.keyboard_button.raise_()


class StorageConsoleDialog(QtWidgets.QDialog):
    SETTINGS = [
        ('Console Settings', 'Console Settings', 'Manage core console preferences and local system information.'),
        ('Kinect Settings', 'Kinect Settings', 'Configure Kinect-style controls and voice navigation.'),
        ('Storage', 'Storage', 'Move or delete saved games, profiles, and other items on storage devices.'),
        ('Network Settings', 'Network Setup', 'Review network adapters, Wi-Fi, and connection diagnostics.'),
        ('Computers', 'Network Info', 'View computers and network information available to this device.'),
        ('TV', 'Live TV', 'Open the TV and video experience.'),
        ('Xbox Live Vision', 'Kinect Settings', 'Configure camera and related device settings.'),
        ('Initial Setup', 'Setup Wizard', 'Run the initial console-style setup again.'),
    ]

    def __init__(self, parent=None, start_section='Console Settings'):
        super().__init__(parent)
        self._page = 'settings'
        self._action = ''
        self._settings_rows = []
        self._destination_rows = []
        self.setWindowTitle('Console Settings')
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint | QtCore.Qt.WindowStaysOnTopHint)
        self.setModal(True)
        screen = parent.screen() if parent is not None else QtWidgets.QApplication.primaryScreen()
        if screen is None:
            screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            self.setGeometry(screen.geometry())
        else:
            self.resize(1280, 720)
        self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
        self._build()
        self._load_destination_devices()
        initial_row = next(
            (i for i, row in enumerate(self.SETTINGS) if row[0] == str(start_section)),
            0,
        )
        self.settings_list.setCurrentRow(initial_row)
        self._show_setting(initial_row)

