    def _load_destination_devices(self):
        try:
            disk = shutil.disk_usage(Path.home())
            total = int(disk.total)
            free = int(disk.free)
            used_pct = int(round(100 * (total - free) / max(1, total)))
            hard_drive = {
                'name': 'Hard Drive',
                'capacity': f'{free / (1024 ** 3):.1f} GB free',
                'detail': f'Home storage • {total / (1024 ** 3):.1f} GB total',
                'used_pct': used_pct,
            }
        except Exception:
            hard_drive = {'name': 'Hard Drive', 'capacity': 'Capacity unavailable', 'detail': str(Path.home()), 'used_pct': 0}

        secondary_disks = self._detect_secondary_disks()
        memory_units = []
        media_roots = [Path('/media') / os.environ.get('USER', ''), Path('/run/media') / os.environ.get('USER', '')]
        for root in media_roots:
            try:
                for mount in root.iterdir():
                    if not mount.is_dir():
                        continue
                    try:
                        disk = shutil.disk_usage(mount)
                    except OSError:
                        continue
                    memory_units.append({
                        'name': mount.name or 'Memory Unit',
                        'capacity': f'{disk.free / (1024 ** 3):.1f} GB free',
                        'detail': f'USB Storage Device • {disk.total / (1024 ** 3):.1f} GB total',
                        'used_pct': int(round(100 * (disk.total - disk.free) / max(1, disk.total))),
                    })
            except OSError:
                continue
        for device in secondary_disks:
            name = str(device.get('model') or device.get('name') or 'Secondary Disk')
            path = str(device.get('name') or '')
            formatted = bool(device.get('fstype') or device.get('partition_fstype'))
            mounted = bool(device.get('mounted'))
            if formatted and not mounted:
                mounted, mountpoint = self._attempt_auto_mount(device)
                device['mounted'] = mounted
                device['mountpoints'] = [mountpoint] if mounted else []
                mounted = bool(mountpoint)
            capacity = int(device.get('size') or 0)
            free = capacity if formatted else capacity
            state = 'Mounted' if mounted else ('Formatted as ' + str(device.get('fstype') or device.get('partition_fstype')) if formatted else 'Unformatted — format with caution')
            detail = f'Secondary disk • {state}'
            if formatted and not mounted:
                detail += '\n\nAutomatic mount was unavailable. Use a terminal with sudo, or connect the disk again.'
            memory_units.append({
                'name': f'{name} — {path}',
                'capacity': f'{free / (1024 ** 3):.1f} GB free',
                'detail': detail,
                'used_pct': 0,
                'device': path,
                'secondary': True,
                'formatted': formatted,
                'fstype': str(device.get('fstype') or device.get('partition_fstype') or ''),
                'mounted': mounted,
                'mountpoint': str(device.get('mountpoints', [None])[0] or ''),
            })
        if not memory_units:
            memory_units.append({
                'name': 'Memory Unit',
                'capacity': 'No device connected',
                'detail': 'Connect a removable storage device to use it as a memory unit.',
                'used_pct': 0,
            })
        cloud = {
            'name': 'Cloud Saved Games',
            'capacity': 'Not configured',
            'detail': 'Cloud storage is not connected in this local XUI installation.',
            'used_pct': 0,
        }
        self._destination_rows = [hard_drive, *memory_units[:8], cloud]
        self.destination_list.clear()
        for row in self._destination_rows:
            item = QtWidgets.QListWidgetItem(f'▰  {row["name"]}\n    {row["capacity"]}')
            item.setData(QtCore.Qt.UserRole, row)
            self.destination_list.addItem(item)
        if self.destination_list.count():
            self.destination_list.setCurrentRow(0)

    @staticmethod
    def _detect_secondary_disks():
        try:
            raw = subprocess.run(
                ['lsblk', '-J', '-o', 'NAME,TYPE,PKNAME,MOUNTPOINTS,FSTYPE,TRAN,SIZE,MODEL,RO'],
                check=True,
                capture_output=True,
                text=True,
                timeout=10,
            ).stdout
            rows = json.loads(raw)
            root_devices = set()
            for block in rows.get('blockdevices') or []:
                mounts = block.get('mountpoints') or []
                if '/' in mounts:
                    root_devices.add(str(block.get('name') or ''))
                    root_devices.add(str(block.get('pkname') or ''))

            result = []
            for block in rows.get('blockdevices') or []:
                name = str(block.get('name') or '')
                kind = str(block.get('type') or '')
                if kind != 'disk' or not name or name in root_devices:
                    continue
                mounts = list(block.get('mountpoints') or [])
                transport = str(block.get('tran') or '').strip().lower()
                is_secondary = transport in ('sata', 'usb', 'mmc', 'ieee1394', 'virtio')
                if not is_secondary and not mounts:
                    # Some removable disks do not expose TRAN in lsblk. Check udev as fallback.
                    if not shutil.which('udevadm'):
                        continue
                    udev_result = subprocess.run(
                        ['udevadm', 'info', '--query=property', f'--path=/dev/{name}'],
                        check=False,
                        capture_output=True,
                        text=True,
                        timeout=5,
                    )
                    is_secondary = any(
                        line.startswith(('ID_BUS=usb', 'ID_BUS=mmc', 'ID_BUS=sata'))
                        for line in (udev_result.stdout or '').splitlines()
                    )
                    if not is_secondary and not mounts:
                        continue
                partition_fstype = ''
                mount_device = ''
                child_mountpoints = []
                partition_children = [
                    child for child in block.get('children') or []
                    if str(child.get('type') or '') == 'part'
                ]
                for child in partition_children:
                    child_fstype = str(child.get('fstype') or '').strip()
                    child_mounts = list(child.get('mountpoints') or [])
                    if child_fstype:
                        partition_fstype = child_fstype
                        mount_device = f"/dev/{child.get('name')}"
                        if child_mounts:
                            child_mountpoints = child_mounts
                        if child_mountpoints:
                            mounts = child_mountpoints
                        break
                size_value = str(block.get('size') or '').strip().replace(',', '')
                size_multiplier = 1
                size_number = size_value
                if size_value[-1:].upper() in ('K', 'M', 'G', 'T'):
                    size_multiplier = {'K': 1024, 'M': 1024 ** 2, 'G': 1024 ** 3, 'T': 1024 ** 4}[size_value[-1:].upper()]
                    size_number = size_value[:-1]
                try:
                    size_bytes = int(size_number) * size_multiplier
                except (TypeError, ValueError):
                    size_bytes = 0
                result.append({
                    'name': f'/dev/{name}',
                    'model': str(block.get('model') or 'Secondary disk'),
                    'size': size_bytes,
                    'fstype': str(block.get('fstype') or ''),
                    'partition_fstype': partition_fstype,
                    'mount_device': mount_device,
                    'partition_device': mount_device,
                    'partition_count': len(partition_children),
                    'transport': transport,
                    'read_only': bool(block.get('ro')),
                    'mounted': bool(mounts),
                    'mountpoints': mounts,
                })
            return result
        except Exception:
            return []

    @staticmethod
    def _attempt_auto_mount(device):
        device_path = str(device.get('mount_device') or device.get('name') or '')
        if not device_path or not (device.get('fstype') or device.get('partition_fstype')):
            return False, ''
        if device.get('read_only'):
            return False, ''
        mount_root = Path.home() / '.xui' / 'mounts'
        safe_name = re.sub(r'[^A-Za-z0-9._-]+', '_', device_path.rsplit('/', 1)[-1])
        mountpoint = mount_root / safe_name
        try:
            mount_root.mkdir(parents=True, exist_ok=True)
            mountpoint.mkdir(exist_ok=True)
        except OSError:
            return False, ''

        command_prefix = []
        if os.geteuid() != 0 and shutil.which('sudo'):
            command_prefix = ['sudo', '-n']
        elif os.geteuid() != 0:
            return False, ''

        try:
            mount_result = subprocess.run(
                command_prefix + ['mount', device_path, str(mountpoint)],
                check=False,
                capture_output=True,
                text=True,
                timeout=20,
            )
            if mount_result.returncode != 0:
                return False, ''
            return True, str(mountpoint)
        except (OSError, subprocess.SubprocessError):
            return False, ''

    def _show_setting(self, row):
        if row < 0 or row >= len(self.SETTINGS):
            return
        title, action, description = self.SETTINGS[row]
        self.settings_detail_title.setText(title)
        self.settings_detail_text.setText(description)

    def _show_destination(self, row):
        if row < 0 or row >= len(self._destination_rows):
            return
        device = self._destination_rows[row]
        self.destination_name.setText(str(device.get('name') or 'Storage Device'))
        self.destination_capacity.setText(str(device.get('capacity') or ''))
        self.destination_description.setText(str(device.get('detail') or ''))
        self.destination_bar.setValue(max(0, min(100, int(device.get('used_pct') or 0))))
        self.format_button.setEnabled(bool(device.get('secondary')) and not bool(device.get('mounted')))
        if device.get('secondary') and device.get('mounted'):
            self.destination_description.setText(
                str(device.get('detail') or '') + '\n\nUnmount the disk before formatting it.'
            )

    def _open_format_selected_disk(self):
        row = self.destination_list.currentRow()
        if row < 0 or row >= len(self._destination_rows):
            return
        device = self._destination_rows[row]
        if not device.get('secondary'):
            self._msg('Format unavailable', 'Select a removable storage device.')
            return
        if device.get('mounted'):
            self._msg('Format unavailable', 'Unmount the disk before formatting it.')
            return
        if device.get('read_only'):
            self._msg('Format unavailable', 'The selected disk is read-only.')
            return
        dialog = SecondaryDiskFormatDialog(
            device.get('device'),
            partition_device=device.get('partition_device'),
            parent=self,
        )
        dialog.exec_()
        if dialog.result() == QtWidgets.QDialog.Accepted:
            self._load_destination_devices()
            self.destination_list.setCurrentRow(row)

    def _activate_setting(self, *_):
        row = self.settings_list.currentRow()
        if row < 0 or row >= len(self.SETTINGS):
            return
        title, action, _description = self.SETTINGS[row]
        if title == 'Storage':
            self._page = 'destinations'
            self.pages.setCurrentWidget(self.destination_page)
            self.destination_list.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if title == 'Console Settings':
            return
        self._action = action
        self.accept()

    def _activate_destination(self, *_):
        row = self.destination_list.currentRow()
        if 0 <= row < len(self._destination_rows):
            device = self._destination_rows[row]
            if device.get('secondary'):
                if device.get('mounted'):
                    self.destination_description.setText(
                        str(device.get('detail') or '') + '\n\nUnmount the disk before formatting it.'
                    )
                    return
                if device.get('read_only'):
                    self.destination_description.setText(
                        str(device.get('detail') or '') + '\n\nThe disk is read-only and cannot be formatted.'
                    )
                    return
                dialog = SecondaryDiskFormatDialog(device.get('device'), self)
                dialog.exec_()
                if dialog.result() == QtWidgets.QDialog.Accepted:
                    self._load_destination_devices()
                    self.destination_list.setCurrentRow(row)
                return
            self.destination_description.setText(
                str(device.get('detail') or '')
                + '\n\nSaved-game file management is local-only in this XUI build.'
            )

    def selected_action(self):
        return str(self._action or '')

    def showEvent(self, event):
        super().showEvent(event)
        screen = self.screen() or QtWidgets.QApplication.primaryScreen()
        if screen is not None and self.geometry() != screen.geometry():
            self.setGeometry(screen.geometry())
        if self._page == 'destinations':
            current_row = self.destination_list.currentRow()
            self._load_destination_devices()
            if current_row >= 0 and current_row < self.destination_list.count():
                self.destination_list.setCurrentRow(current_row)
            else:
                self.destination_list.setCurrentRow(0)
        self.raise_()
        self.activateWindow()
        active_list = self.settings_list if self._page == 'settings' else self.destination_list
        active_list.setFocus(QtCore.Qt.OtherFocusReason)

    def keyPressEvent(self, event):
        key = event.key()
        if key in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
            if self._page == 'destinations':
                self._page = 'settings'
                self.pages.setCurrentWidget(self.settings_page)
                self.settings_list.setCurrentRow(2)
                self.settings_list.setFocus(QtCore.Qt.OtherFocusReason)
            else:
                self.reject()
            return
        if key in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_A):
            if self._page == 'settings':
                self._activate_setting()
            else:
                self._activate_destination()
            return
        if key == QtCore.Qt.Key_Up:
            target = self.settings_list if self._page == 'settings' else self.destination_list
            target.setCurrentRow(max(0, target.currentRow() - 1))
            return
        if key == QtCore.Qt.Key_Down:
            target = self.settings_list if self._page == 'settings' else self.destination_list
            target.setCurrentRow(min(target.count() - 1, target.currentRow() + 1))
            return
        super().keyPressEvent(event)


class SecondaryDiskFormatDialog(QtWidgets.QDialog):
    """Safe, explicit formatter for an unmounted secondary disk."""

    FORMATS = [
        ('FAT32', 'FAT32', 'Compatible with Windows, Xbox and most consoles.'),
        ('exFAT', 'exFAT', 'Large files supported; compatible with modern Windows and Linux.'),
        ('NTFS', 'NTFS', 'Large capacity and Windows compatibility; Linux read/write support is available.'),
    ]

    def __init__(self, device, partition_device='', parent=None):
        super().__init__(parent)
        self.device = str(device or '')
        self.partition_device = str(partition_device or '')
        self.selected_format = 'FAT32'
        self.setWindowTitle('Format secondary disk')
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        self.resize(760, 480)
        self.setStyleSheet('''
            QDialog { background:#cbd1d4; color:#20272c; font-family:"Segoe UI",sans-serif; }
            QFrame { background:#dfe5e6; border:1px solid #9ca7aa; }
            QLabel { color:#263238; font-size:18px; }
            QComboBox { background:#f2f5f6; color:#263238; border:1px solid #69777d; padding:8px; font-size:18px; }
            QPushButton { background:#078d13; color:#fff; border:1px solid #54b75a; padding:10px 18px; font-size:17px; font-weight:700; }
            QPushButton:hover { background:#0d9f18; }
            QPushButton#cancel { background:#666f73; border-color:#aeb6b9; }
        ''')
        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(18, 18, 18, 18)
        root.setSpacing(14)
        warning = QtWidgets.QLabel(
            'WARNING: Formatting destroys every partition and file on this disk. '
            'This operation cannot be undone.'
        )
        warning.setStyleSheet('color:#8c2020;font-weight:700;')
        root.addWidget(warning)
        root.addWidget(QtWidgets.QLabel(f'Secondary disk: {self.device}'))
        if self.partition_device:
            root.addWidget(QtWidgets.QLabel(f'Formatting partition: {self.partition_device}'))
        else:
            root.addWidget(QtWidgets.QLabel('No partition detected; a new GPT partition will be created.'))
        self.format_combo = QtWidgets.QComboBox()
        for label, value, description in self.FORMATS:
            self.format_combo.addItem(f'{label} — {description}', value)
        self.format_combo.currentIndexChanged.connect(self._show_format_description)
        root.addWidget(self.format_combo)
        self.format_description = QtWidgets.QLabel('')
        self.format_description.setWordWrap(True)
        root.addWidget(self.format_description)
        self.result_label = QtWidgets.QLabel('')
        self.result_label.setWordWrap(True)
        root.addWidget(self.result_label)
        root.addStretch(1)
        buttons = QtWidgets.QHBoxLayout()
        buttons.addStretch(1)
        cancel = QtWidgets.QPushButton('Cancel')
        cancel.setObjectName('cancel')
        cancel.clicked.connect(self.reject)
        confirm = QtWidgets.QPushButton('Format disk')
        confirm.clicked.connect(self._confirm_format)
        buttons.addWidget(cancel)
        buttons.addWidget(confirm)
        root.addLayout(buttons)
        self._show_format_description()

    def _show_format_description(self):
        index = self.format_combo.currentIndex()
        if index < 0:
            return
        self.selected_format = str(self.format_combo.currentData() or 'FAT32')
        self.format_description.setText(self.format_combo.currentText().split(' — ', 1)[1])

    def _confirm_format(self):
        if not self.device:
            self.result_label.setText('No disk selected.')
            return
        if not QtWidgets.QMessageBox.warning(
            self,
            'Confirm destructive operation',
            f'Format {self.device} completely as {self.selected_format}?\n\nAll partitions and data will be erased.',
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
            QtWidgets.QMessageBox.No,
        ):
            return
        self.result_label.setText('Formatting disk...')
        self.result_label.setEnabled(False)
        QtCore.QApplication.processEvents()
        result = self._format_device(self.device, self.selected_format, partition_device=self.partition_device)
        self.result_label.setEnabled(True)
        if result[0]:
            QtWidgets.QMessageBox.information(
                self,
                'Format completed',
                f'{self.device} was formatted as {self.selected_format}.\n\n{result[1]}',
            )
            self.accept()
        else:
            self.result_label.setText(result[1])

    @staticmethod
    def _format_device(device, file_system, partition_device=None):
        if not device or not file_system:
            return False, 'Invalid disk or filesystem.'
        if os.geteuid() != 0:
            if not shutil.which('sudo'):
                return False, 'Run XUI as root or install sudo to format this disk.'
            command_prefix = ['sudo', '-n']
        else:
            command_prefix = []
        label = 'XUI-SECONDARY'
        fs_commands = {
            'FAT32': ('mkfs.fat', ['-F', '32', '-n', label]),
            'exFAT': ('mkfs.exfat', ['-n', label]),
            'NTFS': ('mkfs.ntfs', ['-Q', '-L', label]),
        }
        formatter = fs_commands.get(file_system)
        if formatter is None:
            return False, 'Unsupported filesystem.'
        executable, arguments = formatter
        if not shutil.which(executable):
            return False, f'The {file_system} filesystem tool is not installed.'
        target = str(partition_device or device)
        try:
            if not partition_device:
                if not shutil.which('parted'):
                    return False, 'The parted utility is required to create an automatic partition.'
                subprocess.run(
                    command_prefix + ['parted', '-s', device, 'mklabel', 'gpt', 'mkpart', 'primary', '1MiB', '100%'],
                    check=True,
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                target = str(device) + '1'
            subprocess.run(command_prefix + ['wipefs', '-a', target], check=True, capture_output=True, text=True, timeout=30)
            subprocess.run(command_prefix + [executable, *arguments, target], check=True, capture_output=True, text=True, timeout=60)
            out = subprocess.run(
                command_prefix + ['blkid', '-s', 'TYPE', '-o', 'value', target],
                check=True,
                capture_output=True,
                text=True,
                timeout=10,
            ).stdout.strip()
            expected_type = {'FAT32': 'vfat', 'exFAT': 'exfat', 'NTFS': 'ntfs'}[file_system]
            if out.lower() != expected_type:
                return False, f'Formatting finished, but detected filesystem is {out or "unknown"}.'
            return True, f'Detected filesystem: {out}. Volume label: {label}. Partition: {target}.'
        except subprocess.CalledProcessError as exc:
            detail = (exc.stderr or exc.stdout or '').strip()
            if 'password' in detail.lower() or 'authentication' in detail.lower():
                return False, 'Administrative authentication was required. Run XUI with sudo or allow sudo in the terminal.'
            return False, f'Formatting failed: {detail or exc}.'
        except Exception as exc:
            return False, f'Formatting failed: {exc}.'


class DashboardPage(QtWidgets.QWidget):
    actionTriggered = QtCore.pyqtSignal(str)

    def __init__(self, name, spec, parent=None):
        super().__init__(parent)
        self.name = name
        self.spec = spec
        self.left_tiles = []
        self.center_tiles = []
        self.right_tiles = []
        self.hero = None
        self._body_layout = None
        self.left_col = None
        self.left_layout = None
        self.center_col = None
        self.center_layout = None
        self.center_tiles_layout = None
        self.right_col = None
        self.right_layout = None
        self._last_apply_key = None
        self._build()

    def _build_tiles(self, defs, target, layout, alignment=QtCore.Qt.AlignLeft, tile_opts=None):
        opts = dict(tile_opts or {})
        for action, text, size in defs:
            try:
                w0, h0 = int(size[0]), int(size[1])
            except Exception:
                w0, h0 = 220, 120
            if opts.get('metro_left'):
                tile_size = (max(130, int(w0 * 0.64)), max(74, int(h0 * 0.60)))
            elif opts.get('dense'):
                tile_size = (max(110, int(w0 * 0.63)), max(70, int(h0 * 0.62)))
            else:
                tile_size = (max(128, int(w0 * 0.62)), max(78, int(h0 * 0.62)))
            tile = GreenTile(
                action,
                text,
                tile_size,
                icon_scale=float(opts.get('icon_scale', 1.0)),
                text_scale=float(opts.get('text_scale', 1.0)),
                dense=bool(opts.get('dense', False)),
            )
            tile.clicked.connect(self.actionTriggered.emit)
            target.append(tile)
            layout.addWidget(tile, 0, alignment)

    def _build(self):
        wrap = QtWidgets.QVBoxLayout(self)
        wrap.setContentsMargins(0, 0, 0, 0)
        wrap.setSpacing(0)
        wrap.addStretch(1)

        body = QtWidgets.QHBoxLayout()
        self._body_layout = body
        body.setContentsMargins(0, 0, 0, 0)
        body.setSpacing(12)

        left_col = QtWidgets.QWidget()
        self.left_col = left_col
        left_col.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Preferred)
        left = QtWidgets.QVBoxLayout(left_col)
        self.left_layout = left
        left.setContentsMargins(0, 0, 0, 0)
        left.setSpacing(7)
        self._add_column_header(left_col, left, 'PRIMARY ACCESS', 'primary')
        self._build_tiles(
            self.spec.get('left', []),
            self.left_tiles,
            left,
            QtCore.Qt.AlignLeft,
            tile_opts={'metro_left': True, 'icon_scale': 0.86, 'text_scale': 0.88},
        )
        left.addStretch(1)

        center_col = QtWidgets.QWidget()
        self.center_col = center_col
        center_col.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Preferred)
        center = QtWidgets.QVBoxLayout(center_col)
        self.center_layout = center
        center.setContentsMargins(0, 0, 0, 0)
        center.setSpacing(6)
        center.addStretch(1)
        hero_variant = str(self.spec.get('hero_variant', 'default')).strip().lower()
        if hero_variant == 'games':
            self.hero = GamesShowcasePanel(
                self.spec.get('hero_action', 'Games Hub'),
                self.spec.get('hero_title', self.name),
                self.spec.get('hero_subtitle', 'featured'),
            )
        else:
            self.hero = HeroPanel(
                self.spec.get('hero_action', 'Hub'),
                self.spec.get('hero_title', self.name),
                self.spec.get('hero_subtitle', 'featured'),
            )
        self.hero.clicked.connect(self.actionTriggered.emit)
        center.addWidget(self.hero, 0, alignment=QtCore.Qt.AlignHCenter | QtCore.Qt.AlignTop)

        center_bottom_defs = self.spec.get('center_bottom', [])
        if center_bottom_defs:
            self._add_column_header(center_col, center, 'QUICK ACCESS', 'quick')
            center_tiles_wrap = QtWidgets.QWidget()
            center_tiles_row = QtWidgets.QHBoxLayout(center_tiles_wrap)
            self.center_tiles_layout = center_tiles_row
            center_tiles_row.setContentsMargins(0, 0, 0, 0)
            center_tiles_row.setSpacing(6)
            center_tiles_row.addStretch(1)
            self._build_tiles(
                center_bottom_defs,
                self.center_tiles,
                center_tiles_row,
                QtCore.Qt.AlignVCenter,
                tile_opts={'dense': True, 'icon_scale': 0.72, 'text_scale': 0.84},
            )
            center_tiles_row.addStretch(1)
            center.addWidget(center_tiles_wrap, 0, alignment=QtCore.Qt.AlignHCenter | QtCore.Qt.AlignTop)
        center.addStretch(1)

        right_col = QtWidgets.QWidget()
        self.right_col = right_col
        right_col.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Preferred)
        right = QtWidgets.QVBoxLayout(right_col)
        self.right_layout = right
        right.setContentsMargins(0, 0, 0, 0)
        right.setSpacing(6)
        self._add_column_header(right_col, right, 'MORE ACTIONS', 'more')
        self._build_tiles(
            self.spec.get('right', []),
            self.right_tiles,
            right,
            QtCore.Qt.AlignLeft,
            tile_opts={'dense': True, 'icon_scale': 0.62, 'text_scale': 0.78},
        )
        right.addStretch(1)

        body.addStretch(1)
        body.addWidget(left_col, 0, alignment=QtCore.Qt.AlignTop)
        body.addWidget(center_col, 1, alignment=QtCore.Qt.AlignTop)
        body.addWidget(right_col, 0, alignment=QtCore.Qt.AlignTop)
        body.addStretch(1)
        wrap.addLayout(body, 0)
        wrap.addStretch(1)

    @staticmethod
    def _add_column_header(parent, layout, label, kind):
        header = QtWidgets.QLabel(label)
        header.setObjectName(f'dashboard_tile_section_{kind}')
        header.setAlignment(QtCore.Qt.AlignLeft | QtCore.Qt.AlignVCenter)
        header.setStyleSheet(
            'color:#dce6e7; font-size:12px; font-weight:800; letter-spacing:2px; '
            'padding:0 6px 5px;'
        )
        layout.addWidget(header, 0, QtCore.Qt.AlignLeft)

    def _apply_scale_once(self, scale=1.0, compact=False):
        s = max(0.58, float(scale))
        compact_factor = 0.95 if compact else 1.0
        gap = max(4, int(12 * s * compact_factor))
        col_gap = max(3, int(7 * s * compact_factor))
        if self._body_layout is not None:
            self._body_layout.setSpacing(gap)
        if self.left_layout is not None:
            self.left_layout.setSpacing(col_gap)
        if self.center_layout is not None:
            self.center_layout.setSpacing(col_gap)
        if self.center_tiles_layout is not None:
            self.center_tiles_layout.setSpacing(max(3, int(6 * s * compact_factor)))
        if self.right_layout is not None:
            self.right_layout.setSpacing(col_gap)
        available_width = max(320, int(self.width() - self._body_layout.contentsMargins().left() - self._body_layout.contentsMargins().right()))
        if self.left_col is not None and self.right_col is not None:
            compact_columns = available_width < 1080
            left_width = 150 if compact_columns else 220
            right_width = 125 if compact_columns else 170
            left_width = max(left_width, int(left_width * s * compact_factor))
            right_width = max(right_width, int(right_width * s * compact_factor))
            self.left_col.setFixedWidth(left_width)
            self.right_col.setFixedWidth(right_width)
            available_center = max(320, available_width - left_width - right_width - max(0, gap * 2))
            s = min(s, available_center / 780.0)
        for group in (self.left_tiles, self.center_tiles, self.right_tiles):
            for tile in group:
                tile.apply_scale(max(0.58, s), compact)
        if self.hero is not None:
            self.hero.apply_scale(max(0.58, s), compact)

    def _content_size_hint(self):
        gap = int(self._body_layout.spacing()) if self._body_layout is not None else 0
        left_w = int(self.left_col.width()) if self.left_col is not None else 0
        center_w = int(self.center_col.sizeHint().width()) if self.center_col is not None else 0
        right_w = int(self.right_col.width()) if self.right_col is not None else 0
        total_w = left_w + center_w + right_w + max(0, gap * 2)

        left_h = int(self.left_col.sizeHint().height()) if self.left_col is not None else 0
        center_h = int(self.center_col.sizeHint().height()) if self.center_col is not None else 0
        right_h = int(self.right_col.sizeHint().height()) if self.right_col is not None else 0
        total_h = max(left_h, center_h, right_h)
        return total_w, total_h

    def apply_scale(self, scale=1.0, compact=False):
        base = max(0.58, float(scale))
        apply_key = (round(base, 4), bool(compact), int(self.width()), int(self.height()))
        if apply_key == self._last_apply_key:
            return
        fitted = base
        for _ in range(10):
            self._apply_scale_once(fitted, compact)
            self.layout().activate()
            avail_w = max(1, int(self.width()) - 8)
            avail_h = max(1, int(self.height()) - 8)
            need_w, need_h = self._content_size_hint()
            if need_w <= avail_w and need_h <= avail_h:
                break
            nxt = max(0.58, fitted * 0.94)
            if abs(nxt - fitted) < 0.002:
                break
            fitted = nxt
        self._last_apply_key = apply_key


class AchievementToast(QtWidgets.QFrame):
    finished = QtCore.pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName('achievement_toast')
        self.setAttribute(QtCore.Qt.WA_TransparentForMouseEvents, True)
        self.setFixedSize(430, 84)
        self.setFocusPolicy(QtCore.Qt.NoFocus)
        self._compact = False
        self._scale = 1.0
        self._anim = None
        self._opacity = QtWidgets.QGraphicsOpacityEffect(self)
        self._opacity.setOpacity(0.0)
        self.setGraphicsEffect(self._opacity)
        self._build()
        self.hide()

    def _build(self):
        root = QtWidgets.QHBoxLayout(self)
        root.setContentsMargins(12, 10, 16, 10)
        root.setSpacing(10)

        icon_wrap = QtWidgets.QFrame()
        icon_wrap.setObjectName('ach_icon_wrap')
        icon_wrap.setFixedSize(56, 56)
        icon_layout = QtWidgets.QVBoxLayout(icon_wrap)
        icon_layout.setContentsMargins(0, 0, 0, 0)

        self.icon_lbl = QtWidgets.QLabel()
        self.icon_lbl.setObjectName('ach_icon')
        self.icon_lbl.setAlignment(QtCore.Qt.AlignCenter)
        self.icon_lbl.setFixedSize(40, 40)
        px = self.style().standardIcon(QtWidgets.QStyle.SP_DialogApplyButton).pixmap(22, 22)
        self.icon_lbl.setPixmap(px)
        icon_layout.addWidget(self.icon_lbl, 0, QtCore.Qt.AlignCenter)

        text_col = QtWidgets.QVBoxLayout()
        text_col.setContentsMargins(0, 0, 0, 0)
        text_col.setSpacing(2)
        self.title_lbl = QtWidgets.QLabel('Achievement unlocked')
        self.title_lbl.setObjectName('ach_title')
        self.name_lbl = QtWidgets.QLabel('Ready')
        self.name_lbl.setObjectName('ach_name')
        text_col.addWidget(self.title_lbl)
        text_col.addWidget(self.name_lbl)

        self.score_lbl = QtWidgets.QLabel('0G')
        self.score_lbl.setObjectName('ach_score')
        self.score_lbl.setAlignment(QtCore.Qt.AlignCenter)
        self.score_lbl.setFixedWidth(64)

        root.addWidget(icon_wrap, 0, QtCore.Qt.AlignVCenter)
        root.addLayout(text_col, 1)
        root.addWidget(self.score_lbl, 0, QtCore.Qt.AlignVCenter)

        self.setStyleSheet('''
            QFrame#achievement_toast {
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #2d3138, stop:1 #5a5f66);
                border:2px solid rgba(255,255,255,0.28);
                border-radius:40px;
            }
            QFrame#ach_icon_wrap {
                background:qradialgradient(cx:0.35, cy:0.35, radius:0.9, fx:0.35, fy:0.35, stop:0 #3a4047, stop:1 #171d25);
                border:2px solid #79bd3b;
                border-radius:28px;
            }
            QLabel#ach_icon {
                color:#ecf4ea;
                border:none;
            }
            QLabel#ach_title {
                color:#f2f5f7;
                font-size:18px;
                font-weight:800;
            }
            QLabel#ach_name {
                color:rgba(239,246,249,0.9);
                font-size:15px;
                font-weight:700;
            }
            QLabel#ach_score {
                color:#9bdb64;
                font-size:18px;
                font-weight:900;
                border:none;
            }
        ''')

    def apply_scale(self, scale=1.0, compact=False):
        self._scale = max(0.62, float(scale))
        self._compact = bool(compact)
        cf = 0.9 if self._compact else 1.0
        w = max(320, int(430 * self._scale * cf))
        h = max(70, int(84 * self._scale * cf))
        self.setFixedSize(w, h)
        self.score_lbl.setFixedWidth(max(52, int(64 * self._scale)))

    def _target_pos(self):
        parent = self.parentWidget()
        if parent is None:
            return QtCore.QPoint(20, 20)
        margin_x = max(12, int(26 * self._scale))
        margin_y = max(10, int(24 * self._scale))
        x = margin_x
        y = max(margin_y, parent.height() - self.height() - margin_y)
        return QtCore.QPoint(x, y)

    def reposition(self):
        if self.isVisible():
            self.move(self._target_pos())

    def show_achievement(self, name, score=0):
        title = str(name or 'Achievement')
        self.title_lbl.setText('Achievement unlocked')
        self.name_lbl.setText(title)
        try:
            score_int = int(score)
        except Exception:
            score_int = 0
        self.score_lbl.setText(f'{max(0, score_int)}G')

        if self._anim is not None:
            self._anim.stop()
            self._anim = None

        target = self._target_pos()
        start = QtCore.QPoint(-self.width() - 30, target.y())
        end = QtCore.QPoint(-self.width() + 80, target.y())
        self.move(start)
        self._opacity.setOpacity(0.0)
        self.show()
        self.raise_()

        seq = QtCore.QSequentialAnimationGroup(self)
        fade_in = QtCore.QPropertyAnimation(self._opacity, b'opacity')
        fade_in.setDuration(220)
        fade_in.setStartValue(0.0)
        fade_in.setEndValue(1.0)
        fade_in.setEasingCurve(QtCore.QEasingCurve.OutCubic)

        slide_in = QtCore.QPropertyAnimation(self, b'pos')
        slide_in.setDuration(280)
        slide_in.setStartValue(start)
        slide_in.setEndValue(target)
        slide_in.setEasingCurve(QtCore.QEasingCurve.OutCubic)

        hold = QtCore.QPauseAnimation(1700)

        fade_out = QtCore.QPropertyAnimation(self._opacity, b'opacity')
        fade_out.setDuration(280)
        fade_out.setStartValue(1.0)
        fade_out.setEndValue(0.0)
        fade_out.setEasingCurve(QtCore.QEasingCurve.InCubic)

        slide_out = QtCore.QPropertyAnimation(self, b'pos')
        slide_out.setDuration(320)
        slide_out.setStartValue(target)
        slide_out.setEndValue(end)
        slide_out.setEasingCurve(QtCore.QEasingCurve.InCubic)

        grp_in = QtCore.QParallelAnimationGroup()
        grp_in.addAnimation(fade_in)
        grp_in.addAnimation(slide_in)
        grp_out = QtCore.QParallelAnimationGroup()
        grp_out.addAnimation(fade_out)
        grp_out.addAnimation(slide_out)

        seq.addAnimation(grp_in)
        seq.addAnimation(hold)
        seq.addAnimation(grp_out)

        def done():
            if self._anim is seq:
                self._anim = None
            self.hide()
            self.finished.emit()

        seq.finished.connect(done)
        self._anim = seq
        self._anim.start(QtCore.QAbstractAnimation.DeleteWhenStopped)


