        outer = QtWidgets.QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        panel = QtWidgets.QFrame()
        panel.setObjectName('ach_panel')
        outer.addWidget(panel)

        root = QtWidgets.QVBoxLayout(panel)
        root.setContentsMargins(12, 10, 12, 10)
        root.setSpacing(8)

        top = QtWidgets.QHBoxLayout()
        title = QtWidgets.QLabel('Logros')
        title.setObjectName('ach_title')
        self.meta = QtWidgets.QLabel('')
        self.meta.setObjectName('ach_meta')
        top.addWidget(title)
        top.addStretch(1)
        top.addWidget(self.meta)
        root.addLayout(top)

        body = QtWidgets.QHBoxLayout()
        body.setSpacing(10)
        self.listw = QtWidgets.QListWidget()
        self.listw.setObjectName('ach_list')
        self.listw.itemActivated.connect(self._show_current_detail)
        self.listw.currentRowChanged.connect(self._refresh_detail)
        body.addWidget(self.listw, 4)

        side = QtWidgets.QFrame()
        side.setObjectName('ach_side')
        sl = QtWidgets.QVBoxLayout(side)
        sl.setContentsMargins(8, 8, 8, 8)
        sl.setSpacing(7)

        self.stats_lbl = QtWidgets.QLabel('')
        self.stats_lbl.setObjectName('ach_stat')
        self.stats_lbl.setWordWrap(True)
        sl.addWidget(self.stats_lbl, 0)

        self.name_lbl = QtWidgets.QLabel('Selecciona un logro')
        self.name_lbl.setObjectName('ach_name')
        self.name_lbl.setWordWrap(True)
        sl.addWidget(self.name_lbl, 0)

        self.desc_lbl = QtWidgets.QLabel('Detalles del logro.')
        self.desc_lbl.setObjectName('ach_desc')
        self.desc_lbl.setWordWrap(True)
        sl.addWidget(self.desc_lbl, 1)

        self.btn_all = QtWidgets.QPushButton('Ver Todos')
        self.btn_unlocked = QtWidgets.QPushButton('Ver Desbloqueados')
        self.btn_locked = QtWidgets.QPushButton('Ver Bloqueados')
        self.btn_refresh = QtWidgets.QPushButton('Actualizar')
        self.btn_back = QtWidgets.QPushButton('Volver')
        for b in (self.btn_all, self.btn_unlocked, self.btn_locked, self.btn_refresh, self.btn_back):
            b.setObjectName('ach_btn')
            sl.addWidget(b, 0)
        sl.addStretch(1)
        body.addWidget(side, 2)
        root.addLayout(body, 1)

        hint = QtWidgets.QLabel('A/ENTER = Detalle | X = Actualizar | B/ESC = Volver')
        hint.setObjectName('ach_hint')
        root.addWidget(hint)

        self.btn_all.clicked.connect(lambda: self._set_filter('all'))
        self.btn_unlocked.clicked.connect(lambda: self._set_filter('unlocked'))
        self.btn_locked.clicked.connect(lambda: self._set_filter('locked'))
        self.btn_refresh.clicked.connect(self.reload)
        self.btn_back.clicked.connect(self.reject)

        self._clock = QtCore.QTimer(self)
        self._clock.timeout.connect(self._refresh_meta)
        self._clock.start(1000)
        self.reload()

    def _refresh_meta(self):
        now = QtCore.QDateTime.currentDateTime().toString('HH:mm')
        unlocked = int(self._progress.get('unlocked', 0))
        total = int(self._progress.get('total', 0))
        self.meta.setText(f'{self.gamertag}    {now}    {unlocked}/{total}')

    def _filtered_rows(self):
        if self._filter == 'unlocked':
            return [r for r in self._rows if r.get('unlocked')]
        if self._filter == 'locked':
            return [r for r in self._rows if not r.get('unlocked')]
        return list(self._rows)

    def _apply_filter(self):
        rows = self._filtered_rows()
        self.listw.blockSignals(True)
        self.listw.clear()
        for row in rows:
            status = 'UNLOCKED' if row.get('unlocked') else 'LOCKED'
            title = str(row.get('title', 'Achievement'))
            score = int(row.get('score', 0) or 0)
            item = QtWidgets.QListWidgetItem(f'{status}  {title}    {score}G')
            item.setData(QtCore.Qt.UserRole, dict(row))
            self.listw.addItem(item)
        self.listw.blockSignals(False)
        if self.listw.count() > 0:
            self.listw.setCurrentRow(0)
        self._refresh_detail(self.listw.currentRow())

    def _set_filter(self, mode):
        self._filter = str(mode or 'all')
        self._apply_filter()

    def _current_payload(self):
        it = self.listw.currentItem()
        if it is None:
            return {}
        data = it.data(QtCore.Qt.UserRole)
        return data if isinstance(data, dict) else {}

    def _refresh_detail(self, _row):
        row = self._current_payload()
        if not row:
            self.name_lbl.setText('Selecciona un logro')
            self.desc_lbl.setText('Detalles del logro.')
            return
        title = str(row.get('title', 'Achievement')).strip() or 'Achievement'
        desc = str(row.get('desc', 'Sin descripcion.')).strip() or 'Sin descripcion.'
        score = int(row.get('score', 0) or 0)
        aid = str(row.get('id', '')).strip()
        unlocked = bool(row.get('unlocked', False))
        state = 'Desbloqueado' if unlocked else 'Bloqueado'
        self.name_lbl.setText(f'{title} ({score}G)')
        self.desc_lbl.setText(f'{desc}\n\nEstado: {state}\nID: {aid}')

    def _show_current_detail(self, *_):
        row = self._current_payload()
        if not row:
            return
        title = str(row.get('title', 'Achievement')).strip() or 'Achievement'
        desc = str(row.get('desc', 'Sin descripcion.')).strip() or 'Sin descripcion.'
        score = int(row.get('score', 0) or 0)
        unlocked = bool(row.get('unlocked', False))
        state = 'Desbloqueado' if unlocked else 'Bloqueado'
        detail_txt = f'{desc}\n\nEstado: {state}\nGamerscore: {score}G'
        dlg = InfoNoticeDialog(title, detail_txt, self)
        dlg.exec_()

    def reload(self):
        try:
            state = ensure_achievements(5000)
        except Exception:
            state = {'items': [], 'unlocked': [], 'stats': {}}
        items = state.get('items', [])
        if not isinstance(items, list):
            items = []
        unlocked_list = state.get('unlocked', [])
        if not isinstance(unlocked_list, list):
            unlocked_list = []
        unlocked_ts = {}
        for rec in unlocked_list:
            if not isinstance(rec, dict):
                continue
            aid = str(rec.get('id', '')).strip()
            if not aid:
                continue
            try:
                unlocked_ts[aid] = int(rec.get('ts', 0) or 0)
            except Exception:
                unlocked_ts[aid] = 0
        rows = []
        total_score = 0
        unlocked_score = 0
        for item in items:
            if not isinstance(item, dict):
                continue
            aid = str(item.get('id', '')).strip()
            if not aid:
                continue
            score = int(item.get('score', 0) or 0)
            unlocked = aid in unlocked_ts
            if unlocked:
                unlocked_score += score
            total_score += score
            rows.append({
                'id': aid,
                'title': str(item.get('title', aid)).strip() or aid,
                'desc': str(item.get('desc', '')).strip(),
                'score': score,
                'unlocked': unlocked,
                'ts': int(unlocked_ts.get(aid, 0) or 0),
            })
        rows.sort(key=lambda r: (0 if r.get('unlocked') else 1, -int(r.get('ts', 0)), -int(r.get('score', 0)), str(r.get('title', '')).lower()))
        self._rows = rows
        unlocked_n = sum(1 for r in rows if r.get('unlocked'))
        total_n = len(rows)
        self._progress = {
            'total': total_n,
            'unlocked': unlocked_n,
            'locked': max(0, total_n - unlocked_n),
            'score_total': int(total_score),
            'score_unlocked': int(unlocked_score),
        }
        stats = state.get('stats', {})
        if not isinstance(stats, dict):
            stats = {}
        self._stats = {
            'actions': int(stats.get('actions', 0) or 0),
            'launches': int(stats.get('launches', 0) or 0),
            'purchases': int(stats.get('purchases', 0) or 0),
            'missions': int(stats.get('missions', 0) or 0),
        }
        self.stats_lbl.setText(
            f'Logros: {unlocked_n}/{total_n}\n'
            f'Gamerscore: {self._progress["score_unlocked"]}/{self._progress["score_total"]}G\n'
            f'Actions: {self._stats["actions"]}\n'
            f'Launches: {self._stats["launches"]}\n'
            f'Purchases: {self._stats["purchases"]}\n'
            f'Missions: {self._stats["missions"]}'
        )
        self._refresh_meta()
        self._apply_filter()

    def keyPressEvent(self, e):
        if e.key() in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.reject()
            return
        if e.key() in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            self._show_current_detail()
            return
        if e.key() in (QtCore.Qt.Key_PageUp, QtCore.Qt.Key_PageDown):
            n = int(self.listw.count())
            if n > 0:
                step = -8 if e.key() == QtCore.Qt.Key_PageUp else 8
                row = int(self.listw.currentRow())
                if row < 0:
                    row = 0
                row = max(0, min(n - 1, row + step))
                self.listw.setCurrentRow(row)
            return
        if e.key() == QtCore.Qt.Key_Y:
            order = ['all', 'unlocked', 'locked']
            cur = order.index(self._filter) if self._filter in order else 0
            self._set_filter(order[(cur + 1) % len(order)])
            return
        if e.key() == QtCore.Qt.Key_X:
            self.reload()
            return
        super().keyPressEvent(e)


class NotificationCenterDialog(QtWidgets.QDialog):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle('Notification Center')
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        self.setModal(True)
        self.resize(900, 600)
        self.rows = []

        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(16, 14, 16, 14)
        header = QtWidgets.QHBoxLayout()
        title = QtWidgets.QLabel('Notification Center')
        title.setStyleSheet('font-size:28px;font-weight:800;color:#f4f8fb;')
        self.summary = QtWidgets.QLabel('')
        self.summary.setStyleSheet('font-size:16px;font-weight:700;color:#cbd7e2;')
        header.addWidget(title)
        header.addStretch(1)
        header.addWidget(self.summary)
        root.addLayout(header)

        self.listw = QtWidgets.QListWidget()
        self.listw.setStyleSheet('QListWidget{background:#d7dde2;color:#20252b;font-size:19px;} QListWidget::item{padding:9px;} QListWidget::item:selected{background:#328c38;color:white;}')
        self.listw.itemActivated.connect(self._mark_selected_read)
        root.addWidget(self.listw, 1)

        buttons = QtWidgets.QHBoxLayout()
        refresh = QtWidgets.QPushButton('Refresh')
        mark_read = QtWidgets.QPushButton('Mark All Read')
        clear_read = QtWidgets.QPushButton('Clear Read')
        close_btn = QtWidgets.QPushButton('Close (B/ESC)')
        refresh.clicked.connect(self.reload)
        mark_read.clicked.connect(self._mark_all_read)
        clear_read.clicked.connect(self._clear_read)
        close_btn.clicked.connect(self.reject)
        for button in (refresh, mark_read, clear_read):
            buttons.addWidget(button)
        buttons.addStretch(1)
        buttons.addWidget(close_btn)
        root.addLayout(buttons)
        self.setStyleSheet('QDialog{background:#17212b;} QPushButton{background:#378f38;color:white;padding:8px 14px;border:0;font-weight:700;} QPushButton:hover{background:#48aa47;}')
        self.reload()

    @staticmethod
    def _notification_id(kind, source):
        raw = f'{kind}:{source}'
        return hashlib.sha256(raw.encode('utf-8', errors='replace')).hexdigest()[:24]

    @staticmethod
    def _timestamp(value):
        try:
            return max(0, int(value or 0))
        except (TypeError, ValueError, OverflowError):
            return 0

    def _collect_rows(self):
        stored = safe_json_read(NOTIFICATIONS_FILE, [])
        if not isinstance(stored, list):
            stored = []
        rows = [dict(row) for row in stored if isinstance(row, dict)]
        known = {str(row.get('id') or '') for row in rows}

        recent_messages = safe_json_read(SOCIAL_MESSAGES_FILE, [])
        if isinstance(recent_messages, list):
            for msg in recent_messages[:40]:
                if not isinstance(msg, dict):
                    continue
                ts = self._timestamp(msg.get('ts'))
                who = str(msg.get('from') or 'Unknown').strip()[:48]
                body = str(msg.get('text') or '').strip()[:220]
                if not body:
                    continue
                nid = self._notification_id('message', f'{ts}:{who}:{body}')
                if nid not in known:
                    rows.append({'id': nid, 'ts': ts, 'kind': 'message', 'text': f'Nuevo mensaje de {who}: {body}', 'read': False})
                    known.add(nid)

        requests = safe_json_read(FRIEND_REQUESTS_FILE, [])
        if isinstance(requests, list):
            for request in requests[:40]:
                if not isinstance(request, dict):
                    continue
                who = str(request.get('name') or 'Unknown').strip()[:48]
                ts = self._timestamp(request.get('ts'))
                nid = self._notification_id('friend_request', f"{request.get('user_id', '')}:{who}:{ts}")
                if nid not in known:
                    rows.append({'id': nid, 'ts': ts, 'kind': 'friend_request', 'text': f'Solicitud de amistad de {who}', 'read': False})
                    known.add(nid)

        achievement_state = safe_json_read(DATA_HOME / 'achievements.json', {})
        catalog = achievement_state.get('items', []) if isinstance(achievement_state, dict) else []
        unlocked = achievement_state.get('unlocked', []) if isinstance(achievement_state, dict) else []
        if isinstance(catalog, list) and isinstance(unlocked, list):
            by_id = {str(item.get('id') or ''): item for item in catalog if isinstance(item, dict)}
            for record in unlocked[-40:]:
                if not isinstance(record, dict):
                    continue
                aid = str(record.get('id') or '').strip()
                item = by_id.get(aid, {})
                title = str(item.get('title') or aid or 'Logro')
                ts = self._timestamp(record.get('ts'))
                nid = self._notification_id('achievement', f'{aid}:{ts}')
                if nid not in known:
                    rows.append({'id': nid, 'ts': ts, 'kind': 'achievement', 'text': f'Logro desbloqueado: {title}', 'read': False})
                    known.add(nid)

        rows.sort(key=lambda row: int(row.get('ts') or 0), reverse=True)
        rows = rows[:250]
        safe_json_write(NOTIFICATIONS_FILE, rows)
        return rows

    def reload(self):
        self.rows = self._collect_rows()
        self.listw.clear()
        unread = 0
        for row in self.rows:
            is_read = bool(row.get('read', False))
            unread += not is_read
            ts = self._timestamp(row.get('ts'))
            stamp = time.strftime('%Y-%m-%d %H:%M', time.localtime(ts)) if ts > 0 else 'Ahora'
            prefix = '  ' if is_read else '● '
            item = QtWidgets.QListWidgetItem(f"{prefix}{stamp}  [{str(row.get('kind') or 'info').upper()}]  {row.get('text', '')}")
            item.setData(QtCore.Qt.UserRole, str(row.get('id') or ''))
            self.listw.addItem(item)
        self.summary.setText(f'{unread} sin leer  |  {len(self.rows)} total')
        if self.listw.count():
            self.listw.setCurrentRow(0)

    def _save_rows(self):
        safe_json_write(NOTIFICATIONS_FILE, self.rows[:250])
        self.reload()

    def _mark_selected_read(self, item=None):
        item = item or self.listw.currentItem()
        if item is None:
            return
        selected_id = str(item.data(QtCore.Qt.UserRole) or '')
        for row in self.rows:
            if str(row.get('id') or '') == selected_id:
                row['read'] = True
                break
        self._save_rows()

    def _mark_all_read(self):
        for row in self.rows:
            row['read'] = True
        self._save_rows()

    def _clear_read(self):
        self.rows = [row for row in self.rows if not bool(row.get('read', False))]
        self._save_rows()

    def keyPressEvent(self, event):
        if event.key() in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            self._mark_selected_read()
            return
        if event.key() in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
            self.reject()
            return
        if event.key() == QtCore.Qt.Key_X:
            self._mark_all_read()
            return
        if event.key() == QtCore.Qt.Key_Y:
            self.reload()
            return
        super().keyPressEvent(event)


class AvatarPreviewFallback(QtWidgets.QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.avatar = {}
        self._rotation = 0.0
        self._drag_x = None
        self.setFocusPolicy(QtCore.Qt.StrongFocus)
        self.setCursor(QtGui.QCursor(QtCore.Qt.OpenHandCursor))
        self.setMinimumSize(300, 360)

    def set_avatar(self, avatar):
        self.avatar = dict(avatar or {})
        self.update()

    def mousePressEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            self._drag_x = event.pos().x()
            self.setCursor(QtGui.QCursor(QtCore.Qt.ClosedHandCursor))
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._drag_x is not None:
            delta = event.pos().x() - self._drag_x
            self._drag_x = event.pos().x()
            self._rotation = (self._rotation + delta * 0.9) % 360.0
            self.update()
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == QtCore.Qt.LeftButton:
            self._drag_x = None
            self.setCursor(QtGui.QCursor(QtCore.Qt.OpenHandCursor))
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def paintEvent(self, _event):
        painter = QtGui.QPainter(self)
        painter.setRenderHint(QtGui.QPainter.Antialiasing, True)
        bounds = self.rect()
        background = QtGui.QColor(self.avatar.get('background', '#12303a'))
        gradient = QtGui.QRadialGradient(bounds.center(), max(bounds.width(), bounds.height()) * 0.7)
        gradient.setColorAt(0, background.lighter(145))
        gradient.setColorAt(1, background.darker(220))
        painter.setBrush(gradient)
        painter.setPen(QtCore.Qt.NoPen)
        painter.drawRect(bounds)
        cx = bounds.center().x()
        scale = min(bounds.width() / 390.0, bounds.height() / 490.0)

        for ring in (148, 174):
            painter.setBrush(QtCore.Qt.NoBrush)
            painter.setPen(QtGui.QPen(QtGui.QColor(69, 226, 206, 24 if ring == 148 else 14), max(1, int(scale))))
            painter.drawEllipse(QtCore.QPointF(cx, bounds.height() * 0.47), ring * scale, ring * scale * 1.16)
        horizon = QtGui.QLinearGradient(0, bounds.height() * 0.72, 0, bounds.height())
        horizon.setColorAt(0, QtGui.QColor(27, 201, 170, 0))
        horizon.setColorAt(1, QtGui.QColor(27, 201, 170, 58))
        painter.fillRect(QtCore.QRectF(0, bounds.height() * 0.72, bounds.width(), bounds.height() * 0.28), horizon)

        painter.save()
        painter.translate(cx, bounds.height() * 0.49)
        painter.scale(max(0.36, abs(math.cos(math.radians(self._rotation)))), 1.0)
        painter.translate(-cx, -bounds.height() * 0.49)

        def shaded(color, rect):
            base = QtGui.QColor(color)
            fill = QtGui.QLinearGradient(rect.topLeft(), rect.topRight())
            fill.setColorAt(0, base.darker(145))
            fill.setColorAt(0.48, base.lighter(122))
            fill.setColorAt(1, base.darker(125))
            return fill

        def ellipse(x, y, w, h, color):
            rect = QtCore.QRectF(cx + x * scale, y * scale, w * scale, h * scale)
            painter.setBrush(shaded(color, rect))
            painter.setPen(QtGui.QPen(QtGui.QColor(255, 255, 255, 24), max(1, int(scale))))
            painter.drawEllipse(rect)
        def rounded(x, y, w, h, radius, color):
            rect = QtCore.QRectF(cx + x * scale, y * scale, w * scale, h * scale)
            painter.setBrush(shaded(color, rect))
            painter.setPen(QtGui.QPen(QtGui.QColor(10, 20, 23, 90), max(1, int(scale))))
            painter.drawRoundedRect(rect, radius * scale, radius * scale)

        skin = self.avatar.get('skin', '#bd815f')
        hair = self.avatar.get('hair_color', '#29313d')
        outfit = self.avatar.get('outfit', '#38b866')
        shadow = QtGui.QRadialGradient(cx, 372 * scale, 100 * scale)
        shadow.setColorAt(0, QtGui.QColor(0, 0, 0, 105))
        shadow.setColorAt(1, QtGui.QColor(0, 0, 0, 0))
        painter.setBrush(shadow)
        painter.setPen(QtCore.Qt.NoPen)
        painter.drawEllipse(QtCore.QRectF(cx - 105 * scale, 342 * scale, 210 * scale, 60 * scale))

        ellipse(-53, 326, 45, 66, '#172126')
        ellipse(8, 326, 45, 66, '#172126')
        ellipse(-65, 371, 66, 25, '#d4dddc')
        ellipse(0, 371, 66, 25, '#d4dddc')
        rounded(-78, 191, 55, 143, 25, outfit)
        rounded(23, 191, 55, 143, 25, outfit)
        rounded(-72, 173, 144, 174, 40, outfit)
        rounded(-16, 146, 32, 55, 13, skin)
        ellipse(-114, 198, 49, 121, skin)
        ellipse(65, 198, 49, 121, skin)
        ellipse(-58, 51, 116, 132, skin)
        ellipse(-64, 38, 128, 65, hair)
        hairstyle = self.avatar.get('hair_style')
        if hairstyle == 'Long':
            rounded(-65, 67, 29, 119, 13, hair)
            rounded(36, 67, 29, 119, 13, hair)
        elif hairstyle == 'Spiky':
            for spike in range(-2, 3):
                rounded(spike * 19 - 9, 13 + abs(spike) * 5, 19, 47, 9, hair)
        elif hairstyle == 'Curls':
            for curl in range(-2, 3):
                ellipse(curl * 22 - 12, 24 + abs(curl) * 4, 26, 30, hair)
        ellipse(-59, 104, 23, 39, skin)
        ellipse(36, 104, 23, 39, skin)
        ellipse(-31, 103, 10, 12, '#172126')
        ellipse(21, 103, 10, 12, '#172126')
        rounded(-38, 91, 21, 4, 2, hair)
        rounded(17, 91, 21, 4, 2, hair)
        ellipse(-5, 112, 10, 23, '#a96c53')
        painter.setPen(QtGui.QPen(QtGui.QColor('#563b35'), max(2, int(3 * scale))))
        painter.setBrush(QtCore.Qt.NoBrush)
        painter.drawArc(QtCore.QRectF(cx - 18 * scale, 126 * scale, 36 * scale, 23 * scale), 205 * 16, 130 * 16)
        rounded(-72, 184, 144, 12, 6, QtGui.QColor(outfit).lighter(150).name())
        rounded(-14, 208, 28, 83, 10, QtGui.QColor(outfit).darker(125).name())
        accessory = self.avatar.get('accessory')
        if accessory == 'Visor':
            rounded(-60, 95, 120, 24, 9, '#3dd7db')
            rounded(-49, 99, 33, 4, 2, '#ecffff')
        elif accessory == 'Halo':
            painter.setBrush(QtCore.Qt.NoBrush)
            painter.setPen(QtGui.QPen(QtGui.QColor('#f4d76e'), max(3, int(5 * scale))))
            painter.drawEllipse(QtCore.QRectF(cx - 48 * scale, 13 * scale, 96 * scale, 25 * scale))
        elif accessory == 'Headphones':
            painter.setBrush(QtCore.Qt.NoBrush)
            painter.setPen(QtGui.QPen(QtGui.QColor('#ccd8dc'), max(4, int(7 * scale))))
            painter.drawArc(QtCore.QRectF(cx - 70 * scale, 35 * scale, 140 * scale, 133 * scale), 0, 180 * 16)
            ellipse(-71, 91, 22, 48, '#879ba1')
            ellipse(49, 91, 22, 48, '#879ba1')
        painter.restore()
        painter.setPen(QtGui.QColor(222, 238, 235, 165))
        painter.setFont(QtGui.QFont('Segoe UI', max(9, int(11 * scale)), QtGui.QFont.DemiBold))
        painter.drawText(bounds.adjusted(14, 12, -14, -14), QtCore.Qt.AlignLeft | QtCore.Qt.AlignTop, 'XUI AVATAR PREVIEW')
        painter.setPen(QtGui.QColor(205, 224, 221, 190))
        painter.setFont(QtGui.QFont('Segoe UI', max(9, int(10 * scale))))
        painter.drawText(bounds.adjusted(14, 14, -14, -12), QtCore.Qt.AlignLeft | QtCore.Qt.AlignBottom, 'DRAG TO ROTATE')
        painter.end()


class AvatarStudioDialog(QtWidgets.QDialog):
    OPTIONS = {
        'skin': [('Warm', '#bd815f'), ('Light', '#efc8a2'), ('Deep', '#754b3d')],
        'hair_style': [('Short', 'Short'), ('Spiky', 'Spiky'), ('Long', 'Long'), ('Curls', 'Curls')],
        'hair_color': [('Midnight', '#29313d'), ('Silver', '#b9c5ca'), ('Auburn', '#a84f30'), ('Teal', '#38c7bd')],
        'outfit': [('Jade', '#38b866'), ('Cobalt', '#367dc3'), ('Crimson', '#c64d54')],
        'accessory': [('None', 'None'), ('Visor', 'Visor'), ('Headphones', 'Headphones'), ('Halo', 'Halo')],
        'background': [('Reactor', '#12303a'), ('Neon City', '#283354'), ('Forest', '#19473d')],
    }
    FIELD_LABELS = {
        'skin': 'Skin tone', 'hair_style': 'Hair style', 'hair_color': 'Hair color',
        'outfit': 'Outfit', 'accessory': 'Accessory', 'background': 'Scene',
    }
    OFFERS = [
        {'id': 'hair_gold', 'name': 'Solar gold', 'field': 'hair_color', 'value': '#e3b952', 'label': 'Solar Gold hair', 'price': 90},
        {'id': 'hair_violet', 'name': 'Ion violet', 'field': 'hair_color', 'value': '#a77be8', 'label': 'Ion Violet hair', 'price': 90},
        {'id': 'outfit_armor', 'name': 'Carbon armor', 'field': 'outfit', 'value': '#43b9bd', 'label': 'Carbon armor suit', 'price': 140},
        {'id': 'outfit_chrome', 'name': 'Chrome runner', 'field': 'outfit', 'value': '#aebbc4', 'label': 'Chrome runner suit', 'price': 120},
        {'id': 'accessory_crown', 'name': 'Light crown', 'field': 'accessory', 'value': 'Halo', 'label': 'Light crown', 'price': 110},
        {'id': 'scene_arcade', 'name': 'Arcade night', 'field': 'background', 'value': '#552e58', 'label': 'Arcade night scene', 'price': 75},
    ]
    DEFAULT_AVATAR = {
        'skin': '#bd815f', 'hair_style': 'Short', 'hair_color': '#29313d',
        'outfit': '#38b866', 'accessory': 'None', 'background': '#12303a',
    }

    def __init__(self, parent=None, initial_tab='creator'):
        super().__init__(parent)
        self.setWindowTitle('Avatar Studio')
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint | QtCore.Qt.WindowStaysOnTopHint)
        self.setModal(True)
        self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
        screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            self.setGeometry(screen.geometry())
        self.profile = safe_json_read(PROFILE_FILE, {})
        if not isinstance(self.profile, dict):
            self.profile = {}
        self.store = safe_json_read(AVATAR_STORE_FILE, {})
        if not isinstance(self.store, dict):
            self.store = {}
        try:
            self.store['credits'] = max(0, int(self.store.get('credits', 300)))
        except (TypeError, ValueError, OverflowError):
            self.store['credits'] = 300
        if not isinstance(self.store.get('owned'), list):
            self.store['owned'] = []
        self.avatar = dict(self.DEFAULT_AVATAR)
        saved_avatar = self.profile.get('avatar_customization')
        if not isinstance(saved_avatar, dict):
            saved_avatar = self.store.get('avatar')
        if isinstance(saved_avatar, dict):
            self.avatar.update(saved_avatar)
        self.controls = {}
        self.previews = []
        self._build()
        self._refresh_store()
        self._update_preview()
        self.tabs.setCurrentIndex(1 if initial_tab == 'store' else 0)

    def _build(self):
        self.setStyleSheet('''
            QDialog { background:#121a1d; color:#eef5f3; }
            QLabel { color:#e6efec; }
            QLabel#heading { color:#f4f8f6; font-size:25px; font-weight:800; }
