    def _refresh_dashboard_clock(self):
        if hasattr(self, 'dashboard_clock'):
            self.dashboard_clock.setText(time.strftime('%a  %d %b   %H:%M').upper())

    def _compute_ui_metrics(self):
        w = max(800, self.width())
        h = max(480, self.height())
        sw = w
        sh = h
        scr = QtWidgets.QApplication.primaryScreen()
        if scr is not None:
            g = scr.availableGeometry()
            sw = max(800, g.width())
            sh = max(480, g.height())
        vw = min(w, sw)
        vh = min(h, sh)
        rw = vw / 1280.0
        rh = vh / 900.0
        base_scale = min(rw, rh)
        force_compact = os.environ.get('XUI_COMPACT_UI', '0') == '1'
        compact = force_compact or (vw <= 1366) or (vh <= 768)
        scale = min(1.0, base_scale)
        if compact:
            boost = 1.08 if vh <= 800 else 1.0
            scale = min(1.0, scale * boost)
        if force_compact:
            scale = min(scale, 0.92)
        if self._low_power_ui:
            scale = max(0.58, scale)
        env_scale = str(os.environ.get('XUI_UI_SCALE', '')).strip()
        if env_scale:
            try:
                scale = max(0.58, min(1.15, float(env_scale)))
            except Exception:
                pass
        return scale, compact

    def _apply_responsive_layout(self):
        scale, compact = self._compute_ui_metrics()
        layout_key = (round(float(scale), 4), bool(compact), int(self.width()), int(self.height()))
        if layout_key == self._last_responsive_key:
            self._layout_overlays()
            return
        self._last_responsive_key = layout_key
        self._ui_scale = scale
        self._compact_ui = compact
        compact_factor = 0.80 if compact else 1.0
        if self._stage_layout is not None:
            side = max(24, int(min(self.width(), 1600) * 0.055 * (0.85 if compact else 1.0)))
            top = max(16, int(42 * scale * compact_factor))
            bottom = max(12, int(28 * scale * compact_factor))
            spacing = max(6, int(10 * scale * compact_factor))
            self._stage_layout.setContentsMargins(side, top, side, bottom)
            self._stage_layout.setSpacing(spacing)
        if hasattr(self, 'top_tabs') and self.top_tabs is not None:
            self.top_tabs.apply_scale(scale, compact)
        if hasattr(self, 'desc') and self.desc is not None:
            desc_px = max(10, int(18 * scale * (0.92 if compact else 1.0)))
            self.desc.setStyleSheet(
                f'font-size:{desc_px}px; color:rgba(35,35,35,0.78); '
                'font-family:"Segoe UI","Noto Sans",sans-serif;'
            )
        if hasattr(self, 'controls_hint') and self.controls_hint is not None:
            self.controls_hint.setText(
                '<span style="color:#68a923"><b>A</b></span> OPEN&nbsp;&nbsp; '
                '<span style="color:#d64235"><b>B</b></span> BACK&nbsp;&nbsp; '
                '<span style="color:#4594d2"><b>X</b></span> GUIDE'
                if compact else
                '<span style="color:#68a923"><b>A</b></span> OPEN&nbsp;&nbsp;&nbsp; '
                '<span style="color:#d64235"><b>B</b></span> BACK&nbsp;&nbsp;&nbsp; '
                '<span style="color:#4594d2"><b>X</b></span> GUIDE&nbsp;&nbsp;&nbsp; '
                '<span style="color:#dca91b"><b>Y</b></span> HOME&nbsp;&nbsp;&nbsp; LB / RB  CHANGE TAB'
            )
            controls_px = max(8, int(11 * scale * (0.90 if compact else 1.0)))
            self.controls_hint.setStyleSheet(
                f'font-size:{controls_px}px; color:#444444; font-weight:650; '
                'background:transparent; border:0; padding:5px 0;'
            )
        for p in self.pages:
            p.apply_scale(scale, compact)
        if self._achievement_toast is not None:
            self._achievement_toast.apply_scale(scale, compact)
            self._achievement_toast.reposition()
        self._layout_overlays()

    def _layout_overlays(self):
        if self._games_inline is None:
            return
        parent = self._games_inline.parentWidget()
        if parent is None:
            return
        pw = max(640, parent.width())
        ph = max(420, parent.height())
        margin_x = max(18, int(pw * 0.035))
        top = max(72, int(ph * 0.14))
        bottom_margin = max(12, int(ph * 0.06))
        w = max(920, pw - (margin_x * 2))
        h = max(520, ph - top - bottom_margin)
        x = margin_x
        y = top
        new_rect = QtCore.QRect(x, y, w, h)
        if self._games_inline.geometry() != new_rect:
            self._games_inline.setGeometry(new_rect)

    def showEvent(self, e):
        super().showEvent(e)
        QtCore.QTimer.singleShot(0, self._ensure_fullscreen)
        QtCore.QTimer.singleShot(0, self._apply_responsive_layout)
        if not self._startup_update_checked:
            self._startup_update_checked = True
            self._request_mandatory_update_payload(force=True)
            # Startup burst: detect mandatory updates immediately after dashboard appears.
            for delay in (120, 420, 900, 1700):
                QtCore.QTimer.singleShot(delay, self._check_mandatory_update_gate)
            self._start_mandatory_update_monitor()

    def _start_mandatory_update_monitor(self):
        if self._mandatory_update_timer is not None:
            return
        t = QtCore.QTimer(self)
        t.setInterval(20000 if self._ultra_low_ram else 15000)
        t.timeout.connect(self._check_mandatory_update_gate)
        t.start()
        self._mandatory_update_timer = t

    def _queue_mandatory_update_retry(self, delay_ms=900):
        if self._mandatory_update_retry_scheduled:
            return
        if self._mandatory_update_in_progress or self._mandatory_update_dialog_open:
            return
        try:
            delay = int(delay_ms)
        except Exception:
            delay = 900
        if delay < 180:
            delay = 180
        self._mandatory_update_retry_scheduled = True
        def _retry():
            self._mandatory_update_retry_scheduled = False
            self._check_mandatory_update_gate()
        QtCore.QTimer.singleShot(delay, _retry)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if self._tab_animating:
            self._finish_tab_animation(self._tab_anim_generation, self.tab_idx)
        self._apply_responsive_layout()

    def _ensure_fullscreen(self):
        if self._fullscreen_enforced:
            return
        self._fullscreen_enforced = True
        try:
            self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
            self.showFullScreen()
            self.raise_()
            self.activateWindow()
        except Exception:
            pass

    def _current_page(self):
        return self.pages[self.tab_idx]

    def _normalize_page_visibility(self, idx=None):
        if idx is None:
            idx = self.page_stack.currentIndex()
        idx = max(0, min(int(idx), len(self.pages) - 1))
        try:
            self.page_stack.setCurrentIndex(idx)
        except Exception:
            pass
        sl = self.page_stack.layout()
        if hasattr(sl, 'setStackingMode'):
            try:
                sl.setStackingMode(QtWidgets.QStackedLayout.StackOne)
            except Exception:
                pass
        for i, page in enumerate(self.pages):
            page.move(0, 0)
            try:
                page.setGraphicsEffect(None)
            except Exception:
                pass
            page.setVisible(i == idx)
            if i == idx:
                page.raise_()
        self._visible_page_idx = idx

    def _finish_tab_animation(self, generation, to_idx):
        if int(generation) != int(self._tab_anim_generation) or not self._tab_animating:
            return
        to_idx = max(0, min(int(to_idx), len(self.pages) - 1))
        group = self._tab_anim_group
        self._tab_animating = False
        self._tab_anim_group = None
        if group is not None and group.state() != QtCore.QAbstractAnimation.Stopped:
            group.stop()
        try:
            self.page_stack.setCurrentIndex(to_idx)
        except Exception:
            pass
        self._normalize_page_visibility(to_idx)
        overlay = self._tab_transition_overlay
        self._tab_transition_overlay = None
        if overlay is not None:
            try:
                overlay.hide()
                overlay.setGraphicsEffect(None)
                overlay.deleteLater()
            except Exception:
                pass
        wd = self._tab_anim_watchdog
        self._tab_anim_watchdog = None
        if wd is not None:
            try:
                wd.stop()
            except Exception:
                pass
            try:
                wd.deleteLater()
            except Exception:
                pass
        self.update_focus()

    def _animate_tab_transition(self, from_idx, to_idx):
        if from_idx == to_idx:
            self.page_stack.setCurrentIndex(to_idx)
            self._normalize_page_visibility(to_idx)
            return
        if self._tab_animating:
            return
        if self._reduced_motion:
            self.page_stack.setCurrentIndex(to_idx)
            self._normalize_page_visibility(to_idx)
            self.update_focus()
            return
        from_w = self.page_stack.widget(from_idx)
        to_w = self.page_stack.widget(to_idx)
        page_rect = self.page_stack.rect()
        snapshot = None
        if not self._ultra_low_ram and page_rect.width() > 0 and page_rect.height() > 0:
            try:
                snapshot = from_w.grab()
                if snapshot.isNull():
                    snapshot = None
            except Exception:
                snapshot = None
        self._tab_anim_generation += 1
        generation = self._tab_anim_generation
        self._tab_animating = True
        sl = self.page_stack.layout()
        if hasattr(sl, 'setStackingMode'):
            try:
                sl.setStackingMode(QtWidgets.QStackedLayout.StackOne)
            except Exception:
                pass
        self.page_stack.setCurrentIndex(to_idx)
        self._normalize_page_visibility(to_idx)
        self._tab_anim_group = QtCore.QParallelAnimationGroup(self)
        duration = 235 if self._low_power_ui else 300

        if snapshot is not None:
            overlay = QtWidgets.QLabel(self.page_stack)
            overlay.setAttribute(QtCore.Qt.WA_TransparentForMouseEvents, True)
            overlay.setAttribute(QtCore.Qt.WA_OpaquePaintEvent, True)
            overlay.setPixmap(snapshot)
            overlay.setGeometry(page_rect)
            overlay.show()
            overlay.raise_()
            self._tab_transition_overlay = overlay
            overlay_effect = QtWidgets.QGraphicsOpacityEffect(overlay)
            overlay_effect.setOpacity(1.0)
            overlay.setGraphicsEffect(overlay_effect)
            direction = 1 if to_idx > from_idx else -1
            travel = max(54, min(180, int(page_rect.width() * 0.14)))
            slide = QtCore.QPropertyAnimation(overlay, b'pos', self._tab_anim_group)
            slide.setDuration(duration)
            slide.setStartValue(QtCore.QPoint(page_rect.x(), page_rect.y()))
            slide.setEndValue(QtCore.QPoint(page_rect.x() - (direction * travel), page_rect.y()))
            slide.setEasingCurve(QtCore.QEasingCurve.OutCubic)
            fade_out = QtCore.QPropertyAnimation(overlay_effect, b'opacity', self._tab_anim_group)
            fade_out.setDuration(duration)
            fade_out.setStartValue(1.0)
            fade_out.setEndValue(0.0)
            fade_out.setEasingCurve(QtCore.QEasingCurve.OutCubic)
            self._tab_anim_group.addAnimation(slide)
            self._tab_anim_group.addAnimation(fade_out)

        def done():
            self._finish_tab_animation(generation, to_idx)

        self._tab_anim_group.finished.connect(done)
        self._tab_anim_group.start(QtCore.QAbstractAnimation.DeleteWhenStopped)
        watchdog = QtCore.QTimer(self)
        watchdog.setSingleShot(True)
        watchdog.setInterval(max(280, duration + 220))
        watchdog.timeout.connect(lambda: self._finish_tab_animation(generation, to_idx))
        self._tab_anim_watchdog = watchdog
        watchdog.start()

    def _switch_tab(self, idx, animate=True, keep_tabs_focus=False):
        idx = max(0, min(idx, len(self.tabs) - 1))
        if idx == self.tab_idx and self.page_stack.currentIndex() == idx:
            if keep_tabs_focus:
                self.focus_area = 'tabs'
                self.focus_idx = 0
            self.update_focus()
            return
        if self._tab_animating:
            return
        old_idx = self.tab_idx
        self.focus_memory[old_idx] = (self.focus_area, self.focus_idx)
        self.tab_idx = idx
        self.focus_area, self.focus_idx = self.focus_memory.get(idx, ('center', 0))
        if keep_tabs_focus:
            self.focus_area = 'tabs'
            self.focus_idx = 0
        if animate:
            self.top_tabs.set_current(self.tab_idx)
            self._animate_tab_transition(old_idx, idx)
        else:
            self.page_stack.setCurrentIndex(idx)
            self._normalize_page_visibility(idx)
            self.update_focus()
        self._play_sfx('open')

    def update_focus(self):
        if not self._tab_animating:
            self._normalize_page_visibility(self.tab_idx)
        self.top_tabs.set_current(self.tab_idx)
        tab_name = self.tabs[self.tab_idx]
        page = self._current_page()
        self.desc.setText(self.page_specs.get(tab_name, {}).get('hint', f'{tab_name}: use arrows and Enter'))
        center_count = max(1, 1 + len(page.center_tiles))

        if self.focus_area == 'left':
            if page.left_tiles:
                self.focus_idx = max(0, min(self.focus_idx, len(page.left_tiles) - 1))
            else:
                self.focus_area = 'center'
                self.focus_idx = 0
        elif self.focus_area == 'right':
            if page.right_tiles:
                self.focus_idx = max(0, min(self.focus_idx, len(page.right_tiles) - 1))
            else:
                self.focus_area = 'center'
                self.focus_idx = 0
        elif self.focus_area == 'center':
            self.focus_idx = max(0, min(self.focus_idx, center_count - 1))
        else:
            self.focus_idx = 0

        cur = (self.tab_idx, self.focus_area, self.focus_idx)
        if self._last_focus_state is not None and cur == self._last_focus_state:
            return

        for i, t in enumerate(page.left_tiles):
            t.set_selected(self.focus_area == 'left' and self.focus_idx == i)
        for i, t in enumerate(page.center_tiles):
            t.set_selected(self.focus_area == 'center' and self.focus_idx == (i + 1))
        for i, t in enumerate(page.right_tiles):
            t.set_selected(self.focus_area == 'right' and self.focus_idx == i)
        page.hero.set_selected(self.focus_area == 'center' and self.focus_idx == 0)

        if self._last_focus_state is None:
            self._last_focus_state = cur
        else:
            self._play_sfx('hover')
            self._last_focus_state = cur

    def _on_tab_changed(self, idx):
        self._switch_tab(idx, animate=True, keep_tabs_focus=True)

    def _open_current_tab_menu(self):
        name = self.tabs[self.tab_idx]
        options = self.tab_actions.get(name, [])
        if not options:
            self._msg(name, 'No actions configured.')
            return
        self._menu(name, options)

    def _steam_candidate_roots(self):
        home = Path.home()
        roots = [
            home / '.local' / 'share' / 'Steam',
            home / '.steam' / 'steam',
            home / '.var' / 'app' / 'com.valvesoftware.Steam' / 'data' / 'Steam',
        ]
        out = []
        seen = set()
        for p in roots:
            sp = str(p)
            if sp in seen:
                continue
            seen.add(sp)
            out.append(p)
        return out

    def _steam_library_dirs(self):
        libs = []
        seen = set()
        for root in self._steam_candidate_roots():
            steamapps = root / 'steamapps'
            key = str(steamapps)
            if steamapps.exists() and key not in seen:
                libs.append(steamapps)
                seen.add(key)
            lf = steamapps / 'libraryfolders.vdf'
            if not lf.exists():
                continue
            try:
                raw = lf.read_text(encoding='utf-8', errors='ignore')
            except Exception:
                raw = ''
            for m in re.finditer(r'"path"\s*"([^"]+)"', raw):
                ptxt = str(m.group(1) or '').replace('\\\\', '\\').strip()
                if not ptxt:
                    continue
                cand = Path(ptxt) / 'steamapps'
                key2 = str(cand)
                if cand.exists() and key2 not in seen:
                    libs.append(cand)
                    seen.add(key2)
        return libs

    def _steam_installed_games(self, limit=220):
        games = []
        seen = set()
        for lib in self._steam_library_dirs():
            try:
                manifests = sorted(lib.glob('appmanifest_*.acf'))
            except Exception:
                manifests = []
            for mf in manifests:
                if len(games) >= int(limit):
                    return games
                try:
                    raw = mf.read_text(encoding='utf-8', errors='ignore')
                except Exception:
                    continue
                m_id = re.search(r'"appid"\s*"(\d+)"', raw)
                m_name = re.search(r'"name"\s*"([^"]+)"', raw)
                if not m_id:
                    continue
                appid = str(m_id.group(1)).strip()
                if not appid or appid in seen:
                    continue
                seen.add(appid)
                name = str(m_name.group(1)).strip() if m_name else f'Steam App {appid}'
                games.append({
                    'platform': 'steam',
                    'appid': appid,
                    'name': name,
                })
        return games

    def _launch_steam_game_by_name(self, query):
        q = str(query or '').strip().lower()
        if not q:
            return False
        hits = []
        tokens = [tok for tok in re.split(r'[^a-z0-9]+', q) if tok]
        for game in self._steam_installed_games(limit=500):
            appid = str(game.get('appid', '')).strip()
            name = str(game.get('name', '')).strip()
            n = name.lower()
            if not appid or not name:
                continue
            ok = all(tok in n for tok in tokens) if tokens else (q in n)
            if ok:
                score = len(n)
                hits.append((score, appid, name))
        if not hits:
            return False
        hits.sort(key=lambda row: row[0])
        appid = str(hits[0][1])
        steam = XUI_HOME / 'bin' / 'xui_steam.sh'
        if steam.exists():
            self._run_game('/bin/sh', ['-c', f'"{steam}" -applaunch {appid}'])
        else:
            self._run_game('xdg-open', [f'steam://run/{appid}'])
        self._unlock_achievement_event('launch', 'steam')
        return True

    def _platform_games_tiles(self):
        tiles = []
        steam_games = self._steam_installed_games(limit=220)
        for g in steam_games:
            appid = str(g.get('appid', '')).strip()
            name = str(g.get('name', '')).strip() or f'Steam App {appid}'
            if not appid:
                continue
            tiles.append({
                'label': f'{name}',
                'play': f'Launch Steam Game::{appid}',
                'install': '',
                'uninstall': '',
                'desc': f'Steam installed game (AppID {appid}). Launch directly from Games.',
            })
        return tiles

