    def _extract_json_blob(self, text):
        raw = str(text or '').strip()
        if not raw:
            return None
        a = raw.find('{')
        b = raw.rfind('}')
        if a < 0 or b < 0 or b <= a:
            return None
        try:
            return json.loads(raw[a:b+1])
        except Exception:
            return None

    def _is_windows_runtime(self):
        return (os.name == 'nt') or str(sys.platform).lower().startswith('win')

    def _python_exec_for_update(self):
        candidates = []
        if str(getattr(sys, 'executable', '') or '').strip():
            candidates.append(str(sys.executable))
        if self._is_windows_runtime():
            candidates.extend(['py', 'python', 'python3'])
        else:
            candidates.extend(['python3', 'python'])
        seen = set()
        for c in candidates:
            c = str(c or '').strip()
            if not c or c in seen:
                continue
            seen.add(c)
            if os.path.isabs(c):
                if os.path.exists(c):
                    return c
                continue
            if shutil.which(c):
                return c
        return ''

    def _update_checker_path(self):
        xui_bin = XUI_HOME / 'bin'
        if self._is_windows_runtime():
            order = [xui_bin / 'xui_update_check.py', xui_bin / 'xui_update_check.sh']
        else:
            order = [xui_bin / 'xui_update_check.sh', xui_bin / 'xui_update_check.py']
        for p in order:
            try:
                if p.exists():
                    return p
            except Exception:
                continue
        return None

    def _update_checker_invocation(self, mode='mandatory', json_mode=False):
        checker = self._update_checker_path()
        if checker is None:
            return None
        mode = str(mode or 'status').strip() or 'status'
        if checker.suffix.lower() == '.py':
            pyexe = self._python_exec_for_update()
            if not pyexe:
                return None
            args = [str(checker), mode]
            if json_mode:
                args.append('--json')
            return pyexe, args
        checker_q = shlex.quote(str(checker))
        cmd = f'{checker_q} {mode}'
        if json_mode:
            cmd += ' --json'
        return '/bin/sh', ['-lc', cmd]

    def _request_mandatory_update_payload(self, force=False):
        invocation = self._update_checker_invocation('mandatory', json_mode=True)
        if invocation is None:
            return False
        proc = self._mandatory_payload_proc
        if proc is not None and proc.state() != QtCore.QProcess.NotRunning:
            return True
        now = time.monotonic()
        ttl = 4.0
        if (not force) and isinstance(self._mandatory_payload_cache, dict):
            if self._mandatory_payload_cache.get('checked') and (now - float(self._mandatory_payload_checked_at)) <= ttl:
                return False
        p = QtCore.QProcess(self)
        p.setProgram(invocation[0])
        p.setArguments(invocation[1])
        p.setProcessChannelMode(QtCore.QProcess.MergedChannels)

        def finished(_code, _status):
            self._mandatory_payload_watchdog.stop()
            try:
                out = bytes(p.readAllStandardOutput()).decode('utf-8', errors='ignore')
            except Exception:
                out = ''
            payload = self._extract_json_blob(out)
            if isinstance(payload, dict):
                self._mandatory_payload_cache = payload
            else:
                self._mandatory_payload_cache = {'checked': False, 'update_required': False}
            self._mandatory_payload_checked_at = time.monotonic()
            self._mandatory_payload_proc = None
            try:
                p.deleteLater()
            except Exception:
                pass
            if not bool(self._mandatory_payload_cache.get('checked', False)):
                self._queue_mandatory_update_retry(1800)
            if self.isVisible():
                QtCore.QTimer.singleShot(0, self._check_mandatory_update_gate)

        def errored(_err):
            self._mandatory_payload_watchdog.stop()
            self._mandatory_payload_cache = {'checked': False, 'update_required': False}
            self._mandatory_payload_checked_at = time.monotonic()
            self._mandatory_payload_proc = None
            try:
                p.deleteLater()
            except Exception:
                pass
            if self.isVisible():
                self._queue_mandatory_update_retry(1800)

        p.finished.connect(finished)
        p.errorOccurred.connect(errored)
        self._mandatory_payload_proc = p
        self._mandatory_payload_watchdog.start()
        p.start()
        return True

    def _mandatory_update_payload(self, force=False):
        if self._update_checker_path() is None:
            return None
        now = time.monotonic()
        ttl = 4.0
        if force:
            self._request_mandatory_update_payload(force=True)
        if isinstance(self._mandatory_payload_cache, dict):
            if self._mandatory_payload_cache.get('checked') and (now - float(self._mandatory_payload_checked_at)) <= ttl:
                return dict(self._mandatory_payload_cache)
        self._request_mandatory_update_payload(force=False)
        if isinstance(self._mandatory_payload_cache, dict):
            return dict(self._mandatory_payload_cache)
        return None

    def _launch_mandatory_updater_and_quit(self):
        invocation = self._update_checker_invocation('apply', json_mode=False)
        if invocation is None:
            self._msg('Update', 'Updater is unavailable. XUI will remain open.')
            return
        try:
            if self._mandatory_payload_proc is not None:
                if self._mandatory_payload_proc.state() != QtCore.QProcess.NotRunning:
                    self._mandatory_payload_proc.kill()
                self._mandatory_payload_proc.deleteLater()
                self._mandatory_payload_proc = None
        except Exception:
            pass
        if self._mandatory_update_proc is not None:
            if self._mandatory_update_proc.state() != QtCore.QProcess.NotRunning:
                return
        self._mandatory_update_in_progress = True
        self._mandatory_update_output = ''
        self._mandatory_update_stage = 'starting'
        self._mandatory_update_watchdog.stop()
        self._mandatory_update_watchdog.start()
        self._play_sfx('open')

        progress = UpdateProgressDialog(self)
        progress.set_stage('Conectando con el actualizador…', 6)
        progress.show()
        self._mandatory_update_progress = progress

        proc = QtCore.QProcess(self)
        env = QtCore.QProcessEnvironment.systemEnvironment()
        env.insert('AUTO_CONFIRM', '1')
        env.insert('XUI_SKIP_LAUNCH_PROMPT', '1')
        env.insert('GIT_TERMINAL_PROMPT', '0')
        env.insert('GCM_INTERACTIVE', 'Never')
        env.insert('GIT_HTTP_LOW_SPEED_LIMIT', '1000')
        env.insert('GIT_HTTP_LOW_SPEED_TIME', '30')
        proc.setProcessEnvironment(env)
        proc.setProgram(invocation[0])
        proc.setArguments(invocation[1])
        proc.setProcessChannelMode(QtCore.QProcess.MergedChannels)
        proc.readyReadStandardOutput.connect(self._on_mandatory_update_output)
        proc.finished.connect(self._on_mandatory_update_finished)
        proc.errorOccurred.connect(self._on_mandatory_update_error)
        self._mandatory_update_proc = proc
        proc.start()

    def _close_mandatory_update_progress(self):
        dlg = self._mandatory_update_progress
        self._mandatory_update_progress = None
        if dlg is None:
            return
        try:
            dlg.hide()
        except Exception:
            pass
        try:
            dlg.deleteLater()
        except Exception:
            pass

    def _on_mandatory_update_output(self):
        proc = self._mandatory_update_proc
        if proc is None:
            return
        try:
            chunk = bytes(proc.readAllStandardOutput()).decode('utf-8', errors='ignore')
        except Exception:
            chunk = ''
        if not chunk:
            return
        self._mandatory_update_watchdog.start()
        clean = re.sub(r'\x1b\][^\x07]*(?:\x07|\x1b\\)', '', chunk)
        clean = re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]', '', clean)
        clean = re.sub(r'\[\]P[0-9A-Fa-f]{6,}', '', clean)
        clean = ''.join(ch for ch in clean if ch in '\n\r\t' or ord(ch) >= 32)
        clean = clean.replace('\r', '\n')
        self._mandatory_update_output = (self._mandatory_update_output + clean)[-22000:]
        dlg = self._mandatory_update_progress
        if dlg is None:
            return
        stages = {
            'metadata-check': ('Comprobando la versión en GitHub…', 8),
            'sudo-auth': ('Comprobando permisos de actualización…', 10),
            'sudo-check': ('Comprobando permisos sin solicitar contraseña…', 12),
            'pkexec-auth': ('Esperando la confirmación de permisos del sistema…', 16),
            'git-clone': ('Descargando el repositorio inicial…', 24),
            'git-fetch': ('Descargando cambios de GitHub…', 38),
            'git-checkout': ('Seleccionando la rama de XUI…', 47),
            'git-reset': ('Preparando los archivos actualizados…', 54),
            'installer-search': ('Preparando el instalador de XUI…', 59),
            'installer-start': ('Aplicando archivos y configuración…', 64),
            'installer-done': ('Finalizando la instalación…', 91),
            'fnae-deps-background': ('Finalizando dependencias opcionales…', 94),
            'state-written': ('Guardando la versión instalada…', 97),
            'update-applied': ('Actualización aplicada; reiniciando XUI…', 99),
        }
        lines = [ln.strip() for ln in clean.splitlines() if ln.strip()]
        for line in lines:
            step = line.partition('=')[2].strip() if line.startswith('step=') else ''
            if line.startswith('step=') and step in stages:
                self._mandatory_update_stage = step
                label, percent = stages[step]
                dlg.set_stage(label, percent)
        useful = [line for line in lines if not line.startswith('step=')]
        if useful and hasattr(dlg, 'set_detail'):
            dlg.set_detail(useful[-1][:220])

    def _on_mandatory_update_stalled(self):
        proc = self._mandatory_update_proc
        if proc is None or proc.state() == QtCore.QProcess.NotRunning:
            return
        self._mandatory_update_watchdog.stop()
        stage = str(self._mandatory_update_stage or 'unknown')
        marker = f'ERROR: updater stalled for 5 minutes (last stage: {stage}).'
        self._mandatory_update_output = (self._mandatory_update_output + '\n' + marker)[-22000:]
        dlg = self._mandatory_update_progress
        if dlg is not None:
            dlg.set_detail('La actualización no responde; se detendrá para mostrar el diagnóstico.')
        proc.kill()

    def _on_mandatory_payload_stalled(self):
        proc = self._mandatory_payload_proc
        if proc is None or proc.state() == QtCore.QProcess.NotRunning:
            return
        self._mandatory_payload_watchdog.stop()
        proc.kill()
        self._mandatory_payload_proc = None
        self._mandatory_payload_checked_at = time.monotonic()
        self._mandatory_payload_cache = {'checked': False, 'update_required': False}
        self._queue_mandatory_update_retry(1800)

    def _build_update_status_code(self, text='', exit_code=None, process_err=None):
        raw = str(text or '').strip()
        if not raw:
            raw = 'unknown-update-failure'
        seed = f'{raw}|{exit_code}|{process_err}'
        hx = hashlib.sha1(seed.encode('utf-8', errors='ignore')).hexdigest().upper()
        return f'{hx[0:4]}-{hx[4:8]}-{hx[8:12]}-{hx[12:16]}-{hx[16:20]}-{hx[20:24]}'

    def _show_update_failed_dialog(self, detail_text='', status_code=''):
        code = str(status_code or '').strip() or self._build_update_status_code(detail_text)
        self._play_sfx('open')
        d = MandatoryUpdateFailedDialog(detail_text=detail_text, status_code=code, parent=self)
        d.exec_()
        self._play_sfx('back')

    def _restart_system_after_update(self):
        """Restart the host only after the mandatory update has completed successfully."""
        if self._is_windows_runtime():
            try:
                QtCore.QProcess.startDetached('cmd.exe', ['/c', 'shutdown /s /t 0 /f'])
                return True
            except Exception:
                return False

        if shutil.which('systemctl'):
            try:
                QtCore.QProcess.startDetached('systemctl', ['reboot'])
                return True
            except Exception:
                return False

        if shutil.which('sudo'):
            try:
                QtCore.QProcess.startDetached('sudo', ['-n', 'systemctl', 'reboot'])
                return True
            except Exception:
                return False

        try:
            QtCore.QProcess.startDetached('pkexec', ['systemctl', 'reboot'])
            return True
        except Exception:
            return False

    def _restart_dashboard_after_update(self):
        if self._is_windows_runtime():
            launcher = XUI_HOME / 'bin' / 'xui_start.bat'
            dash = XUI_HOME / 'dashboard' / 'pyqt_dashboard_improved.py'
            started = False
            try:
                if launcher.exists():
                    started = QtCore.QProcess.startDetached('cmd.exe', ['/c', str(launcher)])
            except Exception:
                started = False
            if not started:
                pyexe = self._python_exec_for_update() or str(getattr(sys, 'executable', 'python'))
                try:
                    QtCore.QProcess.startDetached(pyexe, [str(dash)])
                except Exception:
                    pass
            QtCore.QTimer.singleShot(520, self._request_application_exit)
            return

        helper = XUI_HOME / 'bin' / 'xui_postupdate_restart.sh'
        script = '''#!/usr/bin/env bash
set -euo pipefail
WRAP="$HOME/.xui/bin/xui_startup_and_dashboard.sh"
START_SH="$HOME/.xui/bin/xui_start.sh"
PYRUN="$HOME/.xui/bin/xui_python.sh"
DASH="$HOME/.xui/dashboard/pyqt_dashboard_improved.py"
OLD_PID="${1:-}"
RESTART_LOG="$HOME/.xui/logs/postupdate_restart.log"
mkdir -p "$(dirname "$RESTART_LOG")"
touch "$RESTART_LOG"
exec >>"$RESTART_LOG" 2>&1
echo "[$(date -Is)] post-update restart requested (old pid: ${OLD_PID:-unknown})"
RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
DBUS_ADDR="${DBUS_SESSION_BUS_ADDRESS:-unix:path=${RUNTIME_DIR}/bus}"
SESSION_ENV=()
for name in DISPLAY WAYLAND_DISPLAY XAUTHORITY XDG_SESSION_TYPE XDG_CURRENT_DESKTOP DESKTOP_SESSION QT_QPA_PLATFORM; do
    if [[ -n "${!name:-}" ]]; then
        SESSION_ENV+=("$name=${!name}")
    fi
done
SESSION_ENV+=("XDG_RUNTIME_DIR=$RUNTIME_DIR" "DBUS_SESSION_BUS_ADDRESS=$DBUS_ADDR" "XUI_POSTUPDATE_RESTART=1")

wait_old_dashboard_exit(){
  local pid="$1"
  if [[ ! "$pid" =~ ^[0-9]+$ ]]; then
    return 0
  fi
  if [ "$pid" -le 1 ]; then
    return 0
  fi
  for _ in $(seq 1 140); do
    if ! kill -0 "$pid" >/dev/null 2>&1; then
      return 0
    fi
    sleep 0.10
  done
    return 1
}

start_via_wrapper(){
  if [ -x "$WRAP" ]; then
        nohup env "${SESSION_ENV[@]}" "$WRAP" &
        LAUNCH_PID=$!
        echo "[$(date -Is)] started wrapper pid $LAUNCH_PID: $WRAP"
    return 0
  fi
  if [ -x "$START_SH" ]; then
        nohup env "${SESSION_ENV[@]}" "$START_SH" &
        LAUNCH_PID=$!
        echo "[$(date -Is)] started launcher pid $LAUNCH_PID: $START_SH"
    return 0
  fi
  return 1
}

start_direct_dashboard(){
  if [ -x "$PYRUN" ] && [ -f "$DASH" ]; then
        nohup env "${SESSION_ENV[@]}" "$PYRUN" "$DASH" &
        LAUNCH_PID=$!
        echo "[$(date -Is)] started dashboard runner pid $LAUNCH_PID"
    return 0
  fi
  if command -v python3 >/dev/null 2>&1 && [ -f "$DASH" ]; then
        nohup env "${SESSION_ENV[@]}" python3 "$DASH" &
        LAUNCH_PID=$!
        echo "[$(date -Is)] started python dashboard pid $LAUNCH_PID"
    return 0
  fi
  return 1
}

new_dashboard_running(){
    local cmdline
    [[ "${LAUNCH_PID:-}" =~ ^[0-9]+$ ]] || return 1
    kill -0 "$LAUNCH_PID" >/dev/null 2>&1 || return 1
    [ -r "/proc/$LAUNCH_PID/cmdline" ] || return 1
    cmdline="$(tr '\0' ' ' < "/proc/$LAUNCH_PID/cmdline" 2>/dev/null || true)"
    [[ "$cmdline" == *pyqt_dashboard_improved.py* || "$cmdline" == *pyqt_dashboard.py* ]]
}

activate_dashboard_window(){
    if command -v wmctrl >/dev/null 2>&1; then
        wmctrl -a 'XUI - Xbox 360 Style' >/dev/null 2>&1 && return 0
        wmctrl -a 'XUI' >/dev/null 2>&1 && return 0
    fi
    if command -v xdotool >/dev/null 2>&1 && [[ -n "${DISPLAY:-}" ]]; then
        local wid
        wid="$(xdotool search --onlyvisible --name 'XUI' 2>/dev/null | head -n 1 || true)"
        if [[ -z "$wid" ]]; then
            wid="$(xdotool search --onlyvisible --class 'pyqt_dashboard_improved' 2>/dev/null | head -n 1 || true)"
    fi
        if [[ -n "$wid" ]]; then
            xdotool windowactivate --sync "$wid" >/dev/null 2>&1 || true
            xdotool windowraise "$wid" >/dev/null 2>&1 || true
            return 0
        fi
    fi
    return 1
}

wait_for_dashboard_window(){
    for _ in $(seq 1 60); do
                if new_dashboard_running; then
            if activate_dashboard_window; then
                                echo "[$(date -Is)] activated new dashboard pid $LAUNCH_PID"
                return 0
            fi
        fi
        sleep 0.20
    done
        if new_dashboard_running; then
            # Wayland may not support external activation; Qt's fullscreen show remains authoritative.
            echo "[$(date -Is)] new dashboard pid $LAUNCH_PID is running; no external activation tool succeeded"
            return 0
        fi
        echo "[$(date -Is)] dashboard launch failed; pid ${LAUNCH_PID:-unknown} exited before startup"
        return 1
}

if ! wait_old_dashboard_exit "$OLD_PID"; then
    if [[ "$OLD_PID" =~ ^[0-9]+$ ]] && [ "$OLD_PID" -gt 1 ]; then
        echo "[$(date -Is)] old dashboard did not exit in time; sending TERM"
        kill -TERM "$OLD_PID" >/dev/null 2>&1 || true
        for _ in $(seq 1 30); do
            kill -0 "$OLD_PID" >/dev/null 2>&1 || break
            sleep 0.10
        done
        if kill -0 "$OLD_PID" >/dev/null 2>&1; then
          echo "[$(date -Is)] old dashboard still exists after TERM; sending KILL"
          kill -KILL "$OLD_PID" >/dev/null 2>&1 || true
        fi
    fi
fi
sleep 0.20

if start_via_wrapper; then
    wait_for_dashboard_window && exit 0
fi

if start_direct_dashboard; then
    wait_for_dashboard_window && exit 0
fi

exit 1
'''
        try:
            helper.parent.mkdir(parents=True, exist_ok=True)
            helper.write_text(script, encoding='utf-8')
            helper.chmod(0o755)
        except Exception:
            pass
        helper_q = shlex.quote(str(helper))
        current_pid_q = shlex.quote(str(os.getpid()))
        cmd = f'nohup {helper_q} {current_pid_q} >/dev/null 2>&1 &'
        QtCore.QProcess.startDetached('/bin/sh', ['-lc', cmd])
        QtCore.QTimer.singleShot(520, self._request_application_exit)

    def _on_mandatory_update_error(self, err):
        self._on_mandatory_update_output()
        self._mandatory_update_watchdog.stop()
        self._close_mandatory_update_progress()
        proc = self._mandatory_update_proc
        self._mandatory_update_proc = None
        if proc is not None:
            proc.deleteLater()
        self._mandatory_update_in_progress = False
        try:
            err_code = int(err)
        except Exception:
            err_code = str(err)
        detail = f'Updater process error: {err_code}'
        status_code = self._build_update_status_code(detail, process_err=err_code)
        self._show_update_failed_dialog(detail, status_code)
        QtCore.QTimer.singleShot(250, self._check_mandatory_update_gate)

    def _on_mandatory_update_finished(self, code, status):
        self._on_mandatory_update_output()
        self._mandatory_update_watchdog.stop()
        proc = self._mandatory_update_proc
        self._mandatory_update_proc = None
        if proc is not None:
            proc.deleteLater()
        self._mandatory_update_in_progress = False
        ok = (status == QtCore.QProcess.NormalExit and int(code) == 0)
        if not ok:
            # Soft-success fallback: updater can return non-zero even when files/state are already updated.
            out = str(self._mandatory_update_output or '')
            if ('update-applied' in out) or ('step=state-written' in out):
                ok = True
            else:
                try:
                    payload_after = self._mandatory_update_payload()
                except Exception:
                    payload_after = {}
                if isinstance(payload_after, dict):
                    if bool(payload_after.get('checked', False)) and not bool(payload_after.get('update_required', True)):
                        ok = True
                if not ok:
                    lower_out = out.lower()
                    success_hits = 0
                    for marker in (
                        'finalizing installation',
                        'installation complete',
                        'attempted to enable user services',
                        'configured passwordless sudo for xui actions',
                    ):
                        if marker in lower_out:
                            success_hits += 1
                    if success_hits >= 2:
                        fatal_markers = (
                            'sudo authentication failed',
                            'cannot reach github metadata',
                            'installer failed with code',
                            'permission denied',
                            'permiso denegado',
                            'traceback (most recent call last)',
                            'no space left on device',
                            'command not found',
                        )
                        if not any(m in lower_out for m in fatal_markers):
                            ok = True
        if ok:
            dlg = self._mandatory_update_progress
            if dlg is not None and hasattr(dlg, 'finish_ok'):
                dlg.finish_ok()
                QtCore.QTimer.singleShot(360, self._close_mandatory_update_progress)
            else:
                self._close_mandatory_update_progress()
            self._msg('Update', 'Mandatory update installed. Restarting system...')
            if not self._restart_system_after_update():
                self._show_update_failed_dialog(
                    'The update was applied, but this system could not launch a restart.\n\nRestart manually from the system menu.',
                    self._build_update_status_code('restart-command-unavailable')
                )
                self._mandatory_update_in_progress = False
                return
            self._mandatory_update_in_progress = False
            return
        self._close_mandatory_update_progress()
        lines = [ln for ln in self._mandatory_update_output.splitlines() if ln.strip()]
        tail = '\n'.join(lines[-14:]).strip()
        if not tail:
            tail = f'Updater finished with exit code: {int(code)}'
        detail = (
            'Could not apply mandatory update.\n\n'
            + tail
            + '\n\nFix network/git access and try again.'
        )
        status_code = self._build_update_status_code(tail, exit_code=code, process_err=status)
        self._show_update_failed_dialog(detail, status_code)
        QtCore.QTimer.singleShot(250, self._check_mandatory_update_gate)

    def _check_mandatory_update_gate(self):
        if self._mandatory_update_in_progress:
            return
        if self._mandatory_update_dialog_open:
            return
        if not self.isVisible():
            self._queue_mandatory_update_retry(1200)
            return
        if QtWidgets.QApplication.activeModalWidget() is not None:
            # Defer while another popup is active, then retry quickly.
            self._queue_mandatory_update_retry(900)
            return
        payload = self._mandatory_update_payload()
        if not isinstance(payload, dict):
            self._queue_mandatory_update_retry(3000)
            return
        if not bool(payload.get('checked', False)):
            # Network/GitHub can come up a bit later after boot; retry sooner than monitor interval.
            self._queue_mandatory_update_retry(4500)
            return
        if not bool(payload.get('update_required', False)):
            return
        self._play_sfx('open')
        self._mandatory_update_dialog_open = True
        d = MandatoryUpdateDialog(payload, self)
        selected = 'No'
        if d.exec_() == QtWidgets.QDialog.Accepted:
            selected = d.selected_choice()
        self._mandatory_update_dialog_open = False
        if str(selected).strip().lower() == 'yes':
            self._launch_mandatory_updater_and_quit()
            return
        self._msg('Update', 'La actualización es obligatoria. XUI se cerrará; vuelve a abrirlo para instalarla.')
        self._request_application_exit()

    def _request_application_exit(self):
        self._allow_exit = True
        QtWidgets.QApplication.quit()

    def _save_recent(self, action):
        try:
            arr = json.loads(RECENT_FILE.read_text()) if RECENT_FILE.exists() else []
            arr = [x for x in arr if x != action]
            arr.insert(0, action)
            RECENT_FILE.write_text(json.dumps(arr[:20], indent=2))
        except Exception:
            pass

    def _play_sfx(self, name):
        key = str(name or '').strip()
        if not key:
            return
        now = time.monotonic()
        if key == 'hover':
            if (now - self._last_hover_at) < 0.08:
                return
            self._last_hover_at = now
        candidates = []
        base = self.sfx.get(key)
        if base:
            candidates.append(base)
        candidates.extend(self.sfx_aliases.get(key, []))
        cache_key = (key, tuple(candidates))
        snd = None
        cached = self._sfx_path_cache.get(cache_key)
        if cached:
            cp = Path(cached)
            if cp.exists():
                snd = cp
        if snd is None:
            snd = pick_existing_sound(candidates)
            if snd is not None:
                self._sfx_path_cache[cache_key] = str(snd)
        if snd is None:
            return
        play_media(snd, video=False, blocking=False)

    def _setup_achievement_toast(self):
        self._achievement_toast = AchievementToast(self)
        self._achievement_toast.finished.connect(self._on_achievement_toast_finished)
        self._achievement_toast.apply_scale(self._ui_scale, self._compact_ui)

    def _queue_achievement_unlocks(self, rows):
        if not rows:
            return
        for row in rows:
            if isinstance(row, dict):
                aid = str(row.get('id', '')).strip()
                if aid and aid in self._achievement_queued_ids:
                    continue
                self._achievement_queue.append(row)
                if aid:
                    self._achievement_queued_ids.add(aid)
        if self._achievement_toast is None:
            return
        if not self._achievement_toast.isVisible():
            self._show_next_achievement_toast()

    def _show_next_achievement_toast(self):
        if self._achievement_toast is None:
            return
        if not self._achievement_queue:
            return
        row = self._achievement_queue.pop(0)
        aid = str(row.get('id', '')).strip()
        if aid and aid in self._achievement_queued_ids:
            self._achievement_queued_ids.discard(aid)
        title = str(row.get('title') or row.get('id') or 'Achievement')
        score = int(row.get('score', 0) or 0)
        now = time.monotonic()
        if (now - float(self._achievement_last_sfx_at)) > 0.75:
            self._play_sfx('achievement')
            self._achievement_last_sfx_at = now
        self._achievement_toast.show_achievement(title, score=score)

    def _on_achievement_toast_finished(self):
        if not self._achievement_queue:
            return
        QtCore.QTimer.singleShot(80, self._show_next_achievement_toast)

    def _unlock_achievement_event(self, kind, value):
        try:
            fresh = unlock_for_event(kind, value, limit=4)
        except Exception:
            fresh = []
        if fresh:
            self._queue_achievement_unlocks(fresh)

    def _launch_event_keys(self, action):
        mapping = {
            'casino': ('casino', 'game_casino'),
            'runner': ('runner', 'game_runner'),
            'gem_match': ('gem_match', 'minigame_bejeweled_xui'),
            'bejeweled': ('gem_match', 'minigame_bejeweled_xui'),
            'fnae': ('fnae', 'game_fnae_fangame'),
            'five_night_s_at_epstein_s': ('fnae', 'game_fnae_fangame'),
            'five_nights_at_epstein_s': ('fnae', 'game_fnae_fangame'),
            'steam': ('steam', 'platform_steam'),
            'retroarch': ('retroarch', 'platform_retroarch'),
            'lutris': ('lutris', 'platform_lutris'),
            'heroic': ('heroic', 'platform_heroic'),
            'store': ('store', 'xui_store_modern'),
            'avatar_store': ('store', 'xui_store_modern'),
            'web_browser': ('web_browser', 'browser_xui_webhub'),
            'media_player': ('media_player',),
            'boot_video': ('boot_video',),
            'playlist': ('playlist',),
            'visualizer': ('visualizer',),
            'system_music': ('system_music',),
            'netflix': ('netflix',),
            'youtube': ('youtube',),
            'kodi': ('kodi',),
            'app_launcher': ('app_launcher',),
            'missions': ('missions', 'game_missions'),
            'misiones': ('missions', 'game_missions'),
            'xui_web_browser': ('web_browser', 'browser_xui_webhub'),
        }
        key = ''.join(ch.lower() if ch.isalnum() else '_' for ch in str(action or '')).strip('_')
        while '__' in key:
            key = key.replace('__', '_')
        return mapping.get(key, ())

    def _run(self, cmd, args=None):
        self._play_sfx('open')
        try:
            argv = list(args or [])
            if str(cmd) in ('/bin/sh', 'sh', '/bin/bash', 'bash') and len(argv) >= 2 and str(argv[0]) in ('-c', '-lc'):
                argv[1] = self._with_controller_env_cmd(argv[1])
            result = QtCore.QProcess.startDetached(str(cmd), argv)
            started = result[0] if isinstance(result, tuple) else bool(result)
            if not started:
                self._msg('App launch', f'No se pudo iniciar: {cmd}. Comprueba que el archivo exista y tenga permiso de ejecución.')
            return bool(started)
        except Exception as exc:
            self._msg('App launch', f'No se pudo iniciar {cmd}: {exc}')
            return False

    def _launch_local_python_app(self, title, relative_script, game=False):
        script = XUI_HOME / relative_script
        if not script.is_file():
            self._msg(str(title or 'App'), f'No se encontró el archivo de la app:\n{script}\n\nEjecuta de nuevo el instalador para restaurar los archivos.')
            return False
        launcher = XUI_HOME / 'bin' / 'xui_python.sh'
        program = str(launcher) if launcher.is_file() and os.access(launcher, os.X_OK) else sys.executable
        if not program or not Path(program).exists():
            self._msg(str(title or 'App'), 'No se encontró Python 3 para abrir esta app.')
            return False
        if game:
            return self._run_game(program, [str(script)])
        return self._run(program, [str(script)])

    def _run_game(self, cmd, args=None):
        intro_launcher = XUI_HOME / 'bin' / 'xui_play_game_intro.sh'
        if not intro_launcher.is_file():
                self._msg('Game boot screen', f'No se encontró el reproductor obligatorio:\n{intro_launcher}\n\nEjecuta de nuevo el instalador para restaurar el boot screen.')
                return False
        command = [str(intro_launcher), '--', str(cmd), *(str(arg) for arg in (args or []))]
        shell_command = ' '.join(shlex.quote(part) for part in command)
        return self._run('/bin/sh', ['-c', shell_command])

    def _controller_env_exports(self):
        env_file = XUI_HOME / 'data' / 'controller_profile.env'
        if not env_file.exists():
            return ''
        parts = []
        try:
            for raw in env_file.read_text(encoding='utf-8', errors='ignore').splitlines():
                line = str(raw).strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                k, v = line.split('=', 1)
                k = str(k).strip()
                v = str(v).strip()
                if not k:
                    continue
                if not (k.startswith('XUI_JOY_') or k.startswith('SDL_') or k.startswith('QT_')):
                    continue
                parts.append(f'export {k}={shlex.quote(v)}')
        except Exception:
            return ''
        return '; '.join(parts)

    def _with_controller_env_cmd(self, shell_cmd):
        exports = self._controller_env_exports()
        body = str(shell_cmd or '').strip()
        if not exports:
            return body
        if not body:
            return exports
        return f'{exports}; {body}'

    def _run_terminal(self, shell_cmd):
        self._play_sfx('open')
        base_cmd = self._with_controller_env_cmd(shell_cmd)
        hold = base_cmd + '; echo; read -r -p "Press Enter to close..." _'
        if shutil.which('x-terminal-emulator'):
            QtCore.QProcess.startDetached('x-terminal-emulator', ['-e', '/bin/bash', '-lc', hold])
            return
        if shutil.which('gnome-terminal'):
            QtCore.QProcess.startDetached('gnome-terminal', ['--', '/bin/bash', '-lc', hold])
            return
        if shutil.which('konsole'):
            QtCore.QProcess.startDetached('konsole', ['-e', '/bin/bash', '-lc', hold])
            return
        if shutil.which('xterm'):
            QtCore.QProcess.startDetached('xterm', ['-e', '/bin/bash', '-lc', hold])
            return
        QtCore.QProcess.startDetached('/bin/bash', ['-lc', hold])

    def _close_install_task_progress(self):
        dlg = self._install_task_progress
        self._install_task_progress = None
        if dlg is None:
            return
        try:
            dlg.hide()
        except Exception:
            pass
        try:
            dlg.deleteLater()
        except Exception:
            pass

    def _on_install_task_output(self):
        proc = self._install_task_proc
        if proc is None:
            return
        try:
            chunk = bytes(proc.readAllStandardOutput()).decode('utf-8', errors='ignore')
        except Exception:
            chunk = ''
        if not chunk:
            return
        self._install_task_output = (self._install_task_output + chunk)[-26000:]
        dlg = self._install_task_progress
        if dlg is None:
            return
        lines = [ln.strip() for ln in self._install_task_output.splitlines() if ln.strip()]
        if lines:
            dlg.set_detail(lines[-1][:180])

    def _on_install_task_error(self, err):
        self._on_install_task_output()
        proc = self._install_task_proc
        self._install_task_proc = None
        if proc is not None:
            proc.deleteLater()
        dlg = self._install_task_progress
        if dlg is not None and hasattr(dlg, 'finish_error'):
            dlg.finish_error('Installer process error.')
        self._close_install_task_progress()
        self._msg(f'{self._install_task_label or "Install"} Failed', f'Process error: {err}')

    def _on_install_task_finished(self, code, status):
        self._on_install_task_output()
        proc = self._install_task_proc
        self._install_task_proc = None
        if proc is not None:
            proc.deleteLater()
        ok = (status == QtCore.QProcess.NormalExit and int(code) == 0)
        if ok:
            dlg = self._install_task_progress
            if dlg is not None and hasattr(dlg, 'finish_ok'):
                dlg.finish_ok('Install completed successfully.')
            QtCore.QTimer.singleShot(260, self._close_install_task_progress)
            success_txt = str(self._install_task_success_msg or f'{self._install_task_label} installed.')
            launch_cmd = str(self._install_task_launch_cmd or '').strip()
            if launch_cmd:
                self._run('/bin/sh', ['-c', launch_cmd])
            self._msg(str(self._install_task_label or 'Install'), success_txt)
            return
        dlg = self._install_task_progress
        if dlg is not None and hasattr(dlg, 'finish_error'):
            dlg.finish_error('Install failed.')
        self._close_install_task_progress()
        lines = [ln.strip() for ln in self._install_task_output.splitlines() if ln.strip()]
        tail = '\n'.join(lines[-10:]).strip()
        fail_txt = str(self._install_task_fail_msg or f'{self._install_task_label} install failed.')
        if 'Xbox 360 Homebrew catalog' in self._install_task_label and 'GitHub devolvió 404' in tail:
            fail_txt = (
                'No se encontró el catálogo público. Comprueba que el repositorio sea público y que '
                'el propietario, la rama y la ruta del TXT sean correctos.\n\n' + tail
            )
        if tail:
            if tail not in fail_txt:
                fail_txt = fail_txt + '\n\n' + tail
        self._msg(f'{self._install_task_label or "Install"} Failed', fail_txt)

    def _run_install_task(self, title, shell_cmd, success_msg='', fail_msg='', launch_cmd=''):
        if self._install_task_proc is not None and self._install_task_proc.state() != QtCore.QProcess.NotRunning:
            self._msg('Install', 'Another installation is already running.')
            return
        self._play_sfx('open')
        self._install_task_output = ''
        self._install_task_success_msg = str(success_msg or '')
        self._install_task_fail_msg = str(fail_msg or '')
        self._install_task_launch_cmd = str(launch_cmd or '')
        self._install_task_label = str(title or 'App')
        dlg = InstallTaskProgressDialog(self._install_task_label, self)
        dlg.show()
        self._install_task_progress = dlg
        proc = QtCore.QProcess(self)
        env = QtCore.QProcessEnvironment.systemEnvironment()
        env_file = XUI_HOME / 'data' / 'controller_profile.env'
        if env_file.exists():
            try:
                for raw in env_file.read_text(encoding='utf-8', errors='ignore').splitlines():
                    line = str(raw).strip()
                    if not line or line.startswith('#') or '=' not in line:
                        continue
                    k, v = line.split('=', 1)
                    k = str(k).strip()
                    if not k:
                        continue
                    if k.startswith('XUI_JOY_') or k.startswith('SDL_') or k.startswith('QT_'):
                        env.insert(k, str(v).strip())
            except Exception:
                pass
        env.insert('XUI_NONINTERACTIVE', '1')
        env.insert('XUI_FORCE_ELEVATED', '1')
        env.insert('DEBIAN_FRONTEND', 'noninteractive')
        proc.setProcessEnvironment(env)
        proc.setProgram('/bin/sh')
        proc.setArguments(['-lc', str(shell_cmd)])
        proc.setProcessChannelMode(QtCore.QProcess.MergedChannels)
        proc.readyReadStandardOutput.connect(self._on_install_task_output)
        proc.finished.connect(self._on_install_task_finished)
        proc.errorOccurred.connect(self._on_install_task_error)
        self._install_task_proc = proc
        proc.start()

    def _open_url(self, url):
        self._prune_web_windows()
        if QtWebEngineWidgets is not None:
            try:
                w = WebKioskWindow(url, self, sfx_cb=self._play_sfx)
                w.setAttribute(QtCore.Qt.WA_DeleteOnClose, True)
                w.destroyed.connect(self._on_web_window_destroyed)
                self._web_windows.append(w)
                w.showFullScreen()
                self._play_sfx('open')
                return
            except Exception:
                pass
        kiosk = XUI_HOME / 'bin' / 'xui_browser.sh'
        if kiosk.exists():
            self._run('/bin/sh', ['-c', f'"{kiosk}" --kiosk "{url}"'])
            return
        if shutil.which('xdg-open'):
            self._run('/bin/sh', ['-c', f'xdg-open "{url}"'])
            return
        self._msg('Browser', f'No browser launcher available.\n{url}')

    def _on_web_window_destroyed(self, _obj=None):
        self._prune_web_windows()

    def _prune_web_windows(self):
        alive = []
        for w in list(self._web_windows):
            if w is None:
                continue
            try:
                _ = w.windowTitle()
            except Exception:
                continue
            alive.append(w)
        self._web_windows = alive

    def _open_url_external(self, url, normal_mode=True):
        u = str(url or '').strip()
        if not u:
            return
        qurl = QtCore.QUrl(u)
        if qurl.scheme().lower() in ('http', 'https'):
            self._open_url(u)
            return
        try:
            if QtGui.QDesktopServices.openUrl(qurl):
                self._play_sfx('open')
                return
        except Exception:
            pass
        kiosk = XUI_HOME / 'bin' / 'xui_browser.sh'
        if kiosk.exists():
            mode = '--hub' if bool(normal_mode) else '--kiosk'
            self._run('/bin/sh', ['-c', f'"{kiosk}" {mode} "{u}"'])
            return
        self._run('/bin/sh', ['-c', f'xdg-open "{u}"'])

    def _open_social_chat(self, initial_mode='messages'):
        self._play_sfx('open')
        if self._social_overlay is None:
            self._social_overlay = SocialOverlay(
                self,
                notification_cb=lambda: self._play_sfx('notification'),
                engine=self._social_engine,
            )
        try:
            self._social_overlay._set_community_mode(initial_mode)
        except Exception:
            pass
        self._social_overlay.show()
        self._social_overlay.raise_()
        self._social_overlay.activateWindow()

    def _poll_social_events(self):
        if self._social_overlay is not None:
            self._social_overlay._poll_events()

