    def _system_snapshot_text(self):
        lines = []
        try:
            lines.append(f'Platform: {subprocess.check_output(["uname", "-srmo"], text=True, timeout=2).strip()}')
        except Exception:
            lines.append(f'Platform: {sys.platform}')
        try:
            mem = {}
            with open('/proc/meminfo', 'r', encoding='utf-8', errors='ignore') as src:
                for row in src:
                    key, _, value = row.partition(':')
                    if key in ('MemTotal', 'MemAvailable'):
                        mem[key] = int(value.strip().split()[0])
            total = mem.get('MemTotal', 0) // 1024
            available = mem.get('MemAvailable', 0) // 1024
            lines.append(f'Memory: {max(0, total - available)} MB used / {total} MB total')
        except Exception:
            lines.append('Memory: not available')
        try:
            disk = shutil.disk_usage(Path.home())
            lines.append(f'Home storage: {disk.free // (1024 ** 3)} GB free / {disk.total // (1024 ** 3)} GB')
        except Exception:
            lines.append('Home storage: not available')
        try:
            uptime = float(Path('/proc/uptime').read_text().split()[0])
            hours, rem = divmod(int(uptime), 3600)
            days, hours = divmod(hours, 24)
            lines.append(f'System uptime: {days}d {hours}h {rem // 60}m')
        except Exception:
            pass
        lines.append(f'CPU threads: {os.cpu_count() or "unknown"}')
        return '\n'.join(lines)

    def _show_system_monitor(self):
        self._msg('System Monitor', self._system_snapshot_text())

    def _network_test(self):
        results = []
        for host in ('1.1.1.1', 'example.com'):
            started = time.perf_counter()
            try:
                with socket.create_connection((host, 443), timeout=3):
                    elapsed = (time.perf_counter() - started) * 1000
                results.append(f'{host}: reachable ({elapsed:.0f} ms)')
            except Exception as exc:
                results.append(f'{host}: failed ({str(exc)[:100]})')
        self._msg('Network Test', '\n'.join(results))

    def _clean_xui_cache(self):
        cache_dir = XUI_HOME / 'cache'
        if cache_dir.is_symlink():
            self._msg('Clean Cache', 'Cache cleanup skipped because ~/.xui/cache is a symbolic link.')
            return
        if not cache_dir.exists():
            self._msg('Clean Cache', 'There is no XUI cache to clean yet.')
            return
        try:
            size = 0
            for entry in cache_dir.rglob('*'):
                if entry.is_file() and not entry.is_symlink():
                    size += entry.stat().st_size
            if not self._ask_yes_no('Clean Cache', f'Remove XUI cache files only? This will free about {size / (1024 ** 2):.1f} MB.'):
                return
            for entry in cache_dir.iterdir():
                if entry.is_symlink() or entry.is_file():
                    entry.unlink(missing_ok=True)
                elif entry.is_dir():
                    shutil.rmtree(entry)
            self._msg('Clean Cache', f'XUI cache cleared ({size / (1024 ** 2):.1f} MB).')
        except Exception as exc:
            self._msg('Clean Cache', f'Could not clean XUI cache: {exc}')

    def _manage_favorites(self):
        favorites_file = DATA_HOME / 'favorites.json'
        favorites = safe_json_read(favorites_file, [])
        if not isinstance(favorites, list):
            favorites = []
        favorites = list(dict.fromkeys(str(item) for item in favorites if str(item).strip()))[:40]
        while True:
            choice = self._choose_from_menu('My Pins', ['Launch favorite', 'Add favorite', 'Remove favorite', 'Cancel'])
            if choice in (None, 'Cancel'):
                safe_json_write(favorites_file, favorites)
                return
            if choice == 'Add favorite':
                candidates = [
                    'My Games', 'Games Marketplace', 'Steam', 'RetroArch', 'Xenia Canary',
                    'Media Player', 'Music Marketplace', 'Web Browser', 'System Info',
                    'Quick Control Center', 'Controller Center', 'Missions', 'Achievements',
                    'Screenshot', 'File Manager', 'Network Test', 'System Monitor',
                ]
                available = [item for item in candidates if item not in favorites]
                if not available:
                    self._msg('My Pins', 'All supported favorite actions are already pinned.')
                    continue
                selected = self._choose_from_menu('Add Favorite', available)
                if selected:
                    favorites.append(selected)
                    safe_json_write(favorites_file, favorites)
            elif choice == 'Remove favorite':
                if not favorites:
                    self._msg('My Pins', 'No favorites to remove.')
                    continue
                selected = self._choose_from_menu('Remove Favorite', favorites)
                if selected in favorites:
                    favorites.remove(selected)
                    safe_json_write(favorites_file, favorites)
            elif choice == 'Launch favorite':
                if not favorites:
                    self._msg('My Pins', 'No favorites yet. Add some first.')
                    continue
                selected = self._choose_from_menu('Launch Favorite', favorites)
                if selected:
                    safe_json_write(favorites_file, favorites)
                    self.handle_action(selected)
                    return

    def _show_quick_control_center(self):
        dialog = QtWidgets.QDialog(self)
        dialog.setWindowTitle('Quick Control Center')
        dialog.setModal(True)
        dialog.resize(660, 500)
        layout = QtWidgets.QVBoxLayout(dialog)
        title = QtWidgets.QLabel('Quick Control Center')
        title.setStyleSheet('font-size:26px; font-weight:800; color:#f4f7fb;')
        layout.addWidget(title)
        summary = QtWidgets.QLabel(self._system_snapshot_text())
        summary.setTextInteractionFlags(QtCore.Qt.TextSelectableByMouse)
        summary.setStyleSheet('font-size:15px; padding:12px; background:rgba(0,0,0,0.24); border-radius:8px;')
        layout.addWidget(summary)
        grid = QtWidgets.QGridLayout()
        layout.addLayout(grid)
        actions = [
            ('System Monitor', 'System Monitor'),
            ('Network Test', 'Network Test'),
            ('Screenshot', 'Screenshot'),
            ('Storage', 'Storage'),
            ('Controller Center', 'Controller Center'),
            ('Logs Viewer', 'Logs Viewer'),
            ('Clean XUI Cache', 'Clean XUI Cache'),
            ('Update Check', 'Update Check'),
        ]
        for index, (label, action) in enumerate(actions):
            button = QtWidgets.QPushButton(label)
            button.setMinimumHeight(42)
            button.clicked.connect(lambda _checked=False, act=action: (dialog.accept(), QtCore.QTimer.singleShot(0, lambda: self.handle_action(act))))
            grid.addWidget(button, index // 2, index % 2)
        close_button = QtWidgets.QPushButton('Close')
        close_button.clicked.connect(dialog.accept)
        layout.addWidget(close_button)
        dialog.exec_()

    def handle_action(self, action):
        self._save_recent(action)
        self._play_sfx('select')
        # Avoid false-positive achievement spam when only navigating tiles.
        # Real unlock events should come from launches/purchases/missions.
        for launch_key in self._launch_event_keys(action):
            self._unlock_achievement_event('launch', launch_key)
        xui = str(XUI_HOME)
        if str(action).startswith('Launch Steam Game::'):
            appid = str(action).split('::', 1)[1].strip()
            if appid.isdigit():
                steam = XUI_HOME / 'bin' / 'xui_steam.sh'
                if steam.exists():
                    self._run_game('/bin/sh', ['-c', f'"{steam}" -applaunch {appid}'])
                else:
                    self._run_game('xdg-open', [f'steam://run/{appid}'])
                self._unlock_achievement_event('launch', 'steam')
                return
        if action == 'Games Hub':
            self._open_games_hub_menu()
        elif action in ('Hub', 'Bing Hub', 'Social Hub', 'Media Hub', 'Music Hub', 'Apps Hub', 'Settings Hub'):
            self._open_current_tab_menu()
        elif action == 'Open Tray':
            self._open_tray_dashboard_menu()
        elif action == 'My Pins':
            self._manage_favorites()
        elif action == 'Manage Favorites':
            self._manage_favorites()
        elif action == 'Quick Control Center':
            self._show_quick_control_center()
        elif action == 'System Monitor':
            self._show_system_monitor()
        elif action == 'Network Test':
            self._network_test()
        elif action == 'Clean XUI Cache':
            self._clean_xui_cache()
        elif action == 'My Games':
            self._menu('My Games', ['Runner', 'Casino', 'Gem Match', 'FNAE', 'Xenia Canary', 'Launch Xbox 360 Game Dump', 'Dump Homebrew DVD to Xenia', 'Xbox 360 DVD Info', 'xemu (Original Xbox)', 'Launch Original Xbox XISO', 'Dump Homebrew DVD to xemu', 'Original Xbox Setup Info', 'Steam', 'RetroArch', 'Games Integrations'])
        elif action in ('Browse Games', 'Browse'):
            self._menu('Browse Games', ['Games Marketplace', 'Game Marketplace', 'Indie Channel', 'Steam', 'RetroArch', 'Store'])
        elif action == 'Xbox Home Feed':
            self._open_url_external('https://www.xbox.com/en-US/', normal_mode=True)
        elif action == 'My TV & Movies':
            self._menu('My TV & Movies', ['Netflix', 'YouTube', 'Twitch', 'Movie Trailers', 'Video Marketplace', 'Live TV'])
        elif action == 'Browse TV & Movies':
            self._menu('Browse TV & Movies', ['Video Marketplace', 'Movie Trailers', 'Netflix', 'YouTube', 'Twitch', 'Live TV', 'Skype'])
        elif action == 'Quickplay Queue':
            self._menu('Quickplay Queue', ['My Games', 'Recently Played', 'Arcade Picks', 'Games Marketplace', 'Web Browser'])
        elif action == 'Spotlight':
            self._menu('Spotlight', ['Xbox Home Feed', 'Games Marketplace', 'Video Marketplace', 'Music Marketplace', 'Bing Search'])
        elif action == 'Bing Search':
            q, ok = self._input_text('Bing Search', 'Search the web:', '')
            if ok and str(q).strip():
                query = urllib.parse.quote_plus(str(q).strip())
                self._open_url_external(f'https://www.bing.com/search?q={query}', normal_mode=True)
        elif action == 'Voice Search':
            q, ok = self._input_text('Voice Search', 'Say something to search:', '')
            if ok and str(q).strip():
                query = urllib.parse.quote_plus(str(q).strip())
                self._open_url_external(f'https://www.bing.com/search?q={query}', normal_mode=True)
        elif action == 'Bing Categories':
            self._menu('Bing Categories', ['Bing Games', 'Bing Apps', 'Bing TV', 'Bing Movies', 'Bing Music'])
        elif action == 'Bing Games':
            self._open_url_external('https://www.bing.com/search?q=xbox+360+games', normal_mode=True)
        elif action == 'Bing Apps':
            self._open_url_external('https://www.bing.com/search?q=xbox+360+apps', normal_mode=True)
        elif action == 'Bing TV':
            self._open_url_external('https://www.bing.com/search?q=xbox+360+tv+apps', normal_mode=True)
        elif action == 'Bing Movies':
            self._open_url_external('https://www.bing.com/search?q=xbox+360+movies', normal_mode=True)
        elif action == 'Bing Music':
            self._open_url_external('https://www.bing.com/search?q=xbox+360+music', normal_mode=True)
        elif action == 'Beacons':
            beacons = safe_json_read(BEACONS_FILE, [])
            if not isinstance(beacons, list):
                beacons = []
            pick = self._choose_from_menu('Beacons', ['View Beacons', 'Add Beacon', 'Remove Beacon', 'Clear Beacons'])
            if not pick:
                return
            if pick == 'View Beacons':
                lines = [f'{i+1:02d}. {b}' for i, b in enumerate(beacons[:20])]
                self._msg('Beacons', '\n'.join(lines) if lines else 'No active beacons.')
            elif pick == 'Add Beacon':
                game, ok = self._input_text('Add Beacon', 'Game or activity:', '')
                name = str(game).strip()
                if ok and name:
                    if name not in beacons:
                        beacons.insert(0, name)
                        beacons = beacons[:40]
                        safe_json_write(BEACONS_FILE, beacons)
                    self._msg('Beacons', f'Beacon set: {name}')
            elif pick == 'Remove Beacon':
                if not beacons:
                    self._msg('Beacons', 'No beacons to remove.')
                else:
                    selected = self._choose_from_menu('Remove Beacon', beacons[:30])
                    if selected and selected in beacons:
                        beacons.remove(selected)
                        safe_json_write(BEACONS_FILE, beacons)
                        self._msg('Beacons', f'Removed beacon: {selected}')
            elif pick == 'Clear Beacons':
                if self._ask_yes_no('Beacons', 'Clear all active beacons?'):
                    safe_json_write(BEACONS_FILE, [])
                    self._msg('Beacons', 'All beacons cleared.')
        elif action in ('View Beacons', 'Add Beacon', 'Remove Beacon', 'Clear Beacons'):
            self.handle_action('Beacons')
        elif action == 'Cloud Storage':
            out = subprocess.getoutput('/bin/sh -c "du -sh $HOME/.xui/data 2>/dev/null | head -n 1"').strip()
            info = (
                f'Profile: {PROFILE_FILE}\n'
                f'Data: {DATA_HOME}\n'
                f'Usage: {out or "Unknown"}\n\n'
                'Cloud save style sync: keep ~/.xui/data backed up or synced.'
            )
            self._msg('Cloud Storage', info)
        elif action == 'Kinect Hub':
            self._menu('Kinect Hub', ['Voice Search', 'Kinect Settings', 'Movie Trailers'])
        elif action == 'Kinect Settings':
            self._msg(
                'Kinect Settings',
                'Kinect mode emulation:\n'
                '- Voice Search opens virtual keyboard input\n'
                '- Guide button (F1/HOME) opens Xbox Guide\n'
                '- Gamepad stick + dpad navigates dashboard tiles'
            )
        elif action == 'Downloads':
            self._msg('Downloads', self._xbox_guide_downloads_text())
        elif action in ('Search Games', 'Games Search'):
            q, ok = self._input_text('Search Games', 'Game or app:', '')
            if ok and str(q).strip():
                try:
                    store_window = StoreWindow()
                    store_window.search.setText(str(q).strip())
                    store_window.showFullScreen()
                    store_window.search.setFocus()
                    self._web_windows.append(store_window)
                except Exception as exc:
                    self._msg('Search Games', f'Could not open filtered store: {exc}')
        elif action in ('Games Marketplace', 'Games Market'):
            self._run('/bin/sh', ['-c', f'{xui}/bin/xui_store.sh'])
        elif action == 'Game Marketplace':
            self._run('/bin/sh', ['-c', f'{xui}/bin/xui_store.sh'])
        elif action == 'Indie Channel':
            self._menu('Indie Channel', ['Store', 'Games Marketplace', 'Itch.io Free Games Hub', 'Game Jolt Games Hub'])
        elif action == 'Itch.io Free Games Hub':
            self._open_url_external('https://itch.io/games/free', normal_mode=True)
        elif action == 'Game Jolt Games Hub':
            self._open_url_external('https://gamejolt.com/games', normal_mode=True)
        elif action == 'Demos':
            self._menu('Demos', ['Runner', 'Casino', 'Gem Match', 'Movie Trailers'])
        elif action == 'Recently Played':
            try:
                arr = json.loads(RECENT_FILE.read_text()) if RECENT_FILE.exists() else []
            except Exception:
                arr = []
            recent_games = [x for x in arr if str(x) in (
                'Runner', 'Casino', 'Gem Match', 'FNAE', 'Steam', 'RetroArch', 'Lutris', 'Heroic', 'Store'
            )]
            self._menu('Recently Played', recent_games or ['No recent games'])
        elif action == 'Arcade Picks':
            self._menu('Arcade Picks', ['Gem Match', 'Runner', 'Casino', 'Missions'])
        elif action == 'Disc & Local Media':
            self._open_tray_dashboard_menu()
        elif action == 'Recent':
            try:
                arr = json.loads(RECENT_FILE.read_text()) if RECENT_FILE.exists() else []
            except Exception:
                arr = []
            self._menu('Recent', arr or ['No recent actions'])
        elif action == 'No recent actions':
            self._msg('Recent', 'No recent actions.')
        elif action == 'No recent games':
            self._msg('Recently Played', 'No recent games.')
        elif action == 'Casino':
            self._launch_local_python_app('Casino', 'casino/casino.py', game=True)
        elif action == 'Runner':
            self._launch_local_python_app('Runner', 'games/runner.py', game=True)
        elif action in ('Gem Match', 'Bejeweled'):
            self._run_game('/bin/sh', ['-c', f'"{xui}/bin/xui_gem_match.sh"'])
        elif action == 'Showcase Halo 4':
            if not self._launch_steam_game_by_name('Halo 4'):
                self._open_url_external('https://www.bing.com/search?q=Halo+4', normal_mode=True)
        elif action == 'Showcase COD Black Ops':
            if not self._launch_steam_game_by_name('Call of Duty Black Ops'):
                self._open_url_external('https://www.bing.com/search?q=Call+of+Duty+Black+Ops', normal_mode=True)
        elif action == 'Showcase FIFA Soccer 13':
            if not self._launch_steam_game_by_name('FIFA 13'):
                self._open_url_external('https://www.bing.com/search?q=FIFA+Soccer+13', normal_mode=True)
        elif action == 'Showcase Nike Kinect Training':
            self._open_url_external('https://www.bing.com/search?q=Nike+Kinect+Training', normal_mode=True)
        elif action in ('Showcase Recommendations', 'Showcase All Recommendations'):
            self._menu('Recommendations', ['Game Marketplace', 'Indie Channel', 'Demos', 'Movie Trailers'])
        elif action in ('FNAE', "Five Night's At Epstein's", "Five Nights At Epstein's"):
            run_fnae = f'{xui}/bin/xui_run_fnae.sh'
            install_fnae = f'{xui}/bin/xui_install_fnae.sh'
            installed = (
                subprocess.call(
                    ['/bin/sh', '-c', f'"{run_fnae}" --check'],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                ) == 0
            )
            if installed:
                self._run_game(run_fnae)
            else:
                if self._ask_yes_no(
                    'FNAE',
                    'FNAE no esta instalado.\n\n'
                    'Se descargara desde MediaFire y se instalara ahora.\n'
                    'URL: https://www.mediafire.com/file/a4q4l09vdfqzzws/Five_Nights_At_Epsteins_Linux.tar/file\n\n'
                    'Deseas continuar?'
                ):
                    self._run_install_task(
                        'FNAE',
                        f'"{install_fnae}"',
                        success_msg='FNAE installed successfully.',
                        fail_msg='FNAE install failed. Check ~/.xui/logs/fnae_install.log',
                        launch_cmd=f'"{xui}/bin/xui_play_game_intro.sh" -- "{run_fnae}"',
                    )
        elif action == 'Uninstall FNAE':
            if self._ask_yes_no('FNAE', 'Uninstall Five Nights At Epstein\'s from local XUI apps folder?'):
                subprocess.getoutput('/bin/sh -c "rm -rf $HOME/.xui/apps/fnae $HOME/.xui/data/fnae_paths.json"')
                self._msg('FNAE', 'FNAE files removed from local install.')
        elif action == 'Steam':
            self._launch_platform('steam')
        elif action == 'Xenia Canary':
            self._launch_platform('xenia-canary')
        elif action == 'Install Xenia Canary':
            self._install_platform('xenia-canary')
        elif action == 'Launch Xbox 360 Game Dump':
            launcher = XUI_HOME / 'bin' / 'xui_xenia_canary.sh'
            if not self._platform_available(launcher):
                self._msg('Xenia Canary', 'Xenia Canary is not installed. Install it first; the installer downloads the official build and verifies its SHA-256.')
                self._install_platform('xenia-canary')
                return
            picker = QtWidgets.QMessageBox(self)
            picker.setWindowTitle('Launch Xbox 360 dump')
            picker.setText('Select a dump file or a folder containing default.xex.')
            choose_file = picker.addButton('Select file', QtWidgets.QMessageBox.AcceptRole)
            choose_folder = picker.addButton('Select game folder', QtWidgets.QMessageBox.ActionRole)
            picker.addButton(QtWidgets.QMessageBox.Cancel)
            picker.exec_()
            if picker.clickedButton() is choose_file:
                game_path, _selected_filter = QtWidgets.QFileDialog.getOpenFileName(
                    self, 'Select an Xbox 360 game dump (.xex/.iso)', str(Path.home()),
                    'Xbox 360 game dumps (*.iso *.xex *.xiso);;All files (*)',
                )
            elif picker.clickedButton() is choose_folder:
                game_path = QtWidgets.QFileDialog.getExistingDirectory(
                    self, 'Select an extracted Xbox 360 game folder', str(Path.home())
                )
            else:
                game_path = ''
            if game_path:
                self._run(str(launcher), [str(Path(game_path).expanduser())])
                self._unlock_achievement_event('launch', 'xenia_canary')
        elif action == 'Dump Homebrew DVD to Xenia':
            launcher = XUI_HOME / 'bin' / 'xui_xenia_canary.sh'
            dumper = XUI_HOME / 'bin' / 'xui_dump_xenia_homebrew_disc.py'
            if not self._platform_available(launcher):
                self._msg('Xenia Canary', 'Install Xenia Canary first, then run this action again.')
                self._install_platform('xenia-canary')
                return
            if not dumper.is_file():
                self._msg('Homebrew DVD', f'DVD dumper not found:\n{dumper}\n\nRun the XUI installer to create it.')
                return
            source = QtWidgets.QFileDialog.getExistingDirectory(
                self,
                'Select the mounted Xbox 360 disc or extracted game folder',
                str(Path.home()),
            )
            if not source:
                return
            self._run_install_task(
                'Xenia Homebrew DVD',
                f'{shlex.quote(str(dumper))} {shlex.quote(source)}',
                success_msg='Disc files copied and launch requested. If Xenia does not open, check ~/.xui/logs/xenia.log and ~/.xui/logs/game_boot.log.',
                fail_msg='Could not find or launch a readable .xex/.iso. Retail Xbox 360 DVDs may not mount as ordinary files; use a legally obtained Xenia-compatible dump.',
            )
            self._unlock_achievement_event('launch', 'xenia_canary')
        elif action == 'xemu (Original Xbox)':
            self._launch_platform('xemu')
        elif action == 'Install xemu':
            self._install_platform('xemu')
        elif action == 'Launch Original Xbox XISO':
            launcher = XUI_HOME / 'bin' / 'xui_xemu.sh'
            if not self._platform_available(launcher):
                self._msg('xemu', 'xemu is not installed yet. Install it first, then choose the XISO again.')
                self._install_platform('xemu')
                return
            picker = QtWidgets.QMessageBox(self)
            picker.setWindowTitle('Launch original Xbox XISO')
            picker.setText('Select an .iso/.xiso image or a folder containing exactly one image.')
            choose_file = picker.addButton('Select image', QtWidgets.QMessageBox.AcceptRole)
            choose_folder = picker.addButton('Select image folder', QtWidgets.QMessageBox.ActionRole)
            picker.addButton(QtWidgets.QMessageBox.Cancel)
            picker.exec_()
            if picker.clickedButton() is choose_file:
                game_path, _selected_filter = QtWidgets.QFileDialog.getOpenFileName(
                    self, 'Select an original Xbox XISO image (not a raw/redump ISO)', str(Path.home()),
                    'Original Xbox XISO images (*.iso *.xiso)',
                )
            elif picker.clickedButton() is choose_folder:
                game_path = QtWidgets.QFileDialog.getExistingDirectory(
                    self, 'Select a folder containing one original Xbox XISO', str(Path.home())
                )
            else:
                game_path = ''
            if game_path:
                selected_path = Path(game_path).expanduser()
                if selected_path.is_file() and selected_path.suffix.lower() not in ('.iso', '.xiso'):
                    self._msg('xemu', 'xemu needs an original Xbox XISO image ending in .iso or .xiso; it cannot launch .xbe or an arbitrary file.')
                    return
                self._run(str(launcher), [str(selected_path)])
                self._unlock_achievement_event('launch', 'xemu')
        elif action == 'Dump Homebrew DVD to xemu':
            launcher = XUI_HOME / 'bin' / 'xui_xemu.sh'
            dumper = XUI_HOME / 'bin' / 'xui_dump_xemu_homebrew_disc.py'
            if not self._platform_available(launcher):
                self._msg('xemu', 'Install xemu first, then run this action again.')
                self._install_platform('xemu')
                return
            if not dumper.is_file():
                self._msg('Homebrew DVD', f'DVD dumper not found:\n{dumper}\n\nRun the XUI installer to create it.')
                return
            source = QtWidgets.QFileDialog.getExistingDirectory(
                self,
                'Select a mounted DVD folder that already contains exactly one original Xbox .iso/.xiso image',
                str(Path.home()),
            )
            if not source:
                return
            self._run_install_task(
                'xemu Homebrew DVD',
                f'{shlex.quote(str(dumper))} {shlex.quote(source)}',
                success_msg='Disc files copied and xemu launch requested. Check ~/.xui/logs/xemu.log and ~/.xui/logs/game_boot.log if it does not open.',
                fail_msg='Could not find a valid XISO .iso image. xemu cannot boot a mounted folder or default.xbe directly; select a folder containing an XISO image.',
            )
            self._unlock_achievement_event('launch', 'xemu')
        elif action == 'Original Xbox Setup Info':
            self._msg(
                'xemu (Original Xbox)',
                'xemu boots original Xbox XISO images, not Xbox 360 XEX files or arbitrary data-disc folders.\n\n'
                'First install xemu and configure the MCPX boot ROM, compatible flash BIOS, and Xbox HDD image in xemu. '
                'Firmware/BIOS files must be dumped from hardware you own; XUI does not download or include them. '
                'A retail BIOS may not boot unsigned homebrew.\n\n'
                'For an optical disc, Linux must mount it as a readable data volume and it must contain an already-created XISO .iso. '
                'This helper copies files only; it cannot read Xbox security sectors or convert raw/redump images.\n\n'
                'Official setup: https://xemu.app/docs/required-files/\n'
                'XISO format: https://xemu.app/docs/disc-images/',
            )
        elif action == 'Xbox 360 DVD Info':
            optical = []
            try:
                probe = subprocess.run(
                    ['lsblk', '--json', '--output', 'NAME,TYPE,MODEL,MOUNTPOINTS'],
                    capture_output=True,
                    text=True,
                    timeout=4,
                    check=False,
                )
                payload = json.loads(probe.stdout or '{}') if probe.returncode == 0 else {}
                def collect_optical(rows):
                    for row in rows if isinstance(rows, list) else []:
                        if not isinstance(row, dict):
                            continue
                        if str(row.get('type') or '').lower() == 'rom':
                            mounts = row.get('mountpoints')
                            mount = ', '.join(str(p) for p in mounts if p) if isinstance(mounts, list) else ''
                            optical.append(f"/dev/{row.get('name', 'sr?')}  {row.get('model') or 'DVD drive'}  {mount or '(not mounted)'}")
                        collect_optical(row.get('children', []))
                collect_optical(payload.get('blockdevices', []))
            except Exception:
                pass
            drives = '\n'.join(optical) if optical else 'No optical drive was detected by lsblk.'
            self._msg(
                'Xbox 360 DVD / Xenia',
                f'{drives}\n\n'
                '“Dump Homebrew DVD to Xenia” copies a mounted, readable homebrew data DVD to ~/.xui/games/xenia_dumps, then opens its default.xex (or a single .xex/.iso) in Xenia. '
                'Linux must be able to mount and read the disc. Xbox 360-formatted or protected discs that a normal PC drive cannot expose as files are not supported by this file-copy feature.\n\n'
                'Use only game dumps you are legally entitled to use. Official guide: '
                'https://github.com/xenia-canary/xenia-canary/wiki/Quickstart#how-to-rip-games',
            )
        elif action == 'Avatar Store':
            dialog = AvatarStudioDialog(self, initial_tab='store')
            dialog.exec_()
        elif action == 'Store':
            store_launcher = XUI_HOME / 'bin' / 'xui_store.sh'
            if store_launcher.is_file():
                self._run('/bin/sh', [str(store_launcher)])
            else:
                self._launch_local_python_app('Store', 'bin/xui_store_modern.py')
        elif action == 'Web Browser':
            self._run('/bin/sh', ['-c', f'{xui}/bin/xui_browser.sh --hub https://www.xbox.com'])
        elif action == 'Close Active App':
            out = subprocess.getoutput(f'/bin/sh -c "{xui}/bin/xui_close_active_app.sh"')
            self._msg('Close Active App', out or 'No output')
        elif action == 'Notifications':
            self._play_sfx('open')
            dialog = NotificationCenterDialog(self)
            dialog.exec_()
            self._play_sfx('close')
        elif action in ('Missions', 'Misiones'):
            self._launch_local_python_app('Missions', 'games/missions.py', game=True)
        elif action in ('Achievements', 'Logros'):
            self._open_achievements_hub()
        elif action == 'LAN':
            self._menu('LAN', ['LAN Chat', 'LAN Status', 'P2P Internet Help'])
        elif action in ('Messages', 'LAN Chat'):
            self._open_social_chat('messages')
        elif action == 'LAN Status':
            out = subprocess.getoutput(f'/bin/sh -c "{xui}/bin/xui_lan_status.sh"')
            self._msg('LAN Status', out or 'No network data.')
        elif action == 'P2P Internet Help':
            out = subprocess.getoutput(f'/bin/sh -c "{xui}/bin/xui_lan_status.sh"')
            self._msg('P2P Internet',
                      'Modo recomendado: usa Tailscale/ZeroTier para enlazar dos redes como si fueran LAN.\n'
                      'Alternativa directa: conecta por IP:PUERTO (reenvia puerto TCP 38600 en el router).\n\n'
                      f'{out}')
        elif action == 'Party':
            self._open_social_chat('party')
        elif action == 'Gamer Card':
            profile = safe_json_read(PROFILE_FILE, {})
            if not isinstance(profile, dict):
                profile = {}
            if self._ask_yes_no('Gamer Card', 'Edit your local player card?'):
                for field, label, limit in (
                    ('gamertag', 'Gamertag', 24),
                    ('motto', 'Motto', 64),
                    ('location', 'Location', 48),
                    ('avatar', 'Avatar name', 32),
                ):
                    current = str(profile.get(field) or ('Player1' if field == 'gamertag' else ''))
                    value, accepted = self._input_text(f'Edit {label}', f'{label}:', current)
                    if not accepted:
                        break
                    profile[field] = ''.join(ch for ch in str(value).strip() if ch.isprintable())[:limit]
                profile['gamertag'] = str(profile.get('gamertag') or 'Player1')[:24]
                profile['updated_at'] = int(time.time())
                safe_json_write(PROFILE_FILE, profile)
