    def _dispatch_dashboard_key(self, key):
        modal = QtWidgets.QApplication.activeModalWidget()
        if modal is not None and bool(modal.isVisible()):
            target = modal.focusWidget() or modal
        else:
            target = QtWidgets.QApplication.focusWidget()
            if target is None:
                target = QtWidgets.QApplication.activeWindow()
            if target is None:
                target = self
        for et in (QtCore.QEvent.KeyPress, QtCore.QEvent.KeyRelease):
            evt = QtGui.QKeyEvent(et, int(key), QtCore.Qt.NoModifier)
            QtWidgets.QApplication.sendEvent(target, evt)

    def _canonical_gamepad_key(self, key):
        k = int(key)
        if k == int(QtCore.Qt.Key_A):
            return int(QtCore.Qt.Key_Return)
        if k == int(QtCore.Qt.Key_B):
            return int(QtCore.Qt.Key_Escape)
        if k == int(QtCore.Qt.Key_X):
            return int(QtCore.Qt.Key_Space)
        if k == int(QtCore.Qt.Key_Y):
            return int(QtCore.Qt.Key_Tab)
        return k

    def _gp_emit(self, key, channel='main', repeat_sec=0.15):
        now = time.monotonic()
        last = float(self._gp_last_emit.get(channel, 0.0))
        if (now - last) < float(repeat_sec):
            return
        self._gp_last_emit[channel] = now
        self._dispatch_dashboard_key(self._canonical_gamepad_key(key))

    def _gp_axis(self, axis_name, value):
        v = float(value)
        prev_dir = int(self._gp_axis_last_dir.get(axis_name, 0))
        if abs(v) <= float(self._gp_axis_release_zone):
            self._gp_axis_last_dir[axis_name] = 0
            return
        if abs(v) < float(self._gp_axis_deadzone):
            return
        direction = -1 if v < 0 else 1
        if direction == prev_dir:
            return
        self._gp_axis_last_dir[axis_name] = direction
        if axis_name in ('lx', 'rx'):
            self._gp_emit(QtCore.Qt.Key_Left if v < 0 else QtCore.Qt.Key_Right, channel=f'axis_{axis_name}', repeat_sec=0.17)
        elif axis_name in ('ly', 'ry'):
            self._gp_emit(QtCore.Qt.Key_Up if v < 0 else QtCore.Qt.Key_Down, channel=f'axis_{axis_name}', repeat_sec=0.17)

    def _on_gp_connected_change(self, _device_id=None):
        if QtGamepad is None:
            return
        manager = QtGamepad.QGamepadManager.instance()
        active = set(manager.connectedGamepads())
        for did in list(self._qgamepads.keys()):
            if did not in active:
                gp = self._qgamepads.pop(did, None)
                if gp is not None:
                    gp.deleteLater()
        for did in sorted(active):
            if did in self._qgamepads:
                continue
            try:
                gp = QtGamepad.QGamepad(did, self)
            except Exception:
                continue
            self._qgamepads[did] = gp

            gp.buttonAChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Return, channel=f'{did}_a'))
            gp.buttonBChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Escape, channel=f'{did}_b'))
            gp.buttonXChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Space, channel=f'{did}_x'))
            gp.buttonYChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Tab, channel=f'{did}_y'))

            gp.buttonStartChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Return, channel=f'{did}_start'))
            gp.buttonSelectChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Escape, channel=f'{did}_back'))

            gp.buttonLeftShoulderChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_PageUp, channel=f'{did}_lb'))
            gp.buttonRightShoulderChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_PageDown, channel=f'{did}_rb'))
            gp.buttonL2Changed.connect(lambda v, did=did: v > 0.55 and self._gp_emit(QtCore.Qt.Key_Backtab, channel=f'{did}_lt'))
            gp.buttonR2Changed.connect(lambda v, did=did: v > 0.55 and self._gp_emit(QtCore.Qt.Key_Tab, channel=f'{did}_rt'))

            gp.buttonUpChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Up, channel=f'{did}_du'))
            gp.buttonDownChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Down, channel=f'{did}_dd'))
            gp.buttonLeftChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Left, channel=f'{did}_dl'))
            gp.buttonRightChanged.connect(lambda p, did=did: p and self._gp_emit(QtCore.Qt.Key_Right, channel=f'{did}_dr'))

            guide_signal = getattr(gp, 'buttonGuideChanged', None)
            if guide_signal is not None:
                guide_signal.connect(lambda pressed, did=did: pressed and self._trigger_guide_action())
            center_signal = getattr(gp, 'buttonCenterChanged', None)
            if center_signal is not None:
                center_signal.connect(lambda pressed, did=did: pressed and self._trigger_guide_action())

            gp.axisLeftXChanged.connect(lambda v, did=did: self._gp_axis('lx', v))
            gp.axisLeftYChanged.connect(lambda v, did=did: self._gp_axis('ly', v))
            gp.axisRightXChanged.connect(lambda v, did=did: self._gp_axis('rx', v))
            gp.axisRightYChanged.connect(lambda v, did=did: self._gp_axis('ry', v))

    def _setup_qt_gamepad_input(self):
        if QtGamepad is None:
            return
        try:
            manager = QtGamepad.QGamepadManager.instance()
            manager.gamepadConnected.connect(self._on_gp_connected_change)
            manager.gamepadDisconnected.connect(self._on_gp_connected_change)
            self._on_gp_connected_change()
        except Exception:
            pass

    def closeEvent(self, e):
        if not self._allow_exit:
            e.ignore()
            try:
                self.showFullScreen()
                self.raise_()
                self.activateWindow()
            except Exception:
                pass
            return
        try:
            if self._social_poll_timer is not None:
                self._social_poll_timer.stop()
        except Exception:
            pass
        try:
            if self._mandatory_update_timer is not None:
                self._mandatory_update_timer.stop()
        except Exception:
            pass
        try:
            if self._mandatory_payload_proc is not None:
                if self._mandatory_payload_proc.state() != QtCore.QProcess.NotRunning:
                    self._mandatory_payload_proc.kill()
                self._mandatory_payload_proc.deleteLater()
                self._mandatory_payload_proc = None
        except Exception:
            pass
        try:
            if self._mandatory_update_proc is not None:
                if self._mandatory_update_proc.state() != QtCore.QProcess.NotRunning:
                    self._mandatory_update_proc.kill()
                self._mandatory_update_proc.deleteLater()
                self._mandatory_update_proc = None
        except Exception:
            pass
        try:
            if self._install_task_proc is not None:
                if self._install_task_proc.state() != QtCore.QProcess.NotRunning:
                    self._install_task_proc.kill()
                self._install_task_proc.deleteLater()
                self._install_task_proc = None
        except Exception:
            pass
        try:
            if self._social_engine is not None:
                self._social_engine.stop()
        except Exception:
            pass
        for did in list(self._qgamepads.keys()):
            gp = self._qgamepads.pop(did, None)
            if gp is not None:
                try:
                    gp.deleteLater()
                except Exception:
                    pass
        for w in list(self._web_windows):
            if w is None:
                continue
            try:
                w.close()
            except Exception:
                pass
        self._web_windows = []
        try:
            if self._gc_timer is not None:
                self._gc_timer.stop()
        except Exception:
            pass
        super().closeEvent(e)

    def keyPressEvent(self, e):
        k = self._canonical_gamepad_key(e.key())
        if self._games_inline is not None and self._games_inline.isVisible():
            if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
                self._games_inline.close_overlay()
                return
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self._play_sfx('back')
            if self.focus_area in ('left', 'right'):
                self.focus_area = 'center'
                self.focus_idx = 0
                self.update_focus()
                return
            if self.focus_area == 'center':
                if self.focus_idx > 0:
                    self.focus_idx = 0
                    self.update_focus()
                    return
                self.focus_area = 'tabs'
                self.focus_idx = 0
                self.update_focus()
                return
            if self._ask_yes_no('Exit', 'Salir al escritorio?'):
                self._request_application_exit()
            return
        if self._is_guide_key_event(e):
            self._trigger_guide_action()
            return
        if self._tab_animating:
            return
        page = self._current_page()
        if k in (QtCore.Qt.Key_PageUp, QtCore.Qt.Key_Backtab):
            self._switch_tab(self.tab_idx - 1, animate=True, keep_tabs_focus=True)
            return
        if k in (QtCore.Qt.Key_PageDown, QtCore.Qt.Key_Tab):
            self._switch_tab(self.tab_idx + 1, animate=True, keep_tabs_focus=True)
            return
        if k == QtCore.Qt.Key_Left:
            if self.focus_area == 'tabs':
                self._switch_tab(self.tab_idx - 1, animate=True, keep_tabs_focus=True)
                return
            elif self.focus_area == 'center':
                if self.focus_idx > 1 and page.center_tiles:
                    self.focus_idx = max(1, self.focus_idx - 1)
                elif self.focus_idx == 1 and page.left_tiles:
                    self.focus_area = 'left'
                    self.focus_idx = 0
                elif self.focus_idx == 0 and page.left_tiles:
                    self.focus_area = 'left'
                    self.focus_idx = min(self.focus_idx, len(page.left_tiles) - 1)
            elif self.focus_area == 'right':
                self.focus_area = 'center'
                if page.center_tiles:
                    self.focus_idx = len(page.center_tiles)
                else:
                    self.focus_idx = 0
            self.update_focus(); return
        if k == QtCore.Qt.Key_Right:
            if self.focus_area == 'tabs':
                self._switch_tab(self.tab_idx + 1, animate=True, keep_tabs_focus=True)
                return
            elif self.focus_area == 'left':
                self.focus_area = 'center'
                self.focus_idx = 1 if page.center_tiles else 0
            elif self.focus_area == 'center':
                if self.focus_idx > 0 and self.focus_idx < len(page.center_tiles):
                    self.focus_idx += 1
                elif page.right_tiles:
                    self.focus_area = 'right'
                    self.focus_idx = min(max(0, self.focus_idx - 1), len(page.right_tiles) - 1)
            self.update_focus(); return
        if k == QtCore.Qt.Key_Up:
            if self.focus_area in ('left', 'right'):
                self.focus_idx = max(0, self.focus_idx - 1)
            elif self.focus_area == 'center':
                if self.focus_idx > 0:
                    self.focus_idx = 0
                else:
                    self.focus_area = 'tabs'
            self.update_focus(); return
        if k == QtCore.Qt.Key_Down:
            if self.focus_area == 'tabs':
                self.focus_area = 'center'
                self.focus_idx = 0
            elif self.focus_area == 'center':
                if self.focus_idx == 0 and page.center_tiles:
                    self.focus_idx = 1
            elif self.focus_area == 'left':
                self.focus_idx = min(len(page.left_tiles)-1, self.focus_idx + 1) if page.left_tiles else 0
            elif self.focus_area == 'right':
                self.focus_idx = min(len(page.right_tiles)-1, self.focus_idx + 1) if page.right_tiles else 0
            self.update_focus(); return
        if k == QtCore.Qt.Key_Tab:
            order = ['tabs']
            if page.left_tiles:
                order.append('left')
            order.append('center')
            if page.right_tiles:
                order.append('right')
            idx = order.index(self.focus_area) if self.focus_area in order else 0
            self.focus_area = order[(idx + 1) % len(order)]
            self.focus_idx = 0
            self.update_focus(); return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_Space):
            if self.focus_area == 'tabs':
                self.focus_area = 'center'
                self.focus_idx = 0
                self._play_sfx('select')
                self.update_focus()
            elif self.focus_area == 'center':
                if self.focus_idx <= 0:
                    self.handle_action(page.hero.action)
                elif page.center_tiles:
                    idx = max(0, min(self.focus_idx - 1, len(page.center_tiles) - 1))
                    self.handle_action(page.center_tiles[idx].action)
            elif self.focus_area == 'left':
                if page.left_tiles:
                    self.handle_action(page.left_tiles[self.focus_idx].action)
            else:
                if page.right_tiles:
                    self.handle_action(page.right_tiles[self.focus_idx].action)
            return
        super().keyPressEvent(e)


def main():
    ultra_low_ram = ultra_low_ram_mode()
    attr = getattr(QtCore.Qt, 'AA_CompressHighFrequencyEvents', None)
    if attr is not None:
        try:
            QtCore.QCoreApplication.setAttribute(attr, True)
        except Exception:
            pass
    app = QtWidgets.QApplication(sys.argv)
    app.setApplicationName('XUI Xbox Style')
    app.setQuitOnLastWindowClosed(False)
    for icon_name in ('logo.png', 'applogo.png', 'bootlogo.png'):
        icon_path = ASSETS / icon_name
        if icon_path.is_file():
            app.setWindowIcon(QtGui.QIcon(str(icon_path)))
            break
    if ultra_low_ram:
        try:
            QtGui.QPixmapCache.setCacheLimit(6144)
        except Exception:
            pass
    f = app.font()
    scr = app.primaryScreen()
    low_ui = use_low_power_ui(scr)
    if scr is not None:
        g = scr.availableGeometry()
        if low_ui and (g.width() <= 1366 or g.height() <= 768):
            base_pt = 11
        else:
            base_pt = 10 if (g.width() <= 1280 or g.height() <= 720) else 12
    else:
        base_pt = 11 if low_ui else 12
    f.setPointSize(base_pt)
    app.setFont(f)
    if low_ui:
        for fx in (
            QtCore.Qt.UI_AnimateMenu,
            QtCore.Qt.UI_AnimateCombo,
            QtCore.Qt.UI_FadeMenu,
            QtCore.Qt.UI_FadeTooltip,
        ):
            try:
                app.setEffectEnabled(fx, False)
            except Exception:
                pass
    play_startup_video()
    w = Dashboard()
    try:
        w.showFullScreen()
    except Exception:
        w.show()
    if os.environ.get('XUI_POSTUPDATE_RESTART') == '1':
        def activate_restarted_dashboard():
            if not w.isVisible():
                w.showFullScreen()
            w.raise_()
            w.activateWindow()
        QtCore.QTimer.singleShot(350, activate_restarted_dashboard)
    sys.exit(app.exec_())


if __name__ == '__main__':
    main()
PY
  chmod a+x "$DASH_DIR/pyqt_dashboard_improved.py" || true
  info "Wrote dashboard to $DASH_DIR/pyqt_dashboard_improved.py"
}

# If an enhanced dashboard file exists next to this installer (pyqt_dashboard_improved_fixed.py),
# offer to deploy it non-destructively: backup existing dashboard and copy the enhanced one.
deploy_custom_dashboard(){
    local script_dir src dst bak
    if [ "${XUI_USE_EXTERNAL_DASHBOARD:-0}" != "1" ]; then
        info "Skipping external dashboard override (use --use-external-dashboard to enable)"
        return 0
    fi
    script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    src="$script_dir/pyqt_dashboard_improved_fixed.py"
    dst="$DASH_DIR/pyqt_dashboard_improved.py"
    if [ ! -f "$src" ]; then
        # nothing to do
        return 0
    fi
    info "Found enhanced dashboard at $src"
    mkdir -p "$DASH_DIR" "$BACKUP_DIR"
    if [ -f "$dst" ]; then
        if cmp -s "$src" "$dst"; then
            info "Installed dashboard already up-to-date; skipping"
            return 0
        fi
        if confirm "Replace existing dashboard with enhanced version from installer?"; then
            bak="$BACKUP_DIR/pyqt_dashboard_improved.$(date +%Y%m%d%H%M%S).bak"
            if cp -f "$dst" "$bak" 2>/dev/null; then
                info "Backed up existing dashboard to $bak"
            else
                warn "Failed to create backup of existing dashboard; aborting"
                return 1
            fi
            if cp -f "$src" "$dst"; then
                chmod a+x "$dst" || true
                info "Replaced installed dashboard with enhanced version"
            else
                warn "Failed to copy enhanced dashboard to $dst"
                return 1
            fi
        else
            info "User declined to replace existing dashboard"
        fi
    else
        if confirm "Install enhanced dashboard from installer to $dst?"; then
            mkdir -p "$(dirname "$dst")"
            if cp -f "$src" "$dst"; then
                chmod a+x "$dst" || true
                info "Installed enhanced dashboard to $dst"
            else
                warn "Failed to copy enhanced dashboard to $dst"
            fi
        fi
    fi
}

write_startup_wrapper(){
  cat > "$BIN_DIR/xui_startup_and_dashboard.sh" <<'SH'
#!/usr/bin/env bash
set -euo pipefail
TARGET_HOME="${XUI_USER_HOME:-$HOME}"
if [ "$(id -u)" -eq 0 ] && [ -n "${SUDO_USER:-}" ]; then
  if command -v getent >/dev/null 2>&1; then
    _su_home="$(getent passwd "$SUDO_USER" | cut -d: -f6 || true)"
    [ -n "${_su_home:-}" ] && TARGET_HOME="$_su_home"
  elif [ -d "/home/$SUDO_USER" ]; then
    TARGET_HOME="/home/$SUDO_USER"
  fi
fi
if [ "$(id -u)" -ne 0 ]; then
  # Running as regular user is valid for launching the dashboard.
  # Elevated permissions are only needed for installer/maintenance actions.
  :
fi
export HOME="$TARGET_HOME"
export USER="${SUDO_USER:-${USER:-$(id -un)}}"
export LOGNAME="${SUDO_USER:-${LOGNAME:-$USER}}"
ASSETS_DIR="$TARGET_HOME/.xui/assets"
DASH_SCRIPT="$TARGET_HOME/.xui/dashboard/pyqt_dashboard_improved.py"
PY_RUNNER="$TARGET_HOME/.xui/bin/xui_python.sh"
info(){ echo "[INFO] $*"; }
play_video(){
  local file="$1"
  [ -f "$file" ] || return 1
  if command -v mpv >/dev/null 2>&1; then
        mpv --no-terminal --really-quiet --fullscreen --no-config --input-conf=/dev/null --input-default-bindings=no --input-cursor=no --input-vo-keyboard=no --cursor-autohide=always --osc=no --osd-bar=no "$file"; return $?
  fi
    echo "mpv is required to play locked video: $file" >&2
  return 1
}
if [ -f "$ASSETS_DIR/startup.mp4" ]; then
  info "Playing startup video"
  if play_video "$ASSETS_DIR/startup.mp4"; then
    PLAYED_STARTUP=1
    else
        exit 1
  fi
fi
if [ -f "$DASH_SCRIPT" ]; then
  if [ "$PLAYED_STARTUP" = "1" ]; then
    export XUI_SKIP_STARTUP_VIDEO=1
  fi
  if [ -x "$PY_RUNNER" ]; then
    exec "$PY_RUNNER" "$DASH_SCRIPT"
  fi
  exec python3 "$DASH_SCRIPT"
else
  echo "Dashboard script not found: $DASH_SCRIPT" >&2
  exit 1
fi
SH
  chmod a+x "$BIN_DIR/xui_startup_and_dashboard.sh" || true
  info "Wrote startup wrapper to $BIN_DIR/xui_startup_and_dashboard.sh"
}

install_desktop_icons(){
    local icon_src icon_root pixmap_dir size candidate
    icon_src=""
    for candidate in "$ASSETS_DIR/logo.png" "$ASSETS_DIR/applogo.png" "$ASSETS_DIR/bootlogo.png"; do
        if [ -s "$candidate" ]; then
            icon_src="$candidate"
            break
        fi
    done
    if [ -z "$icon_src" ]; then
        warn "No XUI logo asset found; desktop entries will use the generic icon"
        return 0
    fi

    icon_root="$USER_HOME/.local/share/icons/hicolor"
    pixmap_dir="$USER_HOME/.local/share/pixmaps"
    mkdir -p "$pixmap_dir" "$icon_root/256x256/apps" || return 0
    cp -f "$icon_src" "$pixmap_dir/xui-dashboard.png" || true

    # Generate correctly sized theme icons when Pillow is available; otherwise
    # copy the source image into each standard hicolor size as a portable fallback.
    if check_cmd python3 && python3 - "$icon_src" "$icon_root" <<'PY'
import sys
from pathlib import Path
try:
    from PIL import Image
except Exception:
    raise SystemExit(1)
source = Path(sys.argv[1])
root = Path(sys.argv[2])
try:
    with Image.open(source) as image:
        image = image.convert('RGBA')
        for size in (16, 22, 24, 32, 48, 64, 128, 256):
            folder = root / f'{size}x{size}' / 'apps'
            folder.mkdir(parents=True, exist_ok=True)
            resampling = getattr(Image, 'Resampling', Image).LANCZOS
            image.resize((size, size), resampling).save(folder / 'xui-dashboard.png', format='PNG')
except Exception:
    raise SystemExit(1)
PY
    then
        :
    else
        for size in 16 22 24 32 48 64 128 256; do
            mkdir -p "$icon_root/${size}x${size}/apps"
            cp -f "$icon_src" "$icon_root/${size}x${size}/apps/xui-dashboard.png" || true
        done
    fi

    # Publish both a menu launcher and an XDG autostart entry for GNOME,
    # KDE, Cinnamon, MATE, XFCE, and other freedesktop-compatible desktops.
    mkdir -p "$USER_HOME/.local/share/applications" "$AUTOSTART_DIR"
    cat > "$USER_HOME/.local/share/applications/xui-dashboard.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=XUI Dashboard
Comment=Xbox-style gaming dashboard
Exec="$BIN_DIR/xui_startup_and_dashboard.sh"
Icon=xui-dashboard
Terminal=false
StartupNotify=false
Categories=Game;Utility;
DESK
    cat > "$AUTOSTART_DIR/xui-dashboard.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=XUI Dashboard
Comment=Start the XUI dashboard when the graphical session begins
Exec="$BIN_DIR/xui_startup_and_dashboard.sh"
Icon=xui-dashboard
Terminal=false
StartupNotify=false
X-GNOME-Autostart-enabled=true
Hidden=false
NoDisplay=false
DBusActivatable=false
DESK

    if check_cmd gtk-update-icon-cache && [ -f "$icon_root/index.theme" ]; then
        gtk-update-icon-cache -f "$icon_root" >/dev/null 2>&1 || true
    fi
    if check_cmd update-desktop-database; then
        update-desktop-database "$USER_HOME/.local/share/applications" >/dev/null 2>&1 || true
    fi
    info "Installed XUI desktop icons and launchers under $USER_HOME/.local/share"
}

