RESCAN_SEC = float(os.environ.get('XUI_JOY_RESCAN_SEC', '2.5'))
GUIDE_COOLDOWN_SEC = float(os.environ.get('XUI_GUIDE_COOLDOWN_SEC', '0.85'))
