#!/usr/bin/env python3
import json
import os
import shutil
import subprocess
import time
from pathlib import Path

DATA_HOME = Path.home() / '.xui' / 'data'
WALLET_FILE = DATA_HOME / 'saldo.json'
STORE_FILE = DATA_HOME / 'store.json'
MISSIONS_FILE = DATA_HOME / 'missions.json'
INVENTORY_FILE = DATA_HOME / 'inventory.json'
ACHIEVEMENTS_FILE = DATA_HOME / 'achievements.json'
ACHIEVEMENTS_MIN = 5000


def _safe_read(path, default):
    try:
        return json.loads(Path(path).read_text(encoding='utf-8'))
    except Exception:
        return default


def _safe_write(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')


def _select_largest_secondary_disk():
    """Return the mounted secondary disk with the most free space."""
    try:
        payload = json.loads(subprocess.run(
            ['lsblk', '-J', '-o', 'NAME,TYPE,PKNAME,MOUNTPOINTS,FSTYPE,TRAN,SIZE,MODEL,RO'],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        ).stdout)
    except (OSError, subprocess.SubprocessError, json.JSONDecodeError, ValueError):
        return None

    candidates = []
    for block in payload.get('blockdevices') or []:
        name = str(block.get('name') or '')
        if str(block.get('type') or '') != 'disk' or not name:
            continue
        partitions = [child for child in block.get('children') or [] if str(child.get('type') or '') == 'part']
        partition = next((child for child in partitions if str(child.get('fstype') or '').strip()), None)
        if partition is None:
            continue
        mountpoints = [str(path) for path in partition.get('mountpoints') or [] if str(path).strip()]
        if '/' in mountpoints:
            continue
        if not mountpoints:
            device_path = f'/dev/{partition.get("name")}'
            mountpoint = Path.home() / '.xui' / 'mounts' / Path(device_path).name
            if os.geteuid() != 0 and shutil.which('sudo'):
                result = subprocess.run(
                    ['sudo', '-n', 'mount', device_path, str(mountpoint)],
                    check=False, capture_output=True, text=True, timeout=20,
                )
                if result.returncode != 0:
                    continue
            elif os.geteuid() == 0:
                mountpoint.mkdir(parents=True, exist_ok=True)
                result = subprocess.run(
                    ['mount', device_path, str(mountpoint)],
                    check=False, capture_output=True, text=True, timeout=20,
                )
                if result.returncode != 0:
                    continue
            else:
                continue
            mountpoints = [str(mountpoint)]
        for mountpoint in mountpoints:
            try:
                free = int(shutil.disk_usage(mountpoint).free)
            except (OSError, ValueError):
                continue
            if free > 0:
                candidates.append((free, str(mountpoint)))
    if not candidates:
        return None
    return max(candidates, key=lambda item: item[0])[1]


def ensure_wallet():
    DATA_HOME.mkdir(parents=True, exist_ok=True)
    if not WALLET_FILE.exists():
        _safe_write(WALLET_FILE, {'balance': 250.0, 'currency': 'EUR'})


def load_wallet():
    ensure_wallet()
    data = _safe_read(WALLET_FILE, {'balance': 250.0, 'currency': 'EUR'})
    try:
        bal = float(data.get('balance', 0.0))
    except Exception:
        bal = 0.0
    return {'balance': round(max(0.0, bal), 2), 'currency': data.get('currency', 'EUR')}


def get_balance():
    return load_wallet()['balance']


def set_balance(value):
    w = load_wallet()
    try:
        w['balance'] = round(max(0.0, float(value)), 2)
    except Exception:
        pass
    _safe_write(WALLET_FILE, w)
    return w['balance']


def change_balance(delta):
    w = load_wallet()
    try:
        w['balance'] = round(max(0.0, float(w.get('balance', 0.0)) + float(delta)), 2)
    except Exception:
        pass
    _safe_write(WALLET_FILE, w)
    return w['balance']


def load_store():
    data = _safe_read(STORE_FILE, {'items': []})
    if not isinstance(data, dict):
        return {'items': []}
    items = data.get('items', [])
    if not isinstance(items, list):
        items = []
    data['items'] = items
    return data


def save_missions(data):
    _safe_write(MISSIONS_FILE, data if isinstance(data, list) else [])


def load_missions():
    data = _safe_read(MISSIONS_FILE, [])
    return data if isinstance(data, list) else []


def load_inventory():
    data = _safe_read(INVENTORY_FILE, {'items': []})
    if not isinstance(data, dict):
        return {'items': []}
    items = data.get('items', [])
    if not isinstance(items, list):
        items = []
    data['items'] = items
    return data


def save_inventory(data):
    _safe_write(INVENTORY_FILE, data if isinstance(data, dict) else {'items': []})


def _norm_key(text):
    raw = str(text or '').strip().lower()
    out = []
    last_sep = False
    for ch in raw:
        if ch.isalnum():
            out.append(ch)
            last_sep = False
        else:
            if not last_sep:
                out.append('_')
            last_sep = True
    key = ''.join(out).strip('_')
    while '__' in key:
        key = key.replace('__', '_')
    return key or 'unknown'


def _achievement(aid, title, desc, score=5, event='generic', value='', threshold=0):
    return {
        'id': str(aid),
        'title': str(title),
        'desc': str(desc),
        'score': int(max(1, score)),
        'event': str(event or 'generic'),
        'value': str(value or ''),
        'threshold': int(max(0, threshold)),
    }


def _action_seed():
    return [
        'Hub', 'Social Hub', 'Games Hub', 'Media Hub', 'Music Hub', 'Apps Hub', 'Settings Hub',
        'Open Tray', 'Rescan Media', 'Toggle Tray', 'Open Tray', 'Close Tray',
        'My Pins', 'Recent', 'Casino', 'Runner', 'Gem Match', 'FNAE', 'Steam', 'RetroArch',
