import sys
from pathlib import Path
from PyQt5 import QtWidgets, QtGui, QtCore

sys.path.insert(0, str(Path.home() / '.xui' / 'bin'))
from xui_game_lib import change_balance, get_balance, complete_mission, unlock_for_event


class RunnerGame(QtWidgets.QWidget):
    def __init__(self):
        super().__init__()
        unlock_for_event('launch', 'runner', limit=2)
        self.setWindowTitle('XUI Runner')
        self.resize(920, 360)
        self.setFocusPolicy(QtCore.Qt.StrongFocus)
        self.ground = 290
        self.player_x = 80
        self.player_y = self.ground - 42
        self.player_w = 34
        self.player_h = 42
        self.vy = 0.0
        self.gravity = 0.85
        self.jump_v = -13.5
        self.obstacles = []
        self.spawn_tick = 0
        self.score = 0
        self.running = True

        self.timer = QtCore.QTimer(self)
        self.timer.timeout.connect(self.tick)
        self.timer.start(16)

    def tick(self):
        if not self.running:
            return
        self.score += 1
        self.spawn_tick += 1

        # Player physics
        self.vy += self.gravity
        self.player_y += self.vy
        max_y = self.ground - self.player_h
        if self.player_y >= max_y:
            self.player_y = max_y
            self.vy = 0.0

        # Obstacles
        if self.spawn_tick >= 48:
            self.spawn_tick = 0
            h = random.randint(28, 58)
            w = random.randint(18, 30)
            self.obstacles.append(QtCore.QRect(920, self.ground - h, w, h))

        speed = 7
        kept = []
        for r in self.obstacles:
            r.translate(-speed, 0)
            if r.right() > 0:
                kept.append(r)
        self.obstacles = kept

        # Collision
        player_rect = QtCore.QRect(int(self.player_x), int(self.player_y), self.player_w, self.player_h)
        for ob in self.obstacles:
            if player_rect.intersects(ob):
                self.end_game()
                return
        self.update()

    def end_game(self):
        self.running = False
        self.timer.stop()
        reward = max(1, self.score // 160)
        bal = change_balance(reward)
        m = complete_mission(mission_id='m2')
        extra = ''
        if m.get('completed'):
            bal = m.get('balance', bal)
            extra = f"\nMission reward: +{float(m.get('reward', 0)):.2f}"
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle('Runner')
        dlg.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        dlg.setModal(True)
        dlg.resize(760, 440)
        dlg.setStyleSheet('''
            QDialog { background:#d7dce1; border:2px solid rgba(239,244,248,0.78); }
            QLabel#title {
                color:#eef4f8;
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #69717a, stop:1 #505860);
                font-size:30px;
                font-weight:800;
                padding:8px 12px;
            }
            QLabel#body { color:#1f2730; font-size:23px; font-weight:650; }
            QListWidget {
                background:#e4e8ec;
                color:#1f252c;
                font-size:30px;
                border:1px solid rgba(76,86,96,0.4);
                outline:none;
            }
            QListWidget::item {
                padding:7px 12px;
                margin:1px 0px;
            }
            QListWidget::item:selected {
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #5abc3e, stop:1 #3e9132);
                color:#f4fff1;
                border:1px solid rgba(249,255,248,0.4);
            }
        ''')
        lay = QtWidgets.QVBoxLayout(dlg)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        hdr = QtWidgets.QLabel('Runner')
        hdr.setObjectName('title')
        lay.addWidget(hdr, 0)
        body = QtWidgets.QWidget()
        bl = QtWidgets.QVBoxLayout(body)
        bl.setContentsMargins(16, 14, 16, 12)
        bl.setSpacing(10)
        txt = QtWidgets.QLabel(
            f'Game Over\nScore: {self.score}\nReward: +{reward} credits{extra}\nBalance: EUR {bal:.2f}'
        )
        txt.setObjectName('body')
        txt.setWordWrap(True)
        bl.addWidget(txt, 1)
        lw = QtWidgets.QListWidget()
        lw.addItem('OK')
        lw.setCurrentRow(0)
        lw.itemActivated.connect(lambda *_: dlg.accept())
        bl.addWidget(lw, 0)
        lay.addWidget(body, 1)

        def _key(ev):
            if ev.key() in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_A):
                dlg.accept()
                return
            if ev.key() in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
                dlg.reject()
                return
            QtWidgets.QDialog.keyPressEvent(dlg, ev)

        dlg.keyPressEvent = _key
        dlg.exec_()
        self.close()

    def keyPressEvent(self, e):
        k = e.key()
        if k in (QtCore.Qt.Key_A, QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            k = QtCore.Qt.Key_Space
        elif k == QtCore.Qt.Key_B:
            k = QtCore.Qt.Key_Escape
        if k in (QtCore.Qt.Key_Space, QtCore.Qt.Key_Up):
            if self.player_y >= (self.ground - self.player_h - 0.5):
                self.vy = self.jump_v
        elif k == QtCore.Qt.Key_Escape:
            self.close()
            return
        super().keyPressEvent(e)

    def paintEvent(self, _e):
        p = QtGui.QPainter(self)
        p.fillRect(self.rect(), QtGui.QColor('#101820'))
        p.fillRect(0, self.ground, self.width(), self.height() - self.ground, QtGui.QColor('#25353f'))

        # Player
        p.fillRect(
            QtCore.QRect(int(self.player_x), int(self.player_y), self.player_w, self.player_h),
            QtGui.QColor('#32c652')
        )

        # Obstacles
        p.setBrush(QtGui.QColor('#f5f5f5'))
        p.setPen(QtCore.Qt.NoPen)
        for ob in self.obstacles:
            p.drawRect(ob)

        p.setPen(QtGui.QColor('#eaf2f2'))
        p.setFont(QtGui.QFont('Sans Serif', 13, QtGui.QFont.Bold))
        p.drawText(14, 24, f'Score: {self.score}')
        p.drawText(14, 48, f'Balance: EUR {get_balance():.2f}')
        p.drawText(14, 72, 'SPACE/UP = jump | ESC = exit')
        p.end()


def main():
    app = QtWidgets.QApplication(sys.argv)
    w = RunnerGame()
    try:
        w.showFullScreen()
    except Exception:
        w.show()
    sys.exit(app.exec_())


if __name__ == '__main__':
    main()
