#!/usr/bin/env python3
import hashlib
import http.cookiejar
import json
import os
import random
import re
import shlex
import shutil
import subprocess
import sys
import tarfile
import time
import urllib.parse
import urllib.request
import zipfile
from datetime import date
from pathlib import Path
from PyQt5 import QtCore, QtGui, QtWidgets
try:
    from PyQt5 import QtGamepad
except Exception:
    QtGamepad = None

sys.path.insert(0, str(Path.home() / '.xui' / 'bin'))
from xui_game_lib import (
    load_store, load_inventory, save_inventory, get_balance, change_balance, complete_mission,
    unlock_for_event, ensure_achievements, _select_largest_secondary_disk,
)

DATA_HOME = Path.home() / '.xui' / 'data'
STORE_FILE = DATA_HOME / 'store.json'
WEB_PORTS_CATALOG_FILE = DATA_HOME / 'web_game_ports.json'
XUI_WALLET_FILE = DATA_HOME / 'xui_wallet.json'
XUI_BIN = Path.home() / '.xui' / 'bin'
COVER_CACHE = Path.home() / '.xui' / 'cache' / 'store_covers'
EXTERNAL_STORE_FILE = DATA_HOME / 'store_external.json'
XBOX360_CATALOG_FILE = DATA_HOME / 'xbox360_homebrew.json'
XBOX360_REPO_CONFIG = DATA_HOME / 'xbox360_repo_url.txt'
XBOX360_GITHUB_TOKEN_FILE = DATA_HOME / 'xbox360_github_token'
XBOX360_REPO_URL = 'https://raw.githubusercontent.com/afitler79-alt/XUI_360GAMES_REP/main/xui360repo.txt'
EXTERNAL_STALE_SECONDS = 6 * 60 * 60
DAILY_ACTIVE_COUNT = 360
ALWAYS_VISIBLE_IDS = {
    'game_fnae_fangame',
    'minigame_bejeweled_xui',
    'game_casino',
    'game_runner',
    'browser_xui_webhub',
    'platform_steam',
    'platform_retroarch',
}


def _safe_write(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')


def get_xui_balance():
    data = None
    try:
        data = json.loads(XUI_WALLET_FILE.read_text(encoding='utf-8'))
    except Exception:
        data = {'balance': 500, 'currency': 'XUI'}
    try:
        data['balance'] = max(0, int(data.get('balance', 500)))
    except (TypeError, ValueError):
        data['balance'] = 500
    data['currency'] = 'XUI'
    _safe_write(XUI_WALLET_FILE, data)
    return data['balance']


def change_xui_balance(delta):
    balance = max(0, get_xui_balance() + int(delta))
    _safe_write(XUI_WALLET_FILE, {'balance': balance, 'currency': 'XUI'})
    return balance


def _catalog_url(url):
    value = str(url or '').strip().rstrip('),.;]')
    match = re.match(r'^https://github\.com/([^/]+)/([^/]+)/blob/([^/]+)/(.*)$', value)
    if match:
        value = 'https://raw.githubusercontent.com/{}/{}/{}/{}'.format(*match.groups())
    parsed = urllib.parse.urlparse(value)
    if parsed.scheme not in ('http', 'https') or not parsed.netloc:
        return ''
    return value


def _github_headers(url):
    return {'User-Agent': 'XUI-Homebrew-Store/1.0'}


def _drive_file_id(url):
    parsed = urllib.parse.urlparse(str(url or ''))
    host = (parsed.hostname or '').lower()
    if not (host == 'drive.google.com' or host.endswith('.drive.google.com') or host == 'docs.google.com'):
        return ''
    query = urllib.parse.parse_qs(parsed.query)
    file_id = (query.get('id') or [''])[0]
    if not file_id:
        match = re.search(r'/(?:file/)?d/([A-Za-z0-9_-]+)', parsed.path)
        file_id = match.group(1) if match else ''
    return file_id if re.fullmatch(r'[A-Za-z0-9_-]{10,}', file_id or '') else ''


def _open_game_download(url):
    file_id = _drive_file_id(url)
    headers = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) XUI-Homebrew-Store/1.0'}
    if not file_id:
        return urllib.request.urlopen(
            urllib.request.Request(url, headers=_github_headers(url)), timeout=90
        )

    cookies = http.cookiejar.CookieJar()
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cookies))
    candidates = [
        'https://drive.google.com/uc?' + urllib.parse.urlencode({'export': 'download', 'id': file_id}),
        'https://drive.usercontent.google.com/download?' + urllib.parse.urlencode(
            {'id': file_id, 'export': 'download', 'confirm': 't'}
        ),
    ]
    last_reason = ''
    while candidates:
        request = urllib.request.Request(candidates.pop(0), headers=headers)
        response = opener.open(request, timeout=90)
        content_type = str(response.headers.get('Content-Type', '')).lower()
        if 'text/html' not in content_type:
            return response
        page = response.read(2 * 1024 * 1024).decode('utf-8', errors='replace')
        response.close()
        token = next((c.value for c in cookies if c.name.startswith('download_warning')), '')
        if token:
            candidates.insert(0, 'https://drive.google.com/uc?' + urllib.parse.urlencode(
                {'export': 'download', 'id': file_id, 'confirm': token}
            ))
        confirm = re.search(r'[?&]confirm=([0-9A-Za-z_-]+)', page)
        if confirm:
            candidates.insert(0, 'https://drive.google.com/uc?' + urllib.parse.urlencode(
                {'export': 'download', 'id': file_id, 'confirm': confirm.group(1)}
            ))
        last_reason = 'Google Drive devolvió una página de vista previa/permisos, no el archivo.'
    raise ValueError(last_reason or 'Google Drive no permitió descargar el archivo; comprueba que el enlace sea público.')


def _catalog_entries(payload):
    try:
        parsed = json.loads(payload)
    except Exception:
        parsed = None
    if isinstance(parsed, dict):
        parsed = parsed.get('games', parsed.get('items', parsed.get('games360', [])))
    entries = []
    if isinstance(parsed, list):
        for raw in parsed:
            if isinstance(raw, str):
                raw = {'url': raw}
            if isinstance(raw, dict):
                url = raw.get('url') or raw.get('link') or raw.get('download') or raw.get('download_url')
                name = raw.get('name') or raw.get('title') or raw.get('id') or ''
                if url:
                    entries.append((str(name).strip(), str(url).strip()))
    else:
        for line in str(payload or '').splitlines():
            text = line.strip()
            if not text or text.startswith(('#', '//')):
                continue
            links = re.findall(r'https?://[^\s<>"\']+', text, flags=re.IGNORECASE)
            if not links:
                continue
            url = links[0].rstrip('),.;]')
            prefix = text[:text.find(links[0])].strip(' \t|;,=-')
            suffix = text[text.find(links[0]) + len(links[0]):].strip(' \t|;,=-')
            name = prefix or suffix
            entries.append((name, url))

    clean = []
    seen = set()
    for name, raw_url in entries:
        url = _catalog_url(raw_url)
        if not url or url in seen:
            continue
        seen.add(url)
        if not name:
            drive_id = _drive_file_id(url)
            leaf = Path(urllib.parse.unquote(urllib.parse.urlparse(url).path)).name
            name = re.sub(r'\.(zip|7z|rar|tar|gz|bz2|xz|iso)$', '', leaf, flags=re.IGNORECASE)
            if not name or name.lower().startswith('view'):
                name = f'Xbox 360 Homebrew {drive_id[-6:]}' if drive_id else 'Xbox 360 Homebrew'
        name = str(name).strip()[:120]
        game_id = 'x360_' + hashlib.sha256(url.encode('utf-8')).hexdigest()[:16]
        downloader = XUI_BIN / 'xui_download_xbox360_repo.sh'
        clean.append({
            'id': game_id,
            'name': name,
            'price': 0,
            'pricing': 'free',
            'category': 'Xbox 360 Homebrew',
            'source': 'XUI 360 Homebrew',
            'desc': 'Homebrew package from the XUI 360 catalog. Downloads and extracts locally.',
            'is_game': True,
            'download_url': url,
            # Route catalog downloads through the Python installer. It handles
            # Google Drive confirmation pages and safely extracts archives.
            'install': f'xui360repo:{game_id}',
            'launch': str(downloader) + f' --name {shlex.quote(name)} --url {shlex.quote(url)} --launch',
        })
    return clean


def _load_xbox360_items():
    try:
        data = json.loads(XBOX360_CATALOG_FILE.read_text(encoding='utf-8'))
        items = data.get('items', []) if isinstance(data, dict) else []
        return [x for x in items if isinstance(x, dict)]
    except Exception:
        return []


def _sync_xbox360_catalog():
    # Remove credentials saved by older builds; public catalog reads never need auth.
    try:
        XBOX360_GITHUB_TOKEN_FILE.unlink(missing_ok=True)
    except Exception:
        pass
    import os
    configured_url = os.environ.get('XUI_360_REPO_URL', '').strip()
    if not configured_url:
        try:
            configured_url = XBOX360_REPO_CONFIG.read_text(encoding='utf-8').strip()
        except Exception:
            configured_url = ''
    url = _catalog_url(configured_url or XBOX360_REPO_URL)
    if not url:
        raise ValueError('La URL del catálogo debe usar HTTP o HTTPS.')
    request = urllib.request.Request(url, headers=_github_headers(url))
    try:
        with urllib.request.urlopen(request, timeout=45) as response:
            payload = response.read(8 * 1024 * 1024 + 1)
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            raise ValueError(
                'GitHub devolvió 404 al leer el catálogo público. Comprueba el propietario, la rama y '
                'la ruta del TXT, y confirma que el repositorio siga siendo público.'
            ) from None
        if exc.code in (401, 403):
            raise ValueError(
                f'GitHub rechazó la lectura pública (HTTP {exc.code}). Confirma que el repositorio sea '
                'público y que GitHub no esté limitando temporalmente las solicitudes.'
            ) from None
        raise ValueError(f'GitHub no pudo entregar el catálogo (HTTP {exc.code}).') from None
    if len(payload) > 8 * 1024 * 1024:
        raise ValueError('El catálogo supera el límite de 8 MiB.')
    items = _catalog_entries(payload.decode('utf-8-sig', errors='replace'))
    if not items:
        raise ValueError('El catálogo no contiene enlaces HTTP/HTTPS reconocibles.')
    try:
        previous = json.loads(XBOX360_CATALOG_FILE.read_text(encoding='utf-8'))
        installed_paths = {
            str(row.get('id')): row.get('installed_path')
            for row in previous.get('items', [])
            if isinstance(row, dict) and row.get('installed_path')
        }
        for item in items:
            if item['id'] in installed_paths:
                item['installed_path'] = installed_paths[item['id']]
    except Exception:
        pass
    _safe_write(XBOX360_CATALOG_FILE, {'source': url, 'updated': int(time.time()), 'items': items})
    print(f'Catálogo sincronizado: {len(items)} juegos homebrew.')


def _safe_archive_target(root, member_name):
    raw = str(member_name or '').replace('\\', '/')
    normalized = raw.rstrip('/')
    path = Path(normalized)
    if not normalized or path.is_absolute() or any(part in ('..', '') for part in normalized.split('/')):
        raise ValueError('El archivo contiene una ruta no segura.')
    target = (root / path).resolve()
    if target != root.resolve() and root.resolve() not in target.parents:
        raise ValueError('El archivo intenta salir de la carpeta de instalación.')
    return target


def _extract_game_archive(archive, destination, progress_callback=None):
    suffix = ''.join(Path(archive).suffixes).lower()
    if suffix.endswith('.zip'):
        with zipfile.ZipFile(archive) as bundle:
            members = bundle.infolist()
            total_bytes = sum(member.file_size for member in members if not member.is_dir())
            completed_bytes = 0
            for member in members:
                target = _safe_archive_target(destination, member.filename)
                mode = (member.external_attr >> 16) & 0o170000
                if mode == 0o120000:
                    raise ValueError('No se permiten enlaces simbólicos dentro del ZIP.')
                if member.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                else:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    with bundle.open(member) as src, target.open('wb') as dst:
                        shutil.copyfileobj(src, dst, length=1024 * 1024)
                    completed_bytes += member.file_size
                    if callable(progress_callback):
                        progress_callback(completed_bytes, total_bytes)
        return True
    if suffix.endswith(('.tar', '.tar.gz', '.tgz', '.tar.xz', '.txz', '.tar.bz2', '.tbz2')):
        with tarfile.open(archive, 'r:*') as bundle:
            members = bundle.getmembers()
            total_bytes = sum(member.size for member in members if member.isfile())
            completed_bytes = 0
            for member in members:
                target = _safe_archive_target(destination, member.name)
                if member.issym() or member.islnk() or not (member.isdir() or member.isfile()):
                    raise ValueError('El TAR contiene enlaces o tipos de archivo no permitidos.')
                if member.isdir():
                    target.mkdir(parents=True, exist_ok=True)
                else:
                    source = bundle.extractfile(member)
                    if source is None:
                        continue
                    target.parent.mkdir(parents=True, exist_ok=True)
                    with source, target.open('wb') as output:
                        shutil.copyfileobj(source, output, length=1024 * 1024)
                    completed_bytes += member.size
                    if callable(progress_callback):
                        progress_callback(completed_bytes, total_bytes)
        return True
    if suffix.endswith(('.7z', '.rar')):
        extractor = shutil.which('7z') or shutil.which('7zz')
        if not extractor:
            raise ValueError('Este paquete es 7z/RAR. Instala p7zip-full o 7zip para extraerlo automáticamente.')
        listing = subprocess.run(
            [extractor, 'l', '-slt', str(archive)], capture_output=True, text=True, check=True
        ).stdout
        for line in listing.splitlines():
            if line.startswith('Path = '):
                member_path = line.partition('=')[2].strip()
                if member_path not in (str(archive), archive.name):
                    _safe_archive_target(destination, member_path)
            elif line.startswith('Symbolic Link = ') or line.startswith('Hard Link = '):
                raise ValueError('No se permiten enlaces simbólicos dentro del archivo.')
        subprocess.run(
            [extractor, 'x', '-y', f'-o{destination}', str(archive)],
            check=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
        )
        return True
    return False


def _record_xbox360_install(game_id, destination):
    try:
        data = json.loads(XBOX360_CATALOG_FILE.read_text(encoding='utf-8'))
        rows = data.get('items', []) if isinstance(data, dict) else []
        for row in rows:
            if isinstance(row, dict) and str(row.get('id')) == str(game_id):
                row['installed_path'] = str(destination)
        _safe_write(XBOX360_CATALOG_FILE, data)
    except Exception:
        pass


def _install_xbox360_game(game_id):
    item = next((row for row in _load_xbox360_items() if str(row.get('id')) == str(game_id)), None)
    if item is None:
        raise ValueError('Juego no encontrado; sincroniza el catálogo de Xbox 360 primero.')
    url = _catalog_url(item.get('download_url', ''))
    if not url:
        raise ValueError('El enlace de descarga del juego no es válido.')
    slug = re.sub(r'[^A-Za-z0-9._-]+', '_', str(item.get('name', game_id))).strip('._')[:80] or str(game_id)
    root = Path(_select_largest_secondary_disk() or str(Path.home() / '.xui' / 'GAMES' / 'Xbox360'))
    if root == Path.home() / '.xui' / 'GAMES' / 'Xbox360':
        root.mkdir(parents=True, exist_ok=True)
    destination = root / slug
    if destination.exists():
        _record_xbox360_install(game_id, destination)
        print(f'Ya está descargado: {destination}')
        return
    root.mkdir(parents=True, exist_ok=True)
    downloads = Path.home() / '.xui' / 'cache' / 'xbox360_downloads' / str(game_id)
    downloads.mkdir(parents=True, exist_ok=True)
    def report_progress(percent, message):
        print(f'XUI_PROGRESS:{int(percent)}:{str(message or "")[:180]}', flush=True)

    report_progress(5, f'Conectando para descargar {item.get("name", slug)}...')
    partial = None
    try:
        with _open_game_download(url) as response:
            content_type = str(response.headers.get('Content-Type', '')).lower()
            if 'text/html' in content_type:
                raise ValueError('El enlace entrega una página web, no el archivo del juego.')
            leaf = response.headers.get_filename() or Path(
                urllib.parse.unquote(urllib.parse.urlparse(response.geturl()).path)
            ).name
            leaf = Path(str(leaf or '').replace('\\', '/')).name
            if not leaf or leaf in ('.', '..') or leaf.lower() in ('download', 'view'):
                leaf = slug + '.download'
            archive = downloads / leaf
            partial = archive.with_name(archive.name + '.part')
            try:
                content_length = max(0, int(response.headers.get('Content-Length') or 0))
            except (TypeError, ValueError):
                content_length = 0
            downloaded = 0
            last_reported_percent = -1
            last_reported_bytes = 0
            with partial.open('wb') as output:
                while True:
                    chunk = response.read(1024 * 1024)
                    if not chunk:
                        break
                    output.write(chunk)
                    downloaded += len(chunk)
                    if content_length:
                        percent = min(68, 8 + int(downloaded * 60 / content_length))
                        if percent >= last_reported_percent + 2 or downloaded >= content_length:
                            report_progress(percent, f'Descargando: {downloaded // (1024 * 1024)} MiB de {content_length // (1024 * 1024)} MiB')
                            last_reported_percent = percent
                    elif downloaded - last_reported_bytes >= 8 * 1024 * 1024:
                        report_progress(8, f'Descargando: {downloaded // (1024 * 1024)} MiB recibidos...')
                        last_reported_bytes = downloaded
            if downloaded <= 0:
                raise ValueError('La descarga terminó sin recibir datos.')
        partial.replace(archive)
        report_progress(70, 'Descarga completa. Preparando extracción...')
        staging = destination.with_name(destination.name + '.installing')
        if staging.exists():
            shutil.rmtree(staging)
        staging.mkdir(parents=True)
        try:
            last_extraction_percent = {'value': 70}

            def extraction_progress(done, total):
                if total > 0:
                    percent = 71 + int(min(total, done) * 26 / total)
                    if percent > last_extraction_percent['value'] or done >= total:
                        report_progress(percent, f'Extrayendo: {min(100, done * 100 // total)}%')
                        last_extraction_percent['value'] = percent
                else:
                    report_progress(97, 'Extracción completa. Finalizando instalación...')

            report_progress(71, 'Extrayendo el paquete del juego...')
            extracted = _extract_game_archive(archive, staging, extraction_progress)
            if not extracted:
                report_progress(85, 'El archivo no es comprimido; copiándolo a la biblioteca...')
                shutil.copy2(archive, staging / archive.name)
            report_progress(98, 'Guardando los archivos instalados...')
            staging.replace(destination)
            _record_xbox360_install(game_id, destination)
        except Exception:
            shutil.rmtree(staging, ignore_errors=True)
            raise
    except Exception:
        if partial is not None:
            partial.unlink(missing_ok=True)
        raise
    report_progress(99, f'Instalación terminada: {destination}')
    print(f'Instalado en: {destination}')


def _xbox360_install_directory(item, game_id):
    install_path = Path(str(item.get('installed_path') or '')).expanduser()
    if install_path.is_dir():
        return install_path
    slug = re.sub(r'[^A-Za-z0-9._-]+', '_', str(item.get('name', game_id))).strip('._')[:80] or str(game_id)
    roots = [
        Path(_select_largest_secondary_disk() or str(Path.home() / '.xui' / 'GAMES' / 'Xbox360')),
        Path.home() / '.xui' / 'GAMES' / 'xbox360_repo',
    ]
    for root in roots:
        for suffix in ('', '_extracted'):
            candidate = root / f'{slug}{suffix}'
            if candidate.is_dir():
                return candidate
    legacy_root = Path.home() / '.xui' / 'GAMES' / 'xbox360_repo'
    wanted = re.sub(r'[^a-z0-9]+', '', slug.casefold())
    if legacy_root.is_dir():
        for candidate in legacy_root.iterdir():
            if candidate.is_dir() and re.sub(r'[^a-z0-9]+', '', candidate.name.removesuffix('_extracted').casefold()) == wanted:
                return candidate
    return roots[0] / slug


def _xbox360_launch_plan(install_path):
    files = [path for path in install_path.rglob('*') if path.is_file()]
    xex_files = sorted(
        (path for path in files if path.suffix.lower() == '.xex'),
        key=lambda path: (path.name.lower() != 'default.xex', str(path).lower()),
    )
    if xex_files:
        return 'xenia', xex_files[0]

    # Xbox 360 disc images are supported by the repository's Xenia integration.
    iso_files = sorted((path for path in files if path.suffix.lower() in ('.iso', '.xiso')),
                       key=lambda path: str(path).lower())
    if iso_files:
        return 'xenia', iso_files[0]

    appimages = sorted((path for path in files if path.suffix.lower() == '.appimage'), key=lambda p: str(p).lower())
    native = sorted(
        (path for path in files if path.suffix.lower() in ('.x86_64', '.x86', '.elf')),
        key=lambda p: str(p).lower(),
    )
    scripts = sorted(
        (path for path in files if path.suffix.lower() == '.sh'
         and re.search(r'(?:^|[/_-])(run|start|launch|game)(?:[/_.-]|$)', path.name, re.IGNORECASE)),
        key=lambda p: (not re.search(r'(?:^|[/_-])run(?:[/_.-]|$)', p.name, re.IGNORECASE), str(p).lower()),
    )
    bare_bins = sorted(
        (path for path in files if not path.suffix and os.access(path, os.X_OK)
         and path.name.lower() not in ('install', 'setup', 'uninstall', 'update')),
        key=lambda p: str(p).lower(),
    )
    windows = sorted((path for path in files if path.suffix.lower() == '.exe'), key=lambda p: str(p).lower())
    if appimages:
        return 'native', appimages[0]
    if native:
        return 'native', native[0]
    if scripts:
        return 'native-script', scripts[0]
    if bare_bins:
        return 'native', bare_bins[0]
    if windows:
        return 'windows', windows[0]
    raise ValueError(
        f'No se encontraron archivos ejecutables compatibles (XEX/ISO de Xbox 360, AppImage, binario Linux o EXE) en {install_path}.'
    )


def _launch_xbox360_game(game_id):
    item = next((row for row in _load_xbox360_items() if str(row.get('id')) == str(game_id)), None)
    if item is None:
        raise ValueError('Juego no encontrado en el catálogo Xbox 360.')
    install_path = _xbox360_install_directory(item, game_id)
    if not install_path.is_dir():
        raise ValueError(f'No se encontró la instalación de {item.get("name", game_id)} en {install_path}. Pulsa Install antes de Launch.')
    backend, target = _xbox360_launch_plan(install_path)
    helper = XUI_BIN / 'xui_play_game_intro.sh'
    if not helper.is_file() or not os.access(helper, os.X_OK):
        raise ValueError(f'No se encontró el reproductor del boot screen: {helper}')
    intro = Path(os.environ.get('XUI_GAME_INTRO', str(Path.home() / '.xui' / 'assets' / 'appbootscreen.mp4')))
    if not intro.is_file() or intro.stat().st_size == 0:
        raise ValueError(f'Falta el boot screen requerido: {intro}. Ejecuta de nuevo el instalador.')
    if not (shutil.which('mpv') or shutil.which('ffplay') or shutil.which('vlc')):
        raise ValueError('No hay reproductor de vídeo disponible para el boot screen (instala mpv, ffplay o VLC).')

    if backend == 'xenia':
        emulator = Path.home() / '.xui' / 'emulators' / 'xenia-canary' / 'xenia_canary_linux.AppImage'
        if not emulator.is_file():
            raise ValueError('Xenia Canary no está instalado. Instálalo desde XUI y vuelve a intentarlo.')
        if not os.access(emulator, os.X_OK):
            emulator.chmod(emulator.stat().st_mode | 0o111)
        game_command = [str(emulator), str(target)]
    elif backend == 'windows':
        launcher = Path.home() / '.xui' / 'bin' / 'xui_wine_run.sh'
        if not launcher.is_file() or not os.access(launcher, os.X_OK):
            raise ValueError('No se encontró el lanzador Wine de XUI para este ejecutable .exe.')
        game_command = [str(launcher), str(target)]
    elif backend == 'native-script':
        game_command = ['bash', str(target)]
    else:
        if not os.access(target, os.X_OK):
            target.chmod(target.stat().st_mode | 0o111)
        game_command = [str(target)]

    log_path = Path.home() / '.xui' / 'logs' / 'xbox360_launch.log'
    log_path.parent.mkdir(parents=True, exist_ok=True)
    launch_env = os.environ.copy()
    if backend == 'xenia' or target.suffix.lower() == '.appimage':
        launch_env['APPIMAGE_EXTRACT_AND_RUN'] = '1'
    with log_path.open('ab') as log_file:
        subprocess.Popen(
            [str(helper), '--', *game_command],
            stdin=subprocess.DEVNULL, stdout=log_file, stderr=subprocess.STDOUT,
            start_new_session=True, close_fds=True, env=launch_env,
        )
    print(f'Lanzando con {backend}: {target}', flush=True)


def _norm_item(raw):
    it = dict(raw or {})
    iid = str(it.get('id', '')).strip()
    if not iid:
        return None
    name = str(it.get('name', iid)).strip() or iid
    try:
        price = float(it.get('price', 0))
    except Exception:
        price = 0.0
    it['id'] = iid
    it['name'] = name
    it['price'] = round(max(0.0, price), 2)
    it['desc'] = str(it.get('desc', '')).strip()
    it['category'] = str(it.get('category', 'Apps')).strip() or 'Apps'
    it['source'] = str(it.get('source', 'XUI')).strip() or 'XUI'
    it['launch'] = str(it.get('launch', '')).strip()
    it['install'] = str(it.get('install', '')).strip()
    it['cover'] = str(it.get('cover', '')).strip()
    it['cover_local'] = str(it.get('cover_local', '')).strip()
    pricing = str(it.get('pricing', '')).strip().lower()
    if pricing not in ('free', 'paid'):
        pricing = 'paid' if float(it['price']) > 0 else 'free'
    it['pricing'] = pricing
    it['purchase_url'] = str(it.get('purchase_url', '')).strip()
    it['is_game'] = bool(it.get('is_game', False))
    it['external_checkout'] = bool(
        bool(it.get('external_checkout', False))
        or (it['pricing'] == 'paid' and bool(it['purchase_url']))
    )
    return it


