#!/usr/bin/env bash
set -euo pipefail
XUI="$HOME/.xui"
mkdir -p "$XUI/data" "$XUI/cache/store_covers"
python3 - <<'PY'
import hashlib
import json
import os
import re
import shlex
import time
import urllib.request
from pathlib import Path

XUI = Path.home() / '.xui'
DATA = XUI / 'data'
COVERS = XUI / 'cache' / 'store_covers'
OUT = DATA / 'store_external.json'
BIN = XUI / 'bin'
DATA.mkdir(parents=True, exist_ok=True)
COVERS.mkdir(parents=True, exist_ok=True)

UA = {'User-Agent': 'xui-store-sync/1.0'}

def get_json(url, timeout=20):
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8', errors='ignore'))

def safe_name(text):
    return re.sub(r'[^a-zA-Z0-9._-]+', '_', str(text or 'item')).strip('_') or 'item'

def cache_cover(url, rid):
    if not url:
        return ''
    ext = '.jpg'
    low = str(url).lower()
    if '.png' in low:
        ext = '.png'
    elif '.webp' in low:
        ext = '.webp'
    name = safe_name(rid) + '_' + hashlib.sha1(str(url).encode('utf-8', errors='ignore')).hexdigest()[:10] + ext
    dst = COVERS / name
    if dst.exists() and dst.stat().st_size > 1024:
        return str(dst)
    try:
        req = urllib.request.Request(url, headers=UA)
        with urllib.request.urlopen(req, timeout=20) as r:
            data = r.read()
        if data and len(data) > 1024:
            dst.write_bytes(data)
            return str(dst)
    except Exception:
        return ''
    return ''

def flathub_items(limit=260):
    items = []
    try:
        apps = get_json('https://flathub.org/api/v2/apps')
        if not isinstance(apps, list):
            return items
        for app in apps:
            if len(items) >= limit:
                break
            app_id = str(app.get('flatpakAppId') or app.get('app_id') or '').strip()
            if not app_id:
                continue
            cats = app.get('categories') or []
            cat_names = {str(c.get('name', c)).lower() for c in cats if c}
            if 'game' not in cat_names and 'games' not in cat_names:
                continue
            name = str(app.get('name') or app_id).strip()
            summary = str(app.get('summary') or 'Flathub game').strip()
            icon = str(app.get('iconDesktopUrl') or app.get('iconMobileUrl') or '').strip()
            rid = f'flathub_{app_id}'
            cover_local = cache_cover(icon, rid)
            items.append({
                'id': rid,
                'name': name,
                'price': 0,
                'pricing': 'free',
                'category': 'Games',
                'source': 'Flathub',
                'desc': summary,
                'is_game': True,
                'cover': icon,
                'cover_local': cover_local,
                'install': str(BIN / 'xui_install_flatpak_game.sh') + f' {app_id}',
                'launch': f'flatpak run {app_id}',
            })
    except Exception:
        return items
    return items

def itch_collection_items(collection_url, id_prefix='itch_collection'):
    items = []
    try:
        req = urllib.request.Request(str(collection_url), headers=UA)
        with urllib.request.urlopen(req, timeout=25) as r:
            raw = r.read().decode('utf-8', errors='ignore')
    except Exception:
        return items

    seen = set()

    # Preferred source: init_ConversionLink(...) JSON snippets include canonical title + href.
    for m in re.finditer(r'init_ConversionLink\\([^\\{]*\\{(.*?)\\}\\);', raw, re.S):
        blob = m.group(1)
        hm = re.search(r'"href":"(https:\\\\/\\\\/[^"]+\\.itch\\.io\\\\/[^"]+)"', blob)
        tm = re.search(r'"children":"([^"]+)"', blob)
        if not hm or not tm:
            continue
        url = hm.group(1).replace('\\/', '/').strip()
        name = tm.group(1).replace("\\'", "'").strip()
        if not url or not name or url in seen:
            continue
        seen.add(url)
        rid = f"{id_prefix}_{safe_name(url.replace('https://', '').replace('/', '_'))}".lower()
        cover = 'https://itch.io/favicon.ico'
        cover_local = cache_cover(cover, rid)
        items.append({
            'id': rid,
            'name': name,
            'price': 0.0,
            'pricing': 'free',
            'category': 'Games',
            'source': 'Itch.io',
            'desc': 'Imported from Itch.io collection.',
            'cover': cover,
            'cover_local': cover_local,
            'launch': str(BIN / 'xui_browser.sh') + f' --hub {url}',
        })

    # Fallback parser if init_ConversionLink is absent.
    if not items:
        for m in re.finditer(r'<a class="game_title" href="(https://[^"]+\\.itch\\.io/[^"]+)">(.*?)</a>', raw, re.S):
            url = str(m.group(1) or '').strip()
            name = re.sub(r'<[^>]+>', '', str(m.group(2) or '')).strip()
            name = name.replace('&#039;', "'")
            if not url or not name or url in seen:
                continue
            seen.add(url)
            rid = f"{id_prefix}_{safe_name(url.replace('https://', '').replace('/', '_'))}".lower()
            cover = 'https://itch.io/favicon.ico'
            cover_local = cache_cover(cover, rid)
            items.append({
                'id': rid,
                'name': name,
                'price': 0.0,
                'pricing': 'free',
                'category': 'Games',
                'source': 'Itch.io',
                'desc': 'Imported from Itch.io collection.',
                'cover': cover,
                'cover_local': cover_local,
                'launch': str(BIN / 'xui_browser.sh') + f' --hub {url}',
            })
    return items

def xbox360_repo_items(repo_urls=None, list_name='xui360repo.txt', limit=60):
    candidates = list(repo_urls or [])
    if not candidates:
        configured_url = ''
        try:
            configured_url = (DATA / 'xbox360_repo_url.txt').read_text(encoding='utf-8').strip()
        except Exception:
            pass
        candidates = ([configured_url] if configured_url else []) + [
            'https://raw.githubusercontent.com/afitler79-alt/XUI_360GAMES_REP/main/xui360repo.txt',
            'https://raw.githubusercontent.com/afitler79-alt/XUI_360GAMES_REP/master/xui360repo.txt',
            'https://github.com/afitler79-alt/XUI_360GAMES_REP/raw/main/xui360repo.txt',
            'https://github.com/afitler79-alt/XUI_360GAMES_REP/raw/master/xui360repo.txt',
            'https://github.com/afitler79-alt/XUI_360GAMES_REP/blob/main/xui360repo.txt?raw=1',
            'https://github.com/afitler79-alt/XUI_360GAMES_REP/blob/master/xui360repo.txt?raw=1',
        ]

    text = ''
    for url in candidates:
        try:
            req = urllib.request.Request(str(url).strip(), headers=UA)
            with urllib.request.urlopen(req, timeout=25) as r:
                text = r.read().decode('utf-8', errors='ignore')
            if text.strip():
                break
        except Exception:
            continue
    if not text.strip():
        return []

    out = []
    seen = set()
    lines = text.splitlines()
    for raw in lines:
        line = str(raw).strip()
        if not line or line.startswith('#') or line.startswith('//'):
            continue
        if line.lower().startswith('http'):
            candidate = line
            name = ''
        else:
            if '|' in line:
                left, right = [part.strip() for part in line.split('|', 1)]
                if right and 'http' in right:
                    name = left or ''
                    candidate = right
                else:
                    continue
            else:
                match = re.search(r'https?://[^\s\)\]>\"]+', line)
                if not match:
                    continue
                candidate = match.group(0)
                name = line[:match.start()].strip().strip(':').strip('-').strip()
        if not candidate:
            continue
        candidate = candidate.strip().rstrip('.,;')
        if not candidate.lower().startswith(('http://', 'https://')):
            continue
        if candidate in seen:
            continue
        seen.add(candidate)
        if len(out) >= limit:
            break
        parsed = urllib.parse.urlparse(candidate)
        basename = Path(parsed.path).name or 'xbox360_game'
        if not name:
            drive_match = re.search(r'/(?:file/)?d/([A-Za-z0-9_-]{10,})', parsed.path)
            drive_id = drive_match.group(1) if drive_match else ''
            if drive_id:
                name = f'Xbox 360 Homebrew {drive_id[-6:]}'
            else:
                stem = os.path.splitext(basename)[0].replace('_', ' ').strip()
                name = stem if stem and stem.lower() not in ('view', 'download') else 'Xbox 360 Homebrew'
        rid = 'x360_' + hashlib.sha256(candidate.encode('utf-8')).hexdigest()[:16]
        downloader = BIN / 'xui_download_xbox360_repo.sh'
        out.append({
            'id': rid,
            'name': name,
            'price': 0.0,
            'pricing': 'free',
            'category': 'Xbox 360 Homebrew',
            'source': 'XUI 360 Homebrew',
            'desc': f'Download from the XUI 360 games repository and extract it automatically.',
            'is_game': True,
            'cover': 'https://raw.githubusercontent.com/afitler79-alt/XUI_360GAMES_REP/main/favicon.ico',
            'cover_local': '',
            'install': str(downloader) + f' --name {shlex.quote(name)} --url {shlex.quote(candidate)}',
            'launch': str(downloader) + f' --name {shlex.quote(name)} --url {shlex.quote(candidate)} --launch',
        })
    return out


