        if not rid or not url:
            continue
        cover = str(entry.get('cover', '')).strip()
        cover_local = cache_cover(cover, rid)
        out.append({
            'id': rid,
            'name': str(entry.get('name', rid)),
            'price': float(max(0.0, float(entry.get('price', 0.0)))),
