#!/usr/bin/env bash
set -euo pipefail

XUI_HOME="${HOME}/.xui"
GAME_ROOT="${XUI_HOME}/GAMES/xbox360_repo"
TARGET_NAME=""
TARGET_URL=""
MODE="install"

while [ "$#" -gt 0 ]; do
  case "$1" in
    --name)
      TARGET_NAME="${2:-}"
      shift 2
      ;;
    --url)
      TARGET_URL="${2:-}"
      shift 2
      ;;
    --download-dir)
      GAME_ROOT="${2:-$GAME_ROOT}"
      shift 2
      ;;
    --launch)
      MODE="launch"
      shift
      ;;
    -h|--help)
      echo "Usage: $0 --name 'Game Name' --url 'https://example.com/game.zip' [--launch]"
      exit 0
      ;;
    *)
      echo "Unknown argument: $1" >&2
      exit 1
      ;;
  esac
done

if [ -z "$TARGET_URL" ]; then
  echo "Missing --url" >&2
  exit 1
fi

if [ -z "$TARGET_NAME" ]; then
  TARGET_NAME="$(basename "${TARGET_URL%%\?*}")"
fi

sanitize_name(){
  printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | sed -E 's/[^a-z0-9._-]+/-/g; s/-+/-/g; s/^-+|-+$//g' | cut -c1-80
}

SAFE_NAME="$(sanitize_name "${TARGET_NAME:-xbox360_repo_game}")"
if [ -z "$SAFE_NAME" ]; then
  SAFE_NAME="xbox360_repo_game"
fi

mkdir -p "$GAME_ROOT"
ARCHIVE_PATH="$GAME_ROOT/${SAFE_NAME}.download"
EXTRACT_DIR="$GAME_ROOT/${SAFE_NAME}_extracted"
if [ "$MODE" = "launch" ]; then
    mkdir -p "$EXTRACT_DIR"
else
    rm -rf "$EXTRACT_DIR"
    mkdir -p "$EXTRACT_DIR"
fi

fetch_archive(){
  local url="$1" out="$2"
  rm -f "$out" >/dev/null 2>&1 || true
  if command -v curl >/dev/null 2>&1; then
    curl -L --fail --retry 3 --retry-delay 2 -A 'Mozilla/5.0 XUI-360-Repo-Downloader' -o "$out" "$url"
  elif command -v wget >/dev/null 2>&1; then
    wget -O "$out" --user-agent='Mozilla/5.0 XUI-360-Repo-Downloader' "$url"
  else
    python3 - "$url" "$out" <<'PY'
import sys, urllib.request
url, out = sys.argv[1], sys.argv[2]
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 XUI-360-Repo-Downloader'})
with urllib.request.urlopen(req, timeout=60) as r:
    data = r.read()
with open(out, 'wb') as fh:
    fh.write(data)
PY
  fi
}

find_executable(){
  local root="$1"
  find "$root" -type f \( -iname '*.exe' -o -iname '*.x86_64' -o -iname '*.x86' -o -iname '*.appimage' -o -iname '*.sh' \) 2>/dev/null | head -n 1 || true
}

find_xbox_payload(){
    local root="$1"
    find "$root" -type f \( -iname '*.xex' -o -iname '*.iso' -o -iname '*.xiso' \) 2>/dev/null | sort | head -n 1 || true
}

if [ "$MODE" = "launch" ]; then
    xbox_payload="$(find_xbox_payload "$EXTRACT_DIR")"
    if [ -n "$xbox_payload" ]; then
        XENIA_LAUNCHER="$HOME/.xui/bin/xui_xenia_canary.sh"
        if [ -x "$XENIA_LAUNCHER" ]; then
            echo "Launching Xbox 360 payload in Xenia: $xbox_payload"
            exec "$XENIA_LAUNCHER" "$xbox_payload" "$@"
        fi
        echo "Xenia launcher is missing: $XENIA_LAUNCHER" >&2
        exit 1
    fi
  exe="$(find_executable "$EXTRACT_DIR" || true)"
  if [ -n "$exe" ] && [ -f "$exe" ]; then
    chmod +x "$exe" >/dev/null 2>&1 || true
    echo "Launching: $exe"
        INTRO_LAUNCHER="$HOME/.xui/bin/xui_play_game_intro.sh"
        if [ -x "$INTRO_LAUNCHER" ]; then
                        case "${exe,,}" in
                            *.exe)
                                WINE_LAUNCHER="$HOME/.xui/bin/xui_wine_run.sh"
                                [ -x "$WINE_LAUNCHER" ] || { echo "Wine launcher missing: $WINE_LAUNCHER" >&2; exit 1; }
                                exec "$INTRO_LAUNCHER" -- "$WINE_LAUNCHER" "$exe" "$@"
                                ;;
                            *.sh)
                                exec "$INTRO_LAUNCHER" -- bash "$exe" "$@"
                                ;;
                            *)
                                exec "$INTRO_LAUNCHER" -- "$exe" "$@"
                                ;;
                        esac
        fi
        echo "Required game boot screen launcher is missing: $INTRO_LAUNCHER" >&2
        exit 1
  fi
  if [ -d "$EXTRACT_DIR" ] && [ -n "$(find "$EXTRACT_DIR" -maxdepth 2 -mindepth 1 -print -quit 2>/dev/null || true)" ]; then
    echo "Downloaded game already present in: $EXTRACT_DIR"
    if command -v xdg-open >/dev/null 2>&1; then
      xdg-open "$EXTRACT_DIR" >/dev/null 2>&1 || true
    fi
    exit 0
  fi
  echo "No extracted game found for: $TARGET_NAME in $EXTRACT_DIR" >&2
  exit 1
fi

fetch_archive "$TARGET_URL" "$ARCHIVE_PATH"

if [ ! -s "$ARCHIVE_PATH" ]; then
  echo "Download failed: $TARGET_URL" >&2
  exit 1
fi

case "${TARGET_URL,,}" in
  *.zip)
    unzip -oq "$ARCHIVE_PATH" -d "$EXTRACT_DIR" || python3 - "$ARCHIVE_PATH" "$EXTRACT_DIR" <<'PY'
import sys, zipfile
src, dst = sys.argv[1], sys.argv[2]
with zipfile.ZipFile(src, 'r') as zf:
    zf.extractall(dst)
PY
    ;;
  *.tar|*.tar.gz|*.tgz|*.tar.bz2|*.tbz|*.tar.xz|*.txz|*.gz|*.bz2|*.xz)
    tar -xf "$ARCHIVE_PATH" -C "$EXTRACT_DIR"
    ;;
  *.7z|*.7zip)
    if command -v 7z >/dev/null 2>&1; then
      7z x -y "$ARCHIVE_PATH" -o"$EXTRACT_DIR" >/dev/null
    elif command -v 7zr >/dev/null 2>&1; then
      7zr x -y "$ARCHIVE_PATH" -o"$EXTRACT_DIR" >/dev/null
    else
      echo "7z is required for 7z archives but not installed." >&2
      exit 1
    fi
    ;;
  *)
    echo "Downloaded archive to $ARCHIVE_PATH but extraction is not automatic for this file type."
    echo "Please install the archive manually or use a .zip/.tar/.7z source link."
    exit 0
    ;;
 esac

exe="$(find_executable "$EXTRACT_DIR" || true)"
if [ -n "$exe" ] && [ -f "$exe" ]; then
  chmod +x "$exe" >/dev/null 2>&1 || true
  echo "Downloaded and extracted: $TARGET_NAME"
  echo "Executable: $exe"
else
  echo "Downloaded and extracted: $TARGET_NAME"
  echo "Extracted into: $EXTRACT_DIR"
fi
BASH
  chmod +x "$BIN_DIR/xui_download_xbox360_repo.sh"

  cat > "$GAMES_DIR/gem_match.py" <<'PY'
#!/usr/bin/env python3
import random
import sys
from PyQt5 import QtCore, QtGui, QtWidgets

COLORS = [
    QtGui.QColor('#e74c3c'),
    QtGui.QColor('#3498db'),
    QtGui.QColor('#2ecc71'),
    QtGui.QColor('#f1c40f'),
    QtGui.QColor('#9b59b6'),
    QtGui.QColor('#e67e22'),
]


class GemMatch(QtWidgets.QWidget):
    def __init__(self):
        super().__init__()
        self.setWindowTitle('Gem Match - XUI')
        self.setFocusPolicy(QtCore.Qt.StrongFocus)
        self.rows = 8
        self.cols = 8
        self.cell = 74
        self.pad = 20
        self.score = 0
        self.selected = None
        self.board = [[0] * self.cols for _ in range(self.rows)]
        self._generate_board()
        self.resize(self.pad * 2 + self.cols * self.cell, self.pad * 2 + self.rows * self.cell + 70)

    def _generate_board(self):
        for r in range(self.rows):
            for c in range(self.cols):
                self.board[r][c] = random.randrange(len(COLORS))
        while self._find_matches():
            self._collapse_matches(self._find_matches())

    def _find_matches(self):
        matches = set()
        for r in range(self.rows):
            streak = 1
            for c in range(1, self.cols + 1):
                prev = self.board[r][c - 1]
                cur = self.board[r][c] if c < self.cols else None
                if cur == prev:
                    streak += 1
                else:
                    if streak >= 3:
                        for k in range(c - streak, c):
                            matches.add((r, k))
                    streak = 1
        for c in range(self.cols):
            streak = 1
            for r in range(1, self.rows + 1):
                prev = self.board[r - 1][c]
                cur = self.board[r][c] if r < self.rows else None
                if cur == prev:
                    streak += 1
                else:
                    if streak >= 3:
                        for k in range(r - streak, r):
                            matches.add((k, c))
                    streak = 1
        return matches

    def _collapse_matches(self, matches):
        if not matches:
            return 0
        for (r, c) in matches:
            self.board[r][c] = -1
        removed = len(matches)
        for c in range(self.cols):
            col_vals = [self.board[r][c] for r in range(self.rows) if self.board[r][c] >= 0]
            missing = self.rows - len(col_vals)
            new_vals = [random.randrange(len(COLORS)) for _ in range(missing)] + col_vals
            for r in range(self.rows):
                self.board[r][c] = new_vals[r]
        return removed

    def _cell_at(self, pos):
        x = pos.x() - self.pad
        y = pos.y() - self.pad
        if x < 0 or y < 0:
            return None
        c = x // self.cell
        r = y // self.cell
        if 0 <= r < self.rows and 0 <= c < self.cols:
            return int(r), int(c)
        return None

    def _adjacent(self, a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1

    def mousePressEvent(self, e):
        cell = self._cell_at(e.pos())
        if cell is None:
            self.selected = None
            self.update()
            return
        if self.selected is None:
            self.selected = cell
            self.update()
            return
        if cell == self.selected:
            self.selected = None
            self.update()
            return
        if not self._adjacent(self.selected, cell):
            self.selected = cell
            self.update()
            return
        (r1, c1), (r2, c2) = self.selected, cell
        self.board[r1][c1], self.board[r2][c2] = self.board[r2][c2], self.board[r1][c1]
        matches = self._find_matches()
        if not matches:
            self.board[r1][c1], self.board[r2][c2] = self.board[r2][c2], self.board[r1][c1]
        else:
            while matches:
                removed = self._collapse_matches(matches)
                self.score += removed * 10
                matches = self._find_matches()
        self.selected = None
        self.update()

    def keyPressEvent(self, e):
        if e.key() in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.close()
            return
        super().keyPressEvent(e)

    def paintEvent(self, _e):
        p = QtGui.QPainter(self)
        p.fillRect(self.rect(), QtGui.QColor('#0f1720'))
        p.setRenderHint(QtGui.QPainter.Antialiasing, True)
        p.setPen(QtGui.QColor('#26384a'))
        for r in range(self.rows):
            for c in range(self.cols):
                x = self.pad + c * self.cell
                y = self.pad + r * self.cell
                rect = QtCore.QRect(x + 4, y + 4, self.cell - 8, self.cell - 8)
                idx = self.board[r][c]
                color = COLORS[idx % len(COLORS)]
                p.setBrush(color)
                p.setPen(QtGui.QPen(QtGui.QColor('#0a1118'), 2))
                p.drawRoundedRect(rect, 12, 12)
                if self.selected == (r, c):
                    p.setBrush(QtCore.Qt.NoBrush)
                    p.setPen(QtGui.QPen(QtGui.QColor('#d5f7d5'), 4))
                    p.drawRoundedRect(rect.adjusted(-2, -2, 2, 2), 12, 12)
        p.setPen(QtGui.QColor('#e8f3ff'))
        p.setFont(QtGui.QFont('Sans Serif', 14, QtGui.QFont.Bold))
        p.drawText(16, self.height() - 34, f'Score: {self.score}')
        p.drawText(190, self.height() - 34, 'Click 2 adjacent gems to swap')
        p.drawText(self.width() - 210, self.height() - 34, 'ESC = exit')
        p.end()


def main():
    app = QtWidgets.QApplication(sys.argv)
    w = GemMatch()
    try:
        w.showFullScreen()
    except Exception:
        w.show()
    sys.exit(app.exec_())


if __name__ == '__main__':
    main()
PY
