#!/usr/bin/env bash
set -euo pipefail
XUI_HOME="$HOME/.xui"
APP_HOME="$XUI_HOME/apps/fnae"
DATA_FILE="$XUI_HOME/data/fnae_paths.json"
BIN_DIR="$XUI_HOME/bin"
LINUX_MEDIAFIRE_URL="${XUI_FNAE_LINUX_URL:-https://www.mediafire.com/file/a4q4l09vdfqzzws/Five_Nights_At_Epsteins_Linux.tar/file}"
LINUX_MEDIAFIRE_DIRECT_URL="${XUI_FNAE_LINUX_DIRECT_URL:-https://www.mediafire.com/download/a4q4l09vdfqzzws/Five_Nights_At_Epsteins_Linux.tar}"
WINDOWS_MEDIAFIRE_URL="${XUI_FNAE_WINDOWS_URL:-https://www.mediafire.com/file/6tj1rd7kmsxv4oe/Five_Nights_At_Epstein%2527s.zip/file}"
WINDOWS_MEDIAFIRE_DIRECT_URL="${XUI_FNAE_WINDOWS_DIRECT_URL:-https://www.mediafire.com/download/6tj1rd7kmsxv4oe/Five_Nights_At_Epstein%27s.zip}"
mkdir -p "$APP_HOME/linux" "$APP_HOME/windows" "$XUI_HOME/data"
HOST_OS="$(uname -s 2>/dev/null || echo Linux)"
IS_LINUX=0
if [ "$HOST_OS" = "Linux" ]; then
  IS_LINUX=1
fi
LOG_DIR="$XUI_HOME/logs"
LOG_FILE="$LOG_DIR/fnae_install.log"
mkdir -p "$LOG_DIR"
touch "$LOG_FILE" >/dev/null 2>&1 || true
if command -v tee >/dev/null 2>&1; then
  exec > >(tee -a "$LOG_FILE") 2>&1
else
  exec >>"$LOG_FILE" 2>&1
fi
echo "=== FNAE install start: $(date '+%Y-%m-%d %H:%M:%S') ==="

if [ "$IS_LINUX" = "1" ] && [ -x "$BIN_DIR/xui_install_fnae_deps.sh" ]; then
  echo "[FNAE] Checking runtime dependencies..."
  if command -v timeout >/dev/null 2>&1; then
    XUI_NONINTERACTIVE=1 timeout "${XUI_FNAE_DEPS_TIMEOUT_SEC:-45}" "$BIN_DIR/xui_install_fnae_deps.sh" || true
  else
    XUI_NONINTERACTIVE=1 "$BIN_DIR/xui_install_fnae_deps.sh" || true
  fi
  echo "[FNAE] Runtime dependency step complete."
fi

find_first_existing(){
  for p in "$@"; do
    [ -f "$p" ] && { echo "$p"; return 0; }
  done
  return 1
}

find_by_name_in_dirs(){
  local name="$1"
  shift || true
  for d in "$@"; do
    [ -d "$d" ] || continue
    local found=""
    found="$(find "$d" -maxdepth 6 -type f -name "$name" 2>/dev/null | head -n1 || true)"
    if [ -n "$found" ] && [ -f "$found" ]; then
      echo "$found"
      return 0
    fi
  done
  return 1
}

is_html_file(){
  local f="$1"
  [ -f "$f" ] || return 0
  if command -v file >/dev/null 2>&1; then
    file -b "$f" 2>/dev/null | grep -Eiq 'html|xml' && return 0
  fi
  head -c 2048 "$f" 2>/dev/null | grep -Eiq '<!doctype html|<html|<head|<body|mediafire' && return 0
  return 1
}

fetch_url_to_file(){
  local url="$1"
  local out="$2"
  local ref="${3:-}"
  local max_time="${XUI_FNAE_FETCH_TIMEOUT_SEC:-180}"
  if ! [[ "$max_time" =~ ^[0-9]+$ ]] || [ "$max_time" -le 0 ]; then
    max_time=180
  fi
  if command -v curl >/dev/null 2>&1; then
    if [ -n "$ref" ]; then
      curl -fL --retry 5 --retry-delay 2 --retry-all-errors \
        --connect-timeout 20 --max-time "$max_time" \
        -A "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 XUI-FNAE" \
        -e "$ref" "$url" -o "$out" >/dev/null 2>&1
    else
      curl -fL --retry 5 --retry-delay 2 --retry-all-errors \
        --connect-timeout 20 --max-time "$max_time" \
        -A "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 XUI-FNAE" \
        "$url" -o "$out" >/dev/null 2>&1
    fi
    return $?
  fi
  if command -v wget >/dev/null 2>&1; then
    if [ -n "$ref" ]; then
      wget -q --tries=5 --waitretry=2 --timeout=25 --user-agent="Mozilla/5.0 (X11; Linux x86_64) XUI-FNAE" --referer="$ref" -O "$out" "$url"
    else
      wget -q --tries=5 --waitretry=2 --timeout=25 --user-agent="Mozilla/5.0 (X11; Linux x86_64) XUI-FNAE" -O "$out" "$url"
    fi
    return $?
  fi
  if command -v python3 >/dev/null 2>&1; then
    python3 - "$url" "$out" "$ref" <<'PY'
import ssl
import sys
import urllib.request

url = sys.argv[1]
out = sys.argv[2]
ref = sys.argv[3] if len(sys.argv) > 3 else ''
headers = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 XUI-FNAE'}
if ref:
    headers['Referer'] = ref
req = urllib.request.Request(url, headers=headers)
ctx = ssl.create_default_context()
with urllib.request.urlopen(req, timeout=60, context=ctx) as r:
    payload = r.read()
if not payload:
    raise SystemExit(1)
with open(out, 'wb') as fh:
    fh.write(payload)
raise SystemExit(0)
PY
    return $?
  fi
  return 1
}

extract_mediafire_direct(){
  local html="$1"
  local direct=""
  direct="$(grep -Eo 'https:\\/\\/download[0-9]*\\.mediafire\\.com\\/[^\"]+' "$html" | head -n1 || true)"
  if [ -z "$direct" ]; then
    direct="$(grep -Eo '//download[0-9]*\\.mediafire\\.com/[^"'"'"' <>]+' "$html" | head -n1 || true)"
    [ -n "$direct" ] && direct="https:${direct}"
  fi
  if [ -z "$direct" ]; then
    direct="$(grep -Eo 'https://download[0-9]*\.mediafire\.com/[^"'"'"' <>]+' "$html" | head -n1 || true)"
  fi
  if [ -z "$direct" ]; then
    direct="$(grep -Eo 'https://[a-z0-9.-]*mediafire\.com/[^"'"'"' <>]*download[^"'"'"' <>]*' "$html" | head -n1 || true)"
  fi
  if [ -z "$direct" ]; then
    direct="$(sed -n 's/.*href="\([^"]*download[^"]*\)".*/\1/p' "$html" | grep -E '^https?://.*mediafire' | head -n1 || true)"
  fi
  if [ -z "$direct" ]; then
    direct="$(sed -n "s/.*href='\([^']*download[^']*\)'.*/\1/p" "$html" | grep -E '^https?://.*mediafire' | head -n1 || true)"
  fi
  if [ -n "$direct" ]; then
    direct="$(printf '%s' "$direct" | sed -e 's/&amp;/\&/g' -e 's#\\/#/#g')"
    printf '%s\n' "$direct"
    return 0
  fi
  return 1
}

extract_mediafire_quickkey(){
  local src="$1"
  local key=""
  key="$(printf '%s' "$src" | sed -n 's#.*mediafire\.com/file/\([^/?#][^/?#]*\).*#\1#p' | head -n1 || true)"
  if [ -z "$key" ]; then
    key="$(printf '%s' "$src" | sed -n 's#.*mediafire\.com/download/\([^/?#][^/?#]*\).*#\1#p' | head -n1 || true)"
  fi
  if [ -n "$key" ]; then
    printf '%s\n' "$key"
    return 0
  fi
  return 1
}

resolve_mediafire_direct_via_api(){
  local src_url="$1"
  local key api_url tmp_json direct
  key="$(extract_mediafire_quickkey "$src_url" || true)"
  [ -n "$key" ] || return 1
  api_url="https://www.mediafire.com/api/1.5/file/get_info.php?quick_key=${key}&response_format=json"
  tmp_json="$(mktemp)"
  if ! fetch_url_to_file "$api_url" "$tmp_json" "$src_url"; then
    rm -f "$tmp_json" >/dev/null 2>&1 || true
    return 1
  fi
  if command -v python3 >/dev/null 2>&1; then
    direct="$(python3 - "$tmp_json" <<'PY'
import json
import sys

try:
    with open(sys.argv[1], "r", encoding="utf-8", errors="ignore") as fh:
        data = json.load(fh)
except Exception:
    raise SystemExit(1)

resp = data.get("response") or {}
if str(resp.get("result") or "").lower() != "success":
    raise SystemExit(1)
file_info = resp.get("file_info") or {}
links = file_info.get("links") or {}
for key in ("normal_download", "direct_download", "one_time_download"):
    val = links.get(key)
    if isinstance(val, str) and val.startswith("http"):
        print(val.strip())
        raise SystemExit(0)
raise SystemExit(1)
PY
)" || true
  else
    direct="$(grep -Eo '"normal_download"[[:space:]]*:[[:space:]]*"[^"]+"' "$tmp_json" | head -n1 | sed -E 's/.*"([^"]+)".*/\1/' || true)"
  fi
  rm -f "$tmp_json" >/dev/null 2>&1 || true
  if [ -n "$direct" ]; then
    direct="$(printf '%s' "$direct" | sed -e 's/&amp;/\&/g' -e 's#\\/#/#g')"
    printf '%s\n' "$direct"
    return 0
  fi
  return 1
}

download_from_mediafire_api(){
  local page_url="$1"
  local out_file="$2"
  local direct=""
  direct="$(resolve_mediafire_direct_via_api "$page_url" || true)"
  [ -n "$direct" ] || return 1
  rm -f "$out_file" >/dev/null 2>&1 || true
  if ! fetch_url_to_file "$direct" "$out_file" "$page_url"; then
    rm -f "$out_file" >/dev/null 2>&1 || true
    return 1
  fi
  [ -s "$out_file" ] || { rm -f "$out_file" >/dev/null 2>&1 || true; return 1; }
  if is_html_file "$out_file"; then
    rm -f "$out_file" >/dev/null 2>&1 || true
    return 1
  fi
  return 0
}

download_from_mediafire(){
  local page_url="$1"
  local out_file="$2"
  local tmp_html tmp_dl direct
  tmp_html="$(mktemp)"
  tmp_dl="$(mktemp)"
  rm -f "$out_file"

  fetch_url_to_file "$page_url" "$tmp_html" || { rm -f "$tmp_html" "$tmp_dl"; return 1; }
  direct="$(extract_mediafire_direct "$tmp_html" || true)"
  if [ -z "$direct" ]; then
    # fallback: some links work with /download suffix
    fetch_url_to_file "${page_url%/}/download" "$tmp_html" "$page_url" || true
    direct="$(extract_mediafire_direct "$tmp_html" || true)"
  fi
  if [ -z "$direct" ]; then
    rm -f "$tmp_html" "$tmp_dl"
    return 1
  fi
  fetch_url_to_file "$direct" "$tmp_dl" "$page_url" || { rm -f "$tmp_html" "$tmp_dl"; return 1; }
  if is_html_file "$tmp_dl"; then
    local nested=""
    nested="$(extract_mediafire_direct "$tmp_dl" || true)"
    if [ -n "$nested" ] && [ "$nested" != "$direct" ]; then
      fetch_url_to_file "$nested" "$tmp_dl" "$page_url" || { rm -f "$tmp_html" "$tmp_dl"; return 1; }
    fi
  fi
  if is_html_file "$tmp_dl"; then
    rm -f "$tmp_html" "$tmp_dl"
    return 1
  fi
  if [ ! -s "$tmp_dl" ]; then
    rm -f "$tmp_html" "$tmp_dl"
    return 1
  fi
  mv -f "$tmp_dl" "$out_file"
  rm -f "$tmp_html"
  return 0
}

download_from_mediafire_python(){
  local page_url="$1"
  local out_file="$2"
  command -v python3 >/dev/null 2>&1 || return 1
  rm -f "$out_file" >/dev/null 2>&1 || true
  python3 - "$page_url" "$out_file" <<'PY'
import html
import re
import ssl
import sys
import urllib.parse
import urllib.request

page_url = sys.argv[1]
out_file = sys.argv[2]
headers = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 XUI-FNAE'}
ctx = ssl.create_default_context()

def fetch(url, referer=''):
    h = dict(headers)
    if referer:
        h['Referer'] = referer
    req = urllib.request.Request(url, headers=h)
    with urllib.request.urlopen(req, timeout=60, context=ctx) as r:
        return r.read()

try:
    raw = fetch(page_url)
    txt = raw.decode('utf-8', 'ignore')

    m = re.search(r'id=["\']downloadButton["\'][^>]*href=["\']([^"\']+)', txt, re.IGNORECASE)
    if not m:
        m = re.search(r'https?://download[0-9]*\.mediafire\.com/[^\s"\'<>]+', txt, re.IGNORECASE)
    if not m:
        m = re.search(r'https:\\/\\/download[0-9]*\\.mediafire\\.com\\/[^\s"\'<>]+', txt, re.IGNORECASE)
    if not m:
        raise SystemExit(1)

    raw_direct = m.group(1) if (getattr(m, 'lastindex', 0) or 0) >= 1 else m.group(0)
    direct = html.unescape(raw_direct).replace('\\/', '/')
    if direct.startswith('//'):
        direct = 'https:' + direct
    if direct.startswith('/'):
        direct = urllib.parse.urljoin(page_url, direct)

    payload = fetch(direct, page_url)
    head = payload[:4096].lower()
    if b'<html' in head or b'<!doctype html' in head:
        raise SystemExit(2)
    if not payload:
        raise SystemExit(3)

    with open(out_file, 'wb') as fh:
        fh.write(payload)
except Exception:
    raise SystemExit(1)
raise SystemExit(0)
PY
  return $?
}

download_mediafire_archive(){
  local out_file="$1"
  local validator="$2"
  shift 2
  local src=""
  rm -f "$out_file" >/dev/null 2>&1 || true
  for src in "$@"; do
    [ -n "$src" ] || continue
    echo "[FNAE] Download attempt: $src"
    if fetch_url_to_file "$src" "$out_file" "$src" && [ -s "$out_file" ] && ! is_html_file "$out_file" && "$validator" "$out_file"; then
      return 0
    fi
    rm -f "$out_file" >/dev/null 2>&1 || true
  done
  for src in "$@"; do
    [ -n "$src" ] || continue
    echo "[FNAE] MediaFire parse attempt: $src"
    if download_from_mediafire "$src" "$out_file" && "$validator" "$out_file"; then
      return 0
    fi
    rm -f "$out_file" >/dev/null 2>&1 || true
  done
  for src in "$@"; do
    [ -n "$src" ] || continue
    echo "[FNAE] MediaFire API attempt: $src"
    if download_from_mediafire_api "$src" "$out_file" && "$validator" "$out_file"; then
      return 0
    fi
    rm -f "$out_file" >/dev/null 2>&1 || true
  done
  for src in "$@"; do
    [ -n "$src" ] || continue
    echo "[FNAE] Python MediaFire attempt: $src"
    if download_from_mediafire_python "$src" "$out_file" && "$validator" "$out_file"; then
      return 0
    fi
    rm -f "$out_file" >/dev/null 2>&1 || true
  done
  return 1
}

validate_tar(){
  local f="$1"
  [ -f "$f" ] || return 1
  tar -tf "$f" >/dev/null 2>&1
}

validate_zip(){
  local f="$1"
  [ -f "$f" ] || return 1
  if command -v unzip >/dev/null 2>&1; then
    unzip -tq "$f" >/dev/null 2>&1
    return $?
  fi
  if command -v python3 >/dev/null 2>&1; then
    python3 - "$f" <<'PY'
import sys, zipfile
try:
    with zipfile.ZipFile(sys.argv[1], 'r') as zf:
        zf.testzip()
except Exception:
    raise SystemExit(1)
raise SystemExit(0)
PY
    return $?
  fi
  return 0
}

find_linux_executable(){
  local root="$1"
  [ -d "$root" ] || return 1

  is_elf(){
    local f="$1"
    [ -f "$f" ] || return 1
    LC_ALL=C head -c 4 "$f" 2>/dev/null | grep -q $'^\x7fELF'
  }

  is_script(){
    local f="$1"
    [ -f "$f" ] || return 1
    head -n1 "$f" 2>/dev/null | grep -q '^#!'
  }

  looks_launcher(){
    local f="$1"
    [ -f "$f" ] || return 1
    local bn low
    bn="$(basename "$f")"
    low="$(printf '%s' "$bn" | tr '[:upper:]' '[:lower:]')"
    case "$low" in
      unitycrashhandler*|crashhandler*|chrome-sandbox|\
      *.so|*.dll|*.pdb|*.json|*.txt|*.md|*.png|*.jpg|*.jpeg|*.bmp|*.svg|*.ico|\
      *.wav|*.mp3|*.ogg|*.desktop|*.cfg|*.ini|*.xml)
        return 1
        ;;
    esac
    if [ -d "${f}_Data" ] || [ -d "$(dirname "$f")/${bn}_Data" ]; then
      return 0
    fi
    case "$low" in
      *epstein*|*fnae*|*five*night*)
        return 0
        ;;
    esac
    is_elf "$f" && return 0
    is_script "$f" && return 0
    return 1
  }

  local exe="" data_dir base cand
  while IFS= read -r data_dir; do
    [ -n "$data_dir" ] || continue
    base="${data_dir%_Data}"
    for cand in "$base" "$base.x86_64" "$base.x86" "$base.sh"; do
      if [ -f "$cand" ] && looks_launcher "$cand"; then
        chmod +x "$cand" >/dev/null 2>&1 || true
        echo "$cand"
        return 0
      fi
    done
  done < <(find "$root" -maxdepth 8 -type d -name '*_Data' 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if looks_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f \( -name '*.x86_64' -o -name '*.x86' -o -name '*.AppImage' \) 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if looks_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f \( -iname '*epstein*' -o -iname '*fnae*' -o -iname '*five*night*' \) 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if looks_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f -perm -u+x 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if looks_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f 2>/dev/null | sort)
  return 1
}

