import json, sys
path = sys.argv[1]
field = sys.argv[2]
try:
    data = json.load(open(path, 'r', encoding='utf-8'))
except Exception:
    print('')
    raise SystemExit(0)
print(str(data.get(field, '')))
PY
}

is_elf_file(){
  local f="$1"
  [ -f "$f" ] || return 1
  LC_ALL=C head -c 4 "$f" 2>/dev/null | grep -q $'^\x7fELF'
}

is_script_file(){
  local f="$1"
  [ -f "$f" ] || return 1
  head -n1 "$f" 2>/dev/null | grep -q '^#!'
}

is_probable_launcher(){
  local f="$1"
  [ -f "$f" ] || return 1
  local bn low
  bn="$(basename "$f")"
  low="$(printf '%s' "$bn" | tr '[:upper:]' '[:lower:]')"
  case "$low" in
    unitycrashhandler*|crashhandler*|chrome-sandbox|\
    *.so|*.dll|*.pdb|*.json|*.txt|*.md|*.png|*.jpg|*.jpeg|*.bmp|*.svg|*.ico|\
    *.wav|*.mp3|*.ogg|*.desktop|*.cfg|*.ini|*.xml)
      return 1
      ;;
  esac
  if [ -d "${f}_Data" ] || [ -d "$(dirname "$f")/${bn}_Data" ]; then
    return 0
  fi
  case "$low" in
    *epstein*|*fnae*|*five*night*)
      return 0
      ;;
  esac
  is_elf_file "$f" && return 0
  is_script_file "$f" && return 0
  return 1
}

find_linux_executable(){
  local root="${1:-$APP_HOME/linux}"
  [ -d "$root" ] || return 1
  local exe="" data_dir base cand

  while IFS= read -r data_dir; do
    [ -n "$data_dir" ] || continue
    base="${data_dir%_Data}"
    for cand in "$base" "$base.x86_64" "$base.x86" "$base.sh"; do
      if [ -f "$cand" ] && is_probable_launcher "$cand"; then
        chmod +x "$cand" >/dev/null 2>&1 || true
        echo "$cand"
        return 0
      fi
    done
  done < <(find "$root" -maxdepth 8 -type d -name '*_Data' 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if is_probable_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f \( -name '*.x86_64' -o -name '*.x86' -o -name '*.AppImage' \) 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if is_probable_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f \( -iname '*epstein*' -o -iname '*fnae*' -o -iname '*five*night*' \) 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if is_probable_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f -perm -u+x 2>/dev/null | sort)

  while IFS= read -r exe; do
    [ -n "$exe" ] || continue
    if is_probable_launcher "$exe"; then
      chmod +x "$exe" >/dev/null 2>&1 || true
      echo "$exe"
      return 0
    fi
  done < <(find "$root" -maxdepth 8 -type f 2>/dev/null | sort)
  return 1
}

version_gt(){
  local a="${1:-0}"
  local b="${2:-0}"
  [ "$a" = "$b" ] && return 1
  [ "$(printf '%s\n%s\n' "$a" "$b" | sort -V | tail -n1)" = "$a" ]
}

host_glibc_version(){
  local v=""
  v="$(ldd --version 2>/dev/null | head -n1 | grep -Eo '[0-9]+\.[0-9]+' | head -n1 || true)"
  printf '%s\n' "$v"
}

required_glibc_version(){
  local exe="$1"
  command -v strings >/dev/null 2>&1 || return 1
  local dir req=""
  dir="$(dirname "$exe")"
  if [ -f "$dir/UnityPlayer.so" ]; then
    req="$(strings "$exe" "$dir/UnityPlayer.so" 2>/dev/null | grep -Eo 'GLIBC_[0-9]+\.[0-9]+' | sed 's/^GLIBC_//' | sort -V | tail -n1 || true)"
  else
    req="$(strings "$exe" 2>/dev/null | grep -Eo 'GLIBC_[0-9]+\.[0-9]+' | sed 's/^GLIBC_//' | sort -V | tail -n1 || true)"
  fi
  [ -n "$req" ] || return 1
  printf '%s\n' "$req"
}

needs_runtime_for_glibc(){
  local exe="$1"
  local host req
  host="$(host_glibc_version || true)"
  req="$(required_glibc_version "$exe" || true)"
  [ -n "$host" ] || return 1
  [ -n "$req" ] || return 1
  version_gt "$req" "$host"
}

ensure_fnae_runtime_deps(){
  [ -x "$DEPS_SCRIPT" ] || return 1
  "$DEPS_SCRIPT" || true
  command -v steam-run >/dev/null 2>&1
}

if [ "$CHECK_ONLY" = "0" ] && [ ! -f "$DATA_FILE" ]; then
  "$BIN_DIR/xui_install_fnae.sh" || true
fi

LINUX_EXE=""
WIN_EXE=""
if [ -f "$DATA_FILE" ]; then
  LINUX_EXE="$(read_json_field linux_exe)"
  WIN_EXE="$(read_json_field windows_exe)"
fi
if [ -n "$LINUX_EXE" ] && { [ ! -f "$LINUX_EXE" ] || ! is_probable_launcher "$LINUX_EXE"; }; then
  run_note "Ignoring stale/invalid linux_exe from data file: $LINUX_EXE"
  LINUX_EXE=""
fi
if [ -z "$LINUX_EXE" ] || [ ! -f "$LINUX_EXE" ]; then
  LINUX_EXE="$(find_linux_executable "$APP_HOME/linux" || true)"
fi

# On Linux, force a Linux reinstall once if no native executable was detected.
if [ "$CHECK_ONLY" = "0" ] && [ "$IS_LINUX" = "1" ] && { [ -z "$LINUX_EXE" ] || [ ! -f "$LINUX_EXE" ]; }; then
  "$BIN_DIR/xui_install_fnae.sh" || true
  if [ -f "$DATA_FILE" ]; then
    LINUX_EXE="$(read_json_field linux_exe)"
    WIN_EXE="$(read_json_field windows_exe)"
  fi
fi

if [ "$CHECK_ONLY" = "1" ]; then
  if [ "$IS_LINUX" = "1" ]; then
    [ -n "$LINUX_EXE" ] && [ -f "$LINUX_EXE" ] && exit 0
    exit 1
  fi
  [ -n "$WIN_EXE" ] && [ -f "$WIN_EXE" ] && exit 0
  exit 1
fi

launch_and_wait(){
  local run_dir="$1"
  shift
  if [ -n "$run_dir" ] && [ -d "$run_dir" ]; then
    (
      cd "$run_dir" || exit 1
      "$@"
    ) &
  else
    "$@" &
  fi
  local pid=$!
  mkdir -p "$(dirname "$PID_FILE")"
  printf '%s\n' "$pid" > "$PID_FILE"
  local rc=0
  wait "$pid" || rc=$?
  if [ -f "$PID_FILE" ] && [ "$(cat "$PID_FILE" 2>/dev/null || true)" = "$pid" ]; then
    rm -f "$PID_FILE"
  fi
  return $rc
}

launch_linux_native(){
  local exe="$1"
  shift || true
  local dir rc ldp
  dir="$(dirname "$exe")"
  rc=0
  ldp="$dir"
  if [ -n "${LD_LIBRARY_PATH:-}" ]; then
    ldp="$dir:$LD_LIBRARY_PATH"
  fi
  chmod +x "$exe" >/dev/null 2>&1 || true
  run_note "Launching native: $exe"
  launch_and_wait "$dir" env LD_LIBRARY_PATH="$ldp" "$exe" "$@" || rc=$?
  if [ "$rc" -eq 0 ]; then
    return 0
  fi
  if is_script_file "$exe"; then
    rc=0
    run_note "Native failed, retrying via bash: $exe"
    launch_and_wait "$dir" env LD_LIBRARY_PATH="$ldp" /bin/bash "$exe" "$@" || rc=$?
  fi
  return "$rc"
}

launch_linux_steam(){
  local exe="$1"
  shift || true
  if ! command -v steam-run >/dev/null 2>&1; then
    ensure_fnae_runtime_deps || true
  fi
  if ! command -v steam-run >/dev/null 2>&1; then
    return 127
  fi
  local rc=0
  run_note "Launching with steam-run: $exe"
  launch_and_wait "$(dirname "$exe")" steam-run "$exe" "$@" || rc=$?
  return "$rc"
}

if [ -n "$LINUX_EXE" ] && [ -f "$LINUX_EXE" ]; then
  chmod +x "$LINUX_EXE" || true
  if [ "$IS_LINUX" = "1" ]; then
    native_rc=1
    steam_rc=1
    mode="$(printf '%s' "$USE_STEAM_RUNTIME" | tr '[:upper:]' '[:lower:]')"
    case "$mode" in
      1|on|force|always)
        launch_linux_steam "$LINUX_EXE" "$@" || steam_rc=$?
        if [ "$steam_rc" -eq 0 ]; then
          exit 0
        fi
        run_note "steam-run failed rc=$steam_rc, fallback native"
        launch_linux_native "$LINUX_EXE" "$@" || native_rc=$?
        [ "$native_rc" -eq 0 ] && exit 0
        echo "FNAE failed to launch (steam-run rc=$steam_rc, native rc=$native_rc)."
        echo "See log: $LOG_FILE"
        exit "${native_rc:-1}"
        ;;
      0|off|never)
        launch_linux_native "$LINUX_EXE" "$@" || native_rc=$?
        [ "$native_rc" -eq 0 ] && exit 0
        echo "FNAE failed to launch natively (rc=$native_rc)."
        echo "See log: $LOG_FILE"
        exit "${native_rc:-1}"
        ;;
      *)
        launch_linux_native "$LINUX_EXE" "$@" || native_rc=$?
        if [ "$native_rc" -eq 0 ]; then
          exit 0
        fi
        run_note "native launch failed rc=$native_rc; trying steam-run fallback"
        if needs_runtime_for_glibc "$LINUX_EXE" || command -v steam-run >/dev/null 2>&1; then
          launch_linux_steam "$LINUX_EXE" "$@" || steam_rc=$?
          if [ "$steam_rc" -eq 0 ]; then
            exit 0
          fi
          run_note "steam-run launch failed rc=$steam_rc"
        fi
        host_glibc="$(host_glibc_version || true)"
        req_glibc="$(required_glibc_version "$LINUX_EXE" || true)"
        echo "FNAE failed to launch on Linux."
        if [ -n "${req_glibc:-}" ] || [ -n "${host_glibc:-}" ]; then
          echo "glibc host=${host_glibc:-unknown} required=${req_glibc:-unknown}"
        fi
        echo "See log: $LOG_FILE"
        echo "You can force runtime mode:"
        echo "  XUI_FNAE_USE_STEAM_RUNTIME=1 $BIN_DIR/xui_run_fnae.sh"
        exit "${native_rc:-1}"
        ;;
    esac
  fi
  launch_and_wait "$(dirname "$LINUX_EXE")" "$LINUX_EXE" "$@"
  exit $?
fi

if [ "$IS_LINUX" = "1" ] && [ "${ALLOW_WIN_ON_LINUX}" != "1" ]; then
  echo "FNAE Linux build was not detected."
  echo "Windows fallback is disabled on Linux to avoid crashes."
  echo "Reinstall Linux build:"
  echo "  $BIN_DIR/xui_install_fnae.sh"
  echo "If you still want to force Wine fallback:"
  echo "  XUI_FNAE_ALLOW_WINDOWS_ON_LINUX=1 $BIN_DIR/xui_run_fnae.sh"
  exit 1
fi

if [ -n "$WIN_EXE" ] && [ -f "$WIN_EXE" ]; then
  launch_and_wait "$(dirname "$WIN_EXE")" "$BIN_DIR/xui_wine_run.sh" "$WIN_EXE" "$@"
  exit $?
fi

echo "FNAE executable not found. Run installer:"
echo "  $BIN_DIR/xui_install_fnae.sh"
exit 1
