# Decode embedded blobs only if explicitly enabled to avoid invalid-placeholder noise
if [ "${XUI_USE_EMBEDDED_ASSETS:-0}" = "1" ]; then
if [ -n "$EMBED_LOGO_B64" ] && [ "$EMBED_LOGO_B64" != "__LOGO_B64_PLACEHOLDER__" ]; then
