    text='XGUI'
    bbox=d.textbbox((0,0),text,font=f)
    w,h=bbox[2]-bbox[0],bbox[3]-bbox[1]
    d.text(((512-w)/2-bbox[0],(512-h)/2-bbox[1]),text,fill=(255,255,255,255),font=f)
