write_auto_update(){
    info "Writing auto-update checker"
    cat > "$BIN_DIR/xui_update_check.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
MODE="${1:-status}"
shift || true
JSON_OUT=0
if [ "${1:-}" = "--json" ]; then
  JSON_OUT=1
  shift || true
fi

REPO="${XUI_UPDATE_REPO:-afitler79-alt/XUI-X360-FRONTEND}"
SRC="${XUI_SOURCE_DIR:-$HOME/.xui/src/XUI-X360-FRONTEND}"
INSTALLER_NAME="${XUI_UPDATE_INSTALLER:-xui11.sh.fixed.sh}"
STATE_FILE="$HOME/.xui/data/update_state.json"
CHANNEL_FILE="$HOME/.xui/data/update_channel.json"
DEFAULT_BRANCH="${XUI_DEFAULT_UPDATE_BRANCH:-Main-XUI}"
mkdir -p "$(dirname "$STATE_FILE")"

require_cmd(){
  command -v "$1" >/dev/null 2>&1
}

now_iso(){
  date -u +"%Y-%m-%dT%H:%M:%SZ"
}

read_state_commit(){
  python3 - "$STATE_FILE" <<'PY'
import json,sys,pathlib
p=pathlib.Path(sys.argv[1])
if not p.exists():
    print("")
    raise SystemExit(0)
try:
    d=json.loads(p.read_text(encoding='utf-8'))
except Exception:
    print("")
    raise SystemExit(0)
print(str(d.get('installed_commit','') or '').strip())
PY
}

write_state(){
  local commit="$1"
  local branch="$2"
  local remote_date="$3"
  local src="$4"
  python3 - "$STATE_FILE" "$commit" "$branch" "$remote_date" "$src" <<'PY'
import json,sys,time,pathlib
path=pathlib.Path(sys.argv[1])
data={
  "installed_commit": str(sys.argv[2] or ""),
  "branch": str(sys.argv[3] or ""),
  "remote_date": str(sys.argv[4] or ""),
  "installed_at_epoch": int(time.time()),
  "source_dir": str(sys.argv[5] or ""),
  "version": 2,
}
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
print("state-updated")
PY
}

read_channel_branch(){
  python3 - "$CHANNEL_FILE" <<'PY'
import json,sys,pathlib
p=pathlib.Path(sys.argv[1])
if not p.exists():
    print("")
    raise SystemExit(0)
try:
    d=json.loads(p.read_text(encoding='utf-8'))
except Exception:
    print("")
    raise SystemExit(0)
print(str(d.get('branch','') or '').strip())
PY
}

resolve_target_branch(){
  local b=""
  b="${XUI_UPDATE_BRANCH:-}"
  if [ -n "$b" ]; then
    echo "$b"
    return 0
  fi
  b="$(read_channel_branch)"
  if [ -n "$b" ]; then
    echo "$b"
    return 0
  fi
  echo "$DEFAULT_BRANCH"
}

TARGET_BRANCH="$(resolve_target_branch)"

remote_meta_line(){
  python3 - "$REPO" "$TARGET_BRANCH" <<'PY'
import json,sys,urllib.request,urllib.error
repo=sys.argv[1]
target=str(sys.argv[2] or "").strip()
headers={
  "Accept":"application/vnd.github+json",
  "User-Agent":"xui-update-checker",
}
def fetch(url, timeout=5):
  req=urllib.request.Request(url, headers=headers)
  with urllib.request.urlopen(req, timeout=timeout) as r:
    return json.loads(r.read().decode('utf-8', errors='ignore'))
try:
  if target:
    branch=target
  else:
    repo_info=fetch(f"https://api.github.com/repos/{repo}")
    branch=str(repo_info.get("default_branch") or "main").strip() or "main"
  commit=fetch(f"https://api.github.com/repos/{repo}/commits/{branch}")
  sha=str(commit.get("sha") or "").strip()
  date=str((((commit.get("commit") or {}).get("committer") or {}).get("date")) or "")
  html=str(commit.get("html_url") or "")
  if not sha:
    print("ERR\t\t\t\tmissing-remote-sha")
    raise SystemExit(0)
  print(f"OK\t{branch}\t{sha}\t{date}\t{html}")
except Exception as exc:
  msg=str(exc).replace("\t"," ").replace("\n"," ")
  if target:
    msg=f"{msg} [branch={target}]"
  print(f"ERR\t\t\t\t{msg}")
PY
}

emit_json(){
  local checked="$1"
  local required="$2"
  local reason="$3"
  local branch="$4"
  local local_commit="$5"
  local remote_commit="$6"
  local remote_date="$7"
  local remote_url="$8"
  python3 - "$checked" "$required" "$reason" "$REPO" "$branch" "$local_commit" "$remote_commit" "$remote_date" "$remote_url" <<'PY'
import json,sys
checked = str(sys.argv[1]).strip() == "1"
required = str(sys.argv[2]).strip() == "1"
obj = {
  "checked": checked,
  "mandatory": True,
  "update_required": required,
  "reason": str(sys.argv[3]),
  "repo": str(sys.argv[4]),
  "branch": str(sys.argv[5]),
  "local_commit": str(sys.argv[6]),
  "remote_commit": str(sys.argv[7]),
  "remote_date": str(sys.argv[8]),
  "remote_url": str(sys.argv[9]),
}
print(json.dumps(obj, ensure_ascii=False))
PY
}

compute_status(){
  local line status branch remote_commit remote_date remote_url extra
  local checked=0 required=0 reason="unknown"
  local local_commit=""
  local_commit="$(read_state_commit)"
  if [ -z "$local_commit" ] && [ -d "$SRC/.git" ]; then
    local_commit="$(git -C "$SRC" rev-parse HEAD 2>/dev/null || true)"
  fi

  line="$(remote_meta_line)"
  IFS=$'\t' read -r status branch remote_commit remote_date remote_url extra <<<"$line"
  if [ "$status" != "OK" ]; then
    checked=0
    required=0
    reason="remote-unavailable:${extra:-unknown}"
    branch="${TARGET_BRANCH:-linux}"
    remote_commit=""
    remote_date=""
    remote_url=""
  else
    checked=1
    if [ -z "$local_commit" ]; then
      required=1
      reason="missing-local-version"
    elif [ "$local_commit" != "$remote_commit" ]; then
      required=1
      reason="outdated"
    else
      required=0
      reason="up-to-date"
    fi
  fi

  if [ "$JSON_OUT" = "1" ]; then
    emit_json "$checked" "$required" "$reason" "$branch" "$local_commit" "$remote_commit" "$remote_date" "$remote_url"
    return 0
  fi

  echo "Repo: $REPO"
  echo "Branch: ${branch:-main}"
  echo "Checked: $([ "$checked" = "1" ] && echo yes || echo no)"
  echo "Mandatory: yes"
  echo "Local commit: ${local_commit:-<none>}"
  echo "Remote commit: ${remote_commit:-<unknown>}"
  [ -n "$remote_date" ] && echo "Remote date: $remote_date"
  [ -n "$remote_url" ] && echo "Remote URL: $remote_url"
  echo "Update required: $([ "$required" = "1" ] && echo yes || echo no)"
  echo "Reason: $reason"
  if [ "$required" = "1" ]; then
    return 10
  fi
  return 0
}

apply_update(){
  local line status branch remote_commit remote_date remote_url extra
  if ! require_cmd git; then
    echo "git is required for apply mode"
    exit 1
  fi

    echo "step=metadata-check"
    line="$(remote_meta_line)"
  IFS=$'\t' read -r status branch remote_commit remote_date remote_url extra <<<"$line"
  if [ "$status" != "OK" ]; then
    echo "Cannot reach GitHub metadata: ${extra:-unknown}"
    exit 1
  fi

    if [ "$(id -u)" -eq 0 ]; then
        XUI_AUTH_MODE="root"
    else
        XUI_AUTH_MODE="none"
    fi

  fix_src_permissions(){
    local target="$1"
    [ -e "$target" ] || return 0
    if [ -w "$target" ] && { [ ! -d "$target/.git" ] || [ -w "$target/.git" ]; }; then
      return 0
    fi
    echo "Fixing source permissions: $target"
  }

  remove_path_safe(){
    local target="$1"
    [ -e "$target" ] || return 0
    rm -rf "$target" >/dev/null 2>&1 && return 0
    fix_src_permissions "$target"
    rm -rf "$target" >/dev/null 2>&1 && return 0
        if [ "${XUI_AUTH_MODE:-}" = "root" ]; then
            rm -rf "$target" >/dev/null 2>&1 && return 0
        fi
    return 1
  }

  clone_fresh_repo(){
    local tmp="${SRC}.tmp.$$"
    remove_path_safe "$tmp" || true
        echo "step=git-clone"
        if command -v timeout >/dev/null 2>&1; then
            GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never timeout --signal=TERM --kill-after=10 180 \
                git clone --progress "https://github.com/$REPO.git" "$tmp"
        else
            GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never git clone --progress "https://github.com/$REPO.git" "$tmp"
        fi
    if ! remove_path_safe "$SRC"; then
      echo "Cannot replace source dir due permissions: $SRC"
      return 1
    fi
    mv "$tmp" "$SRC"
    fix_src_permissions "$SRC" || true
  }

  mkdir -p "$(dirname "$SRC")"
  if [ ! -d "$SRC/.git" ]; then
    clone_fresh_repo
  fi

    echo "step=git-fetch"
    if command -v timeout >/dev/null 2>&1; then
        if ! GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never GIT_HTTP_LOW_SPEED_LIMIT=1000 GIT_HTTP_LOW_SPEED_TIME=30 \
            timeout --signal=TERM --kill-after=10 180 git -C "$SRC" fetch --all --prune --progress; then
            echo "Fetch failed or timed out; recloning source..."
            clone_fresh_repo
            GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never timeout --signal=TERM --kill-after=10 180 \
                git -C "$SRC" fetch --all --prune --progress
        fi
    elif ! GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never GIT_HTTP_LOW_SPEED_LIMIT=1000 GIT_HTTP_LOW_SPEED_TIME=30 \
        git -C "$SRC" fetch --all --prune --progress; then
    echo "Fetch failed, recloning source..."
    clone_fresh_repo
        GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never git -C "$SRC" fetch --all --prune --progress
  fi
    echo "step=git-checkout"
  if ! git -C "$SRC" checkout -B "$branch" "origin/$branch" >/dev/null 2>&1; then
    echo "Checkout failed, recloning source..."
    clone_fresh_repo
        GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never timeout --signal=TERM --kill-after=10 180 \
            git -C "$SRC" fetch --all --prune --progress
    git -C "$SRC" checkout -B "$branch" "origin/$branch"
  fi
    echo "step=git-reset"
    if ! git -C "$SRC" reset --hard "origin/$branch" >/dev/null 2>&1; then
    echo "Reset failed, recloning source..."
    clone_fresh_repo
        GIT_TERMINAL_PROMPT=0 GCM_INTERACTIVE=Never timeout --signal=TERM --kill-after=10 180 \
            git -C "$SRC" fetch --all --prune --progress
    git -C "$SRC" checkout -B "$branch" "origin/$branch"
    git -C "$SRC" reset --hard "origin/$branch"
  fi
  git -C "$SRC" clean -fd >/dev/null 2>&1 || true

  find_installer(){
    local c f
    local names=(
      "$INSTALLER_NAME"
      "xui11.sh.fixed.sh"
      "xui11.sh.fixed"
      "xui11.sh"
      "install.sh"
      "installer.sh"
      "main-xui.sh"
      "Main-XUI.sh"
    )
    for c in "${names[@]}"; do
      [ -n "$c" ] || continue
      if [ -f "$SRC/$c" ]; then
        echo "$SRC/$c"
        return 0
      fi
    done
    for c in "${names[@]}"; do
      [ -n "$c" ] || continue
      f="$(find "$SRC" -maxdepth 6 -type f -name "$c" 2>/dev/null | head -n 1 || true)"
      if [ -n "$f" ]; then
        echo "$f"
        return 0
      fi
    done
    while IFS= read -r f; do
      if grep -q "write_dashboard_py" "$f" 2>/dev/null && grep -q "write_auto_update" "$f" 2>/dev/null; then
        echo "$f"
        return 0
      fi
    done < <(find "$SRC" -maxdepth 6 -type f -name "*.sh" 2>/dev/null | sort)
    f="$(find "$SRC" -maxdepth 6 -type f \( -iname '*xui*installer*.sh' -o -iname '*xui11*.sh' -o -iname '*main*xui*.sh' \) 2>/dev/null | head -n 1 || true)"
    if [ -n "$f" ]; then
      echo "$f"
      return 0
    fi
    return 1
  }

  local installer=""
    echo "step=installer-search"
  installer="$(find_installer || true)"
  if [ -z "$installer" ]; then
    echo "Installer not found in repo: $SRC"
    exit 1
  fi

  echo "step=installer-start"
  local installer_rc=0
  local installer_log=""
  local installer_soft_ok=0
  local installer_started_epoch
  installer_started_epoch="$(date +%s)"
  installer_log="$(mktemp /tmp/xui-installer-log.XXXXXX 2>/dev/null || true)"
  run_installer_once(){
        (
            cd "$SRC"
            if command -v timeout >/dev/null 2>&1; then
                AUTO_CONFIRM=1 XUI_SKIP_LAUNCH_PROMPT=1 XUI_NONINTERACTIVE=1 XUI_SYSTEMCTL_TIMEOUT_SEC="${XUI_SYSTEMCTL_TIMEOUT_SEC:-15}" \
                    timeout "${XUI_APPLY_INSTALLER_TIMEOUT_SEC:-300}" bash "$installer" --no-auto-install --skip-apt-wait
            else
                AUTO_CONFIRM=1 XUI_SKIP_LAUNCH_PROMPT=1 XUI_NONINTERACTIVE=1 XUI_SYSTEMCTL_TIMEOUT_SEC="${XUI_SYSTEMCTL_TIMEOUT_SEC:-15}" \
                    bash "$installer" --no-auto-install --skip-apt-wait
            fi
            )
  }
  set +e
  if [ -n "${installer_log:-}" ] && command -v tee >/dev/null 2>&1; then
    run_installer_once 2>&1 | tee "$installer_log"
    installer_rc=${PIPESTATUS[0]}
  else
    run_installer_once
    installer_rc=$?
  fi
  set -e
  echo "step=installer-done"
  if [ -n "${installer_log:-}" ] && [ -f "$installer_log" ]; then
    if grep -qiE 'Finalizing installation|Installation complete|Attempted to enable user services|state-updated|step=installer-done' "$installer_log" 2>/dev/null; then
      installer_soft_ok=1
    fi
  fi
  if [ "$installer_rc" -ne 0 ]; then
    echo "warning=installer-exit-$installer_rc"
    local dash_file marker_file checker_file
    local dash_mtime marker_mtime checker_mtime
    dash_file="$HOME/.xui/dashboard/pyqt_dashboard_improved.py"
    marker_file="$HOME/.xui/.xui_4_0xv_setup_done"
    checker_file="$HOME/.xui/bin/xui_update_check.sh"
    dash_mtime="$(stat -c %Y "$dash_file" 2>/dev/null || echo 0)"
    marker_mtime="$(stat -c %Y "$marker_file" 2>/dev/null || echo 0)"
    checker_mtime="$(stat -c %Y "$checker_file" 2>/dev/null || echo 0)"
    if [ "$dash_mtime" -lt "$installer_started_epoch" ] && [ "$marker_mtime" -lt "$installer_started_epoch" ] && [ "$checker_mtime" -lt "$installer_started_epoch" ]; then
      if [ "$installer_soft_ok" -ne 1 ]; then
        echo "Installer failed with code $installer_rc and no updated core artifacts were detected."
        [ -n "${installer_log:-}" ] && rm -f "$installer_log" >/dev/null 2>&1 || true
        exit "$installer_rc"
      fi
      echo "warning=installer-soft-success-log-detected"
    else
      echo "warning=installer-soft-success-core-files-detected"
    fi
  fi
  [ -n "${installer_log:-}" ] && rm -f "$installer_log" >/dev/null 2>&1 || true

  # Ensure dashboard service stays enabled after updates.
    if command -v systemctl >/dev/null 2>&1; then
    XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}" \
    DBUS_SESSION_BUS_ADDRESS="${DBUS_SESSION_BUS_ADDRESS:-unix:path=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/bus}" \
      systemctl --user daemon-reload >/dev/null 2>&1 || true
    XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}" \
    DBUS_SESSION_BUS_ADDRESS="${DBUS_SESSION_BUS_ADDRESS:-unix:path=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}/bus}" \
      systemctl --user enable xui-dashboard.service >/dev/null 2>&1 || true
  fi

  if [ -x "$HOME/.xui/bin/xui_install_fnae_deps.sh" ]; then
    # Keep mandatory update responsive: run FNAE deps best-effort in background.
    (
      if command -v timeout >/dev/null 2>&1; then
        XUI_NONINTERACTIVE=1 timeout "${XUI_FNAE_DEPS_TIMEOUT_SEC:-90}" "$HOME/.xui/bin/xui_install_fnae_deps.sh" || true
      else
        XUI_NONINTERACTIVE=1 "$HOME/.xui/bin/xui_install_fnae_deps.sh" || true
      fi
    ) >/dev/null 2>&1 &
    echo "step=fnae-deps-background"
  fi

  local installed_commit=""
  installed_commit="$(git -C "$SRC" rev-parse HEAD 2>/dev/null || true)"
  if [ -z "$installed_commit" ]; then
    installed_commit="$remote_commit"
  fi
  if write_state "$installed_commit" "$branch" "$remote_date" "$SRC" >/dev/null 2>&1; then
    echo "step=state-written"
  else
    echo "warning=state-write-failed"
    echo "step=state-write-skipped"
  fi
  echo "update-applied"
  echo "installed_commit=$installed_commit"
}

pull_only(){
  if [ ! -d "$SRC/.git" ]; then
    echo "No git repo at $SRC"
    echo "Tip: run '$0 apply' to clone and install automatically."
    exit 1
  fi
  git -C "$SRC" fetch --all --prune
  git -C "$SRC" pull --ff-only
}

release_info(){
  python3 - "$REPO" <<'PY'
import json,sys,urllib.request
repo=sys.argv[1]
headers={"Accept":"application/vnd.github+json","User-Agent":"xui-update-checker"}
req=urllib.request.Request(f"https://api.github.com/repos/{repo}/releases/latest", headers=headers)
try:
  with urllib.request.urlopen(req, timeout=10) as r:
    d=json.loads(r.read().decode("utf-8", errors="ignore"))
  print("Latest release:", d.get("tag_name","unknown"))
except Exception as exc:
  print("Could not query latest release:", exc)
  raise SystemExit(1)
PY
}

mark_current(){
  if [ ! -d "$SRC/.git" ]; then
    echo "No git repo at $SRC"
    exit 1
  fi
  local commit branch
  commit="$(git -C "$SRC" rev-parse HEAD)"
  branch="$(git -C "$SRC" rev-parse --abbrev-ref HEAD)"
  write_state "$commit" "$branch" "" "$SRC" >/dev/null
  echo "marked-installed=$commit"
}

case "$MODE" in
  status|mandatory)
    compute_status
    ;;
  pull)
    pull_only
    ;;
  apply)
    apply_update
    ;;
  release)
    release_info
    ;;
  mark)
    mark_current
    ;;
  *)
    echo "Usage: $0 {status|mandatory|pull|apply|release|mark} [--json]"
    exit 1
    ;;
esac
BASH
    chmod +x "$BIN_DIR/xui_update_check.sh"
}

write_uninstall(){
    info "Writing uninstall script"
    cat > "$BIN_DIR/xui_uninstall.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
read -p "This will remove ~/.xui (files only). Continue? [s/N] " r
case "$r" in [sS]) rm -rf "$HOME/.xui"; echo removed;; *) echo aborted; exit 1;; esac
BASH
    chmod +x "$BIN_DIR/xui_uninstall.sh"
}

write_readme_and_requirements(){
    info "Writing README and requirements"
    cat > "$XUI_DIR/README.md" <<TXT
XUI 4.0XV - Ultra Master Installer
Files installed under ~/.xui
Use systemctl --user to enable services
TXT
    cat > "$XUI_DIR/requirements.txt" <<REQ
urwid
evdev
REQ
}

write_basic_tests(){
    info "Writing basic tests"
    mkdir -p "$XUI_DIR/tests"
    cat > "$XUI_DIR/tests/test_balance.py" <<PY
import json, os
f=os.path.expanduser('~/.xui/data/saldo.json')
def test_balance_exists():
        assert os.path.exists(f)
        d=json.load(open(f))
        assert 'balance' in d
PY
}

write_apps_utilities(){
    info "Writing utilities and lightweight apps"
    local script_dir
    script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

    # Prefer user-provided sounds from SONIDOS (or user_sounds) and install them into assets.
    if [ -d "$script_dir/SONIDOS" ] || [ -d "$script_dir/sonidos" ] || [ -d "$script_dir/user_sounds" ]; then
        mkdir -p "$ASSETS_DIR/SONIDOS"
        for d in "$script_dir/SONIDOS" "$script_dir/sonidos" "$script_dir/user_sounds"; do
            [ -d "$d" ] || continue
            find "$d" -type f \( -iname '*.mp3' -o -iname '*.wav' \) -print0 | while IFS= read -r -d '' f; do
                bn="$(basename "$f")"
                cp -f "$f" "$ASSETS_DIR/SONIDOS/$bn" || true
                case "${bn,,}" in
                    startup.mp3) cp -f "$f" "$ASSETS_DIR/startup.mp3" || true ;;
                esac
                info "Installed sound: SONIDOS/$bn"
            done
        done
    fi

    # Screenshot utility
    cat > "$BIN_DIR/xui_screenshot.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
OUT="$HOME/.xui/assets/screenshot-$(date +%Y%m%d-%H%M%S).png"
mkdir -p "$(dirname "$OUT")"
if command -v maim >/dev/null 2>&1; then
    maim "$OUT"
elif command -v scrot >/dev/null 2>&1; then
    scrot "$OUT"
else
    echo "No screenshot tool installed"
    exit 1
fi
echo "$OUT"
BASH
    chmod +x "$BIN_DIR/xui_screenshot.sh"

    # System monitor (top-like summary)
    cat > "$BIN_DIR/xui_sysmon.sh" <<'BASH'
#!/usr/bin/env bash
htop || top -b -n1 | head -n 20
BASH
    chmod +x "$BIN_DIR/xui_sysmon.sh"

    # Custom Chromium-based web hub + launcher
    cat > "$BIN_DIR/xui_webhub.py" <<'PY'
#!/usr/bin/env python3
import argparse
import json
import os
import sys
import time
from pathlib import Path
from urllib.parse import parse_qs, unquote, urlparse
from PyQt5 import QtCore, QtGui, QtWidgets
try:
    from PyQt5 import QtWebEngineWidgets
except Exception:
    QtWebEngineWidgets = None
try:
    from PyQt5 import QtGamepad
except Exception:
    QtGamepad = None

DATA_HOME = Path.home() / '.xui' / 'data'
RECENT_FILE = DATA_HOME / 'webhub_recent.json'
FAV_FILE = DATA_HOME / 'webhub_favorites.json'
SOCIAL_MESSAGES_FILE = DATA_HOME / 'social_messages_recent.json'
MAX_RECENT = 24
MODERN_USER_AGENT = os.environ.get(
    'XUI_WEBHUB_USER_AGENT',
    'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36'
)


def safe_read(path, default):
    try:
        return json.loads(Path(path).read_text(encoding='utf-8'))
    except Exception:
        return default


def safe_write(path, data):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')


def normalize_url(text):
    raw = str(text or '').strip()
    if not raw:
        return 'https://www.xbox.com'
    if '://' not in raw and not raw.startswith('about:'):
        raw = 'https://' + raw
    return raw


def detect_total_ram_mb():
    forced = str(os.environ.get('XUI_RAM_MB', '')).strip()
    if forced:
        try:
            return max(0, int(float(forced)))
        except Exception:
            pass
    try:
        for raw in Path('/proc/meminfo').read_text(encoding='utf-8', errors='ignore').splitlines():
            line = str(raw).strip()
            if not line.lower().startswith('memtotal:'):
                continue
            parts = line.split()
            if len(parts) >= 2:
                return max(0, int(parts[1]) // 1024)
    except Exception:
        pass
    return 0


def ultra_low_ram_mode():
    mode = str(os.environ.get('XUI_RAM_MODE', 'auto')).strip().lower()
    if mode in ('1', 'true', 'on', 'yes', '2g', '2gb', 'ultra', 'low'):
        return True
    if mode in ('0', 'false', 'off', 'no', 'normal', 'full'):
        return False
    mb = int(detect_total_ram_mb() or 0)
    return bool(mb and mb <= 2304)


def unwrap_supported_browser_redirect(url_text):
    raw = normalize_url(url_text)
    try:
        parsed = urlparse(raw)
    except Exception:
        return raw
    host = str(parsed.netloc or '').lower()
    path = str(parsed.path or '')
    if 'youtube.' not in host:
        return raw
    if not path.startswith('/supported_browsers'):
        return raw
    try:
        qs = parse_qs(str(parsed.query or ''), keep_blank_values=False)
    except Exception:
        qs = {}
    next_url = ''
    for key in ('next_url', 'url', 'continue'):
        vals = qs.get(key) or []
        if vals and str(vals[0]).strip():
            next_url = str(vals[0]).strip()
            break
    if not next_url:
        return raw
    try:
        next_url = unquote(next_url).strip()
    except Exception:
        next_url = str(next_url).strip()
    if next_url.startswith('//'):
        next_url = 'https:' + next_url
    elif next_url.startswith('/'):
        next_url = 'https://www.youtube.com' + next_url
    next_url = normalize_url(next_url)
    if next_url and next_url != raw:
        return next_url
    return raw


class VirtualKeyboardDialog(QtWidgets.QDialog):
    def __init__(self, initial='', parent=None):
        super().__init__(parent)
        self._nav_default_cols = 10
        self.setWindowTitle('Virtual Keyboard')
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        self.setModal(True)
        self.resize(900, 420)
        self.setStyleSheet('''
            QDialog { background:#d2d7dc; border:2px solid #e8edf1; }
            QLineEdit { background:#ffffff; border:1px solid #8a96a3; color:#1e2731; font-size:23px; font-weight:700; padding:8px; }
            QListWidget { background:#eef2f5; border:1px solid #9da8b3; color:#24303b; font-size:17px; font-weight:800; outline:none; }
            QListWidget::item { border:1px solid #c1c9d2; min-width:72px; min-height:44px; margin:3px; }
            QListWidget::item:selected { background:#66b340; color:#fff; border:2px solid #2f6e28; }
            QLabel { color:#2f3944; font-size:14px; font-weight:700; }
        ''')
        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(12, 10, 12, 10)
        v.setSpacing(8)
        self.edit = QtWidgets.QLineEdit(str(initial or ''))
        self.edit.setFocusPolicy(QtCore.Qt.ClickFocus)
        self.edit.installEventFilter(self)
        v.addWidget(self.edit)
        self.keys = QtWidgets.QListWidget()
        self.keys.setViewMode(QtWidgets.QListView.IconMode)
        self.keys.setMovement(QtWidgets.QListView.Static)
        self.keys.setResizeMode(QtWidgets.QListView.Adjust)
        self.keys.setWrapping(True)
        self.keys.setSpacing(4)
        self.keys.setGridSize(QtCore.QSize(84, 54))
        self.keys.itemActivated.connect(self._activate_current)
        self.keys.installEventFilter(self)
        for token in list("1234567890QWERTYUIOPASDFGHJKLZXCVBNM") + ['-', '_', '@', '.', '/', ':', 'SPACE', 'BACK', 'CLEAR', 'DONE']:
            self.keys.addItem(QtWidgets.QListWidgetItem(token))
        self.keys.setCurrentRow(0)
        self.keys.setFocus(QtCore.Qt.OtherFocusReason)
        v.addWidget(self.keys, 1)
        v.addWidget(QtWidgets.QLabel('A/ENTER = Select | B/ESC = Back | X = Backspace | Y = Space'))

    def text(self):
        return self.edit.text()

    def _activate_current(self):
        it = self.keys.currentItem()
        if it is None:
            return
        key = str(it.text() or '')
        if key == 'DONE':
            self.accept()
            return
        if key == 'SPACE':
            self.edit.setText(self.edit.text() + ' ')
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if key == 'BACK':
            self.edit.setText(self.edit.text()[:-1])
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if key == 'CLEAR':
            self.edit.setText('')
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        self.edit.setText(self.edit.text() + key)
        self.keys.setFocus(QtCore.Qt.OtherFocusReason)

    def _nav_cols(self):
        try:
            grid_w = int(self.keys.gridSize().width())
            view_w = int(self.keys.viewport().width())
            cols = max(1, view_w // max(1, grid_w))
            return cols
        except Exception:
            return self._nav_default_cols

    def _move_selection(self, dr=0, dc=0):
        total = int(self.keys.count())
        if total <= 0:
            return
        cols = max(1, int(self._nav_cols() or self._nav_default_cols))
        idx = int(self.keys.currentRow())
        if idx < 0:
            idx = 0
        row = idx // cols
        col = idx % cols
        row += int(dr)
        col += int(dc)
        max_row = (total - 1) // cols
        row = max(0, min(max_row, row))
        col = max(0, col)
        row_start = row * cols
        row_end = min(total - 1, row_start + cols - 1)
        new_idx = min(row_end, row_start + col)
        self.keys.setCurrentRow(new_idx)
        it = self.keys.currentItem()
        if it is not None:
            self.keys.scrollToItem(it, QtWidgets.QAbstractItemView.PositionAtCenter)

    def eventFilter(self, obj, event):
        if event.type() == QtCore.QEvent.KeyPress:
            if event.key() in (
                QtCore.Qt.Key_Left, QtCore.Qt.Key_Right,
                QtCore.Qt.Key_Up, QtCore.Qt.Key_Down,
                QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter,
                QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back,
                QtCore.Qt.Key_Space, QtCore.Qt.Key_Backspace,
            ):
                self.keyPressEvent(event)
                return True
        return super().eventFilter(obj, event)

    def keyPressEvent(self, e):
        k = e.key()
        if k in (QtCore.Qt.Key_Left,):
            self._move_selection(0, -1)
            return
        if k in (QtCore.Qt.Key_Right,):
            self._move_selection(0, 1)
            return
        if k in (QtCore.Qt.Key_Up,):
            self._move_selection(-1, 0)
            return
        if k in (QtCore.Qt.Key_Down,):
            self._move_selection(1, 0)
            return
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.reject()
            return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            self._activate_current()
            return
        if k == QtCore.Qt.Key_Space:
            self.edit.setText(self.edit.text() + ' ')
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        if k == QtCore.Qt.Key_Backspace:
            self.edit.setText(self.edit.text()[:-1])
            self.keys.setFocus(QtCore.Qt.OtherFocusReason)
            return
        super().keyPressEvent(e)


class WebHub(QtWidgets.QMainWindow):
    def __init__(self, url='https://www.xbox.com', kiosk=False):
        super().__init__()
