            self.stack.addWidget(fallback)
        else:
            self.web = QtWebEngineWidgets.QWebEngineView()
            self.web.installEventFilter(self)
            self._configure_webengine_runtime()
            self.stack.addWidget(self.web)
        self.hub = self._build_hub_widget()
        self.stack.addWidget(self.hub)
        v.addWidget(self.stack, 1)

        self.btn_back.clicked.connect(self._go_back)
        self.btn_fwd.clicked.connect(self._go_forward)
        self.btn_refresh.clicked.connect(self._reload)
        self.btn_hub.clicked.connect(self._show_hub)
        self.btn_close.clicked.connect(self.close)
        self.addr.returnPressed.connect(self._open_from_bar)

        if self.web is not None:
            self.web.loadProgress.connect(self.bar.setValue)
            self.web.titleChanged.connect(self.setWindowTitle)
            self.web.urlChanged.connect(self._on_url_changed)
            self.web.loadFinished.connect(self._on_loaded)

        QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+W'), self, activated=self.close)
        QtWidgets.QShortcut(QtGui.QKeySequence('Alt+Left'), self, activated=self._go_back)
        QtWidgets.QShortcut(QtGui.QKeySequence('Alt+Right'), self, activated=self._go_forward)
        QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+L'), self, activated=self._focus_addr)
        QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+R'), self, activated=self._reload)
        QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_F5), self, activated=self._reload)
        QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_F1), self, activated=self._show_guide)
        QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_Home), self, activated=self._show_guide)
        QtWidgets.QShortcut(QtGui.QKeySequence(QtCore.Qt.Key_F2), self, activated=self._open_virtual_keyboard_contextual)
        QtWidgets.QShortcut(QtGui.QKeySequence('Ctrl+K'), self, activated=self._open_virtual_keyboard_contextual)

    def _configure_webengine_runtime(self):
        if self.web is None or QtWebEngineWidgets is None:
            return
        profile = None
        try:
            profile = self.web.page().profile()
        except Exception:
            profile = None
        if profile is not None:
            try:
                DATA_HOME.mkdir(parents=True, exist_ok=True)
                cache_dir = DATA_HOME / 'webengine-cache'
                storage_dir = DATA_HOME / 'webengine-profile'
                cache_dir.mkdir(parents=True, exist_ok=True)
                storage_dir.mkdir(parents=True, exist_ok=True)
                profile.setCachePath(str(cache_dir))
                profile.setPersistentStoragePath(str(storage_dir))
            except Exception:
                pass
            try:
                profile.setHttpAcceptLanguage('es-ES,es;q=0.9,en-US;q=0.8,en;q=0.7')
            except Exception:
                pass
            try:
                profile.setHttpUserAgent(MODERN_USER_AGENT)
            except Exception:
                pass
            try:
                profile.setPersistentCookiesPolicy(QtWebEngineWidgets.QWebEngineProfile.ForcePersistentCookies)
            except Exception:
                pass
            try:
                profile.setHttpCacheType(QtWebEngineWidgets.QWebEngineProfile.DiskHttpCache)
            except Exception:
                pass
            if self._ultra_low_ram:
                try:
                    profile.setHttpCacheMaximumSize(16 * 1024 * 1024)
                except Exception:
                    pass
        try:
            settings = self.web.settings()
            attrs = (
                ('JavascriptEnabled', True),
                ('LocalStorageEnabled', True),
                ('PluginsEnabled', True),
                ('FullScreenSupportEnabled', True),
                ('ScreenCaptureEnabled', True),
                ('WebGLEnabled', True),
                ('Accelerated2dCanvasEnabled', True),
                ('PlaybackRequiresUserGesture', False),
            )
            for name, value in attrs:
                attr = getattr(QtWebEngineWidgets.QWebEngineSettings, name, None)
                if attr is not None:
                    settings.setAttribute(attr, bool(value))
        except Exception:
            pass

    def _recent_messages_text(self):
        arr = safe_read(SOCIAL_MESSAGES_FILE, [])
        if not isinstance(arr, list) or not arr:
            return 'No recent messages.'
        out = []
        for i, item in enumerate(arr[:16], 1):
            if isinstance(item, dict):
                out.append(f"{i:02d}. {item.get('from', 'Unknown')}: {item.get('text', '')}")
            else:
                out.append(f'{i:02d}. {item}')
        return '\n'.join(out)

    def _menu_message(self, title, text):
        d = QtWidgets.QDialog(self)
        d.setWindowTitle(str(title or 'Info'))
        d.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        d.setModal(True)
        d.resize(840, 500)
        d.setStyleSheet('''
            QDialog { background:#d7dce1; border:2px solid rgba(239,244,248,0.78); }
            QLabel#title {
                color:#eef4f8;
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #69717a, stop:1 #505860);
                font-size:28px;
                font-weight:800;
                padding:8px 12px;
            }
            QLabel#body {
                color:#1f2730;
                font-size:22px;
                font-weight:650;
            }
            QListWidget {
                background:#e4e8ec;
                color:#1f252c;
                font-size:30px;
                border:1px solid rgba(76,86,96,0.4);
                outline:none;
            }
            QListWidget::item {
                padding:7px 12px;
                margin:1px 0px;
            }
            QListWidget::item:selected {
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #5abc3e, stop:1 #3e9132);
                color:#f4fff1;
                border:1px solid rgba(249,255,248,0.4);
            }
            QLabel#hint { color:#1f252c; font-size:16px; font-weight:800; }
        ''')
        lay = QtWidgets.QVBoxLayout(d)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        hdr = QtWidgets.QLabel(str(title or 'Info'))
        hdr.setObjectName('title')
        lay.addWidget(hdr, 0)
        body = QtWidgets.QWidget()
        bl = QtWidgets.QVBoxLayout(body)
        bl.setContentsMargins(16, 14, 16, 12)
        bl.setSpacing(10)
        txt = QtWidgets.QLabel(str(text or ''))
        txt.setObjectName('body')
        txt.setWordWrap(True)
        bl.addWidget(txt, 1)
        lw = QtWidgets.QListWidget()
        lw.addItem('OK')
        lw.setCurrentRow(0)
        lw.itemActivated.connect(lambda *_: d.accept())
        bl.addWidget(lw, 0)
        hint = QtWidgets.QLabel('A/ENTER = Select | B/ESC = Back')
        hint.setObjectName('hint')
        bl.addWidget(hint, 0)
        lay.addWidget(body, 1)

        def _key(ev):
            k = ev.key()
            if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
                d.reject()
                return
            if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_A):
                d.accept()
                return
            QtWidgets.QDialog.keyPressEvent(d, ev)

        d.keyPressEvent = _key
        d.exec_()

    def _show_guide(self):
        opts = [
            'Recent Messages',
            'Recent Web',
            'Virtual Keyboard',
            'Toggle Hub',
            'Close Current App',
        ]
        d = QtWidgets.QDialog(self)
        d.setWindowTitle('Xbox Guide')
        d.setModal(True)
        d.resize(700, 420)
        d.setStyleSheet('QDialog{background:#d8dde3;} QListWidget{font-size:24px;font-weight:700;}')
        lay = QtWidgets.QVBoxLayout(d)
        lw = QtWidgets.QListWidget()
        lw.addItems(opts)
        lw.setCurrentRow(0)
        lay.addWidget(lw, 1)
        hint = QtWidgets.QLabel('A/ENTER select | B/ESC back')
        lay.addWidget(hint)
        lw.itemActivated.connect(lambda *_: d.accept())
        if d.exec_() != QtWidgets.QDialog.Accepted:
            return
        cur = lw.currentItem()
        choice = cur.text() if cur else ''
        if choice == 'Close Current App':
            self.close()
        elif choice == 'Toggle Hub':
            self._show_hub()
        elif choice == 'Virtual Keyboard':
            self._open_virtual_keyboard_contextual()
        elif choice == 'Recent Messages':
            self._menu_message('Recent Messages', self._recent_messages_text())
        elif choice == 'Recent Web':
            rec = safe_read(RECENT_FILE, [])
            if not isinstance(rec, list) or not rec:
                self._menu_message('Recent Web', 'No recent web activity.')
            else:
                self._menu_message('Recent Web', '\n'.join(str(x) for x in rec[:20]))

    def _setup_gamepad(self):
        if QtGamepad is None:
            return
        try:
            mgr = QtGamepad.QGamepadManager.instance()
            ids = list(mgr.connectedGamepads())
            if not ids:
                return
            self._gp = QtGamepad.QGamepad(ids[0], self)
            self._gp_timer = QtCore.QTimer(self)
            self._gp_timer.timeout.connect(self._poll_gamepad)
            self._gp_timer.start(95 if self._ultra_low_ram else 75)
        except Exception:
            self._gp = None

    def _gpv(self, name, default=0.0):
        gp = self._gp
        if gp is None:
            return default
        v = getattr(gp, name, None)
        try:
            return v() if callable(v) else v
        except Exception:
            return default

    def _send_key_focus(self, key):
        vk = self._active_virtual_keyboard()
        if vk is not None:
            w = QtWidgets.QApplication.focusWidget() or vk
        elif self.stack.currentWidget() is self.web and self.web is not None:
            self.web.setFocus(QtCore.Qt.OtherFocusReason)
            w = self.web
        else:
            w = QtWidgets.QApplication.focusWidget() or self
        press = QtGui.QKeyEvent(QtCore.QEvent.KeyPress, key, QtCore.Qt.NoModifier)
        rel = QtGui.QKeyEvent(QtCore.QEvent.KeyRelease, key, QtCore.Qt.NoModifier)
        QtWidgets.QApplication.postEvent(w, press)
        QtWidgets.QApplication.postEvent(w, rel)

    def _active_virtual_keyboard(self):
        w = QtWidgets.QApplication.activeModalWidget()
        if isinstance(w, VirtualKeyboardDialog) and bool(w.isVisible()):
            return w
        for tw in QtWidgets.QApplication.topLevelWidgets():
            if isinstance(tw, VirtualKeyboardDialog) and bool(tw.isVisible()):
                return tw
        return None

    def _poll_gamepad(self):
        gp = self._gp
        if gp is None:
            return
        cur = {
            'left': bool(self._gpv('buttonLeft', False)) or float(self._gpv('axisLeftX', 0.0)) < -0.6,
            'right': bool(self._gpv('buttonRight', False)) or float(self._gpv('axisLeftX', 0.0)) > 0.6,
            'up': bool(self._gpv('buttonUp', False)) or float(self._gpv('axisLeftY', 0.0)) < -0.6,
            'down': bool(self._gpv('buttonDown', False)) or float(self._gpv('axisLeftY', 0.0)) > 0.6,
            'a': bool(self._gpv('buttonA', False)),
            'b': bool(self._gpv('buttonB', False)),
            'x': bool(self._gpv('buttonX', False)),
            'y': bool(self._gpv('buttonY', False)),
            'guide': bool(self._gpv('buttonGuide', False)),
            'lb': bool(self._gpv('buttonL1', False)),
            'rb': bool(self._gpv('buttonR1', False)),
        }

        def pressed(name):
            return cur.get(name, False) and not self._gp_prev.get(name, False)

        vk = self._active_virtual_keyboard()
        if vk is not None:
            if pressed('guide') or pressed('b'):
                self._send_key_focus(QtCore.Qt.Key_Escape)
            elif pressed('a'):
                self._send_key_focus(QtCore.Qt.Key_Return)
            elif pressed('y'):
                self._send_key_focus(QtCore.Qt.Key_Space)
            elif pressed('x'):
                self._send_key_focus(QtCore.Qt.Key_Backspace)
            elif pressed('left'):
                self._send_key_focus(QtCore.Qt.Key_Left)
            elif pressed('right'):
                self._send_key_focus(QtCore.Qt.Key_Right)
            elif pressed('up'):
                self._send_key_focus(QtCore.Qt.Key_Up)
            elif pressed('down'):
                self._send_key_focus(QtCore.Qt.Key_Down)
            self._gp_prev = cur
            return

        if pressed('guide'):
            self._show_guide()
        elif pressed('x'):
            self._open_virtual_keyboard_contextual()
        elif pressed('b'):
            if self.stack.currentWidget() is self.hub:
                self.close()
            else:
                self._go_back()
        elif pressed('lb'):
            self._go_back()
        elif pressed('rb'):
            self._go_forward()
        elif pressed('a'):
            if self.stack.currentWidget() is self.hub:
                self._send_key_focus(QtCore.Qt.Key_Return)
            else:
                self._open_keyboard_if_web_editable()
        elif pressed('y'):
            if self.stack.currentWidget() is self.hub:
                self._focus_addr_with_keyboard()
            else:
                self._send_key_focus(QtCore.Qt.Key_Tab)
                self._auto_open_keyboard_if_web_editable(140)
        else:
            now = time.monotonic()
            directions = (
                ('left', QtCore.Qt.Key_Left),
                ('right', QtCore.Qt.Key_Right),
                ('up', QtCore.Qt.Key_Up),
                ('down', QtCore.Qt.Key_Down),
            )
            for name, key in directions:
                if not cur.get(name, False):
                    self._gp_repeat_at.pop(name, None)
                    continue
                repeat_at = self._gp_repeat_at.get(name, 0.0)
                if pressed(name):
                    self._send_key_focus(key)
                    self._gp_repeat_at[name] = now + 0.34
                    break
                if now >= repeat_at:
                    self._send_key_focus(key)
                    self._gp_repeat_at[name] = now + 0.11
                    break
        self._gp_prev = cur

    def _focus_addr(self):
        self.addr.setFocus(QtCore.Qt.OtherFocusReason)
        self.addr.selectAll()

    def _focus_addr_with_keyboard(self):
        self._focus_addr()
        self._open_virtual_keyboard_for_addr()

    def _open_virtual_keyboard_for_addr(self):
        if self._kbd_opening:
            return
        if (time.monotonic() - float(self._kbd_last_close)) < 0.35:
            return
        self._kbd_opening = True
        try:
            d = VirtualKeyboardDialog(self.addr.text(), self)
            if d.exec_() == QtWidgets.QDialog.Accepted:
                txt = d.text()
                self.addr.setText(txt)
                if txt.strip():
                    self._open_from_bar()
        finally:
            self._kbd_last_close = time.monotonic()
            self._kbd_opening = False

    def _inject_text_into_page(self, text):
        if self.web is None:
            return
        payload = json.dumps(str(text or ''))
        js = f"""
(() => {{
  const deepActive = (root) => {{
    let el = root && root.activeElement ? root.activeElement : null;
    let guard = 0;
    while (el && el.shadowRoot && el.shadowRoot.activeElement && guard < 8) {{
      el = el.shadowRoot.activeElement;
      guard += 1;
    }}
    return el;
  }};
  const el = deepActive(document);
  if (!el) return false;
  const tag = (el.tagName || '').toLowerCase();
  const tp = (el.type || '').toLowerCase();
  const editable = el.isContentEditable || tag === 'textarea' ||
    (tag === 'input' && !['button','submit','checkbox','radio','range','color','file','image','reset','hidden'].includes(tp));
  if (el.readOnly || el.disabled) return false;
  if (!editable) return false;
  const txt = {payload};
  el.focus();
  if (el.isContentEditable) {{
    try {{
      document.execCommand('selectAll', false, null);
      document.execCommand('insertText', false, txt);
    }} catch (_e) {{
      el.textContent = txt;
    }}
  }} else {{
    const proto = tag === 'textarea'
      ? (window.HTMLTextAreaElement && window.HTMLTextAreaElement.prototype)
      : (window.HTMLInputElement && window.HTMLInputElement.prototype);
    const desc = proto ? Object.getOwnPropertyDescriptor(proto, 'value') : null;
    if (desc && typeof desc.set === 'function') {{
      desc.set.call(el, txt);
    }} else {{
      el.value = txt;
    }}
  }}
  try {{
    el.dispatchEvent(new InputEvent('input', {{ bubbles: true, composed: true, data: txt, inputType: 'insertText' }}));
  }} catch (_e) {{
    el.dispatchEvent(new Event('input', {{ bubbles: true, composed: true }}));
  }}
  el.dispatchEvent(new Event('change', {{ bubbles: true, composed: true }}));
  return true;
}})();
"""
        self.web.page().runJavaScript(js)
        self.web.setFocus(QtCore.Qt.OtherFocusReason)

    def _forward_enter_to_web(self):
        if self.web is None:
            return
        self._skip_web_return_once = 1
        press = QtGui.QKeyEvent(QtCore.QEvent.KeyPress, QtCore.Qt.Key_Return, QtCore.Qt.NoModifier)
        rel = QtGui.QKeyEvent(QtCore.QEvent.KeyRelease, QtCore.Qt.Key_Return, QtCore.Qt.NoModifier)
        QtWidgets.QApplication.postEvent(self.web, press)
        QtWidgets.QApplication.postEvent(self.web, rel)

    def _probe_web_editable(self, callback):
        if self.web is None:
            try:
                callback(False, '')
            except Exception:
                pass
            return
        if self._web_edit_probe_pending:
            return
        self._web_edit_probe_pending = True
        probe = """
(() => {
  const deepActive = (root) => {
    let el = root && root.activeElement ? root.activeElement : null;
    let guard = 0;
    while (el && el.shadowRoot && el.shadowRoot.activeElement && guard < 8) {
      el = el.shadowRoot.activeElement;
      guard += 1;
    }
    return el;
  };
  const el = deepActive(document);
  if (!el) return { editable: false, value: '' };
  const tag = (el.tagName || '').toLowerCase();
  const tp = (el.type || '').toLowerCase();
  const editable = !el.readOnly && !el.disabled && (
    el.isContentEditable ||
    tag === 'textarea' ||
    (tag === 'input' && !['button','submit','checkbox','radio','range','color','file','image','reset','hidden'].includes(tp))
  );
  let value = '';
  if (editable) {
    if (el.isContentEditable) value = el.innerText || el.textContent || '';
    else value = el.value || '';
  }
  return { editable: !!editable, value: String(value || '') };
})();
"""
        def _cb(result):
            self._web_edit_probe_pending = False
            editable = False
            value = ''
            if isinstance(result, dict):
                editable = bool(result.get('editable', False))
                value = str(result.get('value', '') or '')
            else:
                editable = bool(result)
            try:
                callback(editable, value)
            except Exception:
                pass
        try:
            self.web.page().runJavaScript(probe, _cb)
        except Exception:
            self._web_edit_probe_pending = False
            try:
                callback(False, '')
            except Exception:
                pass

    def _auto_open_keyboard_if_web_editable(self, delay_ms=120):
        if self.web is None:
            return
        if self._active_virtual_keyboard() is not None:
            return
        try:
            delay = max(0, int(delay_ms))
        except Exception:
            delay = 120
        def _probe_and_open():
            if self._active_virtual_keyboard() is not None:
                return
            self._probe_web_editable(lambda editable, value: editable and self._open_virtual_keyboard_for_web(value))
        if delay <= 0:
            _probe_and_open()
            return
        QtCore.QTimer.singleShot(delay, _probe_and_open)

    def _open_keyboard_if_web_editable(self):
        if self.web is None:
            return
        def cb(editable, value):
            if bool(editable):
                self._open_virtual_keyboard_for_web(value)
            else:
                self._forward_enter_to_web()
        self._probe_web_editable(cb)

    def _open_virtual_keyboard_for_web(self, initial_text=''):
        if self.web is None:
            return
        if self._active_virtual_keyboard() is not None:
            return
        if self._kbd_opening:
            return
        if (time.monotonic() - float(self._kbd_last_close)) < 0.35:
            return
        self._kbd_opening = True
        d = VirtualKeyboardDialog(str(initial_text or ''), self)
        try:
            if d.exec_() == QtWidgets.QDialog.Accepted:
                txt = d.text()
                self._inject_text_into_page(txt)
        finally:
            self._kbd_last_close = time.monotonic()
            self._kbd_opening = False

    def _open_virtual_keyboard_contextual(self):
        if self.stack.currentWidget() is self.hub:
            self._open_virtual_keyboard_for_addr()
        else:
            self._open_virtual_keyboard_for_web()

    def eventFilter(self, obj, event):
        if obj is self.web:
            if event.type() == QtCore.QEvent.KeyPress:
                if event.key() in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter) and self._skip_web_return_once > 0:
                    self._skip_web_return_once -= 1
        return super().eventFilter(obj, event)

    def _build_hub_widget(self):
        hub = QtWidgets.QWidget()
        hub.setObjectName('hub')
        v = QtWidgets.QVBoxLayout(hub)
        v.setContentsMargins(16, 14, 16, 12)
        v.setSpacing(8)
        ttl = QtWidgets.QLabel('Web Hub')
        ttl.setObjectName('hubtitle')
        v.addWidget(ttl)
        grid = QtWidgets.QGridLayout()
        grid.setHorizontalSpacing(10)
        grid.setVerticalSpacing(8)
        self.fav_list = QtWidgets.QListWidget()
        self.recent_list = QtWidgets.QListWidget()
        self.featured_list = QtWidgets.QListWidget()
        for lw in (self.fav_list, self.recent_list, self.featured_list):
            lw.setObjectName('cards')
            lw.itemActivated.connect(self._open_card)
            lw.itemDoubleClicked.connect(self._open_card)
            lw.setMinimumHeight(210)
        grid.addWidget(self._section('Favorites', self.fav_list), 0, 0)
        grid.addWidget(self._section('Recent', self.recent_list), 0, 1)
        grid.addWidget(self._section('Featured', self.featured_list), 0, 2)
        v.addLayout(grid, 1)
        hint = QtWidgets.QLabel('A/ENTER open | Y/TAB focus | X/F2 keyboard | LB/RB back/next | F1 guide | B/ESC close')
        hint.setObjectName('hint')
        v.addWidget(hint)
        return hub

    def _section(self, title, body):
        w = QtWidgets.QWidget()
        l = QtWidgets.QVBoxLayout(w)
        l.setContentsMargins(0, 0, 0, 0)
        l.setSpacing(4)
        t = QtWidgets.QLabel(title)
        t.setObjectName('sec')
        l.addWidget(t)
        l.addWidget(body, 1)
        return w

    def _load_hub_lists(self):
        defaults = [
            'https://www.xbox.com',
            'https://www.youtube.com',
            'https://news.ycombinator.com',
            'https://www.github.com',
            'https://www.reddit.com/r/linux_gaming',
        ]
        favs = safe_read(FAV_FILE, defaults)
        if not isinstance(favs, list) or not favs:
            favs = defaults
        safe_write(FAV_FILE, favs[:20])
        self.fav_list.clear()
        for u in favs[:20]:
            self.fav_list.addItem(str(u))
        rec = safe_read(RECENT_FILE, [])
        self.recent_list.clear()
        for u in rec[:20]:
            self.recent_list.addItem(str(u))
        self.featured_list.clear()
        featured = [
            'https://www.xbox.com/en-US/games',
            'https://store.steampowered.com',
            'https://www.gog.com',
            'https://www.retroarch.com',
            'https://www.duckduckgo.com',
        ]
        for u in featured:
            self.featured_list.addItem(u)

    def _remember_recent(self, url):
        u = str(url or '').strip()
        if not u or u.startswith('about:'):
            return
        rec = safe_read(RECENT_FILE, [])
        if not isinstance(rec, list):
            rec = []
        rec = [x for x in rec if str(x) != u]
        rec.insert(0, u)
        safe_write(RECENT_FILE, rec[:MAX_RECENT])
        self._load_hub_lists()

    def _open_card(self, item):
        if item is None:
            return
        self.open_url(item.text())

    def _show_hub(self):
        if self.stack.currentWidget() is self.hub:
            if self.web is not None:
                self.stack.setCurrentWidget(self.web)
            return
        self._load_hub_lists()
        self.stack.setCurrentWidget(self.hub)

    def _open_from_bar(self):
        self.open_url(self.addr.text())

    def open_url(self, raw):
        url = normalize_url(raw)
        url = unwrap_supported_browser_redirect(url)
        self.addr.setText(url)
        if self.web is None:
            return
        self.stack.setCurrentWidget(self.web)
        self.web.load(QtCore.QUrl(url))

    def _on_url_changed(self, qurl):
        s = qurl.toString()
        self.addr.setText(unwrap_supported_browser_redirect(s))

    def _on_loaded(self, ok):
        if ok and self.web is not None:
            current = self.web.url().toString()
            fixed = unwrap_supported_browser_redirect(current)
            if fixed and fixed != current:
                self.open_url(fixed)
                return
            self._remember_recent(current)
            self.web.setFocus(QtCore.Qt.OtherFocusReason)

    def _go_back(self):
        if self.web is not None:
            self.web.back()

    def _browser_back_or_close(self):
        if self.stack.currentWidget() is self.hub:
            self.close()
        elif self.web is not None and self.web.history().canGoBack():
            self._go_back()
        else:
            self.close()

    def _go_forward(self):
        if self.web is not None:
            self.web.forward()

    def _reload(self):
        if self.web is not None:
            self.web.reload()

    def showEvent(self, e):
        super().showEvent(e)
        if self.kiosk:
            try:
                self.showFullScreen()
            except Exception:
                pass

    def closeEvent(self, e):
        try:
            if self._gp_timer is not None:
                self._gp_timer.stop()
        except Exception:
            pass
        try:
            if self.web is not None:
                self.web.stop()
        except Exception:
            pass
        super().closeEvent(e)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--mode', choices=['hub', 'kiosk', 'normal'], default='hub')
    parser.add_argument('url', nargs='?', default='https://www.xbox.com')
    args = parser.parse_args()
    ultra_low_ram = ultra_low_ram_mode()
    attr = getattr(QtCore.Qt, 'AA_CompressHighFrequencyEvents', None)
    if attr is not None:
        try:
            QtCore.QCoreApplication.setAttribute(attr, True)
        except Exception:
            pass
    app = QtWidgets.QApplication(sys.argv)
    if ultra_low_ram:
        try:
            QtGui.QPixmapCache.setCacheLimit(4096)
        except Exception:
            pass
    fullscreen_mode = args.mode in ('hub', 'kiosk')
    w = WebHub(url=args.url, kiosk=fullscreen_mode)
    if fullscreen_mode:
        try:
            w.showFullScreen()
        except Exception:
            try:
                w.showMaximized()
            except Exception:
                w.show()
    else:
        w.show()
    sys.exit(app.exec_())


if __name__ == '__main__':
    main()
