    cat > "$BIN_DIR/xui_global_guide.py" <<'PY'
#!/usr/bin/env python3
import os
import fcntl
import logging
import signal
import socket
import subprocess
import sys
import time
from pathlib import Path
from PyQt5 import QtCore, QtGui, QtWidgets, QtNetwork

DATA = Path.home() / '.xui' / 'data'
PAUSED_FILE = DATA / 'active_paused.pid'
ACTIVE_FILE = DATA / 'active_game.pid'
SOCIAL_FILE = DATA / 'social_messages_recent.json'
RECENT_FILE = DATA / 'recent.json'
PROFILE_FILE = DATA / 'profile.json'
REDEEM_FILE = DATA / 'redeemed_codes.json'
LOCK_FILE = DATA / 'guide_global.lock'
LOCK_SOCKET = DATA / 'guide_global.sock'
CLOSE_SCRIPT = str(Path.home() / '.xui' / 'bin' / 'xui_close_active_app.sh')
XUI_BIN = Path.home() / '.xui' / 'bin'
SOCIAL_CHAT_APP = XUI_BIN / 'xui_social_chat.py'
PYRUN = XUI_BIN / 'xui_python.sh'
ASSETS_DIR = Path.home() / '.xui' / 'assets'

SFX = {
    'hover': 'hover.mp3',
    'open': 'open.mp3',
    'select': 'select.mp3',
    'back': 'back.mp3',
    'close': 'close.mp3',
}
SFX_ALIASES = {
    'hover': ['hover.mp3', 'click.mp3'],
    'open': ['open.mp3', 'click.mp3'],
    'select': ['select.mp3', '10. Select A.mp3', 'click.mp3'],
    'back': ['back.mp3', '14. Back.mp3'],
    'close': ['close.mp3', '14. Back.mp3'],
}


def _json_read(path, default):
    try:
        import json
        return json.loads(Path(path).read_text(encoding='utf-8', errors='ignore'))
    except Exception:
        return default


def _json_write(path, value):
    try:
        import json
        Path(path).write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding='utf-8')
        return True
    except Exception:
        return False


def _profile_gamertag():
    prof = _json_read(PROFILE_FILE, {})
    if isinstance(prof, dict):
        gt = str(prof.get('gamertag', '')).strip()
        if gt:
            return gt
    return 'Player1'


def _cmdline_of(pid):
    try:
        return Path(f'/proc/{int(pid)}/cmdline').read_text(encoding='utf-8', errors='ignore').replace('\x00', ' ').lower()
    except Exception:
        return ''


def _is_dashboard_pid(pid):
    cl = _cmdline_of(pid)
    return any(t in cl for t in ('pyqt_dashboard_improved.py', 'xui-dashboard.service', 'xui_startup_and_dashboard', 'xui dashboard'))


def _active_window_pid():
    try:
        wid = subprocess.check_output(['xdotool', 'getactivewindow'], text=True, stderr=subprocess.DEVNULL).strip()
        if not wid:
            return None
        pid = subprocess.check_output(['xdotool', 'getwindowpid', wid], text=True, stderr=subprocess.DEVNULL).strip()
        return int(pid) if pid else None
    except Exception:
        return None


def _active_window_id():
    try:
        wid = subprocess.check_output(['xdotool', 'getactivewindow'], text=True, stderr=subprocess.DEVNULL).strip()
        return int(wid) if wid else None
    except Exception:
        return None


def _session_display():
    if os.environ.get('DISPLAY') or os.environ.get('WAYLAND_DISPLAY'):
        return True
    return any(Path(f'/tmp/.X11-unix/X{idx}').exists() for idx in range(10))


def _forward_to_existing():
    if not LOCK_SOCKET.exists():
        return False
    client = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    try:
        client.settimeout(1.0)
        client.connect(str(LOCK_SOCKET))
        client.sendall(b'toggle\n')
        return client.recv(16).strip() == b'ok'
    except OSError:
        return False
    finally:
        client.close()


def _open_global_guide():
    if _forward_to_existing():
        return True
    if not _session_display():
        logging.error('cannot open global Guide without DISPLAY/WAYLAND_DISPLAY')
        return False
    launcher = XUI_BIN / 'xui_global_guide.sh'
    if not launcher.is_file():
        logging.error('global guide launcher missing: %s', launcher)
        return False
    try:
        subprocess.Popen(
            [str(launcher)],
            env=os.environ.copy(),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
        return True
    except Exception:
        logging.exception('cannot start global guide')
        return False


def _pick_target_pid():
    try:
        if ACTIVE_FILE.exists():
            pid = int((ACTIVE_FILE.read_text(encoding='utf-8', errors='ignore') or '0').strip() or '0')
            if pid > 1 and not _is_dashboard_pid(pid):
                return pid
    except Exception:
        pass
    pid = _active_window_pid()
    if pid and pid > 1 and not _is_dashboard_pid(pid):
        return pid
    return None


def _pick_target_window():
    try:
        if ACTIVE_FILE.exists():
            pid = int((ACTIVE_FILE.read_text(encoding='utf-8', errors='ignore') or '0').strip() or '0')
            if pid > 1 and not _is_dashboard_pid(pid):
                ids = subprocess.check_output(
                    ['xdotool', 'search', '--onlyvisible', '--pid', str(pid)],
                    text=True, stderr=subprocess.DEVNULL,
                ).splitlines()
                if ids:
                    return int(ids[0])
    except Exception:
        pass
    return _active_window_id()


def _remember_target_window():
    wid = _pick_target_window()
    if wid and wid > 0:
        DATA.mkdir(parents=True, exist_ok=True)
        (DATA / 'guide_target_window.id').write_text(str(wid), encoding='utf-8')
        return wid
    return None


def _pause_pid(pid):
    try:
        os.kill(int(pid), signal.SIGSTOP)
        DATA.mkdir(parents=True, exist_ok=True)
        PAUSED_FILE.write_text(str(int(pid)), encoding='utf-8')
        return True
    except Exception:
        return False


def _resume_paused():
    if not PAUSED_FILE.exists():
        return
    try:
        pid = int((PAUSED_FILE.read_text(encoding='utf-8', errors='ignore') or '0').strip() or '0')
    except Exception:
        pid = 0
    try:
        if pid > 1:
            os.kill(pid, signal.SIGCONT)
    except Exception:
        pass
    try:
        PAUSED_FILE.unlink()
    except Exception:
        pass


def _activate_dashboard():
    cmd = (
        '/bin/sh -lc '
        '"xdotool search --name \'XUI - Xbox 360 Style\' windowactivate 2>/dev/null '
        '|| xdotool search --name \'XUI\' windowactivate 2>/dev/null '
        '|| xdotool search --name \'dashboard\' windowactivate 2>/dev/null"'
    )
    rc = subprocess.call(cmd, shell=True)
    return rc == 0


def _recent_text():
    arr = _json_read(RECENT_FILE, [])
    if not isinstance(arr, list) or not arr:
        return 'No hay actividad reciente todavia.'
    lines = []
    for i, item in enumerate(arr[:12], 1):
        lines.append(f'{i:02d}. {item}')
    return '\n'.join(lines)


def _messages_text():
    arr = _json_read(SOCIAL_FILE, [])
    if not isinstance(arr, list) or not arr:
        return 'No hay mensajes recientes todavia.'
    lines = []
    for i, item in enumerate(arr[:18], 1):
        if isinstance(item, dict):
            who = str(item.get('from', 'Unknown'))
            txt = str(item.get('text', ''))
            lines.append(f'{i:02d}. {who}: {txt}')
        else:
            lines.append(f'{i:02d}. {item}')
    return '\n'.join(lines)


def _downloads_text():
    cmd = (
        "/bin/sh -c \"ps -eo comm,args 2>/dev/null | "
        "egrep -i 'steam|flatpak|apt|dnf|pacman|aria2c|transmission|qbittorrent|wget|curl' "
        "| grep -v egrep | head -n 12\""
    )
    out = subprocess.getoutput(cmd).strip()
    if out:
        return f'Procesos de descarga detectados:\n{out}'
    return 'No se detectan descargas activas.'


class TextPromptDialog(QtWidgets.QDialog):
    def __init__(self, title, label, text='', parent=None):
        super().__init__(parent)
        self._accepted = False
        self.setWindowTitle(str(title or 'Input'))
        self.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
        self.setModal(True)
        self.resize(860, 460)
        self.setStyleSheet('''
            QDialog { background:#d7dce1; border:2px solid rgba(239,244,248,0.78); }
            QLabel#title {
                color:#eef4f8;
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #69717a, stop:1 #505860);
                font-size:30px;
                font-weight:800;
                padding:8px 12px;
            }
            QLabel#label { color:#1f2730; font-size:22px; font-weight:650; }
            QLineEdit {
                background:#ffffff;
                border:1px solid #8ea2b6;
                color:#1f2730;
                font-size:22px;
                font-weight:700;
                padding:8px;
            }
            QListWidget {
                background:#e4e8ec;
                color:#1f252c;
                font-size:29px;
                border:1px solid rgba(76,86,96,0.4);
                outline:none;
            }
            QListWidget::item {
                padding:7px 12px;
                margin:1px 0px;
            }
            QListWidget::item:selected {
                background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #5abc3e, stop:1 #3e9132);
                color:#f4fff1;
                border:1px solid rgba(249,255,248,0.4);
            }
            QLabel#hint { color:#1f252c; font-size:16px; font-weight:800; }
        ''')
        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)
        hdr = QtWidgets.QLabel(str(title or 'Input'))
        hdr.setObjectName('title')
        root.addWidget(hdr, 0)
        body = QtWidgets.QWidget()
        bl = QtWidgets.QVBoxLayout(body)
        bl.setContentsMargins(16, 14, 16, 12)
        bl.setSpacing(10)
        lbl = QtWidgets.QLabel(str(label or 'Value:'))
        lbl.setObjectName('label')
        bl.addWidget(lbl, 0)
        self.edit = QtWidgets.QLineEdit(str(text or ''))
        self.edit.setFocus(QtCore.Qt.OtherFocusReason)
        bl.addWidget(self.edit, 0)
        self.listw = QtWidgets.QListWidget()
        self.listw.addItems(['OK', 'Cancel'])
        self.listw.setCurrentRow(0)
        self.listw.itemActivated.connect(self._activate_current)
        bl.addWidget(self.listw, 0)
        hint = QtWidgets.QLabel('A/ENTER = Select | B/ESC = Back')
        hint.setObjectName('hint')
        bl.addWidget(hint, 0)
        root.addWidget(body, 1)

    def _activate_current(self, *_):
        it = self.listw.currentItem()
        choice = str(it.text()).strip().lower() if it is not None else 'cancel'
        if choice == 'ok':
            self._accepted = True
            self.accept()
            return
        self._accepted = False
        self.reject()

    def value(self):
        return str(self.edit.text() or '')

    def accepted_value(self):
        return bool(self._accepted)

    def keyPressEvent(self, e):
        k = e.key()
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
            self._accepted = False
            self.reject()
            return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_A):
            self._activate_current()
            return
        super().keyPressEvent(e)


def _redeem_code(parent):
    d = TextPromptDialog('Canjear codigo', 'Introduce tu codigo:', '', parent)
    if d.exec_() != QtWidgets.QDialog.Accepted or not d.accepted_value():
        return None
    code = d.value()
    code = ''.join(ch for ch in str(code).upper() if ch.isalnum() or ch == '-')
    if not code:
        return 'Codigo no valido.'
    redeemed = _json_read(REDEEM_FILE, [])
    if not isinstance(redeemed, list):
        redeemed = []
    if code in redeemed:
        return f'El codigo {code} ya fue usado en este perfil.'
    redeemed.append(code)
    if not _json_write(REDEEM_FILE, redeemed):
        return 'No se pudo guardar el codigo.'
    return f'Codigo {code} guardado correctamente.'


def _close_session():
    prof = _json_read(PROFILE_FILE, {})
    if not isinstance(prof, dict):
        prof = {}
    prof['signed_in'] = False
    _json_write(PROFILE_FILE, prof)


def _pick_existing_sound(candidates):
    if not candidates:
        return None
    key = tuple(str(fn) for fn in candidates if fn)
    cache = getattr(_pick_existing_sound, '_cache', {})
    if key:
        cached = cache.get(key)
        if cached:
            cp = Path(cached)
            if cp.exists():
                return cp
    search_dirs = [
        ASSETS_DIR / 'SONIDOS',
        ASSETS_DIR / 'sonidos',
        Path.home() / '.xui' / 'SONIDOS',
        Path.home() / '.xui' / 'sonidos',
        Path.home() / '.xui' / 'user_sounds',
        ASSETS_DIR,
    ]
    for fn in candidates:
        if not fn:
            continue
        for d in search_dirs:
            p = d / str(fn)
            if p.exists():
                if key:
                    cache[key] = str(p)
                    _pick_existing_sound._cache = cache
                return p
    return None


def _play_sfx(name):
    key = str(name or '').strip()
    if not key:
        return
    if key == 'hover':
        now = time.monotonic()
        last = float(getattr(_play_sfx, '_last_hover_at', 0.0))
        if (now - last) < 0.08:
            return
        _play_sfx._last_hover_at = now

    candidates = []
    base = SFX.get(key)
    if base:
        candidates.append(base)
    candidates.extend(SFX_ALIASES.get(key, []))
    snd = _pick_existing_sound(candidates)
    if snd is None:
        return

    players = getattr(_play_sfx, '_players', None)
    if players is None:
        players = []
        if shutil.which('mpv'):
            players.append(('mpv', ['--really-quiet', '--no-terminal', '--no-video']))
        if shutil.which('ffplay'):
            players.append(('ffplay', ['-nodisp', '-autoexit', '-loglevel', 'quiet']))
        if shutil.which('paplay'):
            players.append(('paplay', []))
        if shutil.which('aplay'):
            players.append(('aplay', ['-q']))
        _play_sfx._players = players

    for bin_name, args in players:
        try:
            subprocess.Popen([bin_name, *args, str(snd)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            return
        except Exception:
            continue


class Guide(QtWidgets.QDialog):
    def __init__(self, gamertag='Player1', paused_pid=None, previous_window=None):
        super().__init__()
        self.paused_pid = paused_pid
        self.previous_window = previous_window
        self.gamertag = str(gamertag or 'Player1')
        self.action = ''
        self._open_anim = None
        self._last_row = 0
        self._target_was_fullscreen = False
        self._topmost_timer = QtCore.QTimer(self)
        self._topmost_timer.setInterval(250)
        self._topmost_timer.timeout.connect(self._maintain_overlay_topmost)
        self.setWindowTitle('Xbox Guide')
        self.setWindowFlags(
            QtCore.Qt.Dialog
            | QtCore.Qt.FramelessWindowHint
            | QtCore.Qt.WindowStaysOnTopHint
        )
        self.setAttribute(QtCore.Qt.WA_TranslucentBackground, True)
        self.setModal(False)
        screen = QtWidgets.QApplication.primaryScreen()
        if screen is not None:
            self.setGeometry(screen.geometry())
        else:
            self.resize(1060, 560)
        self.setWindowState(self.windowState() | QtCore.Qt.WindowFullScreen)
        self.setStyleSheet('''
            QDialog { background:rgba(13, 19, 22, 0.78); }
            QFrame#xguide_panel {
                background:qlineargradient(x1:0,y1:0,x2:0,y2:1, stop:0 #727b80, stop:1 #a8afb2);
