        for txt in ('Inicio de Xbox', 'Manage Storage', 'System Settings', 'Close Game', 'Sign Out'):
            b = QtWidgets.QPushButton(txt)
            b.setObjectName('xguide_action_btn')
            b.clicked.connect(lambda _=False, action=txt: self._accept_action(action))
            actions_l.addWidget(b)
        actions_l.addStretch(1)
        body.addWidget(actions, 3)
        for button in actions.findChildren(QtWidgets.QPushButton):
            button.setFocusPolicy(QtCore.Qt.NoFocus)
            button.installEventFilter(self)
        root.addLayout(body, 1)

        hint = QtWidgets.QLabel('<font color="#49b93e">A Select</font>   <font color="#cf2d2d">B Back</font>   <font color="#2b7fd8">X Sign Out</font>   <font color="#ddb126">Y Inicio de Xbox</font>')
        hint.setObjectName('xguide_hint')
        root.addWidget(hint)

        self._clock = QtCore.QTimer(self)
        self._clock.timeout.connect(self._refresh_meta)
        self._clock.start(1000)
        self._refresh_meta()

    def _on_row_changed(self, row):
        try:
            row = int(row)
        except Exception:
            return
        if row != int(self._last_row):
            self._last_row = row
            _play_sfx('hover')

    def _refresh_meta(self):
        now = QtCore.QDateTime.currentDateTime().toString('HH:mm')
        pid_meta = f' PID:{self.paused_pid}' if self.paused_pid else ''
        self.meta.setText(f'{self.gamertag}    {now}{pid_meta}')

    def _accept_current(self, *_):
        it = self.listw.currentItem()
        if it is None:
            return
        self.action = it.text()
        _play_sfx('select')
        self.accept()

    def _accept_action(self, action):
        self.action = str(action or '')
        _play_sfx('select')
        self.accept()

    def showEvent(self, e):
        super().showEvent(e)
        scr = QtWidgets.QApplication.screenAt(QtGui.QCursor.pos()) if hasattr(QtWidgets.QApplication, 'screenAt') else None
        if scr is None:
            scr = QtWidgets.QApplication.primaryScreen()
        if scr is not None:
            g = scr.geometry()
            if self.geometry() != g:
                self.setGeometry(g)
        self.raise_()
        _play_sfx('open')
        self._refresh_meta()
        self._animate_open()

    def eventFilter(self, watched, event):
        if event.type() == QtCore.QEvent.KeyPress:
            key = event.key()
            if key in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
                self.action = ''
                _play_sfx('back')
                self.hide_overlay()
                return True
            if key in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_A):
                if self.listw.currentRow() < 0:
                    self.listw.setCurrentRow(0)
                self._accept_current()
                return True
            if key in (QtCore.Qt.Key_X, QtCore.Qt.Key_Space):
                self._accept_action('Close Game')
                return True
            if key in (QtCore.Qt.Key_Y, QtCore.Qt.Key_Tab):
                self.listw.setCurrentRow(min(self.listw.count() - 1, self.listw.currentRow() + 1))
                return True
            if key == QtCore.Qt.Key_Left:
                self._accept_action('Inicio de Xbox')
                return True
            if key == QtCore.Qt.Key_Up:
                self.listw.setCurrentRow(max(0, self.listw.currentRow() - 1))
                return True
            if key == QtCore.Qt.Key_Down:
                self.listw.setCurrentRow(min(self.listw.count() - 1, self.listw.currentRow() + 1))
                return True
        return super().eventFilter(watched, event)

    def toggle_visible(self):
        if self.isVisible():
            self.hide_overlay()
            return
        self.show_overlay()

    def _target_window_has_fullscreen_state(self):
        if not self.previous_window:
            return False
        try:
            result = subprocess.run(
                ['xprop', '-id', str(self.previous_window), '_NET_WM_STATE'],
                capture_output=True, text=True, timeout=1.0, check=False,
            )
            if result.returncode == 0:
                return '_NET_WM_STATE_FULLSCREEN' in result.stdout
        except (OSError, subprocess.SubprocessError):
            pass
        # Xenia's launcher enforces fullscreen; retain that state on systems without xprop.
        try:
            title = subprocess.check_output(
                ['xdotool', 'getwindowname', str(self.previous_window)],
                text=True, stderr=subprocess.DEVNULL, timeout=1.0,
            ).strip().lower()
            return 'xenia' in title
        except (OSError, subprocess.SubprocessError):
            return False

    def _raise_overlay_window(self):
        self.showFullScreen()
        self.raise_()
        self.activateWindow()
        try:
            ids = subprocess.check_output(
                ['xdotool', 'search', '--onlyvisible', '--pid', str(os.getpid())],
                text=True, stderr=subprocess.DEVNULL, timeout=1.0,
            ).splitlines()
            if ids:
                overlay_id = ids[-1]
                subprocess.run(['xdotool', 'windowstate', overlay_id, '--add', 'ABOVE'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
                subprocess.run(['xdotool', 'windowraise', overlay_id], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
                subprocess.run(['xdotool', 'windowactivate', '--sync', overlay_id], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
                if shutil.which('wmctrl'):
                    subprocess.run(['wmctrl', '-ir', overlay_id, '-b', 'add,above,fullscreen'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        except (OSError, subprocess.SubprocessError):
            pass

    def _maintain_overlay_topmost(self):
        if not self.isVisible():
            self._topmost_timer.stop()
            return
        if self.previous_window and self._target_was_fullscreen:
            subprocess.run(
                ['xdotool', 'windowstate', str(self.previous_window), '--remove', 'FULLSCREEN'],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
            )
        self._raise_overlay_window()

    def show_overlay(self):
        # The Guide process may stay alive while hidden; recapture the newly active
        # application on every open instead of returning to the first game forever.
        active_window = _active_window_id()
        if active_window:
            try:
                active_pid = int(subprocess.check_output(
                    ['xdotool', 'getwindowpid', str(active_window)],
                    text=True, stderr=subprocess.DEVNULL, timeout=1.0,
                ).strip() or '0')
            except (OSError, ValueError, subprocess.SubprocessError):
                active_pid = 0
            if active_pid != os.getpid():
                self.previous_window = active_window
                try:
                    (DATA / 'guide_target_window.id').write_text(str(active_window), encoding='utf-8')
                except OSError:
                    pass
        self._target_was_fullscreen = self._target_window_has_fullscreen_state()
        if self._target_was_fullscreen:
            subprocess.run(
                ['xdotool', 'windowstate', str(self.previous_window), '--remove', 'FULLSCREEN'],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
            )
        self._raise_overlay_window()
        self._topmost_timer.start()
        QtCore.QTimer.singleShot(120, self._maintain_overlay_topmost)

    def _restore_target_window(self):
        if not self.previous_window:
            return
        if self._target_was_fullscreen:
            subprocess.run(
                ['xdotool', 'windowstate', str(self.previous_window), '--add', 'FULLSCREEN'],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
            )
        subprocess.run(
            ['xdotool', 'windowmap', str(self.previous_window)],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
        )
        subprocess.run(
            ['xdotool', 'windowactivate', '--sync', str(self.previous_window)],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
        )
        self._target_was_fullscreen = False

    def hide_overlay(self):
        self._topmost_timer.stop()
        self.hide()
        self._restore_target_window()

    def _animate_open(self):
        effect = QtWidgets.QGraphicsOpacityEffect(self)
        self.setGraphicsEffect(effect)
        effect.setOpacity(0.0)
        end_rect = self.geometry()
        start_rect = QtCore.QRect(
            end_rect.x() - max(24, end_rect.width() // 18),
            end_rect.y(),
            end_rect.width(),
            end_rect.height(),
        )
        self.setGeometry(start_rect)
        self._open_anim = QtCore.QParallelAnimationGroup(self)
        fade = QtCore.QPropertyAnimation(effect, b'opacity', self)
        fade.setDuration(190)
        fade.setStartValue(0.0)
        fade.setEndValue(1.0)
        fade.setEasingCurve(QtCore.QEasingCurve.OutCubic)
        slide = QtCore.QPropertyAnimation(self, b'geometry', self)
        slide.setDuration(230)
        slide.setStartValue(start_rect)
        slide.setEndValue(end_rect)
        slide.setEasingCurve(QtCore.QEasingCurve.OutCubic)
        self._open_anim.addAnimation(fade)
        self._open_anim.addAnimation(slide)
        self._open_anim.finished.connect(lambda: self.setGraphicsEffect(None))
        self._open_anim.start(QtCore.QAbstractAnimation.DeleteWhenStopped)

    def keyPressEvent(self, e):
        if e.key() in (QtCore.Qt.Key_Y, QtCore.Qt.Key_Tab):
            self.listw.setCurrentRow(min(self.listw.count() - 1, self.listw.currentRow() + 1))
            return
        if e.key() in (QtCore.Qt.Key_X, QtCore.Qt.Key_Space):
            self.action = 'Close Game'
            _play_sfx('select')
            self.accept()
            return
        if e.key() == QtCore.Qt.Key_Left:
            self.action = 'Inicio de Xbox'
            _play_sfx('select')
            self.accept()
            return
        if e.key() == QtCore.Qt.Key_Right:
            self.listw.setCurrentRow(min(self.listw.count() - 1, self.listw.currentRow() + 1))
            return
        if e.key() in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back):
            self.action = ''
            _play_sfx('back')
            self.hide_overlay()
            return
        if e.key() in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter):
            self._accept_current()
            return
        super().keyPressEvent(e)


def _msg(parent, title, text):
    d = QtWidgets.QDialog(parent)
    d.setWindowTitle(str(title or 'Info'))
    d.setWindowFlags(QtCore.Qt.Dialog | QtCore.Qt.FramelessWindowHint)
    d.setModal(True)
    d.resize(900, 520)
    d.setStyleSheet('''
        QDialog { background:#d7dce1; border:2px solid rgba(239,244,248,0.78); }
        QLabel#title {
            color:#eef4f8;
            background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #69717a, stop:1 #505860);
            font-size:30px;
            font-weight:800;
            padding:8px 12px;
        }
        QLabel#body {
            color:#1f2730;
            font-size:24px;
            font-weight:650;
        }
        QListWidget {
            background:#e4e8ec;
            color:#1f252c;
            font-size:31px;
            border:1px solid rgba(76,86,96,0.4);
            outline:none;
        }
        QListWidget::item {
            padding:7px 12px;
            margin:1px 0px;
        }
        QListWidget::item:selected {
            background:qlineargradient(x1:0,y1:0,x2:1,y2:0, stop:0 #5abc3e, stop:1 #3e9132);
            color:#f4fff1;
            border:1px solid rgba(249,255,248,0.4);
        }
        QLabel#hint { color:#1f252c; font-size:16px; font-weight:800; }
    ''')
    lay = QtWidgets.QVBoxLayout(d)
    lay.setContentsMargins(0, 0, 0, 0)
    lay.setSpacing(0)
    hdr = QtWidgets.QLabel(str(title or 'Info'))
    hdr.setObjectName('title')
    lay.addWidget(hdr, 0)
    body = QtWidgets.QWidget()
    bl = QtWidgets.QVBoxLayout(body)
    bl.setContentsMargins(16, 14, 16, 12)
    bl.setSpacing(10)
    txt = QtWidgets.QLabel(str(text or ''))
    txt.setObjectName('body')
    txt.setWordWrap(True)
    bl.addWidget(txt, 1)
    lw = QtWidgets.QListWidget()
    lw.addItem('OK')
    lw.setCurrentRow(0)
    lw.itemActivated.connect(lambda *_: d.accept())
    bl.addWidget(lw, 0)
    hint = QtWidgets.QLabel('A/ENTER = Select | B/ESC = Back')
    hint.setObjectName('hint')
    bl.addWidget(hint, 0)
    lay.addWidget(body, 1)

    def _key(ev):
        k = ev.key()
        if k in (QtCore.Qt.Key_Escape, QtCore.Qt.Key_Back, QtCore.Qt.Key_B):
            d.reject()
            return
        if k in (QtCore.Qt.Key_Return, QtCore.Qt.Key_Enter, QtCore.Qt.Key_A):
            d.accept()
            return
        QtWidgets.QDialog.keyPressEvent(d, ev)

    d.keyPressEvent = _key
    d.exec_()


def _launch_social_global(parent):
    if not SOCIAL_CHAT_APP.exists():
        _msg(parent, 'Social global', f'No se encontro: {SOCIAL_CHAT_APP}')
        return
    cmd = []
    if PYRUN.exists() and os.access(str(PYRUN), os.X_OK):
        cmd = [str(PYRUN), str(SOCIAL_CHAT_APP)]
    else:
        cmd = ['python3', str(SOCIAL_CHAT_APP)]
    try:
        subprocess.call(cmd)
    except Exception as exc:
        _msg(parent, 'Social global', f'No se pudo abrir Social global:\n{exc}')


def _handle_action(action, parent):
    name = str(action or '').strip()
    if not name:
        if getattr(parent, 'previous_window', None):
            subprocess.run(['xdotool', 'windowactivate', '--sync', str(parent.previous_window)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        return
    if name == 'Xbox Home':
        _activate_dashboard()
        _resume_paused()
        return
    if name == 'Leave Game':
        subprocess.getoutput(f'/bin/sh -c "{CLOSE_SCRIPT}"')
        return
    if name == 'Sign Out':
        _close_session()
        _msg(parent, 'Sesion', 'Sesion cerrada.')
        _activate_dashboard()
        _resume_paused()
        return
    if name == 'Friends':
        _activate_dashboard()
        _resume_paused()
        return
    if name == 'Party':
        _msg(parent, 'Party', 'Party Center available in dashboard social hub.')
        _resume_paused()
        return
    if name == 'Messages':
        _launch_social_global(parent)
        _resume_paused()
        return
    if name == 'Chat':
        _launch_social_global(parent)
        _resume_paused()
        return
    if name == 'Beacons & Activity':
        _activate_dashboard()
        _resume_paused()
        return
    if name == 'Manage Storage':
        _activate_dashboard()
        _resume_paused()
        return
    if name in (
        'Open Tray', 'Video Marketplace', 'YouTube', 'Netflix', 'Twitch',
        'Movie Trailers', 'Music Marketplace', 'System Music',
        'System Settings', 'Account Security', 'Network Setup', 'Family', 'Theme Toggle',
    ):
        _activate_dashboard()
        return
    if name == 'Reciente':
        _msg(parent, 'Reciente', _recent_text())
        _resume_paused()
        return
    if name == 'Mensajes recientes':
        _msg(parent, 'Mensajes recientes', _messages_text())
        _resume_paused()
        return
    if name == 'Social global':
        _launch_social_global(parent)
        _resume_paused()
        return
    if name == 'Descargas activas':
        _msg(parent, 'Descargas activas', _downloads_text())
        _resume_paused()
        return
    if name == 'Canjear codigo':
        res = _redeem_code(parent)
        if res:
            _msg(parent, 'Canjear codigo', res)
        _resume_paused()
        return
    if name == 'Cerrar app actual':
        subprocess.run([CLOSE_SCRIPT], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        return
    if name == 'Close Game':
        subprocess.run([CLOSE_SCRIPT], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        return
    if name == 'Cerrar sesion':
        _close_session()
        _msg(parent, 'Sesion', 'Sesion cerrada.')
        _activate_dashboard()
        return
    if name == 'Logros':
        if _activate_dashboard():
            subprocess.getoutput('/bin/sh -lc "sleep 0.08; xdotool key --clearmodifiers F1 Return >/dev/null 2>&1 || true"')
        return
    if name in ('Premios', 'Mis juegos', 'Configuracion', 'Inicio de Xbox'):
        _activate_dashboard()
        return
    if getattr(parent, 'previous_window', None):
        subprocess.run(['xdotool', 'windowmap', str(parent.previous_window)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        subprocess.run(['xdotool', 'windowactivate', '--sync', str(parent.previous_window)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)


def main():
    DATA.mkdir(parents=True, exist_ok=True)
    if not _session_display():
        print('No graphical session found (DISPLAY/WAYLAND_DISPLAY); cannot show external Guide.', file=sys.stderr)
        return 2
    lock_handle = LOCK_FILE.open('a+')
    try:
        fcntl.flock(lock_handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        # Another launcher may still be creating its IPC socket. Forward once it is ready;
        # if it is already visible, do not start a second Guide process.
        for _ in range(30):
            if _forward_to_existing():
                lock_handle.close()
                return 0
            time.sleep(0.05)
        lock_handle.close()
        return 0
    if _forward_to_existing():
        lock_handle.close()
        return 0
    previous_window = _remember_target_window()
    app = QtWidgets.QApplication(sys.argv)
    app.setApplicationName('XUI Global Guide')
    app.setQuitOnLastWindowClosed(False)
    d = Guide(gamertag=_profile_gamertag(), previous_window=previous_window)
    d.accepted.connect(app.quit)
    server = QtNetwork.QLocalServer(d)
    try:
        # The lock is held, so removing a stale socket cannot disrupt another instance.
        server.removeServer(str(LOCK_SOCKET))
        if not server.listen(str(LOCK_SOCKET)):
            print(f'Cannot listen on Guide IPC socket: {server.errorString()}', file=sys.stderr)
            return 3
        os.chmod(LOCK_SOCKET, 0o600)
    except Exception as exc:
        print(f'Cannot listen on Guide IPC socket: {exc}', file=sys.stderr)
        return 3

    def handle_clients():
        while server.hasPendingConnections():
            client = server.nextPendingConnection()
            if client is None:
                continue
            client.waitForReadyRead(200)
            raw = bytes(client.readAll()).decode('utf-8', errors='ignore').strip().lower()
            if raw == 'toggle':
                d.toggle_visible()
            elif raw == 'up':
                d.listw.setCurrentRow(max(0, d.listw.currentRow() - 1))
            elif raw == 'down':
                d.listw.setCurrentRow(min(d.listw.count() - 1, d.listw.currentRow() + 1))
            elif raw in ('select', 'enter'):
                d._accept_current()
            elif raw == 'back':
                d.action = ''
                d.hide_overlay()
            elif raw == 'tab':
                d.listw.setCurrentRow(min(d.listw.count() - 1, d.listw.currentRow() + 1))
            elif raw == 'closegame':
                d._accept_action('Close Game')
            elif raw == 'home':
                d._accept_action('Inicio de Xbox')
            elif raw == 'right':
                d.listw.setCurrentRow(min(d.listw.count() - 1, d.listw.currentRow() + 1))
            elif raw == 'left':
                d.listw.setCurrentRow(max(0, d.listw.currentRow() - 1))
            elif raw == 'pageup':
                d.listw.setCurrentRow(max(0, d.listw.currentRow() - 5))
            elif raw == 'pagedown':
                d.listw.setCurrentRow(min(d.listw.count() - 1, d.listw.currentRow() + 5))
            client.write(b'ok\n')
            client.flush()
            client.disconnectFromServer()

    server.newConnection.connect(handle_clients)
    d.show_overlay()
    try:
        result = app.exec_()
    finally:
        d.hide()
        d._restore_target_window()
        server.close()
        QtNetwork.QLocalServer.removeServer(str(LOCK_SOCKET))
        lock_handle.close()
    if d.action:
        _handle_action(d.action, d)
    elif previous_window:
        subprocess.run(['xdotool', 'windowmap', str(previous_window)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
        subprocess.run(['xdotool', 'windowactivate', '--sync', str(previous_window)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
    return result


if __name__ == '__main__':
    raise SystemExit(main())
