write_battery_tools(){
        info "Writing battery saver, info, profiles and monitor"

        # Battery saver: reduce frequencies, dim audio, disable wifi/bluetooth
        cat > "$BIN_DIR/xui_battery_saver.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
ACTION=${1:-enable}
STATE_FILE="$HOME/.xui/data/battery_saver_on"

set_cpu_max(){
    val="$1"
    # prefer cpupower if available
    if command -v cpupower >/dev/null 2>&1; then
        cpupower frequency-set -u "${val}Hz" >/dev/null 2>&1 || true
        return
    fi
    for cpu in /sys/devices/system/cpu/cpu[0-9]*; do
        f="$cpu/cpufreq/scaling_max_freq"
        if [ -f "$f" ]; then
            if [ -w "$f" ]; then
                echo "$val" > "$f" || true
            else
                sudo sh -c "echo $val > $f" 2>/dev/null || true
            fi
        fi
    done
}

set_cpu_default_max(){
    local cpu f max_file max_val
    for cpu in /sys/devices/system/cpu/cpu[0-9]*; do
        f="$cpu/cpufreq/scaling_max_freq"
        max_file="$cpu/cpufreq/cpuinfo_max_freq"
        [ -f "$f" ] || continue
        [ -f "$max_file" ] || continue
        max_val="$(cat "$max_file" 2>/dev/null || true)"
        [ -n "$max_val" ] || continue
        if [ -w "$f" ]; then
            echo "$max_val" > "$f" || true
        else
            sudo sh -c "echo $max_val > $f" 2>/dev/null || true
        fi
    done
}

set_brightness_pct(){
    pct=${1:-25}
    # try brightnessctl, xbacklight, sysfs
    if command -v brightnessctl >/dev/null 2>&1; then
        brightnessctl set ${pct}% >/dev/null 2>&1 || true
        return
    fi
    if command -v xbacklight >/dev/null 2>&1; then
        xbacklight -set $pct >/dev/null 2>&1 || true
        return
    fi
    for d in /sys/class/backlight/*; do
        if [ -f "$d/brightness" ] && [ -f "$d/max_brightness" ]; then
            max=$(cat "$d/max_brightness")
            val=$((max * pct / 100))
            if [ -w "$d/brightness" ]; then
                echo "$val" > "$d/brightness" || true
            else
                sudo sh -c "echo $val > $d/brightness" 2>/dev/null || true
            fi
        fi
    done
}

mute_audio(){
    if command -v pactl >/dev/null 2>&1; then
        pactl set-sink-mute @DEFAULT_SINK@ 1 2>/dev/null || true
    elif command -v amixer >/dev/null 2>&1; then
        amixer -D pulse sset Master mute >/dev/null 2>&1 || true
    fi
}

unmute_audio(){
    if command -v pactl >/dev/null 2>&1; then
        pactl set-sink-mute @DEFAULT_SINK@ 0 2>/dev/null || true
    elif command -v amixer >/dev/null 2>&1; then
        amixer -D pulse sset Master unmute >/dev/null 2>&1 || true
    fi
}

disable_net_bt(){
    if command -v nmcli >/dev/null 2>&1; then nmcli radio wifi off >/dev/null 2>&1 || true; fi
    if command -v bluetoothctl >/dev/null 2>&1; then bluetoothctl power off >/dev/null 2>&1 || true; fi
}

enable_net_bt(){
    if command -v nmcli >/dev/null 2>&1; then nmcli radio wifi on >/dev/null 2>&1 || true; fi
    if command -v bluetoothctl >/dev/null 2>&1; then bluetoothctl power on >/dev/null 2>&1 || true; fi
}

case "$ACTION" in
    enable)
        mkdir -p "$(dirname "$STATE_FILE")"
        set_cpu_max 300000 || true
        set_brightness_pct 25 || true
        mute_audio || true
        disable_net_bt || true
        touch "$STATE_FILE" || true
        echo "Battery saver enabled"
        ;;
    disable)
        set_cpu_default_max || true
        set_brightness_pct 85 || true
        unmute_audio || true
        enable_net_bt || true
        rm -f "$STATE_FILE" || true
        echo "Battery saver disabled"
        ;;
    toggle)
        if [ -f "$STATE_FILE" ]; then exec "$0" disable; else exec "$0" enable; fi
        ;;
    *) echo "Usage: $0 {enable|disable|toggle}"; exit 1;;
esac
BASH
        chmod +x "$BIN_DIR/xui_battery_saver.sh"

        # Battery info: show capacity, status and power/voltage if available
        cat > "$BIN_DIR/xui_battery_info.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
if command -v upower >/dev/null 2>&1; then
    upower -e | while read -r dev; do
        upower -i "$dev" | awk '/percentage|state|voltage|time to/{print}'
    done
    exit 0
fi
for s in /sys/class/power_supply/*; do
    [ -d "$s" ] || continue
    name=$(basename "$s")
    if [ -f "$s/capacity" ]; then
        cap=$(cat "$s/capacity")
        stat=$(cat "$s/status" 2>/dev/null || echo Unknown)
        echo "$name: $cap% ($stat)"
    fi
    if [ -f "$s/voltage_now" ]; then
        v=$(cat "$s/voltage_now")
        echo "$name voltage: $v" 
    fi
done
BASH
        chmod +x "$BIN_DIR/xui_battery_info.sh"

        # Battery profiles: eco, balanced, performance
        cat > "$BIN_DIR/xui_battery_profile.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
PROFILE=${1:-balanced}
write_profile(){ echo "$1" > "$HOME/.xui/data/battery_profile" 2>/dev/null || true }
case "$PROFILE" in
    eco)
        # minimal
        setval=300000
        ;;
    balanced)
        setval=1150000
        ;;
    performance)
        # try to use maxfreq from CPU0
        if [ -f /sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq ]; then
            setval=$(cat /sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq)
        else
            setval=0
        fi
        ;;
    *) echo "Usage: $0 {eco|balanced|performance}"; exit 1;;
esac
if [ "$setval" -ne 0 ]; then
    if command -v cpupower >/dev/null 2>&1; then
        cpupower frequency-set -u "${setval}Hz" >/dev/null 2>&1 || true
    else
        for cpu in /sys/devices/system/cpu/cpu[0-9]*; do
            f="$cpu/cpufreq/scaling_max_freq"
            if [ -f "$f" ]; then
                if [ -w "$f" ]; then
                    echo "$setval" > "$f" || true
                else
                    sudo sh -c "echo $setval > $f" 2>/dev/null || true
                fi
            fi
        done
    fi
fi
write_profile "$PROFILE"
echo "Profile set to $PROFILE"
BASH
        chmod +x "$BIN_DIR/xui_battery_profile.sh"

        # Platform-aware power optimizer for handhelds/laptops (Linux active, future OS placeholders).
        cat > "$BIN_DIR/xui_power_optimize.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
MODE="${1:-auto}" # auto|battery|ac|balanced|performance
CONF="$HOME/.xui/data/power_platform_profile.json"
mkdir -p "$(dirname "$CONF")"

is_on_ac(){
  for a in /sys/class/power_supply/AC*/online /sys/class/power_supply/AC/online /sys/class/power_supply/*/online; do
    [ -f "$a" ] || continue
    case "$(cat "$a" 2>/dev/null || true)" in
      1) return 0 ;;
    esac
  done
  return 1
}

device_tag(){
  local m=""
  m="$(cat /proc/device-tree/model 2>/dev/null || true)"
  if [ -z "$m" ]; then
    m="$(cat /sys/devices/virtual/dmi/id/product_name 2>/dev/null || true) $(cat /sys/devices/virtual/dmi/id/board_name 2>/dev/null || true)"
  fi
  m="$(printf '%s' "$m" | tr '[:upper:]' '[:lower:]')"
  if echo "$m" | grep -Eq 'switch|tegra|l4t'; then echo "switch-l4t"; return; fi
  if echo "$m" | grep -Eq 'steam deck|neptune|jupiter'; then echo "steamdeck"; return; fi
  if echo "$m" | grep -Eq 'rog ally|aya|gpd|onexplayer|legion go'; then echo "pc-handheld"; return; fi
  echo "generic-linux"
}

set_governor(){
  local gov="$1"
  for f in /sys/devices/system/cpu/cpu[0-9]*/cpufreq/scaling_governor; do
    [ -f "$f" ] || continue
    if [ -w "$f" ]; then
      echo "$gov" > "$f" 2>/dev/null || true
    fi
  done
}

set_cpu_max(){
  local val="$1"
  [ -n "$val" ] || return 0
  for f in /sys/devices/system/cpu/cpu[0-9]*/cpufreq/scaling_max_freq; do
    [ -f "$f" ] || continue
    if [ -w "$f" ]; then
      echo "$val" > "$f" 2>/dev/null || true
    fi
  done
}

apply_linux_profile(){
  local prof="$1" tag="$2"
  case "$prof" in
    battery)
      set_governor powersave || true
      case "$tag" in
        switch-l4t) set_cpu_max 1020000 || true ;;
        steamdeck|pc-handheld) set_cpu_max 1800000 || true ;;
        *) set_cpu_max 1400000 || true ;;
      esac
      "$HOME/.xui/bin/xui_battery_saver.sh" enable >/dev/null 2>&1 || true
      ;;
    ac|performance)
      set_governor schedutil || set_governor performance || true
      "$HOME/.xui/bin/xui_battery_saver.sh" disable >/dev/null 2>&1 || true
      ;;
    balanced|*)
      set_governor schedutil || true
      "$HOME/.xui/bin/xui_battery_saver.sh" disable >/dev/null 2>&1 || true
      ;;
  esac
}

tag="$(device_tag)"
profile="$MODE"
if [ "$MODE" = "auto" ]; then
  if is_on_ac; then profile="ac"; else profile="battery"; fi
fi

uname_s="$(uname -s 2>/dev/null || echo Linux)"
if [ "$uname_s" = "Linux" ]; then
  apply_linux_profile "$profile" "$tag"
fi

cat > "$CONF" <<JSON
{
  "platform_detected": "$tag",
  "os": "$uname_s",
  "profile_applied": "$profile",
  "future_targets": ["windows", "android9plus", "windows_handheld"]
}
JSON

echo "Power optimizer: $profile ($tag)"
BASH
        chmod +x "$BIN_DIR/xui_power_optimize.sh"

        # Battery monitor: Python small script that watches capacity and enables saver below threshold
        cat > "$BIN_DIR/xui_battery_monitor.py" <<'PY'
#!/usr/bin/env python3
import time, os, subprocess, logging
XUI=os.path.expanduser('~/.xui')
logging.basicConfig(filename=os.path.join(XUI,'logs','battery_monitor.log'), level=logging.INFO, format='%(asctime)s %(message)s')
THRESHOLD=int(os.environ.get('XUI_BATTERY_THRESHOLD','20'))
CHECK=int(os.environ.get('XUI_BATTERY_CHECK_SEC','60'))

def read_capacity():
    # try sysfs
    for base in ['/sys/class/power_supply']:
        if os.path.isdir(base):
            for s in os.listdir(base):
                p=os.path.join(base,s,'capacity')
                if os.path.exists(p):
                    try:
                        return int(open(p).read().strip())
                    except Exception:
                        continue
    # fallback to upower
    try:
        out=subprocess.check_output(['upower','-e'], text=True)
        for dev in out.splitlines():
            try:
                info=subprocess.check_output(['upower','-i',dev], text=True)
                for line in info.splitlines():
                    line=line.strip()
                    if line.startswith('percentage:'):
                        return int(line.split()[1].strip('%'))
            except Exception:
                continue
    except Exception:
        pass
    return None

def is_charging():
    for base in ['/sys/class/power_supply']:
        if os.path.isdir(base):
            for s in os.listdir(base):
                p=os.path.join(base,s,'status')
                if os.path.exists(p):
                    try:
                        st=open(p).read().strip().lower()
                        if 'charging' in st:
                            return True
                    except Exception:
                        continue
    try:
        out=subprocess.check_output(['upower','-i',subprocess.check_output(['upower','-e']).splitlines()[0]], text=True)
        for line in out.splitlines():
            if 'state:' in line:
                if 'charging' in line.lower():
                    return True
    except Exception:
        pass
    return False

def enable_saver():
    subprocess.run([os.path.join(XUI,'bin','xui_battery_saver.sh'),'enable'])
def disable_saver():
    subprocess.run([os.path.join(XUI,'bin','xui_battery_saver.sh'),'disable'])

def main():
    saver_on=False
    logging.info('battery monitor started, threshold=%s, check=%s', THRESHOLD, CHECK)
    while True:
        try:
            cap=read_capacity()
            ch=is_charging()
            logging.debug('cap=%s charging=%s saver_on=%s', cap, ch, saver_on)
            if cap is not None:
                if cap<=THRESHOLD and not ch and not saver_on:
                    logging.info('capacity %s <= %s, enabling saver', cap, THRESHOLD)
                    enable_saver(); saver_on=True
                if ch and saver_on:
                    logging.info('charging detected, disabling saver')
                    disable_saver(); saver_on=False
        except Exception as e:
            logging.exception('monitor loop error: %s', e)
        time.sleep(CHECK)

if __name__=='__main__':
    main()
PY
        chmod +x "$BIN_DIR/xui_battery_monitor.py"

        # Systemd user unit to run monitor
        cat > "$SYSTEMD_USER_DIR/xui-battery-monitor.service" <<UNIT
[Unit]
Description=XUI Battery Monitor

[Service]
Type=simple
ExecStart=%h/.xui/bin/xui_battery_monitor.py
Restart=on-failure

[Install]
WantedBy=default.target
UNIT

        cat > "$SYSTEMD_USER_DIR/xui-power-opt.service" <<UNIT
[Unit]
Description=XUI Power Optimizer
After=graphical-session.target

[Service]
Type=oneshot
ExecStart=%h/.xui/bin/xui_power_optimize.sh auto

[Install]
WantedBy=default.target
UNIT

}


configure_dashboard_passwordless_sudo(){
  local target_user sudoers_file tmpf
  target_user="${SUDO_USER:-$USER}"
  sudoers_file="/etc/sudoers.d/xui-autosudo-${target_user}"
  tmpf="$(mktemp /tmp/xui-sudoers.XXXXXX)"
  {
    printf '# XUI automatic sudo (generated)\n'
    printf '%s ALL=(root) NOPASSWD: ALL\n' "$target_user"
  } > "$tmpf"

  if ! run_as_root install -m 0440 "$tmpf" "$sudoers_file"; then
    warn "Could not install sudoers rule for automatic XUI sudo."
    rm -f "$tmpf"
    return 1
  fi

  if command -v visudo >/dev/null 2>&1; then
    if ! run_as_root visudo -cf "$sudoers_file" >/dev/null 2>&1; then
      warn "sudoers validation failed, removing $sudoers_file"
      run_as_root rm -f "$sudoers_file" || true
      rm -f "$tmpf"
      return 1
    fi
  fi

  rm -f "$tmpf"
  info "Configured passwordless sudo for XUI actions ($target_user)."
  return 0
}


finish_setup(){
  info "Finalizing installation"
  run_user_systemctl(){
    local rc=0
    set +e
    if command -v timeout >/dev/null 2>&1; then
      timeout "${XUI_SYSTEMCTL_TIMEOUT_SEC:-15}" systemctl --user "$@" >/dev/null 2>&1
      rc=$?
      set -e
      if [ "$rc" -eq 124 ]; then
        warn "systemctl --user $* timed out after ${XUI_SYSTEMCTL_TIMEOUT_SEC:-15}s"
        return 1
      fi
      return "$rc"
    fi
    systemctl --user "$@" >/dev/null 2>&1
    rc=$?
    set -e
    return "$rc"
  }
  # make sure everything is executable
  chmod -R a+x "$BIN_DIR" || true
  chmod +x "$DASH_DIR/pyqt_dashboard_improved.py" || true
  chmod +x "$DASH_DIR/pyqt_dashboard.py" || true
  chmod +x "$BIN_DIR/xui_joy_listener.py" || true
  touch "$XUI_DIR/.xui_4_0xv_setup_done"
  if command -v python3 >/dev/null 2>&1; then
    python3 - "$DATA_DIR/update_channel.json" "${XUI_LINUX_UPDATE_BRANCH:-Main-XUI}" <<'PY' >/dev/null 2>&1 || true
import json,sys,time,pathlib
path=pathlib.Path(sys.argv[1])
branch=str(sys.argv[2] or "linux").strip() or "linux"
data={
  "platform":"linux",
  "branch":branch,
  "updated_at_epoch":int(time.time()),
}
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
PY
  fi
  configure_dashboard_passwordless_sudo || warn "XUI may ask for credentials until sudoers rule is applied."
  info "Configuring autostart for each login"
  mkdir -p "$AUTOSTART_DIR" "$SYSTEMD_USER_DIR" || true
  local openbox_file xprofile_file
  openbox_file="$HOME/.config/openbox/autostart"
  xprofile_file="$HOME/.xprofile"
  mkdir -p "$(dirname "$openbox_file")" || true
  touch "$openbox_file" "$xprofile_file" || true
  # Remove legacy duplicate autostart hooks (Openbox / xprofile).
  sed -i '/xui_startup_and_dashboard.sh/d' "$openbox_file" 2>/dev/null || true
  sed -i '/xui_startup_and_dashboard.sh/d' "$xprofile_file" 2>/dev/null || true
  info "Cleaned Openbox/Xprofile duplicate hooks."

    # Always keep the XDG entry enabled: it inherits the actual X11/Wayland session environment.
  if [ -f "$AUTOSTART_DIR/xui-dashboard.desktop" ]; then
        sed -i 's/^Hidden=.*/Hidden=false/' "$AUTOSTART_DIR/xui-dashboard.desktop" 2>/dev/null || true
        sed -i 's/^X-GNOME-Autostart-enabled=.*/X-GNOME-Autostart-enabled=true/' "$AUTOSTART_DIR/xui-dashboard.desktop" 2>/dev/null || true
  fi
  if command -v systemctl >/dev/null 2>&1; then
    if run_user_systemctl daemon-reload; then
            # The desktop entry is the dashboard autostart source of truth. Disable an old
            # systemd dashboard link so it cannot race the graphical session or grab the lock early.
            run_user_systemctl disable xui-dashboard.service || true
            # Use XDG autostart for the input bridge so it inherits the actual graphical
            # session (including Wayland/Xauthority), instead of a user service with DISPLAY=:0.
            run_user_systemctl disable --now xui-joy.service || true
      run_user_systemctl enable --now xui-battery-monitor.service || true
      run_user_systemctl enable --now xui-power-opt.service || true
            info "Enabled XDG dashboard and Guide-input autostart, plus battery/power services"
    else
            warn "systemctl --user daemon-reload failed; XDG desktop autostart remains enabled"
    fi
  fi
  if [ -x "$BIN_DIR/xui_install_fnae_deps.sh" ]; then
    if command -v timeout >/dev/null 2>&1; then
      XUI_NONINTERACTIVE=1 timeout "${XUI_FNAE_DEPS_TIMEOUT_SEC:-120}" "$BIN_DIR/xui_install_fnae_deps.sh" >/dev/null 2>&1 || true
    else
      XUI_NONINTERACTIVE=1 "$BIN_DIR/xui_install_fnae_deps.sh" >/dev/null 2>&1 || true
    fi
  fi
  info "Installation complete."
}

write_game_intro_wrapper(){
    mkdir -p "$BIN_DIR" "$ASSETS_DIR"
    cat > "$BIN_DIR/xui_play_game_intro.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
INTRO="${XUI_GAME_INTRO:-$HOME/.xui/assets/appbootscreen.mp4}"
LOG_DIR="$HOME/.xui/logs"
mkdir -p "$LOG_DIR"
exec >>"$LOG_DIR/game_boot.log" 2>&1
if [[ ! -s "$INTRO" ]]; then
    echo "Required game boot screen is missing: $INTRO" >&2
    exit 1
fi
if [[ "${1:-}" != "--" ]]; then
    echo "Usage: $0 -- <game command> [args...]" >&2
    exit 2
fi
shift
if [[ "$#" -eq 0 ]]; then
    echo "No game command was provided." >&2
    exit 2
fi
    if [[ "$(basename -- "$1")" == "xenia_canary_linux.AppImage" ]]; then
        exec "$HOME/.xui/bin/xui_xenia_run.sh" "$@"
    fi
played=0
if command -v mpv >/dev/null 2>&1 && mpv --no-terminal --really-quiet --fullscreen --no-config --input-conf=/dev/null --input-default-bindings=no --input-cursor=no --input-vo-keyboard=no --cursor-autohide=always --osc=no --osd-bar=no "$INTRO"; then
    played=1
fi
if [[ "$played" -eq 0 ]] && command -v ffplay >/dev/null 2>&1 && ffplay -autoexit -fs -an -loglevel error "$INTRO"; then
    played=1
fi
if [[ "$played" -eq 0 ]] && command -v vlc >/dev/null 2>&1 && vlc --fullscreen --play-and-exit --no-video-title-show --quiet "$INTRO"; then
    played=1
fi
if [[ "$played" -eq 0 ]]; then
    echo "Install mpv, ffplay, or VLC to play the required game boot screen." >&2
    exit 1
fi
exec "$@"
BASH
    chmod +x "$BIN_DIR/xui_play_game_intro.sh"

    cat > "$BIN_DIR/xui_xenia_run.sh" <<'BASH'
#!/usr/bin/env bash
set -uo pipefail
XUI_HOME="$HOME/.xui"
DATA_DIR="$XUI_HOME/data"
PID_FILE="$DATA_DIR/active_game.pid"
LOG_FILE="$XUI_HOME/logs/xenia.log"
mkdir -p "$DATA_DIR" "$(dirname "$LOG_FILE")"
if [[ "$#" -eq 0 ]]; then
    echo "Usage: $0 <Xenia command> [args...]" >&2
    exit 2
fi

# Prevent two Xenia windows from racing the Guide target-window tracking.
if command -v flock >/dev/null 2>&1; then
    exec 9>"$DATA_DIR/xenia_run.lock"
    if ! flock -n 9; then
        echo "Xenia is already running; refusing to create a duplicate instance." >&2
        exit 0
    fi
fi

"$@" >>"$LOG_FILE" 2>&1 &
game_pid=$!
printf '%s\n' "$game_pid" > "$PID_FILE"
cleanup(){
    if [[ "$(cat "$PID_FILE" 2>/dev/null || true)" == "$game_pid" ]]; then
        rm -f "$PID_FILE"
    fi
}
trap cleanup EXIT

# Request EWMH fullscreen after Xenia has created its window. XUI's Guide is a
# separate always-on-top window, so it remains drawable above this fullscreen window.
if [[ "${XUI_XENIA_FULLSCREEN:-1}" != "0" ]] && command -v xdotool >/dev/null 2>&1; then
    for _ in {1..120}; do
        kill -0 "$game_pid" 2>/dev/null || break
        window_id="$(xdotool search --onlyvisible --pid "$game_pid" 2>/dev/null | tail -n 1 || true)"
        if [[ -z "$window_id" ]]; then
            window_id="$(xdotool search --onlyvisible --name 'Xenia' 2>/dev/null | tail -n 1 || true)"
        fi
        if [[ -n "$window_id" ]]; then
            xdotool windowstate "$window_id" --add FULLSCREEN >/dev/null 2>&1 || true
            xdotool windowraise "$window_id" >/dev/null 2>&1 || true
            break
        fi
        sleep 0.1
    done
else
    echo "xdotool unavailable or fullscreen disabled; Xenia will use its own window mode." >>"$LOG_FILE"
fi

wait "$game_pid"
BASH
    chmod +x "$BIN_DIR/xui_xenia_run.sh"
}

write_xenia_canary_tools(){
    write_game_intro_wrapper
  info "Writing Xenia Canary installer and launcher"
  mkdir -p "$BIN_DIR" "$XUI_DIR/emulators/xenia-canary"
  cat > "$BIN_DIR/xui_install_xenia_canary.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
DEST="$HOME/.xui/emulators/xenia-canary"
APPIMAGE="$DEST/xenia_canary_linux.AppImage"
VERSION_FILE="$DEST/release.json"
ARCH="$(uname -m)"
if [[ "$ARCH" != "x86_64" && "$ARCH" != "amd64" ]]; then
  echo "Xenia Canary AppImage requires Linux x86_64; detected $ARCH." >&2
  exit 2
fi
mkdir -p "$DEST"
exec python3 - "$APPIMAGE" "$VERSION_FILE" <<'PY'
import hashlib
import json
import os
import pathlib
import sys
import tempfile
import urllib.error
import urllib.request

app = pathlib.Path(sys.argv[1]).expanduser()
version_file = pathlib.Path(sys.argv[2]).expanduser()
api = 'https://api.github.com/repos/xenia-canary/xenia-canary/releases/latest'
request = urllib.request.Request(api, headers={
    'Accept': 'application/vnd.github+json',
    'User-Agent': 'XUI-Xenia-Canary-Installer',
})
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        release = json.load(response)
except Exception as exc:
    if app.is_file() and os.access(app, os.X_OK):
        print(f'GitHub is unavailable; keeping installed Xenia Canary: {exc}')
        raise SystemExit(0)
    print(f'Cannot query official Xenia Canary releases: {exc}', file=sys.stderr)
    raise SystemExit(1)

tag = str(release.get('tag_name') or '').strip()
asset = next((item for item in release.get('assets', [])
              if item.get('name') == 'xenia_canary_linux.AppImage'), None)
if not tag or not isinstance(asset, dict):
    print('The latest official release has no Linux AppImage asset.', file=sys.stderr)
    raise SystemExit(1)
digest = str(asset.get('digest') or '')
if not digest.startswith('sha256:') or len(digest) != 71:
    print('GitHub did not provide a valid SHA-256 for the AppImage; refusing to install it.', file=sys.stderr)
    raise SystemExit(1)
expected_hash = digest.removeprefix('sha256:').lower()
url = str(asset.get('browser_download_url') or '')
if not url.startswith('https://github.com/xenia-canary/xenia-canary/releases/download/'):
    print('Unexpected release download URL; refusing to install.', file=sys.stderr)
    raise SystemExit(1)
try:
    installed = json.loads(version_file.read_text(encoding='utf-8'))
except Exception:
    installed = {}
if app.is_file() and os.access(app, os.X_OK) and installed.get('tag') == tag:
    print(f'Xenia Canary {tag} is already installed.')
    raise SystemExit(0)

app.parent.mkdir(parents=True, exist_ok=True)
fd, temporary_name = tempfile.mkstemp(prefix='.xenia-canary-', suffix='.AppImage', dir=app.parent)
temporary = pathlib.Path(temporary_name)
hasher = hashlib.sha256()
total = 0
try:
    request = urllib.request.Request(url, headers={'User-Agent': 'XUI-Xenia-Canary-Installer'})
    with os.fdopen(fd, 'wb') as output, urllib.request.urlopen(request, timeout=60) as response:
        while True:
            chunk = response.read(1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            if total > 512 * 1024 * 1024:
                raise RuntimeError('AppImage exceeded the 512 MiB safety limit.')
            hasher.update(chunk)
            output.write(chunk)
        output.flush()
        os.fsync(output.fileno())
    if total < 1024 * 1024:
        raise RuntimeError('Downloaded AppImage is unexpectedly small.')
    actual_hash = hasher.hexdigest().lower()
    if actual_hash != expected_hash:
        raise RuntimeError(f'SHA-256 verification failed (expected {expected_hash}, got {actual_hash}).')
    temporary.chmod(0o755)
    temporary.replace(app)
    version_file.write_text(json.dumps({
        'tag': tag,
        'asset': asset['name'],
        'sha256': actual_hash,
        'source': url,
    }, indent=2) + '\n', encoding='utf-8')
    print(f'Installed verified Xenia Canary {tag} at {app}')
except Exception as exc:
    try:
        temporary.unlink(missing_ok=True)
    except Exception:
        pass
    print(f'Xenia Canary installation failed: {exc}', file=sys.stderr)
    raise SystemExit(1)
PY
BASH
  chmod +x "$BIN_DIR/xui_install_xenia_canary.sh"

  cat > "$BIN_DIR/xui_xenia_canary.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
APPIMAGE="$HOME/.xui/emulators/xenia-canary/xenia_canary_linux.AppImage"
INSTALLER="$HOME/.xui/bin/xui_install_xenia_canary.sh"
mkdir -p "$HOME/.xui/logs"
exec >>"$HOME/.xui/logs/xenia.log" 2>&1
case "${1:-}" in
  --check)
    [[ -x "$APPIMAGE" ]]
    exit $?
    ;;
  --install)
    exec "$INSTALLER"
    ;;
esac
if [[ ! -x "$APPIMAGE" ]]; then
  echo "Xenia Canary is not installed. Run: $INSTALLER" >&2
  exit 1
fi
# Fallback extracts AppImages without requiring system-wide FUSE installation.
export APPIMAGE_EXTRACT_AND_RUN=1
if [[ "$#" -gt 0 ]]; then
    if [[ -d "$1" ]]; then
        ROOT="$1"
        mapfile -t XEX_FILES < <(find "$ROOT" -type f -iname '*.xex' | sort)
        if [[ "${#XEX_FILES[@]}" -eq 0 ]]; then
            echo "No .xex game executable found in folder: $ROOT" >&2
            exit 2
        fi
        if [[ "${#XEX_FILES[@]}" -gt 1 ]]; then
            DEFAULT_XEX=""
            for candidate in "${XEX_FILES[@]}"; do
                candidate_name="$(basename "$candidate")"
                if [[ "${candidate_name,,}" == "default.xex" ]]; then DEFAULT_XEX="$candidate"; break; fi
            done
            if [[ -z "$DEFAULT_XEX" ]]; then
                printf 'Multiple .xex files found; select a specific game executable:\n%s\n' "${XEX_FILES[@]}" >&2
                exit 2
            fi
            set -- "$DEFAULT_XEX" "${@:2}"
        fi
        if [[ "${#XEX_FILES[@]}" -eq 1 ]]; then set -- "${XEX_FILES[0]}" "${@:2}"; fi
    fi
    exec "$HOME/.xui/bin/xui_play_game_intro.sh" -- "$APPIMAGE" "$@"
fi
exec "$HOME/.xui/bin/xui_xenia_run.sh" "$APPIMAGE" "$@"
BASH
  chmod +x "$BIN_DIR/xui_xenia_canary.sh"

  cat > "$BIN_DIR/xui_dump_xenia_homebrew_disc.py" <<'PY'
#!/usr/bin/env python3
import datetime
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys


HOME = Path.home()
DUMP_ROOT = HOME / '.xui' / 'games' / 'xenia_dumps'
XENIA = HOME / '.xui' / 'bin' / 'xui_xenia_canary.sh'


def optical_mounts():
    try:
        result = subprocess.run(
            ['lsblk', '--json', '--output', 'PATH,TYPE,MOUNTPOINTS'],
            check=True,
            capture_output=True,
            text=True,
            timeout=8,
        )
        devices = json.loads(result.stdout).get('blockdevices', [])
    except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as exc:
        raise RuntimeError(f'Unable to inspect optical drives with lsblk: {exc}') from exc

    mounts = []

    def visit(rows):
        for row in rows if isinstance(rows, list) else []:
            if not isinstance(row, dict):
                continue
            if str(row.get('type') or '').lower() == 'rom':
                points = row.get('mountpoints')
                if not isinstance(points, list):
                    points = [row.get('mountpoint')]
                for point in points:
                    path = Path(str(point or '')).expanduser()
                    if path.is_dir() and os.access(path, os.R_OK):
                        mounts.append(path.resolve())
            visit(row.get('children', []))

    visit(devices)
    return list(dict.fromkeys(mounts))


def disc_size(source):
    total = 0
    for root, dirs, files in os.walk(source, followlinks=False):
        dirs[:] = [name for name in dirs if not (Path(root) / name).is_symlink()]
        for name in files:
            path = Path(root) / name
            try:
                if not path.is_symlink():
                    total += path.stat().st_size
            except OSError:
                continue
    return total


def dump_disc(source):
    DUMP_ROOT.mkdir(parents=True, exist_ok=True)
    label = ''.join(ch if ch.isalnum() or ch in '-_' else '_' for ch in source.name).strip('_') or 'homebrew_dvd'
    stamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    destination = DUMP_ROOT / f'{label}-{stamp}'
    staging = DUMP_ROOT / f'.{destination.name}.partial'
    needed = disc_size(source)
    free = shutil.disk_usage(DUMP_ROOT).free
    if needed > free:
        raise RuntimeError(f'Not enough free space: need {needed} bytes, have {free} bytes.')

    print(f'Copying mounted disc {source} ({needed} bytes)...', flush=True)
    try:
        shutil.copytree(source, staging, symlinks=True)
        staging.rename(destination)
    except Exception:
        shutil.rmtree(staging, ignore_errors=True)
        raise

    executables = sorted(
        (path for path in destination.rglob('*') if path.is_file() and path.suffix.lower() in ('.xex', '.iso')),
        key=lambda path: (path.name.lower() != 'default.xex', str(path).lower()),
    )
    if not executables:
        raise RuntimeError(f'Disc copied to {destination}, but it contains no .xex or .iso for Xenia.')
    if len(executables) > 1 and executables[0].name.lower() != 'default.xex':
        raise RuntimeError(
            f'Disc copied to {destination}, but it contains multiple XEX/ISO files. '
            'Use “Launch Xbox 360 Game Dump” to select the correct one.'
        )
    return destination, executables[0]


def main():
    if not XENIA.is_file() or not os.access(XENIA, os.X_OK):
        raise RuntimeError('Xenia Canary is not installed. Install it from the XUI Games menu first.')
    if len(sys.argv) > 2:
        raise RuntimeError(f'Usage: {Path(sys.argv[0]).name} [mounted-disc-or-game-folder]')
    if len(sys.argv) == 2:
        source = Path(sys.argv[1]).expanduser().resolve()
        if not source.is_dir() or not os.access(source, os.R_OK):
            raise RuntimeError(f'Selected source is not a readable folder: {source}')
    else:
        mounts = optical_mounts()
        if not mounts:
            raise RuntimeError('No mounted optical disc was found. Mount the disc or pass its folder path.')
        if len(mounts) > 1:
            details = '\n'.join(str(path) for path in mounts)
            raise RuntimeError(f'More than one optical disc is mounted; specify the target folder.\n{details}')
        source = mounts[0]

    destination, game = dump_disc(source)
    print(f'Dump complete: {destination}', flush=True)
    print(f'Launching in Xenia: {game}', flush=True)
    subprocess.Popen(
        [str(XENIA), str(game)],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=True,
    )
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f'Homebrew DVD dump failed: {exc}', file=sys.stderr, flush=True)
        raise SystemExit(1)
PY
  chmod +x "$BIN_DIR/xui_dump_xenia_homebrew_disc.py"
}

write_xemu_tools(){
