except Exception as exc:
    if app.is_file() and os.access(app, os.X_OK):
        print(f'GitHub is unavailable; keeping installed xemu: {exc}')
        raise SystemExit(0)
    print(f'Cannot query official xemu releases: {exc}', file=sys.stderr)
    raise SystemExit(1)

tag = str(release.get('tag_name') or '').strip()
version = tag.removeprefix('v')
asset_name = f'xemu-{version}-{arch}.AppImage'
asset = next((item for item in release.get('assets', []) if item.get('name') == asset_name), None)
if not tag or not isinstance(asset, dict):
    print(f'The official release has no AppImage asset named {asset_name}.', file=sys.stderr)
    raise SystemExit(1)
digest = str(asset.get('digest') or '')
if not digest.startswith('sha256:') or len(digest) != 71:
    print('GitHub did not provide a valid SHA-256 digest for xemu; refusing to install.', file=sys.stderr)
    raise SystemExit(1)
expected_hash = digest.removeprefix('sha256:').lower()
url = str(asset.get('browser_download_url') or '')
if not url.startswith('https://github.com/xemu-project/xemu/releases/download/'):
    print('Unexpected xemu release URL; refusing to install.', file=sys.stderr)
    raise SystemExit(1)
try:
    installed = json.loads(version_file.read_text(encoding='utf-8'))
except Exception:
    installed = {}
if app.is_file() and os.access(app, os.X_OK) and installed.get('tag') == tag:
    print(f'xemu {tag} is already installed.')
    raise SystemExit(0)

app.parent.mkdir(parents=True, exist_ok=True)
fd, temporary_name = tempfile.mkstemp(prefix='.xemu-', suffix='.AppImage', dir=app.parent)
temporary = pathlib.Path(temporary_name)
hasher = hashlib.sha256()
total = 0
try:
    request = urllib.request.Request(url, headers={'User-Agent': 'XUI-xemu-Installer'})
    with os.fdopen(fd, 'wb') as output, urllib.request.urlopen(request, timeout=60) as response:
        while True:
            chunk = response.read(1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            if total > 256 * 1024 * 1024:
                raise RuntimeError('AppImage exceeded the 256 MiB safety limit.')
            hasher.update(chunk)
            output.write(chunk)
        output.flush()
        os.fsync(output.fileno())
    if total < 1024 * 1024:
        raise RuntimeError('Downloaded AppImage is unexpectedly small.')
    actual_hash = hasher.hexdigest().lower()
    if actual_hash != expected_hash:
        raise RuntimeError(f'SHA-256 verification failed (expected {expected_hash}, got {actual_hash}).')
    temporary.chmod(0o755)
    temporary.replace(app)
    version_file.write_text(json.dumps({
        'tag': tag,
        'asset': asset_name,
        'sha256': actual_hash,
        'source': url,
    }, indent=2) + '\n', encoding='utf-8')
    print(f'Installed verified xemu {tag} at {app}')
except Exception as exc:
    try:
        temporary.unlink(missing_ok=True)
    except Exception:
        pass
    print(f'xemu installation failed: {exc}', file=sys.stderr)
    raise SystemExit(1)
PY
BASH
  chmod +x "$BIN_DIR/xui_install_xemu.sh"

  cat > "$BIN_DIR/xui_xemu.sh" <<'BASH'
#!/usr/bin/env bash
set -euo pipefail
APPIMAGE="$HOME/.xui/emulators/xemu/xemu.AppImage"
INSTALLER="$HOME/.xui/bin/xui_install_xemu.sh"
mkdir -p "$HOME/.xui/logs"
exec >>"$HOME/.xui/logs/xemu.log" 2>&1
case "${1:-}" in
  --check)
    [[ -x "$APPIMAGE" ]]
    exit $?
    ;;
  --install)
    exec "$INSTALLER"
    ;;
esac
if [[ ! -x "$APPIMAGE" ]]; then
  echo "xemu is not installed. Run: $INSTALLER" >&2
  exit 1
fi
if [[ "$#" -gt 0 && "${1:-}" != -* ]]; then
  IMAGE="$1"
  shift
    if [[ -d "$IMAGE" ]]; then
        mapfile -t XISOS < <(find "$IMAGE" -type f \( -iname '*.iso' -o -iname '*.xiso' \) | sort)
        if [[ "${#XISOS[@]}" -ne 1 ]]; then
            echo "Expected exactly one XISO image in folder; found ${#XISOS[@]}. Use Launch Original Xbox XISO to select one file." >&2
            exit 2
        fi
        IMAGE="${XISOS[0]}"
    fi
  if [[ ! -f "$IMAGE" ]]; then
    echo "XISO image not found: $IMAGE" >&2
    exit 2
  fi
    case "${IMAGE,,}" in
        *.iso|*.xiso) ;;
        *) echo "xemu requires an original Xbox .iso/.xiso image, not: $IMAGE" >&2; exit 2 ;;
    esac
  export APPIMAGE_EXTRACT_AND_RUN=1
    exec "$HOME/.xui/bin/xui_play_game_intro.sh" -- "$APPIMAGE" -dvd_path "$IMAGE" "$@"
fi
export APPIMAGE_EXTRACT_AND_RUN=1
exec "$APPIMAGE" "$@"
BASH
  chmod +x "$BIN_DIR/xui_xemu.sh"

  cat > "$BIN_DIR/xui_dump_xemu_homebrew_disc.py" <<'PY'
#!/usr/bin/env python3
import datetime
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys


HOME = Path.home()
DUMP_ROOT = HOME / '.xui' / 'games' / 'xemu_dumps'
XEMU = HOME / '.xui' / 'bin' / 'xui_xemu.sh'


def optical_mounts():
    try:
        result = subprocess.run(
            ['lsblk', '--json', '--output', 'PATH,TYPE,MOUNTPOINTS'],
            check=True,
            capture_output=True,
            text=True,
            timeout=8,
        )
        devices = json.loads(result.stdout).get('blockdevices', [])
    except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as exc:
        raise RuntimeError(f'Unable to inspect optical drives with lsblk: {exc}') from exc

    mounts = []

    def visit(rows):
        for row in rows if isinstance(rows, list) else []:
            if not isinstance(row, dict):
                continue
            if str(row.get('type') or '').lower() == 'rom':
                points = row.get('mountpoints')
                if not isinstance(points, list):
                    points = [row.get('mountpoint')]
                for point in points:
                    path = Path(str(point or '')).expanduser()
                    if path.is_dir() and os.access(path, os.R_OK):
                        mounts.append(path.resolve())
            visit(row.get('children', []))

    visit(devices)
    return list(dict.fromkeys(mounts))


def media_size(source):
    total = 0
    for root, dirs, files in os.walk(source, followlinks=False):
        dirs[:] = [name for name in dirs if not (Path(root) / name).is_symlink()]
        for name in files:
            path = Path(root) / name
            try:
                if not path.is_symlink():
                    total += path.stat().st_size
            except OSError:
                continue
    return total


def dump_disc(source):
    DUMP_ROOT.mkdir(parents=True, exist_ok=True)
    label = ''.join(ch if ch.isalnum() or ch in '-_' else '_' for ch in source.name).strip('_') or 'xbox_homebrew_dvd'
    stamp = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    destination = DUMP_ROOT / f'{label}-{stamp}'
    staging = DUMP_ROOT / f'.{destination.name}.partial'
    needed = media_size(source)
    free = shutil.disk_usage(DUMP_ROOT).free
    if needed > free:
        raise RuntimeError(f'Not enough free space: need {needed} bytes, have {free} bytes.')

    print(f'Copying mounted disc {source} ({needed} bytes)...', flush=True)
    try:
        shutil.copytree(source, staging, symlinks=True)
        staging.rename(destination)
    except Exception:
        shutil.rmtree(staging, ignore_errors=True)
        raise

    images = sorted(
        (path for path in destination.rglob('*') if path.is_file() and path.suffix.lower() in ('.iso', '.xiso')),
        key=lambda path: str(path).lower(),
    )
    if not images:
        raise RuntimeError(
            f'Disc copied to {destination}, but contains no .iso/.xiso image. '
            'xemu needs an XISO image; a mounted folder or raw/redump ISO is not sufficient.'
        )
    if len(images) != 1:
        raise RuntimeError(
            f'Disc copied to {destination}, but contains {len(images)} ISO files. '
            'Use “Launch Original Xbox XISO” to select the correct XISO.'
        )
    return destination, images[0]


def main():
    if not XEMU.is_file() or not os.access(XEMU, os.X_OK):
        raise RuntimeError('xemu is not installed. Install it from the XUI Games menu first.')
    if len(sys.argv) > 2:
        raise RuntimeError(f'Usage: {Path(sys.argv[0]).name} [mounted-disc-or-game-folder]')
    if len(sys.argv) == 2:
        source = Path(sys.argv[1]).expanduser().resolve()
        if not source.is_dir() or not os.access(source, os.R_OK):
            raise RuntimeError(f'Selected source is not a readable folder: {source}')
    else:
        mounts = optical_mounts()
        if not mounts:
            raise RuntimeError('No mounted optical disc was found. Mount the disc or pass its folder path.')
        if len(mounts) > 1:
            details = '\n'.join(str(path) for path in mounts)
            raise RuntimeError(f'More than one optical disc is mounted; specify the target folder.\n{details}')
        source = mounts[0]

    destination, image = dump_disc(source)
    print(f'Dump complete: {destination}', flush=True)
    print(f'Launching XISO in xemu: {image}', flush=True)
    subprocess.Popen(
        [str(XEMU), str(image)],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=True,
    )
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f'Original Xbox DVD dump failed: {exc}', file=sys.stderr, flush=True)
        raise SystemExit(1)
PY
  chmod +x "$BIN_DIR/xui_dump_xemu_homebrew_disc.py"
}

main(){
  parse_args "$@"
  if [ "${XUI_ONLY_EXPORT_WIN:-0}" = "1" ]; then
    info "Exporting Windows bundle only"
    write_windows_bundle
    exit 0
  fi
  if [ "${XUI_ONLY_REFRESH_CONTROLLERS:-0}" = "1" ]; then
    info "Refreshing controller integration only (Joy-Con/Xbox)"
    ensure_dirs
    write_joy_py
    write_systemd_and_autostart
    write_even_more_apps
    if command -v systemctl >/dev/null 2>&1; then
      systemctl --user daemon-reload >/dev/null 2>&1 || true
      systemctl --user restart xui-joy.service >/dev/null 2>&1 || true
    fi
    info "Controller tools refreshed. Run:"
    info "  ~/.xui/bin/xui_controller_probe.sh"
    info "  ~/.xui/bin/xui_controller_mappings.sh"
    info "  ~/.xui/bin/xui_controller_l4t_fix.sh"
    exit 0
  fi
    if [ "${XUI_ONLY_REFRESH_UPDATER:-0}" = "1" ]; then
        info "Refreshing Mandatory Update checker and dashboard progress UI"
        ensure_dirs
        write_auto_update
        write_dashboard_py
        info "Updater refreshed at: $HOME/.xui/bin/xui_update_check.sh"
        info "Dashboard progress UI refreshed at: $HOME/.xui/dashboard/pyqt_dashboard_improved.py"
        info "Close and relaunch XUI before retrying Mandatory Update."
        exit 0
    fi
    if [ "${XUI_ONLY_REFRESH_XENIA:-0}" = "1" ]; then
        info "Refreshing Xbox emulator integrations only"
        ensure_dirs
        copy_assets
        write_dashboard_py
        write_xenia_canary_tools
        write_xemu_tools
        info "Xenia dumper refreshed at: $HOME/.xui/bin/xui_dump_xenia_homebrew_disc.py"
        info "xemu installer and homebrew DVD dumper refreshed at: $HOME/.xui/bin/xui_install_xemu.sh"
        info "Restart XUI to use the Xbox 360 and original Xbox actions."
        exit 0
    fi
  if [ "${XUI_ONLY_REFRESH_STORE:-0}" = "1" ]; then
        info "Refreshing casino and store apps only (fast mode)"
    ensure_dirs
    write_extras
        info "Casino poker engine refreshed at: $HOME/.xui/casino/poker_engine_v2.py"
        info "Store UI refreshed at: $HOME/.xui/games/store.py"
        info "Restart XUI before opening Casino or Store again."
    exit 0
  fi
  info "Starting XUI Ultra Master installer"
  ensure_dirs
  install_dependencies
    install_browser
  create_basics
    post_create_assets
  write_dashboard_py
  deploy_custom_dashboard
    write_apps_utilities
    write_more_apps
  write_joy_py
  write_extras
  write_systemd_and_autostart
  write_enable_autostart_script
    install_desktop_icons
    # Additional utilities
    write_logger_and_helpers
    write_backup_restore
    write_diagnostics
    write_profiles_manager
    write_plugins_skeleton
    write_auto_update
    write_uninstall
    write_readme_and_requirements
    write_basic_tests
        write_web_control
        write_theme_toggle
        install_compat_layer
        write_xenia_canary_tools
        write_xemu_tools
        if [ "${XUI_SKIP_XENIA:-0}" != "1" ]; then
            case "$(uname -m)" in
                x86_64|amd64)
                    "$BIN_DIR/xui_install_xenia_canary.sh" || warn "Xenia Canary auto-install failed; run ~/.xui/bin/xui_install_xenia_canary.sh later"
                    ;;
                *)
                    info "Skipping Xenia Canary AppImage auto-install: Linux x86_64 is required"
                    ;;
            esac
        else
            info "Skipping Xenia Canary auto-install (--skip-xenia)"
        fi
        write_battery_tools
        write_even_more_apps
  if [ "${XUI_EXPORT_WIN:-0}" = "1" ]; then
    write_windows_bundle || warn "Windows bundle export failed"
  fi
  finish_setup
  if [ "${XUI_SKIP_LAUNCH_PROMPT:-0}" = "1" ]; then
    info "Skipping launch prompt (XUI_SKIP_LAUNCH_PROMPT=1)"
  elif confirm "Do you want to launch the dashboard now?"; then
    "$BIN_DIR/xui_start.sh"
  fi
}

main "$@"
